window.HT.BAI = {"G00":{"ma":"G00","tieu_de":"Từ Làng Sen Đến Ba Đình: Hành Trình Một Đời Người","sapo":"Giữa Sảnh Hành trình hình tròn với mười tám mặt vòm, toàn bộ 79 năm cuộc đời Chủ tịch Hồ Chí Minh được kể lại bằng chính những nơi Người đã sống: một cậu bé làng Sen mang nhiều tên gọi khác nhau, ba mươi năm bôn ba qua hàng chục thành phố ở nhiều châu lục, rồi trở về dẫn dắt một dân tộc giành độc lập. Mỗi vòm cửa quanh sảnh là một cánh cửa mở vào một chặng đường có thật.","sapo_en":"This rotunda hall maps President Ho Chi Minh's entire 79-year life through the real places he lived — from a boy in Sen village who carried many names, through thirty years abroad across several continents, to the founding of independent Vietnam.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_1946_and_signature_cropped.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một cậu bé làng Sen mang nhiều tên gọi","text":"Người đàn ông cả thế giới biết đến với tên gọi Hồ Chí Minh đã đi qua cuộc đời mình với rất nhiều cái tên khác nhau, mỗi tên gắn với một chặng đường. Khi cất tiếng khóc chào đời ngày 19 tháng 5 năm 1890 tại làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, cậu bé được đặt tên Nguyễn Sinh Cung. Năm 1901, khi cha là ông Nguyễn Sinh Sắc đỗ Phó bảng và cả nhà chuyển về làng Sen, cậu được đổi tên thành Nguyễn Tất Thành theo lệ đặt tên của nhà nho. Ngày 5 tháng 6 năm 1911, chàng thanh niên hai mươi mốt tuổi xuống tàu Amiral Latouche-Tréville rời bến cảng Sài Gòn với một cái tên giản dị: Văn Ba, phụ bếp trên tàu. Từ năm 1919, khi gửi bản Yêu sách của nhân dân An Nam tới Hội nghị Versailles, Người ký tên Nguyễn Ái Quốc — cái tên gắn liền với những năm hoạt động công khai ở Pháp. Trong những năm bí mật hoạt động ở Trung Quốc, Xiêm, Hồng Kông, Người còn mang nhiều bí danh khác như Lý Thụy, Tống Văn Sơ, Thầu Chín... Tháng 8/1942, khi lên đường sang Trung Quốc, Người lấy tên Hồ Chí Minh; ít ngày sau (29/8/1942), Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ ở Quảng Tây. Đó là cái tên trở thành tên gọi chính thức từ sau Cách mạng Tháng Tám 1945, đi vào lịch sử dân tộc.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","chu_thich":"Trụ sở hãng Messageries Maritimes tại Bến Nhà Rồng, Sài Gòn, cuối thế kỷ XIX – đầu thế kỷ XX. Ngày 5/6/1911, từ chính bến cảng này, chàng thanh niên Nguyễn Tất Thành — mang tên Văn Ba — xuống tàu Amiral Latouche-Tréville làm phụ bếp, mở đầu ba mươi năm bôn ba tìm đường cứu nước.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ba mươi năm qua bốn phương trời","text":"Suốt ba mươi năm, từ 1911 đến 1941, dấu chân Người in trên rất nhiều bến cảng và thành phố: Marseille, Le Havre, Dunkerque của nước Pháp; London, nơi Người từng phụ bếp, cào tuyết, rửa bát trong các khách sạn; Boston và New York bên kia Đại Tây Dương; rồi Paris, nơi Người sống và hoạt động chính trị sôi nổi suốt những năm 1919-1923. Từ Paris, hành trình đưa Người tới Moskva để học tập trong bộ máy Quốc tế Cộng sản, tới Quảng Châu để huấn luyện lớp thanh niên yêu nước đầu tiên, tới Xiêm (Thái Lan ngày nay), Hồng Kông, rồi trở lại Liên Xô một lần nữa trước khi tìm đường về gần biên giới Tổ quốc. Trong ngần ấy năm tháng, Người từng làm rất nhiều nghề để mưu sinh và hoạt động cách mạng: phụ bếp trên tàu viễn dương, thợ làm bánh, thợ ảnh, người viết báo... Chính hành trình lao động và quan sát ấy — chứ không phải sách vở trong giảng đường — đã cho Người vốn hiểu biết sống động về thế giới thuộc địa và những người cùng khổ ở khắp nơi.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_at_the_age_of_30_in_franc.jpg","chu_thich":"Nguyễn Ái Quốc ở Pháp, tuổi ba mươi (1920) — những năm tháng hoạt động sôi nổi trong phong trào công nhân Pháp và cộng đồng người Việt yêu nước tại Paris.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Trong suốt cuộc đời hoạt động cách mạng, Người đã dùng rất nhiều bí danh, bút danh khác nhau tùy từng giai đoạn và vỏ bọc: Văn Ba, Nguyễn Ái Quốc, Lý Thụy, Tống Văn Sơ, Thầu Chín... Theo thống kê của các nhà nghiên cứu, tổng số tên gọi, bí danh và bút danh Người từng sử dụng lên tới hơn một trăm.","nguon_ten":"en.wikipedia.org","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_nguyen_ai_quoc_in_the_soviet_union_in_1923.jpg","chu_thich":"Nguyễn Ái Quốc tại Liên Xô, năm 1923 — thời gian Người học tập và làm việc trong bộ máy Quốc tế Cộng sản ở Moskva.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những bước ngoặt của một đời người","text":"Trong ba mươi năm bôn ba, có những khoảnh khắc làm thay đổi hẳn hướng đi của cả một dân tộc. Tháng 12 năm 1920, tại Đại hội lần thứ 18 của Đảng Xã hội Pháp họp ở thành phố Tours, Nguyễn Ái Quốc bỏ phiếu tán thành gia nhập Quốc tế Cộng sản, trở thành một trong những người sáng lập Đảng Cộng sản Pháp — cũng là người Việt Nam đầu tiên trở thành đảng viên cộng sản. Mười năm sau, từ ngày 6/1 đến 7/2/1930, tại Cửu Long (Hương Cảng), Người chủ trì hội nghị hợp nhất các tổ chức cộng sản trong nước thành một chính đảng duy nhất: Đảng Cộng sản Việt Nam. Ngày 28 tháng 1 năm 1941, sau gần ba mươi năm xa xứ, Người vượt cột mốc biên giới, đặt chân trở lại Tổ quốc tại Pác Bó, Cao Bằng. Bốn năm sau, ngày 2 tháng 9 năm 1945, giữa rừng người ở Quảng trường Ba Đình, Người đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa.","doc":4},{"loai":"trich","text":"Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta!”","nguoi":"Hồ Chí Minh","nguon_ten":"Bài viết “Con đường dẫn tôi đến chủ nghĩa Lênin”, Báo Nhân Dân số ra ngày 22/4/1960; in lại trong Hồ Chí Minh Toàn tập, tập 12","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_sung_man_cho_victoria_prison_1930.jpg","chu_thich":"Tống Văn Sơ — bí danh của Nguyễn Ái Quốc — tại nhà tù Victoria, Hồng Kông, khoảng 1931 – 1932, hơn một năm sau khi Người chủ trì hội nghị thành lập Đảng Cộng sản Việt Nam.","credit":"Ảnh: Victoria Prison · Public domain · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_coc_bo.jpg","chu_thich":"Hang Cốc Bó, Pác Bó, Cao Bằng — nơi Người sống và làm việc sau khi trở về Tổ quốc ngày 28/1/1941, khép lại gần ba mươi năm bôn ba tìm đường cứu nước.","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những con số ít ai để ý","text":"Đằng sau một hành trình dài là những con số đáng suy ngẫm. Đó là ba mươi năm ròng rã xa quê hương (1911-1941) không một lần được trở về. Đó là vốn ngoại ngữ phong phú — tiếng Pháp, tiếng Anh, tiếng Hoa, tiếng Nga — mà Người tích lũy chủ yếu bằng con đường tự học, qua chính công việc và cuộc sống ở xứ người. Đó cũng là mười bảy gian trưng bày mà bảo tàng này dành cho hành trình ấy, mỗi gian là một nơi chốn có thật Người từng sống hoặc dừng chân — từ làng Sen đến Paris, Moskva, Quảng Châu, Hồng Kông, rồi Pác Bó, Tân Trào, Hà Nội. Con số 79 — tuổi Người khi từ trần năm 1969 — khép lại một cuộc đời mà phần lớn quãng tuổi trẻ, từ hai mươi mốt đến năm mươi mốt tuổi, gắn liền với những chuyến tàu, những căn phòng trọ và những công việc chân tay ở xứ người.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_president_ho_chi_minh_lit_la_proclamation_d_inde.jpg","chu_thich":"Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập tại Quảng trường Ba Đình, Hà Nội, ngày 2/9/1945, khai sinh nước Việt Nam Dân chủ Cộng hòa.","credit":"Ảnh: Front pour l'indépendance du Việt-Nam · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Tại Paris đầu những năm 1920, Nguyễn Ái Quốc là chủ bút của tờ báo Le Paria (Người cùng khổ), số đầu ra năm 1922 — tờ báo do những người thuộc địa Pháp lập nên để lên tiếng cho những người bị áp bức từ khắp các xứ thuộc địa.","nguon_ten":"en.wikipedia.org","doc":7},{"loai":"anh","src":"textures/bai/G00_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện Sảnh Hành trình","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Ngày 25/8/1969, chỉ hơn một tuần trước khi qua đời, Chủ tịch Hồ Chí Minh ký thư trả lời Tổng thống Mỹ Richard Nixon, kiên quyết đòi Mỹ chấm dứt chiến tranh xâm lược và rút quân khỏi miền Nam Việt Nam — bức thư cuối cùng Người gửi một tổng thống Mỹ.","nguon_ten":"en.wikipedia.org","doc":8},{"loai":"anh","src":"textures/bai/G00_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Sảnh Hành trình","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Đi hết 17 gian là đi hết một đời người","text":"Khác với nhiều bảo tàng sắp xếp hiện vật theo chủ đề, không gian này chọn cách kể chuyện theo nơi chốn. Đứng giữa Sảnh Hành trình, khách tham quan nhìn thấy mười bảy vòm cửa mở ra mười bảy gian, xếp theo đúng trình tự thời gian và địa lý cuộc đời Người: quê nhà Nghệ An, rồi Huế, Phan Thiết, Sài Gòn — nơi Người ra đi — sau đó lần lượt là các gian dành riêng cho từng chặng ở nước ngoài, và cuối cùng là Pác Bó, Tân Trào, Hà Nội, Việt Bắc, Phủ Chủ tịch và gian Di sản khép lại hành trình. Đi hết vòng tròn ấy, bắt đầu từ gian làng Sen và ngược chiều kim đồng hồ, là đi hết tuổi thơ, ba mươi năm bôn ba và gần ba mươi năm tiếp theo gắn bó với vận mệnh dân tộc — trọn vẹn một đời người được kể lại bằng chính những nơi người ấy đã sống.","doc":9},{"loai":"moc","items":[["1890","Sinh tại Hoàng Trù, Nam Đàn, Nghệ An"],["1911","Rời Bến Nhà Rồng ra đi tìm đường cứu nước"],["1920","Tham gia sáng lập Đảng Cộng sản Pháp tại Tours"],["1930","Chủ trì hợp nhất, thành lập Đảng Cộng sản Việt Nam"],["1941","Về nước tại Pác Bó, Cao Bằng"],["1945","Đọc Tuyên ngôn Độc lập tại Ba Đình"],["1954","Về Hà Nội sau kháng chiến chống Pháp"],["1969","Từ trần tại Hà Nội, để lại Di chúc"]]}],"doc":[{"i":-1,"t":"Từ Làng Sen Đến Ba Đình: Hành Trình Một Đời Người. Giữa Sảnh Hành trình hình tròn với mười tám mặt vòm, toàn bộ 79 năm cuộc đời Chủ tịch Hồ Chí Minh được kể lại bằng chính những nơi Người đã sống: một cậu bé làng Sen mang nhiều tên gọi khác nhau, ba mươi năm bôn ba qua hàng chục thành phố ở nhiều châu lục, rồi trở về dẫn dắt một dân tộc giành độc lập. Mỗi vòm cửa quanh sảnh là một cánh cửa mở vào một chặng đường có thật."},{"t":"Một cậu bé làng Sen mang nhiều tên gọi. Người đàn ông cả thế giới biết đến với tên gọi Hồ Chí Minh đã đi qua cuộc đời mình với rất nhiều cái tên khác nhau, mỗi tên gắn với một chặng đường. Khi cất tiếng khóc chào đời ngày 19 tháng 5 năm 1890 tại làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An, cậu bé được đặt tên Nguyễn Sinh Cung. Năm 1901, khi cha là ông Nguyễn Sinh Sắc đỗ Phó bảng và cả nhà chuyển về làng Sen, cậu được đổi tên thành Nguyễn Tất Thành theo lệ đặt tên của nhà nho. Ngày 5 tháng 6 năm 1911, chàng thanh niên hai mươi mốt tuổi xuống tàu Amiral Latouche-Tréville rời bến cảng Sài Gòn với một cái tên giản dị: Văn Ba, phụ bếp trên tàu. Từ năm 1919, khi gửi bản Yêu sách của nhân dân An Nam tới Hội nghị Versailles, Người ký tên Nguyễn Ái Quốc — cái tên gắn liền với những năm hoạt động công khai ở Pháp. Trong những năm bí mật hoạt động ở Trung Quốc, Xiêm, Hồng Kông, Người còn mang nhiều bí danh khác như Lý Thụy, Tống Văn Sơ, Thầu Chín... Tháng 8/1942, khi lên đường sang Trung Quốc, Người lấy tên Hồ Chí Minh; ít ngày sau (29/8/1942), Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ ở Quảng Tây. Đó là cái tên trở thành tên gọi chính thức từ sau Cách mạng Tháng Tám 1945, đi vào lịch sử dân tộc."},{"t":"Ba mươi năm qua bốn phương trời. Suốt ba mươi năm, từ 1911 đến 1941, dấu chân Người in trên rất nhiều bến cảng và thành phố: Marseille, Le Havre, Dunkerque của nước Pháp; London, nơi Người từng phụ bếp, cào tuyết, rửa bát trong các khách sạn; Boston và New York bên kia Đại Tây Dương; rồi Paris, nơi Người sống và hoạt động chính trị sôi nổi suốt những năm 1919-1923. Từ Paris, hành trình đưa Người tới Moskva để học tập trong bộ máy Quốc tế Cộng sản, tới Quảng Châu để huấn luyện lớp thanh niên yêu nước đầu tiên, tới Xiêm (Thái Lan ngày nay), Hồng Kông, rồi trở lại Liên Xô một lần nữa trước khi tìm đường về gần biên giới Tổ quốc. Trong ngần ấy năm tháng, Người từng làm rất nhiều nghề để mưu sinh và hoạt động cách mạng: phụ bếp trên tàu viễn dương, thợ làm bánh, thợ ảnh, người viết báo... Chính hành trình lao động và quan sát ấy — chứ không phải sách vở trong giảng đường — đã cho Người vốn hiểu biết sống động về thế giới thuộc địa và những người cùng khổ ở khắp nơi."},{"t":"Bạn có biết? Trong suốt cuộc đời hoạt động cách mạng, Người đã dùng rất nhiều bí danh, bút danh khác nhau tùy từng giai đoạn và vỏ bọc: Văn Ba, Nguyễn Ái Quốc, Lý Thụy, Tống Văn Sơ, Thầu Chín... Theo thống kê của các nhà nghiên cứu, tổng số tên gọi, bí danh và bút danh Người từng sử dụng lên tới hơn một trăm."},{"t":"Những bước ngoặt của một đời người. Trong ba mươi năm bôn ba, có những khoảnh khắc làm thay đổi hẳn hướng đi của cả một dân tộc. Tháng 12 năm 1920, tại Đại hội lần thứ 18 của Đảng Xã hội Pháp họp ở thành phố Tours, Nguyễn Ái Quốc bỏ phiếu tán thành gia nhập Quốc tế Cộng sản, trở thành một trong những người sáng lập Đảng Cộng sản Pháp — cũng là người Việt Nam đầu tiên trở thành đảng viên cộng sản. Mười năm sau, từ ngày 6/1 đến 7/2/1930, tại Cửu Long (Hương Cảng), Người chủ trì hội nghị hợp nhất các tổ chức cộng sản trong nước thành một chính đảng duy nhất: Đảng Cộng sản Việt Nam. Ngày 28 tháng 1 năm 1941, sau gần ba mươi năm xa xứ, Người vượt cột mốc biên giới, đặt chân trở lại Tổ quốc tại Pác Bó, Cao Bằng. Bốn năm sau, ngày 2 tháng 9 năm 1945, giữa rừng người ở Quảng trường Ba Đình, Người đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa."},{"t":"Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta!” — Hồ Chí Minh"},{"t":"Những con số ít ai để ý. Đằng sau một hành trình dài là những con số đáng suy ngẫm. Đó là ba mươi năm ròng rã xa quê hương (1911-1941) không một lần được trở về. Đó là vốn ngoại ngữ phong phú — tiếng Pháp, tiếng Anh, tiếng Hoa, tiếng Nga — mà Người tích lũy chủ yếu bằng con đường tự học, qua chính công việc và cuộc sống ở xứ người. Đó cũng là mười bảy gian trưng bày mà bảo tàng này dành cho hành trình ấy, mỗi gian là một nơi chốn có thật Người từng sống hoặc dừng chân — từ làng Sen đến Paris, Moskva, Quảng Châu, Hồng Kông, rồi Pác Bó, Tân Trào, Hà Nội. Con số 79 — tuổi Người khi từ trần năm 1969 — khép lại một cuộc đời mà phần lớn quãng tuổi trẻ, từ hai mươi mốt đến năm mươi mốt tuổi, gắn liền với những chuyến tàu, những căn phòng trọ và những công việc chân tay ở xứ người."},{"t":"Bạn có biết? Tại Paris đầu những năm 1920, Nguyễn Ái Quốc là chủ bút của tờ báo Le Paria (Người cùng khổ), số đầu ra năm 1922 — tờ báo do những người thuộc địa Pháp lập nên để lên tiếng cho những người bị áp bức từ khắp các xứ thuộc địa."},{"t":"Bạn có biết? Ngày 25/8/1969, chỉ hơn một tuần trước khi qua đời, Chủ tịch Hồ Chí Minh ký thư trả lời Tổng thống Mỹ Richard Nixon, kiên quyết đòi Mỹ chấm dứt chiến tranh xâm lược và rút quân khỏi miền Nam Việt Nam — bức thư cuối cùng Người gửi một tổng thống Mỹ."},{"t":"Đi hết 17 gian là đi hết một đời người. Khác với nhiều bảo tàng sắp xếp hiện vật theo chủ đề, không gian này chọn cách kể chuyện theo nơi chốn. Đứng giữa Sảnh Hành trình, khách tham quan nhìn thấy mười bảy vòm cửa mở ra mười bảy gian, xếp theo đúng trình tự thời gian và địa lý cuộc đời Người: quê nhà Nghệ An, rồi Huế, Phan Thiết, Sài Gòn — nơi Người ra đi — sau đó lần lượt là các gian dành riêng cho từng chặng ở nước ngoài, và cuối cùng là Pác Bó, Tân Trào, Hà Nội, Việt Bắc, Phủ Chủ tịch và gian Di sản khép lại hành trình. Đi hết vòng tròn ấy, bắt đầu từ gian làng Sen và ngược chiều kim đồng hồ, là đi hết tuổi thơ, ba mươi năm bôn ba và gần ba mươi năm tiếp theo gắn bó với vận mệnh dân tộc — trọn vẹn một đời người được kể lại bằng chính những nơi người ấy đã sống."}],"hien_vat":[{"ten":"Bản đồ hành trình khảm sàn","mo_ta":"Giữa nền đá cẩm thạch của sảnh là một bản đồ lớn khảm theo phép chiếu phương vị lấy Hà Nội làm tâm, thể hiện toàn bộ lộ trình ba mươi năm bôn ba (1911-1941) của Người qua các thành phố như Marseille, Paris, Moskva, Quảng Châu, Hồng Kông. Đây là cách bảo tàng tóm lược trực quan cả một hành trình dài trước khi khách bước vào từng gian riêng.","nguon":"https://hochiminh.vn/ho-chi-minh-va-the-gioi/ban-be-quoc-te-voi-ho-chi-minh/hanh-trinh-tim-duong-cuu-nuoc-cua-chu-tich-ho-chi-minh-qua-goc-nhin-quoc-te.html"},{"ten":"Tường danh dự","mo_ta":"Mặt thứ 18 của sảnh, đối diện hướng nam, là bức tường duy nhất không dẫn vào một gian trưng bày nào mà treo chân dung Chủ tịch Hồ Chí Minh năm 1946 cùng câu nói nổi tiếng: “Tôi chỉ có một sự ham muốn, ham muốn tột bậc, là làm sao cho nước ta được hoàn toàn độc lập, dân ta được hoàn toàn tự do, đồng bào ai cũng có cơm ăn áo mặc, ai cũng được học hành.”","nguon":"Hồ Chí Minh, trả lời các nhà báo, 21/1/1946"},{"ten":"Mười bảy vòm cửa vào các gian","mo_ta":"Mười bảy vòm cửa vòng quanh sảnh, mỗi vòm dẫn vào một gian trưng bày ứng với một nơi chốn có thật trong cuộc đời Người, được sắp theo đúng trình tự thời gian: từ quê nhà Nghệ An, qua Huế, các chặng nước ngoài, đến Pác Bó, Hà Nội và gian Di sản khép lại vòng tròn."},{"ten":"Mái vòm ô trám và giếng trời","mo_ta":"Phần mái của Sảnh Hành trình được dựng theo dạng vòm ô trám, giữa có giếng trời lấy ánh sáng tự nhiên; quanh chân mái là một hàng cửa sổ vòm giúp cả không gian tròn 40 mét luôn ngập nắng, gợi hình ảnh một mái nhà chung của cả hành trình 79 năm."},{"ten":"Hàng cửa sổ vòm quanh sảnh","mo_ta":"Bao quanh phần trên của sảnh tròn là một hàng cửa sổ hình vòm, vừa lấy ánh sáng cho không gian trưng bày, vừa tạo nhịp kiến trúc hô ứng với mười tám vòm cửa lớn bên dưới."}],"hoi_dap":[{"hoi":"Chủ tịch Hồ Chí Minh sinh ngày, tháng, năm nào?","dap":"Ngày 19 tháng 5 năm 1890, tại làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An.","sai":["19/5/1889","3/2/1890","2/9/1890"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Người rời Bến Nhà Rồng ra đi tìm đường cứu nước vào ngày nào, với tên gọi gì?","dap":"Ngày 5/6/1911, trên tàu Amiral Latouche-Tréville, với tên gọi Văn Ba, làm phụ bếp.","sai":["2/9/1911, với tên Nguyễn Ái Quốc","19/5/1911, với tên Nguyễn Tất Thành","3/2/1911, với tên Hồ Chí Minh"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Tên gọi “Nguyễn Ái Quốc” gắn liền với sự kiện nào vào năm 1919?","dap":"Gửi bản Yêu sách của nhân dân An Nam tới Hội nghị Versailles.","sai":["Thành lập Đảng Cộng sản Việt Nam","Đọc Tuyên ngôn Độc lập","Dự Đại hội Tours của Đảng Xã hội Pháp"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Nguyễn Ái Quốc tham gia sáng lập Đảng Cộng sản Pháp tại sự kiện nào?","dap":"Đại hội lần thứ 18 của Đảng Xã hội Pháp, họp tại Tours, tháng 12/1920.","sai":["Đại hội Quốc tế Cộng sản lần thứ V ở Moskva","Hội nghị hợp nhất ở Hương Cảng","Hội nghị Versailles"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Đảng Cộng sản Việt Nam được thành lập ở đâu, khi nào?","dap":"Tại Cửu Long (Hương Cảng), qua hội nghị hợp nhất các tổ chức cộng sản trong nước họp từ ngày 6/1 đến 7/2/1930; ngày 3/2 được lấy làm ngày kỷ niệm thành lập Đảng.","sai":["Tại Tours, Pháp, năm 1920","Tại Quảng Châu, Trung Quốc, năm 1925","Tại Pác Bó, năm 1941"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Người trở về nước sau gần bao nhiêu năm bôn ba, vào ngày nào?","dap":"Sau gần 30 năm, ngày 28/1/1941, đặt chân về Pác Bó, Cao Bằng.","sai":["20 năm, ngày 2/9/1941","35 năm, ngày 19/5/1941","25 năm, ngày 3/2/1941"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Tên gọi “Hồ Chí Minh” bắt đầu được Người sử dụng trong hoàn cảnh nào?","dap":"Tháng 8/1942, khi Người lên đường sang Trung Quốc (ít ngày sau, ngày 29/8/1942, Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ ở Quảng Tây); tên gọi này trở thành tên chính thức, công khai từ sau Cách mạng Tháng Tám 1945.","sai":["Ngay khi sinh ra ở Hoàng Trù năm 1890","Khi dự Đại hội Tours năm 1920","Khi thành lập Đảng năm 1930"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Bản Tuyên ngôn Độc lập được Người đọc ở đâu, vào ngày nào?","dap":"Tại Quảng trường Ba Đình, Hà Nội, ngày 2/9/1945.","sai":["Tại Pác Bó, ngày 28/1/1941","Tại Tân Trào, ngày 16/8/1945","Tại Huế, ngày 30/8/1945"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Mười bảy gian trưng bày quanh Sảnh Hành trình được sắp xếp theo nguyên tắc nào?","dap":"Theo nơi chốn và trình tự thời gian cuộc đời Người — mỗi gian là một nơi Người đã thực sự sống hoặc dừng chân.","sai":["Theo các chủ đề tư tưởng","Theo tên các quốc gia xếp theo bảng chữ cái","Ngẫu nhiên, không theo trình tự"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Quê nội (làng Sen) và quê ngoại (Hoàng Trù) của Người đều thuộc xã, huyện, tỉnh nào?","dap":"Xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An.","sai":["Xã Kim Liên, huyện Hưng Nguyên, Nghệ An","Xã Sen Thủy, huyện Nam Đàn, Hà Tĩnh","Xã Kim Liên, huyện Nam Đàn, Thanh Hóa"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Chủ tịch Hồ Chí Minh từ trần ngày nào, hưởng thọ bao nhiêu tuổi, để lại di sản tinh thần nào?","dap":"Ngày 2/9/1969 tại Hà Nội, hưởng thọ 79 tuổi, để lại bản Di chúc.","sai":["Ngày 19/5/1969, hưởng thọ 79 tuổi","Ngày 2/9/1970, hưởng thọ 80 tuổi","Ngày 3/2/1969, hưởng thọ 78 tuổi"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"}],"nguon":[{"ten":"Ho Chi Minh – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Tiểu sử Chủ tịch Hồ Chí Minh (1890-1969) – Cổng TTĐT về Chủ tịch Hồ Chí Minh","url":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"ten":"Hành trình tìm đường cứu nước của Chủ tịch Hồ Chí Minh qua góc nhìn quốc tế – hochiminh.vn","url":"https://hochiminh.vn/ho-chi-minh-va-the-gioi/ban-be-quoc-te-voi-ho-chi-minh/hanh-trinh-tim-duong-cuu-nuoc-cua-chu-tich-ho-chi-minh-qua-goc-nhin-quoc-te.html"},{"ten":"Biên niên tiểu sử Hồ Chí Minh – hochiminh.vn","url":"https://hochiminh.vn/cuoc-doi-su-nghiep/bien-nien-tieu-su-ho-chi-minh"}],"so_chu":1286},"G01":{"ma":"G01","tieu_de":"Làng Sen, Hoàng Trù – Tuổi Thơ Bên Tiếng Ru Của Mẹ","sapo":"Trước khi trở thành Nguyễn Ái Quốc rồi Hồ Chí Minh, cậu bé Nguyễn Sinh Cung đã có những năm tháng tuổi thơ gắn với hai làng nhỏ ở Nam Đàn, Nghệ An: Hoàng Trù, quê ngoại nơi cậu chào đời và lớn lên trong tiếng thoi dệt vải của mẹ, và làng Sen, quê nội nơi cậu sống những năm thiếu niên bên những trang chữ Hán của cha. Gian trưng bày này dựng lại chính ngôi nhà tranh, khu vườn và con đường làng đã nuôi dưỡng những năm tháng ấy.","sapo_en":"Before he became Nguyễn Ái Quốc and later Hồ Chí Minh, young Nguyễn Sinh Cung spent much of his childhood between two small villages in Nam Đàn, Nghệ An — Hoàng Trù, his birthplace, and Sen village, where he grew up.","bia":{"src":"textures/ht/ht_anh_cong_chao_lang_hoang_tru_va_mau_tai_nam_dan_nghe.jpg","credit":"Ảnh: Linhcandng (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Tiếng khóc chào đời ở Hoàng Trù","text":"Ngày 19 tháng 5 năm 1890, tại ngôi nhà nhỏ ba gian của ông bà ngoại ở làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An — một vùng đất trung du ven chân núi Chung, nổi tiếng hiếu học nhưng cũng lắm gian khó — một cậu bé cất tiếng khóc chào đời và được đặt tên Nguyễn Sinh Cung. Cha cậu, ông Nguyễn Sinh Sắc, mồ côi cha mẹ từ nhỏ, được nhà nho Hoàng Xuân Đường ở làng Hoàng Trù bên cạnh đón về nuôi dạy, cho ăn học chữ thánh hiền. Lớn lên, ông Sắc trở thành con rể của chính người thầy đã cưu mang mình, khi cưới bà Hoàng Thị Loan — con gái cụ Hoàng Xuân Đường — làm vợ. Năm 1894, ông Sắc đỗ Cử nhân; con đường học hành của một nhà nho nghèo bắt đầu hé mở, nhưng gia cảnh vẫn thanh bạch, mọi việc đồng áng, cửi vải trong nhà đều trông cậy vào một tay người vợ trẻ.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_records_of_the_government_of_french_indochina_on.jpg","chu_thich":"Hồ sơ của chính quyền Đông Dương về cụ Phó bảng Nguyễn Sinh Sắc, thân sinh của Người.","credit":"Ảnh: French protectorate of Annam · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Ông Nguyễn Sinh Sắc mồ côi cha mẹ từ nhỏ và được chính người thầy dạy chữ của mình — cụ Hoàng Xuân Đường ở Hoàng Trù — đón về nuôi dạy, rồi sau này gả con gái là bà Hoàng Thị Loan cho làm vợ. Nói cách khác, người thầy đầu tiên của cha Nguyễn Sinh Cung cũng chính là ông ngoại của Người.","nguon_ten":"en.wikipedia.org","doc":2},{"loai":"doan","tieu_de":"Người mẹ dệt vải nuôi chồng ăn học","text":"Bà Hoàng Thị Loan sinh năm 1868, cũng tại làng Hoàng Trù. Là con gái một nhà nho, bà không chỉ thạo việc đồng áng mà còn giỏi nghề dệt vải — công việc giúp bà nuôi chồng dùi mài kinh sử và nuôi các con khôn lớn. Ông bà sinh được bốn người con: con gái đầu Nguyễn Thị Thanh, con trai thứ hai Nguyễn Sinh Khiêm, người con thứ ba là Nguyễn Sinh Cung, và người con út Nguyễn Sinh Nhuận mất sớm khi còn nhỏ. Trong ký ức của những người từng nghe kể lại, tiếng thoi đưa bên khung cửi là âm thanh quen thuộc của tuổi thơ Nguyễn Sinh Cung ở Hoàng Trù, nơi cậu sống những năm đầu đời.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_hoa_sen.jpg","chu_thich":"Hoa sen — loài hoa cho làng Sen cái tên dân dã của nó, cũng là nghĩa của cái tên chữ Kim Liên (nghĩa là “sen vàng”) mà xã này mang từ xưa.","credit":"Ảnh: Teyvatism · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Cái tên “làng Sen” và tên chữ Hán “Kim Liên” của xã thực ra là một: Kim (vàng) Liên (sen) — “sen vàng” — bắt nguồn từ những ao sen rải rác quanh làng, trong đó nhiều ao vẫn còn đến ngày nay trong Khu di tích Kim Liên.","nguon_ten":"","doc":4},{"loai":"doan","tieu_de":"Trở về làng Sen, mang tên mới","text":"Năm 1901 là một năm đầy biến động với gia đình nhỏ ấy. Tại kỳ thi Hội khoa Tân Sửu, ông Nguyễn Sinh Sắc đỗ Phó bảng — học vị cao quý mà cả vùng Nam Đàn tự hào. Nhưng cũng trong năm ấy, bà Hoàng Thị Loan qua đời tại Huế, khi ông Sắc đang đi làm việc ở trường thi Thanh Hóa, để lại các con thơ. Sau khi đỗ đạt, theo tục “vinh quy bái tổ”, ông Sắc đưa các con trở về quê nội — làng Sen. Dân làng góp công, góp của dựng tặng gia đình tân khoa một ngôi nhà tranh năm gian khang trang, có nhà ngang ba gian kề bên làm bếp và nơi đặt cối xay, cối giã gạo, khung cửi. Cũng từ đây, cậu bé Nguyễn Sinh Cung được cha đặt tên mới: Nguyễn Tất Thành, mang theo kỳ vọng về một sự nghiệp trọn vẹn.","doc":5},{"loai":"anh","src":"textures/bai/G01_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Làng Sen – Kim Liên","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Học chữ thánh hiền, nghe chuyện anh hùng","text":"Từ năm 1901 đến 1906, cậu bé Tất Thành ở hẳn tại làng Sen, ngày ngày học chữ Hán với cha và các thầy đồ trong vùng. Ông Sắc vốn là nhà nho có tư tưởng cởi mở, thường bàn luận thời cuộc với bạn bè, không giấu con cái những chuyện quốc sự đang khiến sĩ phu cả nước trăn trở. Nam Đàn khi ấy là vùng đất giàu truyền thống khoa bảng và cũng lắm người yêu nước: ngay trong huyện, không xa làng Sen, là quê hương của chí sĩ Phan Bội Châu — người từng có giao tình với ông Nguyễn Sinh Sắc và là một trong những gương mặt lãnh đạo phong trào yêu nước đầu thế kỷ XX. Cậu học trò nhỏ còn được nghe kể về cuộc khởi nghĩa của cụ Phan Đình Phùng ở vùng Nghệ Tĩnh những năm trước đó. Những câu chuyện ấy, kể bên ánh đèn dầu trong ngôi nhà tranh nhỏ, âm thầm gieo vào lòng cậu bé những hạt giống đầu tiên của một tinh thần yêu nước sẽ theo suốt cuộc đời.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_khu_mo_ba_hoang_thi_loan.jpg","chu_thich":"Khu mộ bà Hoàng Thị Loan, thân mẫu của Người, trên núi Động Tranh, Nam Đàn.","credit":"Ảnh: David Brewer · CC BY-SA 2.0 · Wikimedia Commons"},{"loai":"anh","src":"textures/bai/G01_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Làng Sen – Kim Liên","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Từ mái nhà tranh đến Khu di tích Kim Liên","text":"Năm 1906, Nguyễn Tất Thành rời làng Sen theo cha vào Huế lần thứ hai, khép lại quãng tuổi thơ gắn với đồng lúa, ao sen quê nhà. Ngôi nhà tranh năm gian năm xưa, cùng ngôi nhà ở Hoàng Trù bên kia cánh đồng, ngày nay được phục dựng và gìn giữ trong Khu di tích Kim Liên, đón rất đông người về thăm mỗi năm. Hằng năm, cứ đến dịp 19 tháng 5, đông đảo người dân cả nước lại tìm về đây, thắp nén hương thơm trước ngôi nhà tranh giản dị đã sinh ra một con người làm thay đổi vận mệnh dân tộc. Đi giữa vườn cau, hàng rào chè tàu và ao sen vẫn xanh mát ấy, người ta như còn nghe thấy bước chân của một cậu bé nhà nghèo mà sau này đã đi khắp năm châu bốn biển, nhưng chưa từng quên nơi mình cất tiếng khóc chào đời.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_kim_lien_monuments_park.jpg","chu_thich":"Khu Di tích Kim Liên ngày nay — nơi lưu giữ ngôi nhà tranh làng Sen, ngôi nhà Hoàng Trù và khung cảnh làng quê Nam Đàn của tuổi thơ Người.","credit":"Ảnh: Liftold at Vietnamese Wikipedia · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"moc","items":[["1868","Bà Hoàng Thị Loan (thân mẫu) sinh tại Hoàng Trù"],["19/5/1890","Sinh tại làng Hoàng Trù, tên khai sinh Nguyễn Sinh Cung"],["1895","Theo cha mẹ vào Huế"],["1901","Cha đỗ Phó bảng; mẹ qua đời tại Huế; cả nhà về làng Sen, mang tên Nguyễn Tất Thành"],["1901 – 1906","Học chữ Hán ở quê, nghe chuyện các sĩ phu yêu nước"]]}],"doc":[{"i":-1,"t":"Làng Sen, Hoàng Trù – Tuổi Thơ Bên Tiếng Ru Của Mẹ. Trước khi trở thành Nguyễn Ái Quốc rồi Hồ Chí Minh, cậu bé Nguyễn Sinh Cung đã có những năm tháng tuổi thơ gắn với hai làng nhỏ ở Nam Đàn, Nghệ An: Hoàng Trù, quê ngoại nơi cậu chào đời và lớn lên trong tiếng thoi dệt vải của mẹ, và làng Sen, quê nội nơi cậu sống những năm thiếu niên bên những trang chữ Hán của cha. Gian trưng bày này dựng lại chính ngôi nhà tranh, khu vườn và con đường làng đã nuôi dưỡng những năm tháng ấy."},{"t":"Tiếng khóc chào đời ở Hoàng Trù. Ngày 19 tháng 5 năm 1890, tại ngôi nhà nhỏ ba gian của ông bà ngoại ở làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An — một vùng đất trung du ven chân núi Chung, nổi tiếng hiếu học nhưng cũng lắm gian khó — một cậu bé cất tiếng khóc chào đời và được đặt tên Nguyễn Sinh Cung. Cha cậu, ông Nguyễn Sinh Sắc, mồ côi cha mẹ từ nhỏ, được nhà nho Hoàng Xuân Đường ở làng Hoàng Trù bên cạnh đón về nuôi dạy, cho ăn học chữ thánh hiền. Lớn lên, ông Sắc trở thành con rể của chính người thầy đã cưu mang mình, khi cưới bà Hoàng Thị Loan — con gái cụ Hoàng Xuân Đường — làm vợ. Năm 1894, ông Sắc đỗ Cử nhân; con đường học hành của một nhà nho nghèo bắt đầu hé mở, nhưng gia cảnh vẫn thanh bạch, mọi việc đồng áng, cửi vải trong nhà đều trông cậy vào một tay người vợ trẻ."},{"t":"Bạn có biết? Ông Nguyễn Sinh Sắc mồ côi cha mẹ từ nhỏ và được chính người thầy dạy chữ của mình — cụ Hoàng Xuân Đường ở Hoàng Trù — đón về nuôi dạy, rồi sau này gả con gái là bà Hoàng Thị Loan cho làm vợ. Nói cách khác, người thầy đầu tiên của cha Nguyễn Sinh Cung cũng chính là ông ngoại của Người."},{"t":"Người mẹ dệt vải nuôi chồng ăn học. Bà Hoàng Thị Loan sinh năm 1868, cũng tại làng Hoàng Trù. Là con gái một nhà nho, bà không chỉ thạo việc đồng áng mà còn giỏi nghề dệt vải — công việc giúp bà nuôi chồng dùi mài kinh sử và nuôi các con khôn lớn. Ông bà sinh được bốn người con: con gái đầu Nguyễn Thị Thanh, con trai thứ hai Nguyễn Sinh Khiêm, người con thứ ba là Nguyễn Sinh Cung, và người con út Nguyễn Sinh Nhuận mất sớm khi còn nhỏ. Trong ký ức của những người từng nghe kể lại, tiếng thoi đưa bên khung cửi là âm thanh quen thuộc của tuổi thơ Nguyễn Sinh Cung ở Hoàng Trù, nơi cậu sống những năm đầu đời."},{"t":"Bạn có biết? Cái tên “làng Sen” và tên chữ Hán “Kim Liên” của xã thực ra là một: Kim (vàng) Liên (sen) — “sen vàng” — bắt nguồn từ những ao sen rải rác quanh làng, trong đó nhiều ao vẫn còn đến ngày nay trong Khu di tích Kim Liên."},{"t":"Trở về làng Sen, mang tên mới. Năm 1901 là một năm đầy biến động với gia đình nhỏ ấy. Tại kỳ thi Hội khoa Tân Sửu, ông Nguyễn Sinh Sắc đỗ Phó bảng — học vị cao quý mà cả vùng Nam Đàn tự hào. Nhưng cũng trong năm ấy, bà Hoàng Thị Loan qua đời tại Huế, khi ông Sắc đang đi làm việc ở trường thi Thanh Hóa, để lại các con thơ. Sau khi đỗ đạt, theo tục “vinh quy bái tổ”, ông Sắc đưa các con trở về quê nội — làng Sen. Dân làng góp công, góp của dựng tặng gia đình tân khoa một ngôi nhà tranh năm gian khang trang, có nhà ngang ba gian kề bên làm bếp và nơi đặt cối xay, cối giã gạo, khung cửi. Cũng từ đây, cậu bé Nguyễn Sinh Cung được cha đặt tên mới: Nguyễn Tất Thành, mang theo kỳ vọng về một sự nghiệp trọn vẹn."},{"t":"Học chữ thánh hiền, nghe chuyện anh hùng. Từ năm 1901 đến 1906, cậu bé Tất Thành ở hẳn tại làng Sen, ngày ngày học chữ Hán với cha và các thầy đồ trong vùng. Ông Sắc vốn là nhà nho có tư tưởng cởi mở, thường bàn luận thời cuộc với bạn bè, không giấu con cái những chuyện quốc sự đang khiến sĩ phu cả nước trăn trở. Nam Đàn khi ấy là vùng đất giàu truyền thống khoa bảng và cũng lắm người yêu nước: ngay trong huyện, không xa làng Sen, là quê hương của chí sĩ Phan Bội Châu — người từng có giao tình với ông Nguyễn Sinh Sắc và là một trong những gương mặt lãnh đạo phong trào yêu nước đầu thế kỷ XX. Cậu học trò nhỏ còn được nghe kể về cuộc khởi nghĩa của cụ Phan Đình Phùng ở vùng Nghệ Tĩnh những năm trước đó. Những câu chuyện ấy, kể bên ánh đèn dầu trong ngôi nhà tranh nhỏ, âm thầm gieo vào lòng cậu bé những hạt giống đầu tiên của một tinh thần yêu nước sẽ theo suốt cuộc đời."},{"t":"Từ mái nhà tranh đến Khu di tích Kim Liên. Năm 1906, Nguyễn Tất Thành rời làng Sen theo cha vào Huế lần thứ hai, khép lại quãng tuổi thơ gắn với đồng lúa, ao sen quê nhà. Ngôi nhà tranh năm gian năm xưa, cùng ngôi nhà ở Hoàng Trù bên kia cánh đồng, ngày nay được phục dựng và gìn giữ trong Khu di tích Kim Liên, đón rất đông người về thăm mỗi năm. Hằng năm, cứ đến dịp 19 tháng 5, đông đảo người dân cả nước lại tìm về đây, thắp nén hương thơm trước ngôi nhà tranh giản dị đã sinh ra một con người làm thay đổi vận mệnh dân tộc. Đi giữa vườn cau, hàng rào chè tàu và ao sen vẫn xanh mát ấy, người ta như còn nghe thấy bước chân của một cậu bé nhà nghèo mà sau này đã đi khắp năm châu bốn biển, nhưng chưa từng quên nơi mình cất tiếng khóc chào đời."}],"hien_vat":[{"ten":"Nhà tranh năm gian ở làng Sen","mo_ta":"Ngôi nhà chính do dân làng góp công, góp của dựng năm 1901 để mừng ông Nguyễn Sinh Sắc đỗ Phó bảng. Nhà lợp tranh, vách đất, gồm năm gian đơn sơ, bên trong có bộ phản gỗ, bàn thờ và tủ sách chữ Hán của ông Sắc — nơi cả gia đình sinh sống từ năm 1901 đến 1906.","nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"ten":"Khung cửi trong nhà ngang","mo_ta":"Đặt trong gian nhà ngang ba gian sát nhà chính, chiếc khung cửi gợi nhớ nghề dệt vải mà bà Hoàng Thị Loan từng dùng để nuôi chồng ăn học và nuôi các con — dù bà đã mất năm 1901, trước khi gia đình về sống trong ngôi nhà này."},{"ten":"Cối xay, cối giã gạo","mo_ta":"Đặt cùng khu nhà ngang, cối xay và cối giã gạo là những vật dụng lao động hằng ngày, cho thấy nếp sống tự cấp tự túc bình dị của một gia đình nhà nho nghèo vùng Nam Đàn đầu thế kỷ XX."},{"ten":"Ao sen làng Sen","mo_ta":"Những ao sen rải rác quanh làng là nguồn gốc của cái tên dân dã “làng Sen”, cũng chính là nghĩa của tên chữ Kim Liên (sen vàng) mà xã này mang. Mùa hè, sen nở khắp các ao quanh khu di tích."},{"ten":"Ngôi nhà ở Hoàng Trù, quê ngoại","mo_ta":"Cách làng Sen một cánh đồng, ngôi nhà ba gian tại Hoàng Trù là nơi ông bà ngoại Hoàng Xuân Đường sinh sống và cũng là nơi Nguyễn Sinh Cung cất tiếng khóc chào đời ngày 19/5/1890.","nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"}],"hoi_dap":[{"hoi":"Nguyễn Sinh Cung sinh ngày, tháng, năm nào, ở đâu?","dap":"Ngày 19/5/1890, tại làng Hoàng Trù, xã Kim Liên, huyện Nam Đàn, tỉnh Nghệ An.","sai":["19/5/1890, tại làng Sen","19/5/1901, tại Huế","5/6/1890, tại Vinh"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Tên khai sinh của Người là gì?","dap":"Nguyễn Sinh Cung.","sai":["Nguyễn Tất Thành","Nguyễn Ái Quốc","Nguyễn Sinh Sắc"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Cha của Người tên gì, đỗ đạt gì và vào năm nào?","dap":"Nguyễn Sinh Sắc, đỗ Phó bảng năm 1901.","sai":["Đỗ Trạng nguyên năm 1890","Đỗ Cử nhân năm 1901","Đỗ Tiến sĩ năm 1895"],"nguon":"https://en.wikipedia.org/wiki/Nguy%E1%BB%85n_Sinh_S%E1%BA%AFc"},{"hoi":"Mẹ của Người tên gì, làm nghề gì để phụ giúp gia đình?","dap":"Hoàng Thị Loan, làm ruộng và dệt vải.","sai":["Buôn bán vải ở chợ","Dạy học chữ Nho","Làm nghề thuốc bắc"],"nguon":"https://en.wikipedia.org/wiki/Ho%C3%A0ng_Th%E1%BB%8B_Loan"},{"hoi":"Năm 1901, sau khi cha đỗ Phó bảng, cả nhà chuyển về đâu và cậu bé được đổi tên gì?","dap":"Về làng Sen; đổi tên thành Nguyễn Tất Thành.","sai":["Về Huế; đổi tên thành Nguyễn Ái Quốc","Về Hoàng Trù; giữ nguyên tên cũ","Về Vinh; đổi tên thành Nguyễn Văn Ba"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Ngôi nhà tranh năm gian ở làng Sen được dựng lên trong hoàn cảnh nào?","dap":"Năm 1901, do dân làng góp công, góp của dựng tặng gia đình ông Nguyễn Sinh Sắc nhân dịp ông đỗ Phó bảng.","sai":["Do triều đình Huế cấp cho quan Phó bảng","Gia đình tự bỏ tiền xây từ năm 1890","Do chính quyền Pháp xây tặng"]},{"hoi":"Chí sĩ yêu nước nào cùng quê Nam Đàn và có giao tình với ông Nguyễn Sinh Sắc?","dap":"Phan Bội Châu.","sai":["Phan Chu Trinh","Phan Đình Phùng","Hoàng Hoa Thám"],"nguon":"https://en.wikipedia.org/wiki/Phan_B%E1%BB%99i_Ch%C3%A2u"},{"hoi":"Vì sao xã Kim Liên còn được gọi là “làng Sen”?","dap":"Vì Kim Liên trong chữ Hán nghĩa là “sen vàng”, gắn với những ao sen quanh làng.","sai":["Vì cả làng chỉ trồng một loại hoa sen để bán","Vì đây là tên một loài chim quý của vùng","Không liên quan đến hoa sen, chỉ là tên gọi ngẫu nhiên"]},{"hoi":"Bà Hoàng Thị Loan mất năm nào, ở đâu?","dap":"Năm 1901, tại Huế.","sai":["Năm 1929, tại Cao Lãnh","Năm 1890, tại Nam Đàn","Năm 1911, tại Sài Gòn"],"nguon":"https://en.wikipedia.org/wiki/Ho%C3%A0ng_Th%E1%BB%8B_Loan"},{"hoi":"Ngày nay mộ bà Hoàng Thị Loan được an táng ở đâu?","dap":"Trên núi Động Tranh, Nam Đàn, Nghệ An.","sai":["Trên núi Ba Vì, Hà Nội","Tại Nghĩa trang Mai Dịch, Hà Nội","Trên núi Ngự Bình, Huế"],"nguon":"https://en.wikipedia.org/wiki/Ho%C3%A0ng_Th%E1%BB%8B_Loan"},{"hoi":"Ai đã nuôi dạy ông Nguyễn Sinh Sắc từ nhỏ và sau này trở thành cha vợ của ông?","dap":"Cụ Hoàng Xuân Đường, nhà nho ở Hoàng Trù, thầy dạy chữ của ông Sắc.","sai":["Cụ Phan Bội Châu","Cụ Phan Đình Phùng","Một vị quan triều đình ở Huế"],"nguon":"https://en.wikipedia.org/wiki/Ho%C3%A0ng_Th%E1%BB%8B_Loan"}],"nguon":[{"ten":"Ho Chi Minh – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Nguyễn Sinh Sắc – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Nguy%E1%BB%85n_Sinh_S%E1%BA%AFc"},{"ten":"Hoàng Thị Loan – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho%C3%A0ng_Th%E1%BB%8B_Loan"},{"ten":"Phan Bội Châu – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Phan_B%E1%BB%99i_Ch%C3%A2u"},{"ten":"Tiểu sử Chủ tịch Hồ Chí Minh (1890-1969) – Cổng TTĐT về Chủ tịch Hồ Chí Minh","url":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"}],"so_chu":1005},"G02":{"ma":"G02","tieu_de":"Huế: Nơi Cậu Học Trò Lần Đầu Nhìn Thấy Bộ Mặt Thực Dân","sapo":"Hai lần theo cha vào kinh đô Huế — lần đầu năm 1895 khi mới lên năm, lần sau năm 1906 khi đã là thiếu niên — Nguyễn Tất Thành vừa nếm trải nỗi đau mất mẹ giữa đất khách, vừa được ngồi trong những lớp học của Trường Quốc Học bên bờ sông Hương. Cũng chính tại đây, năm 1908, cậu học trò lần đầu chứng kiến cảnh nông dân bị áp bức đứng lên phản kháng, và bắt đầu đặt câu hỏi về vận mệnh dân tộc.","sapo_en":"Twice brought to the imperial capital of Huế as a child, Nguyễn Tất Thành lost his mother there in 1901 and later studied at the famous Quốc Học school by the Perfume River, where the 1908 anti-tax protests first drew him toward revolutionary politics.","bia":{"src":"textures/ht/ht_anh_quoc_hoc_hue.jpg","credit":"Ảnh: Lưu Ly · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Từ làng Sen tới đất kinh kỳ","text":"Năm 1895, khi mới lên năm tuổi, cậu bé Nguyễn Sinh Cung lần đầu theo cha mẹ rời quê Nam Đàn vào kinh đô Huế. Ông Nguyễn Sinh Sắc khi ấy ra Huế để tiếp tục việc học, chuẩn bị cho các kỳ thi Hội, thi Đình sau khi đã đỗ Cử nhân ở quê nhà. Gia đình nhỏ thuê một căn nhà đơn sơ trong khu vực Thành Nội, phía trong vòng thành của kinh đô triều Nguyễn — nơi những gia đình quan lại nhỏ, sĩ tử nghèo từ các tỉnh về trọ học vẫn thường sống chen chúc. Cuộc sống thị thành xa lạ, thiếu thốn hơn nhiều so với làng quê, nhưng cũng là nơi cậu bé lần đầu nhìn thấy sự phồn hoa của một kinh đô, đồng thời chứng kiến khoảng cách giàu nghèo giữa quan lại triều đình, người Pháp cai trị và dân thường. Sông Hương uốn quanh chân thành, những mái ngói cung điện lấp lánh trong nắng, nhưng ngay bên ngoài cổng thành là những xóm nghèo lam lũ — hai hình ảnh trái ngược mà cậu bé làng Sen chưa từng thấy ở quê nhà.","doc":1},{"loai":"anh","src":"textures/bai/G02_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Huế – Kinh thành và trường Quốc Học","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Khu vực Thành Nội, nơi gia đình Nguyễn Sinh Sắc từng thuê nhà trọ học, nằm ngay bên trong vòng tường thành của Kinh thành Huế — khu thành lũy được vua Gia Long cho khởi công và các đời vua sau tiếp tục xây dựng, hoàn thiện trong suốt nhiều thập kỷ đầu thế kỷ XIX.","nguon_ten":"en.wikipedia.org","doc":2},{"loai":"doan","tieu_de":"Mất mẹ giữa kinh thành","text":"Cuối năm 1900, ông Nguyễn Sinh Sắc được cử đi làm việc ở trường thi Hương Thanh Hóa, mang theo người con trai lớn là Nguyễn Sinh Khiêm; Nguyễn Sinh Cung ở lại Huế với mẹ. Sau khi sinh người con út, bà Hoàng Thị Loan lâm bệnh và qua đời ngày 10/2/1901 tại căn nhà nhỏ giữa kinh thành. Nguyễn Sinh Cung khi ấy mới mười một tuổi, có những ngày phải bồng em nhỏ đi khắp xóm xin sữa của những người hàng xóm tốt bụng. Cái chết của mẹ giữa nơi đất khách, trong lúc cha và anh vắng nhà, là một trong những biến cố đau buồn nhất tuổi thơ Người — một ký ức mà về sau, những người viết tiểu sử vẫn nhắc lại như một trong những dấu mốc hun đúc nghị lực sống của cậu bé mồ côi mẹ giữa kinh thành.","doc":3},{"loai":"ban_co_biet","text":"Người em út trong gia đình, Nguyễn Sinh Nhuận, chào đời ngay tại Huế trong những năm gia đình sống ở Thành Nội, nhưng cũng mất sớm khi còn thơ ấu — khiến biến cố năm 1901 trở thành một trong những giai đoạn mất mát liên tiếp nặng nề nhất của gia đình nhỏ này.","nguon_ten":"en.wikipedia.org","doc":4},{"loai":"doan","tieu_de":"Trở lại Huế, vào Trường Quốc Học","text":"Sau nhiều năm ở làng Sen, năm 1906 ông Nguyễn Sinh Sắc được triều đình bổ vào làm việc tại Bộ Lễ ở Huế; ông đưa hai con trai theo cùng. Nguyễn Tất Thành khi đó theo học tại Trường Tiểu học Pháp - Việt Đông Ba, ngôi trường mang tên khu vực Đông Ba nổi tiếng của kinh thành. Khoảng năm 1907 – 1908, cậu học trò vào học Trường Quốc Học Huế — trường trung học Pháp - Việt lớn, được triều đình và chính quyền bảo hộ lập ra từ ngày 23/10/1896 để đào tạo đội ngũ thông ngôn, viên chức cho bộ máy cai trị.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_2e_annee_complementaire.jpg","chu_thich":"Một lớp học tại Trường Quốc Học Huế đầu thế kỷ XX.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_college_quoc_hoc_a_hue_cours_de_gymnastique.jpg","chu_thich":"Giờ thể dục ngoài sân Trường Quốc Học Huế đầu thế kỷ XX.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Người phiên dịch trẻ tuổi trong phong trào chống sưu thuế","text":"Đầu năm 1908, một phong trào đấu tranh chống sưu cao thuế nặng bùng lên khắp các tỉnh Trung Kỳ, lan tới tận kinh đô Huế. Từng đoàn nông dân kéo về trước Tòa Khâm sứ Pháp để đưa kiến nghị, phản đối chế độ sưu dịch hà khắc. Theo nhiều tài liệu về sau, người thanh niên Nguyễn Tất Thành, khi đó đang theo học tiếng Pháp, đã tham gia giúp đoàn người biểu tình chuyển đạt nguyện vọng tới nhà cầm quyền. Sự việc khiến cậu học trò lọt vào tầm theo dõi của mật thám Pháp và ban giám hiệu nhà trường. Chính những gì tận mắt chứng kiến ở đất kinh kỳ — cảnh sưu cao thuế nặng, cảnh đàn áp người biểu tình, sự bất lực của cả một triều đình trước sự cai trị của ngoại bang — đã góp phần nung nấu trong lòng chàng trai trẻ câu hỏi về vận mệnh dân tộc, thôi thúc một quyết định lớn lao sắp tới.","doc":6},{"loai":"trich","text":"Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em.","nguoi":"Hồ Chí Minh","nguon_ten":"Thư gửi học sinh nhân ngày khai trường đầu tiên của nước Việt Nam Dân chủ Cộng hòa, tháng 9/1945; in trong Hồ Chí Minh Toàn tập, tập 4","doc":7},{"loai":"anh","src":"textures/bai/G02_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Huế – Kinh thành và trường Quốc Học","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Trường Quốc Học Huế sau này còn là nơi học tập của nhiều nhân vật lịch sử khác của Việt Nam thế kỷ XX, trong đó có Võ Nguyên Giáp và Phạm Văn Đồng — dù mỗi người theo học vào những năm khác nhau, cách xa thời gian Nguyễn Tất Thành ngồi trên ghế nhà trường.","nguon_ten":"en.wikipedia.org","doc":8},{"loai":"anh","src":"textures/bai/G02_v4.jpg","chu_thich":"Một góc không gian 3D tái hiện Huế – Kinh thành và trường Quốc Học","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Cầu Trường Tiền bắc qua sông Hương, không xa trường, được xây dựng trong những năm 1899 – 1900, gồm sáu nhịp vòm thép. Năm 1904, cây cầu bị hư hại nặng trong cơn bão lớn năm Giáp Thìn và phải sửa chữa lại.","nguon_ten":"en.wikipedia.org","doc":9},{"loai":"doan","tieu_de":"Rời kinh thành, một quyết định đã hình thành","text":"Năm 1909, Nguyễn Tất Thành rời Huế, không hoàn tất chương trình học tại Quốc Học. Ông theo cha vào Bình Định, rồi từ đó một mình xuôi vào Phan Thiết, Sài Gòn trong hai năm sau đó — những chặng đường cuối cùng trước khi bước chân lên con tàu rời Bến Nhà Rồng năm 1911. Kinh thành Huế những năm tháng ấy — với sông Hương, cầu Trường Tiền mới bắc qua, những dãy lớp học Quốc Học và cả nỗi đau mất mẹ — đã in dấu sâu đậm trong hành trình trưởng thành của một con người sau này làm thay đổi vận mệnh cả dân tộc. Ngày nay, Trường Quốc Học vẫn đứng bên bờ sông Hương, còn giữ bức tượng người học trò Nguyễn Tất Thành trong sân trường, nhắc nhớ về những năm tháng thiếu thời của một trong những học trò nổi tiếng nhất của ngôi trường hơn một thế kỷ tuổi.","doc":10},{"loai":"anh","src":"textures/ht/ht_anh_tuong_nguyen_tat_thanh_tai_quoc_hoc_hue.jpg","chu_thich":"Tượng người học trò Nguyễn Tất Thành trong sân Trường Quốc Học Huế ngày nay, tưởng nhớ quãng thời gian Người theo học tại đây (khoảng 1907 – 1908).","credit":"Ảnh: Lưu Ly at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},{"loai":"moc","items":[["1895","Lần đầu vào Huế cùng cha mẹ, sống ở Thành Nội"],["1901","Mẹ, bà Hoàng Thị Loan, qua đời tại Huế"],["1906","Cha được bổ vào Bộ Lễ; học Trường Tiểu học Pháp – Việt Đông Ba"],["1907 – 1908","Vào học Trường Quốc Học Huế (1907); tháng 5/1908 tham gia phong trào chống sưu thuế"],["1909","Rời Huế, theo cha vào Bình Định"]]}],"doc":[{"i":-1,"t":"Huế: Nơi Cậu Học Trò Lần Đầu Nhìn Thấy Bộ Mặt Thực Dân. Hai lần theo cha vào kinh đô Huế — lần đầu năm 1895 khi mới lên năm, lần sau năm 1906 khi đã là thiếu niên — Nguyễn Tất Thành vừa nếm trải nỗi đau mất mẹ giữa đất khách, vừa được ngồi trong những lớp học của Trường Quốc Học bên bờ sông Hương. Cũng chính tại đây, năm 1908, cậu học trò lần đầu chứng kiến cảnh nông dân bị áp bức đứng lên phản kháng, và bắt đầu đặt câu hỏi về vận mệnh dân tộc."},{"t":"Từ làng Sen tới đất kinh kỳ. Năm 1895, khi mới lên năm tuổi, cậu bé Nguyễn Sinh Cung lần đầu theo cha mẹ rời quê Nam Đàn vào kinh đô Huế. Ông Nguyễn Sinh Sắc khi ấy ra Huế để tiếp tục việc học, chuẩn bị cho các kỳ thi Hội, thi Đình sau khi đã đỗ Cử nhân ở quê nhà. Gia đình nhỏ thuê một căn nhà đơn sơ trong khu vực Thành Nội, phía trong vòng thành của kinh đô triều Nguyễn — nơi những gia đình quan lại nhỏ, sĩ tử nghèo từ các tỉnh về trọ học vẫn thường sống chen chúc. Cuộc sống thị thành xa lạ, thiếu thốn hơn nhiều so với làng quê, nhưng cũng là nơi cậu bé lần đầu nhìn thấy sự phồn hoa của một kinh đô, đồng thời chứng kiến khoảng cách giàu nghèo giữa quan lại triều đình, người Pháp cai trị và dân thường. Sông Hương uốn quanh chân thành, những mái ngói cung điện lấp lánh trong nắng, nhưng ngay bên ngoài cổng thành là những xóm nghèo lam lũ — hai hình ảnh trái ngược mà cậu bé làng Sen chưa từng thấy ở quê nhà."},{"t":"Bạn có biết? Khu vực Thành Nội, nơi gia đình Nguyễn Sinh Sắc từng thuê nhà trọ học, nằm ngay bên trong vòng tường thành của Kinh thành Huế — khu thành lũy được vua Gia Long cho khởi công và các đời vua sau tiếp tục xây dựng, hoàn thiện trong suốt nhiều thập kỷ đầu thế kỷ XIX."},{"t":"Mất mẹ giữa kinh thành. Cuối năm 1900, ông Nguyễn Sinh Sắc được cử đi làm việc ở trường thi Hương Thanh Hóa, mang theo người con trai lớn là Nguyễn Sinh Khiêm; Nguyễn Sinh Cung ở lại Huế với mẹ. Sau khi sinh người con út, bà Hoàng Thị Loan lâm bệnh và qua đời ngày 10/2/1901 tại căn nhà nhỏ giữa kinh thành. Nguyễn Sinh Cung khi ấy mới mười một tuổi, có những ngày phải bồng em nhỏ đi khắp xóm xin sữa của những người hàng xóm tốt bụng. Cái chết của mẹ giữa nơi đất khách, trong lúc cha và anh vắng nhà, là một trong những biến cố đau buồn nhất tuổi thơ Người — một ký ức mà về sau, những người viết tiểu sử vẫn nhắc lại như một trong những dấu mốc hun đúc nghị lực sống của cậu bé mồ côi mẹ giữa kinh thành."},{"t":"Bạn có biết? Người em út trong gia đình, Nguyễn Sinh Nhuận, chào đời ngay tại Huế trong những năm gia đình sống ở Thành Nội, nhưng cũng mất sớm khi còn thơ ấu — khiến biến cố năm 1901 trở thành một trong những giai đoạn mất mát liên tiếp nặng nề nhất của gia đình nhỏ này."},{"t":"Trở lại Huế, vào Trường Quốc Học. Sau nhiều năm ở làng Sen, năm 1906 ông Nguyễn Sinh Sắc được triều đình bổ vào làm việc tại Bộ Lễ ở Huế; ông đưa hai con trai theo cùng. Nguyễn Tất Thành khi đó theo học tại Trường Tiểu học Pháp - Việt Đông Ba, ngôi trường mang tên khu vực Đông Ba nổi tiếng của kinh thành. Khoảng năm 1907 – 1908, cậu học trò vào học Trường Quốc Học Huế — trường trung học Pháp - Việt lớn, được triều đình và chính quyền bảo hộ lập ra từ ngày 23/10/1896 để đào tạo đội ngũ thông ngôn, viên chức cho bộ máy cai trị."},{"t":"Người phiên dịch trẻ tuổi trong phong trào chống sưu thuế. Đầu năm 1908, một phong trào đấu tranh chống sưu cao thuế nặng bùng lên khắp các tỉnh Trung Kỳ, lan tới tận kinh đô Huế. Từng đoàn nông dân kéo về trước Tòa Khâm sứ Pháp để đưa kiến nghị, phản đối chế độ sưu dịch hà khắc. Theo nhiều tài liệu về sau, người thanh niên Nguyễn Tất Thành, khi đó đang theo học tiếng Pháp, đã tham gia giúp đoàn người biểu tình chuyển đạt nguyện vọng tới nhà cầm quyền. Sự việc khiến cậu học trò lọt vào tầm theo dõi của mật thám Pháp và ban giám hiệu nhà trường. Chính những gì tận mắt chứng kiến ở đất kinh kỳ — cảnh sưu cao thuế nặng, cảnh đàn áp người biểu tình, sự bất lực của cả một triều đình trước sự cai trị của ngoại bang — đã góp phần nung nấu trong lòng chàng trai trẻ câu hỏi về vận mệnh dân tộc, thôi thúc một quyết định lớn lao sắp tới."},{"t":"Non sông Việt Nam có trở nên tươi đẹp hay không, dân tộc Việt Nam có bước tới đài vinh quang để sánh vai với các cường quốc năm châu được hay không, chính là nhờ một phần lớn ở công học tập của các em. — Hồ Chí Minh"},{"t":"Bạn có biết? Trường Quốc Học Huế sau này còn là nơi học tập của nhiều nhân vật lịch sử khác của Việt Nam thế kỷ XX, trong đó có Võ Nguyên Giáp và Phạm Văn Đồng — dù mỗi người theo học vào những năm khác nhau, cách xa thời gian Nguyễn Tất Thành ngồi trên ghế nhà trường."},{"t":"Bạn có biết? Cầu Trường Tiền bắc qua sông Hương, không xa trường, được xây dựng trong những năm 1899 – 1900, gồm sáu nhịp vòm thép. Năm 1904, cây cầu bị hư hại nặng trong cơn bão lớn năm Giáp Thìn và phải sửa chữa lại."},{"t":"Rời kinh thành, một quyết định đã hình thành. Năm 1909, Nguyễn Tất Thành rời Huế, không hoàn tất chương trình học tại Quốc Học. Ông theo cha vào Bình Định, rồi từ đó một mình xuôi vào Phan Thiết, Sài Gòn trong hai năm sau đó — những chặng đường cuối cùng trước khi bước chân lên con tàu rời Bến Nhà Rồng năm 1911. Kinh thành Huế những năm tháng ấy — với sông Hương, cầu Trường Tiền mới bắc qua, những dãy lớp học Quốc Học và cả nỗi đau mất mẹ — đã in dấu sâu đậm trong hành trình trưởng thành của một con người sau này làm thay đổi vận mệnh cả dân tộc. Ngày nay, Trường Quốc Học vẫn đứng bên bờ sông Hương, còn giữ bức tượng người học trò Nguyễn Tất Thành trong sân trường, nhắc nhớ về những năm tháng thiếu thời của một trong những học trò nổi tiếng nhất của ngôi trường hơn một thế kỷ tuổi."}],"hien_vat":[{"ten":"Cổng Trường Quốc Học","mo_ta":"Cổng trường hai tầng mang biển khắc chữ Hán 國學 (Quốc Học) — lối vào ngôi trường Pháp - Việt tiêu biểu nhất xứ Trung Kỳ, nơi Nguyễn Tất Thành vào học khoảng năm 1907 – 1908.","nguon":"https://en.wikipedia.org/wiki/Quoc_Hoc_High_School"},{"ten":"Dãy lớp học quanh sân trường","mo_ta":"Những dãy lớp học quanh sân trường, tái hiện không gian học tập của Trường Quốc Học những năm đầu thế kỷ XX, khi Nguyễn Tất Thành theo học (khoảng 1907 – 1908).","nguon":"https://en.wikipedia.org/wiki/Quoc_Hoc_High_School"},{"ten":"Cầu Trường Tiền","mo_ta":"Cây cầu sáu nhịp vòm thép bắc qua sông Hương, xây dựng trong những năm 1899 – 1900. Đứng trong sân trường, học trò Quốc Học những năm 1900 có thể nhìn thấy cây cầu mới này ở phía đông.","nguon":"https://en.wikipedia.org/wiki/Truong_Tien_Bridge"},{"ten":"Kỳ Đài và tường Kinh thành","mo_ta":"Bên kia sông Hương, đối diện Trường Quốc Học, là tường thành và Kỳ Đài (cột cờ) của Kinh thành Huế — biểu tượng quyền lực của triều đình nhà Nguyễn, được xây dựng và hoàn thiện qua nhiều đời vua từ đầu thế kỷ XIX.","nguon":"https://en.wikipedia.org/wiki/Hu%E1%BA%BF"},{"ten":"Bến thuyền ven sông Hương","mo_ta":"Con đường và bến thuyền nhỏ trước cổng trường là nơi thuyền bè, người dân kinh thành qua lại mỗi ngày — một phần khung cảnh quen thuộc mà cậu học trò Nguyễn Tất Thành đi qua trên đường tới lớp."}],"hoi_dap":[{"hoi":"Gia đình Nguyễn Sinh Cung vào Huế lần đầu tiên vào năm nào?","dap":"Năm 1895.","sai":["Năm 1890","Năm 1901","Năm 1906"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Vì sao gia đình chuyển vào Huế lần đầu năm 1895?","dap":"Để ông Nguyễn Sinh Sắc tiếp tục học tập, chuẩn bị thi Hội, thi Đình.","sai":["Để ông Sắc nhậm chức tri huyện","Để tránh nạn đói ở Nghệ An","Để Nguyễn Tất Thành vào học Quốc Học"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Bà Hoàng Thị Loan qua đời năm nào, ở đâu?","dap":"Năm 1901, tại Huế.","sai":["Năm 1895, tại Nam Đàn","Năm 1906, tại Huế","Năm 1911, tại Sài Gòn"],"nguon":"https://en.wikipedia.org/wiki/Ho%C3%A0ng_Th%E1%BB%8B_Loan"},{"hoi":"Khi mẹ mất, Nguyễn Sinh Cung bao nhiêu tuổi và đã làm gì để chăm em?","dap":"Mười một tuổi, phải bồng em nhỏ đi xin sữa hàng xóm.","sai":["Mười lăm tuổi, gửi em cho người quen","Bảy tuổi, nhờ chị nuôi em","Mười một tuổi, thuê vú nuôi cho em"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Nguyễn Tất Thành theo học trường tiểu học nào ở Huế trước khi vào Quốc Học?","dap":"Trường Tiểu học Pháp - Việt Đông Ba.","sai":["Trường Tiểu học Pháp - Việt Vinh","Trường Dục Thanh","Trường Hậu Bổ"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Trường Quốc Học Huế được thành lập vào năm nào?","dap":"Ngày 23/10/1896.","sai":["Năm 1901","Năm 1908","Năm 1915"],"nguon":"https://en.wikipedia.org/wiki/Quoc_Hoc_High_School"},{"hoi":"Năm 1908, Nguyễn Tất Thành tham gia vào sự kiện nào ở Huế?","dap":"Giúp đoàn nông dân biểu tình chống sưu thuế chuyển đạt nguyện vọng tới chính quyền.","sai":["Tham gia kỳ thi Hội cùng cha","Dẫn đầu một cuộc bãi khóa ở Quốc Học","Tổ chức biểu tình đòi tăng lương giáo viên"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"},{"hoi":"Cây cầu sáu nhịp vòm thép bắc qua sông Hương, không xa Trường Quốc Học, tên là gì?","dap":"Cầu Trường Tiền.","sai":["Cầu Long Biên","Cầu Hiền Lương","Cầu Bình Lợi"],"nguon":"https://en.wikipedia.org/wiki/Truong_Tien_Bridge"},{"hoi":"Cầu Trường Tiền được xây dựng trong khoảng thời gian nào?","dap":"Trong những năm 1899 – 1900.","sai":["1908 - 1910","1915 - 1918","1885 - 1888"],"nguon":"https://en.wikipedia.org/wiki/Truong_Tien_Bridge"},{"hoi":"Nguyễn Tất Thành rời Huế vào khoảng thời gian nào, để đi đâu?","dap":"Năm 1909, theo cha vào Bình Định rồi tiếp tục vào Phan Thiết, Sài Gòn.","sai":["Đầu năm 1911, đi thẳng sang Pháp","Năm 1901, về lại làng Sen hẳn","Năm 1915, ra Hà Nội"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"}],"nguon":[{"ten":"Ho Chi Minh – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Quoc Hoc High School – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Quoc_Hoc_High_School"},{"ten":"Huế – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Hu%E1%BA%BF"},{"ten":"Truong Tien Bridge – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Truong_Tien_Bridge"},{"ten":"Tiểu sử Chủ tịch Hồ Chí Minh (1890-1969) – Cổng TTĐT về Chủ tịch Hồ Chí Minh","url":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9"}],"so_chu":1134},"G03":{"ma":"G03","tieu_de":"Thầy giáo Thành bên dòng Cà Ty","sapo":"Mùa thu năm 1910, người thanh niên Nguyễn Tất Thành, vừa tròn hai mươi tuổi, dừng chân ở Phan Thiết và nhận dạy học tại Trường Dục Thanh – ngôi trường do các nhà yêu nước theo tinh thần Duy Tân lập nên và nuôi bằng lợi nhuận từ nghề làm nước mắm. Gần nửa năm đứng lớp bên dòng Cà Ty là chặng dừng chân dài cuối cùng của Người trước khi vào Sài Gòn và xuống tàu ra đi tìm đường cứu nước.","sapo_en":"In autumn 1910, twenty-year-old Nguyễn Tất Thành stopped in Phan Thiết and taught at the Dục Thanh School, founded by reform-minded patriots and funded by a fish-sauce trading company. Those few months beside the Cà Ty River were his last long stay before Saigon and the voyage abroad.","bia":{"src":"textures/ht/ht_anh_truong_duc_thanh.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Từ Bình Định đi về phương Nam","text":"Giữa năm 1909, Nguyễn Tất Thành theo cha là cụ Nguyễn Sinh Sắc rời Huế vào Bình Định, khi cụ được cử làm tri huyện Bình Khê. Từ tháng 9 năm ấy, người con trai mười chín tuổi được cha gửi xuống Quy Nhơn học thêm tiếng Pháp. Đất nước đang dưới ách đô hộ, và câu hỏi làm thế nào để cứu nước ngày càng thôi thúc người thanh niên.\n\nKhoảng tháng 8/1910, rời Bình Định, Nguyễn Tất Thành một mình tiếp tục đi về phía Nam, qua Phan Rang rồi tới Phan Thiết. Nhờ cụ Trương Gia Mô, một nhà nho yêu nước quen biết cụ Nguyễn Sinh Sắc, giới thiệu, anh được các nhà Duy Tân của hội Liên Thành đón nhận. Từ tháng 9/1910, người thanh niên hai mươi tuổi trở thành thầy giáo của Trường Dục Thanh ở thị xã Phan Thiết, tỉnh Bình Thuận.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_lop_hoc_trong_duc_thanh.jpg","chu_thich":"Lớp học trong Trường Dục Thanh, nơi thầy Thành đứng lớp","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ngôi trường sinh ra từ nghề nước mắm","text":"Trường Dục Thanh được dựng năm 1907 (có tài liệu ghi năm 1908) trên khu đất của gia đình nhà thơ, nhà yêu nước Nguyễn Thông, bên bờ sông Cà Ty. Người đứng ra vận động lập trường là hai người con của ông, Nguyễn Trọng Lội và Nguyễn Quý Anh. Tên trường, “Dục Thanh”, mang ý nghĩa giáo dục lớp thanh thiếu niên.\n\nĐứng sau ngôi trường là Liên Thành, hội buôn được sáu nhà yêu nước Nguyễn Trọng Lội, Nguyễn Quý Anh, Hồ Tá Bang, Trần Lệ Chất, Nguyễn Hiệt Chi và Ngô Văn Nhượng lập ra ở Phan Thiết vào tháng 3/1906. Liên Thành làm nước mắm, đặc sản của vùng biển Bình Thuận, rồi dùng lợi nhuận trang trải cho việc dạy học. Buôn bán để nuôi trường, mở trường để thức tỉnh lòng yêu nước: đó là cách các nhà Duy Tân ở Phan Thiết hiện thực hóa chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”.\n\nTrường có khoảng năm, sáu mươi học trò, chia làm bốn lớp Tư, Ba, Nhì, Nhất. Chữ Quốc ngữ được dạy làm chính, bên cạnh chữ Hán, chữ Pháp và môn thể dục – một chương trình rất mới mẻ so với lối học khoa cử còn thịnh hành khi ấy.","doc":2},{"loai":"ban_co_biet","text":"Hội buôn Liên Thành được các nhà Duy Tân lập ở Phan Thiết vào tháng 3/1906 – trước cả khi có Trường Dục Thanh. Hội chủ yếu sản xuất nước mắm và dùng lợi nhuận để trang trải chi phí cho nhà trường.","nguon_ten":"tuoitre.vn","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_truong_duc_thanh_noi_bac_ho_day_o_truong_duc_tha.jpg","chu_thich":"Gian nhà nơi Bác Hồ dạy học ở Dục Thanh","credit":"Ảnh: Phương Huy · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Thầy Thành đứng lớp","text":"Thầy giáo trẻ được phân dạy lớp nhì, chủ yếu dạy chữ Quốc ngữ và chữ Hán, kiêm luôn môn thể dục; khi trường cần, thầy còn dạy thay tiếng Pháp. Những học trò cũ về sau vẫn nhớ thầy giảng bài nhiệt tình, dễ hiểu; giảng xong một ý, thầy hỏi lại xem trò đã hiểu chưa rồi mới chuyển sang ý khác.\n\nNgoài giờ lên lớp, thầy Thành đưa học trò đi thăm cảnh vật quê hương, tìm hiểu đời sống của người lao động quanh vùng, ghé cả những xóm chài nghèo ven biển. Trên đường đi, thầy kể chuyện Hai Bà Trưng, Bà Triệu, đọc cho trò nghe những vần thơ yêu nước. Mỗi bài học chữ được dạy song hành với một bài học về lòng yêu quê hương, đất nước và tình thương với người nghèo khổ.\n\nVới học trò Dục Thanh, thầy giáo hai mươi tuổi vừa nghiêm vừa gần gũi như một người bạn lớn: khen ngợi khi trò tiến bộ, ân cần chỉ bảo khi trò mắc lỗi.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_gieng_truong_duc_thanh.jpg","chu_thich":"Giếng nước trong sân Trường Dục Thanh","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Dục Thanh là một ngôi trường nhỏ: chỉ khoảng 60 học trò, chia bốn lớp Tư, Ba, Nhì, Nhất. Thầy Nguyễn Tất Thành phụ trách lớp nhì.","nguon_ten":"baocantho.com.vn","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_song_ca_ty.jpg","chu_thich":"Sông Cà Ty, Phan Thiết","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ngọa Du Sào, cây khế và giếng nước","text":"Thầy Thành sống ngay trong khuôn viên trường. Nhà Ngư, được dựng năm 1906 để chứa ngư cụ, về sau thành chỗ ở nội trú của thầy và trò. Cạnh đó là Ngọa Du Sào, ngôi nhà nhỏ do cụ Nguyễn Thông dựng từ năm 1880. Khi trường hoạt động, Ngọa Du Sào được dùng làm thư viện; đây là nơi thầy Thành đọc sách báo và soạn bài.\n\nGiữa sân, cây khế do phu nhân cụ Nguyễn Thông trồng từ hơn một trăm năm trước vẫn xanh lá. Theo tư liệu của khu di tích, thầy Thành thường chăm sóc, tưới nước cho cây, lấy nước từ chiếc giếng gạch gần đó – cũng là giếng thầy dùng để sinh hoạt hằng ngày.\n\nTrước cửa lớp, dòng Cà Ty lặng lẽ chảy qua lòng thị xã rồi đổ ra biển, trên sông là những chiếc thuyền nan, thuyền thúng của ngư dân. Cây khế, giếng nước, dòng sông – những chứng nhân bình dị ấy đã ở lại cùng ký ức về người thầy giáo trẻ.","doc":6},{"loai":"anh","src":"textures/bai/G03_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Phan Thiết – Trường Dục Thanh","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Ngọa Du Sào có trước Trường Dục Thanh gần ba mươi năm: nhà thơ Nguyễn Thông dựng ngôi nhà này từ năm 1880. Khi trường hoạt động, căn nhà trở thành thư viện.","nguon_ten":"vnexpress.net","doc":7},{"loai":"anh","src":"textures/bai/G03_v4.jpg","chu_thich":"Một góc không gian 3D tái hiện Phan Thiết – Trường Dục Thanh","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Cây khế cổ thụ trong sân trường do phu nhân cụ Nguyễn Thông trồng. Thầy Thành thường chăm sóc, tưới nước cho cây trong những tháng dạy học ở đây.","nguon_ten":"danviet.vn","doc":8},{"loai":"doan","tieu_de":"Lên đường vào Sài Gòn","text":"Tháng 2/1911, sau gần nửa năm đứng lớp, thầy Thành rời Dục Thanh, lên đường vào Sài Gòn. Bốn tháng sau, từ thành phố cảng ấy, người thanh niên xuống tàu sang Pháp, mở đầu ba mươi năm bôn ba tìm đường cứu nước.\n\nNhững tháng ở Phan Thiết cho Nguyễn Tất Thành sống giữa những con người mang tinh thần Duy Tân: họ vừa làm kinh tế, vừa mở trường, vừa nuôi chí lớn. Người thầy giáo trẻ năm ấy, về sau trên cương vị Chủ tịch nước, luôn coi việc học và việc “trồng người” là sự nghiệp lâu dài của cả dân tộc.","doc":9},{"loai":"anh","src":"textures/bai/G03_v5.jpg","chu_thich":"Một góc không gian 3D tái hiện Phan Thiết – Trường Dục Thanh","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"trich","text":"Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người","nguoi":"Hồ Chí Minh","nguon_ten":"Nói chuyện tại lớp học chính trị của giáo viên cấp II, cấp III toàn miền Bắc, ngày 13/9/1958 – Hồ Chí Minh Toàn tập, t.11, Nxb Chính trị quốc gia, H.2011, tr.528; dẫn theo https://tapchiqptd.vn/vi/loi-bac-day-ngay-nay-nam-xua/vi-loi-ich-tram-nam-thi-phai-trong-nguoi/12400.html","doc":10},{"loai":"doan","tieu_de":"Dục Thanh hôm nay","text":"Từ tháng 11/1978 đến tháng 12/1980, lớp học, nhà Ngư và Ngọa Du Sào được trùng tu theo dáng xưa. Năm 1986, khu di tích Trường Dục Thanh được xếp hạng di tích lịch sử – văn hóa cấp quốc gia. Ngày 19/5/1986, nhân kỷ niệm 96 năm ngày sinh Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận được khánh thành ngay bên cạnh, tại số 39 Trưng Nhị, thành phố Phan Thiết.\n\nLớp học ngày nay rộng khoảng 137 m², cao 4,4 m, vẫn kê 21 bộ bàn ghế học trò. Nhiều trường học, đoàn thanh niên chọn nơi đây làm điểm đến “về nguồn” để nghe kể về người thầy giáo Nguyễn Tất Thành.","doc":11},{"loai":"moc","items":[["1880","Nhà thơ Nguyễn Thông dựng Ngọa Du Sào bên sông Cà Ty"],["3/1906","Các nhà Duy Tân lập hội buôn Liên Thành ở Phan Thiết"],["1907","Trường Dục Thanh ra đời (có tài liệu ghi năm 1908)"],["giữa 1909","Nguyễn Tất Thành theo cha vào Bình Khê, Bình Định"],["khoảng 8/1910","Rời Bình Định, qua Phan Rang tới Phan Thiết"],["9/1910","Bắt đầu dạy học tại Trường Dục Thanh"],["2/1911","Rời Dục Thanh vào Sài Gòn"],["11/1978 – 12/1980","Trùng tu khu di tích"],["1986","Xếp hạng di tích quốc gia; khánh thành Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận (19/5/1986)"]]}],"doc":[{"i":-1,"t":"Thầy giáo Thành bên dòng Cà Ty. Mùa thu năm 1910, người thanh niên Nguyễn Tất Thành, vừa tròn hai mươi tuổi, dừng chân ở Phan Thiết và nhận dạy học tại Trường Dục Thanh – ngôi trường do các nhà yêu nước theo tinh thần Duy Tân lập nên và nuôi bằng lợi nhuận từ nghề làm nước mắm. Gần nửa năm đứng lớp bên dòng Cà Ty là chặng dừng chân dài cuối cùng của Người trước khi vào Sài Gòn và xuống tàu ra đi tìm đường cứu nước."},{"t":"Từ Bình Định đi về phương Nam. Giữa năm 1909, Nguyễn Tất Thành theo cha là cụ Nguyễn Sinh Sắc rời Huế vào Bình Định, khi cụ được cử làm tri huyện Bình Khê. Từ tháng 9 năm ấy, người con trai mười chín tuổi được cha gửi xuống Quy Nhơn học thêm tiếng Pháp. Đất nước đang dưới ách đô hộ, và câu hỏi làm thế nào để cứu nước ngày càng thôi thúc người thanh niên. Khoảng tháng 8/1910, rời Bình Định, Nguyễn Tất Thành một mình tiếp tục đi về phía Nam, qua Phan Rang rồi tới Phan Thiết. Nhờ cụ Trương Gia Mô, một nhà nho yêu nước quen biết cụ Nguyễn Sinh Sắc, giới thiệu, anh được các nhà Duy Tân của hội Liên Thành đón nhận. Từ tháng 9/1910, người thanh niên hai mươi tuổi trở thành thầy giáo của Trường Dục Thanh ở thị xã Phan Thiết, tỉnh Bình Thuận."},{"t":"Ngôi trường sinh ra từ nghề nước mắm. Trường Dục Thanh được dựng năm 1907 (có tài liệu ghi năm 1908) trên khu đất của gia đình nhà thơ, nhà yêu nước Nguyễn Thông, bên bờ sông Cà Ty. Người đứng ra vận động lập trường là hai người con của ông, Nguyễn Trọng Lội và Nguyễn Quý Anh. Tên trường, “Dục Thanh”, mang ý nghĩa giáo dục lớp thanh thiếu niên. Đứng sau ngôi trường là Liên Thành, hội buôn được sáu nhà yêu nước Nguyễn Trọng Lội, Nguyễn Quý Anh, Hồ Tá Bang, Trần Lệ Chất, Nguyễn Hiệt Chi và Ngô Văn Nhượng lập ra ở Phan Thiết vào tháng 3/1906. Liên Thành làm nước mắm, đặc sản của vùng biển Bình Thuận, rồi dùng lợi nhuận trang trải cho việc dạy học. Buôn bán để nuôi trường, mở trường để thức tỉnh lòng yêu nước: đó là cách các nhà Duy Tân ở Phan Thiết hiện thực hóa chủ trương “khai dân trí, chấn dân khí, hậu dân sinh”. Trường có khoảng năm, sáu mươi học trò, chia làm bốn lớp Tư, Ba, Nhì, Nhất. Chữ Quốc ngữ được dạy làm chính, bên cạnh chữ Hán, chữ Pháp và môn thể dục – một chương trình rất mới mẻ so với lối học khoa cử còn thịnh hành khi ấy."},{"t":"Bạn có biết? Hội buôn Liên Thành được các nhà Duy Tân lập ở Phan Thiết vào tháng 3/1906 – trước cả khi có Trường Dục Thanh. Hội chủ yếu sản xuất nước mắm và dùng lợi nhuận để trang trải chi phí cho nhà trường."},{"t":"Thầy Thành đứng lớp. Thầy giáo trẻ được phân dạy lớp nhì, chủ yếu dạy chữ Quốc ngữ và chữ Hán, kiêm luôn môn thể dục; khi trường cần, thầy còn dạy thay tiếng Pháp. Những học trò cũ về sau vẫn nhớ thầy giảng bài nhiệt tình, dễ hiểu; giảng xong một ý, thầy hỏi lại xem trò đã hiểu chưa rồi mới chuyển sang ý khác. Ngoài giờ lên lớp, thầy Thành đưa học trò đi thăm cảnh vật quê hương, tìm hiểu đời sống của người lao động quanh vùng, ghé cả những xóm chài nghèo ven biển. Trên đường đi, thầy kể chuyện Hai Bà Trưng, Bà Triệu, đọc cho trò nghe những vần thơ yêu nước. Mỗi bài học chữ được dạy song hành với một bài học về lòng yêu quê hương, đất nước và tình thương với người nghèo khổ. Với học trò Dục Thanh, thầy giáo hai mươi tuổi vừa nghiêm vừa gần gũi như một người bạn lớn: khen ngợi khi trò tiến bộ, ân cần chỉ bảo khi trò mắc lỗi."},{"t":"Bạn có biết? Dục Thanh là một ngôi trường nhỏ: chỉ khoảng 60 học trò, chia bốn lớp Tư, Ba, Nhì, Nhất. Thầy Nguyễn Tất Thành phụ trách lớp nhì."},{"t":"Ngọa Du Sào, cây khế và giếng nước. Thầy Thành sống ngay trong khuôn viên trường. Nhà Ngư, được dựng năm 1906 để chứa ngư cụ, về sau thành chỗ ở nội trú của thầy và trò. Cạnh đó là Ngọa Du Sào, ngôi nhà nhỏ do cụ Nguyễn Thông dựng từ năm 1880. Khi trường hoạt động, Ngọa Du Sào được dùng làm thư viện; đây là nơi thầy Thành đọc sách báo và soạn bài. Giữa sân, cây khế do phu nhân cụ Nguyễn Thông trồng từ hơn một trăm năm trước vẫn xanh lá. Theo tư liệu của khu di tích, thầy Thành thường chăm sóc, tưới nước cho cây, lấy nước từ chiếc giếng gạch gần đó – cũng là giếng thầy dùng để sinh hoạt hằng ngày. Trước cửa lớp, dòng Cà Ty lặng lẽ chảy qua lòng thị xã rồi đổ ra biển, trên sông là những chiếc thuyền nan, thuyền thúng của ngư dân. Cây khế, giếng nước, dòng sông – những chứng nhân bình dị ấy đã ở lại cùng ký ức về người thầy giáo trẻ."},{"t":"Bạn có biết? Ngọa Du Sào có trước Trường Dục Thanh gần ba mươi năm: nhà thơ Nguyễn Thông dựng ngôi nhà này từ năm 1880. Khi trường hoạt động, căn nhà trở thành thư viện."},{"t":"Bạn có biết? Cây khế cổ thụ trong sân trường do phu nhân cụ Nguyễn Thông trồng. Thầy Thành thường chăm sóc, tưới nước cho cây trong những tháng dạy học ở đây."},{"t":"Lên đường vào Sài Gòn. Tháng 2/1911, sau gần nửa năm đứng lớp, thầy Thành rời Dục Thanh, lên đường vào Sài Gòn. Bốn tháng sau, từ thành phố cảng ấy, người thanh niên xuống tàu sang Pháp, mở đầu ba mươi năm bôn ba tìm đường cứu nước. Những tháng ở Phan Thiết cho Nguyễn Tất Thành sống giữa những con người mang tinh thần Duy Tân: họ vừa làm kinh tế, vừa mở trường, vừa nuôi chí lớn. Người thầy giáo trẻ năm ấy, về sau trên cương vị Chủ tịch nước, luôn coi việc học và việc “trồng người” là sự nghiệp lâu dài của cả dân tộc."},{"t":"Vì lợi ích mười năm thì phải trồng cây, vì lợi ích trăm năm thì phải trồng người — Hồ Chí Minh"},{"t":"Dục Thanh hôm nay. Từ tháng 11/1978 đến tháng 12/1980, lớp học, nhà Ngư và Ngọa Du Sào được trùng tu theo dáng xưa. Năm 1986, khu di tích Trường Dục Thanh được xếp hạng di tích lịch sử – văn hóa cấp quốc gia. Ngày 19/5/1986, nhân kỷ niệm 96 năm ngày sinh Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận được khánh thành ngay bên cạnh, tại số 39 Trưng Nhị, thành phố Phan Thiết. Lớp học ngày nay rộng khoảng 137 m², cao 4,4 m, vẫn kê 21 bộ bàn ghế học trò. Nhiều trường học, đoàn thanh niên chọn nơi đây làm điểm đến “về nguồn” để nghe kể về người thầy giáo Nguyễn Tất Thành."}],"hien_vat":[{"ten":"Lớp học năm gian","mo_ta":"Ngôi nhà gỗ lợp ngói là lớp học chính của Trường Dục Thanh, rộng khoảng 137 m², cao 4,4 m. Tại đây thầy Nguyễn Tất Thành dạy lớp nhì từ tháng 9/1910 đến tháng 2/1911. Công trình được trùng tu từ tháng 11/1978 đến tháng 12/1980 theo dáng xưa.","nguon":"https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html"},{"ten":"Bàn ghế học trò, bục giảng và bảng đen","mo_ta":"Trong lớp kê 21 bộ bàn ghế học trò cùng bục giảng và bảng đen. Trường khi ấy có khoảng 60 học trò chia bốn lớp. Thầy Thành dạy chủ yếu chữ Quốc ngữ, chữ Hán và kiêm môn thể dục.","nguon":"https://giaoducthoidai.vn/noi-luu-dau-cua-thay-giao-nguyen-tat-thanh-post671585.html"},{"ten":"Nhà Ngọa Du Sào","mo_ta":"Ngôi nhà do nhà thơ, nhà yêu nước Nguyễn Thông dựng năm 1880. Khi Trường Dục Thanh hoạt động, đây là thư viện của trường, nơi thầy Thành đọc sách báo và soạn bài.","nguon":"https://baocantho.com.vn/thang-nam-ve-truong-duc-thanh-nho-thay-nguyen-tat-thanh-a21012.html"},{"ten":"Giếng nước","mo_ta":"Chiếc giếng gạch trong sân là nơi thầy Thành lấy nước dùng hằng ngày và tưới cây. Giếng vẫn được giữ lại trong khu di tích đến nay.","nguon":"https://danviet.vn/tham-truong-duc-thanh-noi-thay-giao-nguyen-tat-thanh-day-hoc-hon-110-nam-truoc-2022051813395126-d829136.html"},{"ten":"Cây khế","mo_ta":"Cây khế do phu nhân cụ Nguyễn Thông trồng, đến nay đã hơn một trăm năm tuổi. Theo tư liệu của khu di tích, thầy Thành thường chăm sóc, tưới nước cho cây.","nguon":"https://giaoducthoidai.vn/noi-luu-dau-cua-thay-giao-nguyen-tat-thanh-post671585.html"},{"ten":"Sông Cà Ty","mo_ta":"Trường Dục Thanh nằm bên dòng Cà Ty, con sông chảy qua lòng thị xã Phan Thiết ra biển. Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận, khánh thành ngày 19/5/1986, cũng đứng bên dòng sông này.","nguon":"https://baotanghochiminh.vn/bao-tang-ho-chi-minh-chi-nhanh-binh-thuan.htm"}],"hoi_dap":[{"hoi":"Nguyễn Tất Thành dạy học ở Trường Dục Thanh trong khoảng thời gian nào?","dap":"Từ tháng 9/1910 đến tháng 2/1911, khi Người khoảng hai mươi tuổi.","sai":["Từ năm 1907 đến năm 1909","Từ tháng 6/1911 đến tháng 12/1911","Từ năm 1905 đến năm 1906"],"nguon":"https://baotanghochiminh.vn/ngoi-truong-duc-thanh-noi-luu-dau-cua-chu-tich-ho-chi-minh.htm"},{"hoi":"Ai là những người đứng ra lập Trường Dục Thanh?","dap":"Nguyễn Trọng Lội và Nguyễn Quý Anh, hai người con của nhà thơ yêu nước Nguyễn Thông, trong phong trào Duy Tân.","sai":["Phan Bội Châu và Phan Châu Trinh","Chính quyền thuộc địa Pháp","Cụ Nguyễn Sinh Sắc"],"nguon":"https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html"},{"hoi":"Hội buôn nào dùng lợi nhuận để nuôi Trường Dục Thanh?","dap":"Hội Liên Thành, lập tháng 3/1906 ở Phan Thiết, chuyên sản xuất nước mắm.","sai":["Hãng Messageries Maritimes","Đông Kinh Nghĩa Thục","Hãng Chargeurs Réunis"],"nguon":"https://vusta.vn/cong-ty-lien-thanh-1906-1975-tu-hoi-duy-tan-den-doanh-nghiep-hien-dai-p77095.html"},{"hoi":"Thầy Thành phụ trách lớp nào ở Dục Thanh?","dap":"Lớp nhì.","sai":["Lớp tư","Lớp nhất","Lớp đồng ấu"],"nguon":"https://baocantho.com.vn/thang-nam-ve-truong-duc-thanh-nho-thay-nguyen-tat-thanh-a21012.html"},{"hoi":"Ngoài chữ Quốc ngữ và chữ Hán, thầy Thành còn kiêm dạy môn gì?","dap":"Môn thể dục; khi cần, thầy còn dạy thay tiếng Pháp.","sai":["Môn hội họa","Môn âm nhạc","Môn địa chất"],"nguon":"https://baotanghochiminh.vn/ngoi-truong-duc-thanh-noi-luu-dau-cua-chu-tich-ho-chi-minh.htm"},{"hoi":"Ngọa Du Sào do ai dựng và vào năm nào?","dap":"Nhà thơ, nhà yêu nước Nguyễn Thông dựng năm 1880.","sai":["Nguyễn Tất Thành dựng năm 1910","Hội Liên Thành dựng năm 1906","Người Pháp dựng năm 1920"],"nguon":"https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html"},{"hoi":"Khi trường hoạt động, Ngọa Du Sào được dùng làm gì?","dap":"Làm thư viện của trường; thầy Thành đọc sách báo và soạn bài ở đây.","sai":["Làm kho chứa nước mắm","Làm nhà bếp","Làm trạm gác của lính Pháp"],"nguon":"https://baocantho.com.vn/thang-nam-ve-truong-duc-thanh-nho-thay-nguyen-tat-thanh-a21012.html"},{"hoi":"Lớp học ở Dục Thanh ngày nay có bao nhiêu bộ bàn ghế học trò?","dap":"21 bộ.","sai":["12 bộ","30 bộ","50 bộ"],"nguon":"https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html"},{"hoi":"Cây khế trong sân trường do ai trồng?","dap":"Phu nhân cụ Nguyễn Thông.","sai":["Thầy Nguyễn Tất Thành","Học trò lớp nhì","Cụ Trương Gia Mô"],"nguon":"https://danviet.vn/tham-truong-duc-thanh-noi-thay-giao-nguyen-tat-thanh-day-hoc-hon-110-nam-truoc-2022051813395126-d829136.html"},{"hoi":"Khu di tích Trường Dục Thanh được xếp hạng di tích lịch sử – văn hóa cấp quốc gia vào năm nào?","dap":"Năm 1986; cùng năm đó Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận được khánh thành (19/5/1986).","sai":["Năm 1975","Năm 1995","Năm 2005"],"nguon":"https://baotanghochiminh.vn/bao-tang-ho-chi-minh-chi-nhanh-binh-thuan.htm"},{"hoi":"Ai giới thiệu Nguyễn Tất Thành với các nhà Duy Tân ở Phan Thiết?","dap":"Cụ Trương Gia Mô, một nhà nho yêu nước quen biết cụ Nguyễn Sinh Sắc.","sai":["Cụ Phan Châu Trinh","Cụ Huỳnh Thúc Kháng","Một viên quan người Pháp"],"nguon":"https://thanhnien.vn/thay-thanh-o-truong-duc-thanh-185292454.htm"},{"hoi":"Rời Phan Thiết tháng 2/1911, Nguyễn Tất Thành đi đâu?","dap":"Vào Sài Gòn; bốn tháng sau, ngày 5/6/1911, Người xuống tàu sang Pháp.","sai":["Trở về Huế","Ra Hà Nội","Sang Xiêm (Thái Lan)"],"nguon":"https://tuoitre.vn/nld/thoi-su-trong-nuoc/sai-gon-voi-nguyen-tat-thanh-20110522115636410.htm"}],"nguon":[{"ten":"Bảo tàng Hồ Chí Minh – Ngôi trường Dục Thanh, nơi lưu dấu của Chủ tịch Hồ Chí Minh","url":"https://baotanghochiminh.vn/ngoi-truong-duc-thanh-noi-luu-dau-cua-chu-tich-ho-chi-minh.htm"},{"ten":"Bảo tàng Hồ Chí Minh – Chi nhánh Bình Thuận","url":"https://baotanghochiminh.vn/bao-tang-ho-chi-minh-chi-nhanh-binh-thuan.htm"},{"ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1 (hochiminh.vn)","url":"https://hochiminh.vn/book/cuoc-doi-su-nghiep/bien-nien-tieu-su-ho-chi-minh/ho-chi-minh-bien-nien-tieu-su-tap-1-19-5-1890-1929-21?categoryId=102001151"},{"ten":"Báo Chính phủ – Ngày Bác đến Trường Dục Thanh","url":"https://baochinhphu.vn/ngay-bac-den-truong-duc-thanh-10278722.htm"},{"ten":"VnExpress – Nơi Chủ tịch Hồ Chí Minh từng dạy học tại Phan Thiết","url":"https://vnexpress.net/noi-chu-tich-ho-chi-minh-tung-day-hoc-tai-phan-thiet-5114971.html"},{"ten":"Thanh Niên – Thầy Thành ở trường Dục Thanh","url":"https://thanhnien.vn/thay-thanh-o-truong-duc-thanh-185292454.htm"},{"ten":"Tuổi Trẻ – Thầy giáo Nguyễn Tất Thành","url":"https://tuoitre.vn/thay-giao-nguyen-tat-thanh-230227.htm"},{"ten":"Giáo dục & Thời đại – Nơi lưu dấu của thầy giáo Nguyễn Tất Thành","url":"https://giaoducthoidai.vn/noi-luu-dau-cua-thay-giao-nguyen-tat-thanh-post671585.html"},{"ten":"Báo Văn hóa – Kỳ 1: Về Dục Thanh nghe kể chuyện Bác Hồ dạy học","url":"https://baovanhoa.vn/van-hoa/ky-1-ve-duc-thanh-nghe-ke-chuyen-bac-ho-day-hoc-255667.html"},{"ten":"Báo Văn hóa – Kỳ 2: “Địa chỉ đỏ” về nguồn thiêng liêng","url":"https://baovanhoa.vn/van-hoa/ky-2-dia-chi-do-ve-nguon-thieng-lieng-256668.html"},{"ten":"Báo Cần Thơ – Tháng Năm, về Trường Dục Thanh nhớ thầy Nguyễn Tất Thành","url":"https://baocantho.com.vn/thang-nam-ve-truong-duc-thanh-nho-thay-nguyen-tat-thanh-a21012.html"},{"ten":"Dân Việt – Trường Dục Thanh, nơi thầy giáo Nguyễn Tất Thành dạy học","url":"https://danviet.vn/tham-truong-duc-thanh-noi-thay-giao-nguyen-tat-thanh-day-hoc-hon-110-nam-truoc-2022051813395126-d829136.html"},{"ten":"Người Lao Động – Phong trào Duy Tân ở Bình Thuận đã khai sinh ra Liên Thành","url":"https://tuoitre.vn/nld/hoi-nhap/bai-1-phong-trao-duy-tan-o-binh-thuan-da-khai-sinh-ra-lien-thanh-20090522104457589.htm"},{"ten":"VUSTA – Công ty Liên Thành (1906–1975): Từ hội Duy Tân đến doanh nghiệp hiện đại","url":"https://vusta.vn/cong-ty-lien-thanh-1906-1975-tu-hoi-duy-tan-den-doanh-nghiep-hien-dai-p77095.html"},{"ten":"Người Lao Động – Sài Gòn với Nguyễn Tất Thành","url":"https://tuoitre.vn/nld/thoi-su-trong-nuoc/sai-gon-voi-nguyen-tat-thanh-20110522115636410.htm"},{"ten":"Tạp chí Quốc phòng toàn dân – Vì lợi ích trăm năm thì phải trồng người","url":"https://tapchiqptd.vn/vi/loi-bac-day-ngay-nay-nam-xua/vi-loi-ich-tram-nam-thi-phai-trong-nguoi/12400.html"}],"so_chu":1184},"G04":{"ma":"G04","tieu_de":"Bến Nhà Rồng – Hai bàn tay và một con tàu","sapo":"Đầu năm 1911, Nguyễn Tất Thành đến Sài Gòn, học nghề, sống giữa những người thợ và tìm cách ra nước ngoài. Ngày 5/6/1911, với cái tên Văn Ba, người phụ bếp hai mươi mốt tuổi theo tàu Amiral Latouche-Tréville rời Sài Gòn, mở đầu ba mươi năm bôn ba tìm đường cứu nước.","sapo_en":"In early 1911 Nguyễn Tất Thành came to Saigon, trained as a mechanic and looked for a way abroad. On 5 June 1911, under the name Văn Ba, he left as a kitchen hand aboard the Amiral Latouche-Tréville, beginning thirty years of travel in search of a path to national liberation.","bia":{"src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Bốn tháng ở Sài Gòn","text":"Tháng 2/1911, rời Phan Thiết, Nguyễn Tất Thành đến Sài Gòn – thành phố cảng lớn của xứ Nam Kỳ thuộc Pháp, nơi những con tàu viễn dương đi về giữa Đông Dương và chính quốc. Người tạm trú tại Liên Thành phân cuộc, chi nhánh của hội Liên Thành ở Chợ Lớn, nay là ngôi nhà số 5 Châu Văn Liêm. Đây cũng là nơi gặp gỡ của nhiều nhà yêu nước trong phong trào Duy Tân. Ngày 16/11/1988, ngôi nhà được công nhận là di tích lịch sử quốc gia.\n\nTrong khoảng ba tháng đầu năm 1911, Người theo học Trường Cơ khí Á châu (École des Mécaniciens Asiatiques), người Sài Gòn quen gọi là trường Bá Nghệ. Trường do người Pháp lập năm 1906 để đào tạo thợ máy và nhân viên hàng hải; ngày nay là Trường Cao đẳng Kỹ thuật Cao Thắng.\n\nHọc nghề, sống giữa những người thợ, lui tới bến cảng, Nguyễn Tất Thành chứng kiến tận mắt đời sống cực nhọc của người lao động dưới chế độ thuộc địa. Ý định ra nước ngoài để xem các nước khác làm thế nào dần trở thành một kế hoạch cụ thể.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","chu_thich":"Sông Sài Gòn đoạn mũi Pointe des Blagueurs, tàu viễn dương Paul-Lecat neo trên sông – bưu ảnh đầu thế kỷ XX.","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Trường Bá Nghệ – nơi Nguyễn Tất Thành học nghề đầu năm 1911 – cũng là nơi người thợ máy Tôn Đức Thắng từng theo học. Hai học trò của ngôi trường này về sau đều trở thành Chủ tịch nước.","nguon_ten":"nhandan.vn","doc":2},{"loai":"doan","tieu_de":"“Đây, tiền đây”","text":"Cuốn sách “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên kể lại một cuộc trò chuyện ở Sài Gòn giữa Nguyễn Tất Thành và người bạn tên Lê. Anh hỏi bạn có yêu nước không, có giữ được bí mật không, rồi mới nói ra dự định của mình.\n\nKhi người bạn băn khoăn không biết lấy đâu ra tiền để đi, Nguyễn Tất Thành giơ hai bàn tay lên: “Đây, tiền đây”. Anh nói rằng họ sẽ làm việc, làm bất cứ việc gì để sống và để đi. Câu chuyện “hai bàn tay” từ đó trở thành hình ảnh tiêu biểu cho ý chí tự lực của người thanh niên yêu nước: không tiền bạc, không người đỡ đầu, chỉ có sức lao động và khát vọng tìm hiểu thế giới.","doc":3},{"loai":"anh","src":"textures/bai/G04_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Sài Gòn – Bến Nhà Rồng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"trich","text":"Tôi muốn đi ra ngoài, xem nước Pháp và các nước khác. Sau khi xem xét họ làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta.","nguoi":"Nguyễn Tất Thành (lời kể trong sách của Trần Dân Tiên)","nguon_ten":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”; dẫn theo Tuổi Trẻ: https://tuoitre.vn/5-6-1911-chuyen-ra-di-lich-su-204166.htm","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_museum_saigon.jpg","chu_thich":"Bến Nhà Rồng ngày nay — Bảo tàng Hồ Chí Minh, chi nhánh TP. Hồ Chí Minh","credit":"Ảnh: Gary Todd · CC0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Người phụ bếp Văn Ba","text":"Ngày 3/6/1911, với cái tên Văn Ba, Nguyễn Tất Thành được nhận làm phụ bếp trên tàu Amiral Latouche-Tréville (Đô đốc Latouche-Tréville) của hãng Chargeurs Réunis, với đồng lương 45 franc mỗi tháng. Theo nhà nghiên cứu Nguyễn Đình Đầu, anh Ba đến xin việc tại văn phòng của hãng tàu trên lầu một quán cà phê La Rotonde, số 2 đường Catinat (nay là đường Đồng Khởi).\n\nAmiral Latouche-Tréville là tàu chở hàng kiêm chở khách, hạ thủy năm 1904, trọng tải 5.572 tấn, chạy tuyến Pháp – Đông Dương và hoạt động đến năm 1929. Công việc phụ bếp trên một con tàu viễn dương rất nặng nhọc. Nhưng với Văn Ba, đó là con đường duy nhất để tận mắt nhìn thấy các nước phương Tây “làm như thế nào”.","doc":5},{"loai":"ban_co_biet","text":"Người Việt khi ấy quen gọi hãng Chargeurs Réunis – chủ tàu Amiral Latouche-Tréville – là “hãng Năm Sao”. Con tàu phục vụ từ năm 1904 đến năm 1929.","nguon_ten":"tapchihochiminh.hcma.vn","doc":6},{"loai":"ban_co_biet","text":"Con tàu mang tên đô đốc Pháp Louis-René Levassor de Latouche-Tréville (1745 – 1804), người đã đẩy lui các cuộc tấn công của đô đốc Anh Horatio Nelson vào Boulogne tháng 8/1801.","nguon_ten":"napoleon-empire.org","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_tuong_nguyen_ai_quoc_nguyen_tat_thanh_nha_tuong_.jpg","chu_thich":"Tượng Nguyễn Tất Thành tại Bến Nhà Rồng","credit":"Ảnh: vi:User:TDA · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Tòa nhà có đôi rồng chầu","text":"Cái tên Bến Nhà Rồng gắn với tòa nhà trụ sở của Tổng công ty Vận tải Hoàng đế (Messageries Impériales), được xây từ giữa năm 1862 và hoàn thành năm 1863 bên sông Sài Gòn. Trên nóc, người ta đắp đôi rồng chầu mặt nguyệt theo mô típ “lưỡng long chầu nguyệt” quen thuộc của kiến trúc Việt; người dân vì thế gọi tòa nhà là Nhà Rồng.\n\nNăm 1870, hãng đổi tên thành Messageries Maritimes (Công ty Vận tải Hàng hải). Tòa nhà với hàng hiên vòm, cửa chớp và mái ngói đỏ dần trở thành một dấu mốc quen thuộc của cảng Sài Gòn, chứng kiến dòng người, dòng hàng hóa đi về giữa thuộc địa và chính quốc suốt nhiều thập kỷ.","doc":8},{"loai":"ban_co_biet","text":"Đôi rồng trên nóc Nhà Rồng từng “đổi dáng” nhiều lần: năm 1870, mặt nguyệt ở giữa bị thay bằng biểu tượng vương miện, mỏ neo và đầu ngựa của hãng Messageries Maritimes – vì thế dân gian gọi đây là “hãng Đầu Ngựa”; sau năm 1955, đôi rồng được thay bằng đôi rồng khác quay đầu ra ngoài.","nguon_ten":"svhtt.hochiminhcity.gov.vn","doc":9},{"loai":"anh","src":"textures/bai/G04_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Sài Gòn – Bến Nhà Rồng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Rời bến ngày 5/6/1911","text":"Ngày 5/6/1911, tàu Amiral Latouche-Tréville rời Sài Gòn. Hải trình đưa người phụ bếp trẻ qua Singapore, Colombo (Tích Lan, nay là Sri Lanka), vượt kênh Suez, ghé Port Said (Ai Cập) rồi cập cảng Marseille ngày 6/7/1911; sau đó tàu vòng lên Le Havre, tới nơi ngày 15/7/1911. Từ đây bắt đầu ba mươi năm Người bôn ba khắp năm châu trước khi trở về Tổ quốc năm 1941.\n\nVị trí chính xác nơi con tàu neo đậu hôm ấy vẫn được giới nghiên cứu bàn luận. Nhà nghiên cứu Nguyễn Đình Đầu cho rằng bến Nhà Rồng khi đó chủ yếu dành cho tàu của hãng Messageries Maritimes, còn tàu của hãng Chargeurs Réunis cập cầu tàu lớn của thương cảng ở đầu đường Charner (nay là đường Nguyễn Huệ). Dù chi tiết ấy thế nào, Bến Nhà Rồng đã trở thành biểu tượng của cuộc ra đi, và ngày 5/6 hằng năm được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước.","doc":10},{"loai":"anh","src":"textures/bai/G04_v4.jpg","chu_thich":"Một góc không gian 3D tái hiện Sài Gòn – Bến Nhà Rồng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Từ trụ sở hãng tàu đến bảo tàng","text":"Năm 1979, tòa Nhà Rồng được chọn làm nơi lưu niệm Chủ tịch Hồ Chí Minh. Ngày 30/10/1995, nơi đây chính thức trở thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Các phòng trưng bày giới thiệu cuộc đời, sự nghiệp của Người, đặc biệt là hành trình ra đi tìm đường cứu nước năm 1911.\n\nĐứng trên bến sông hôm nay, nhìn dòng Sài Gòn vẫn chảy ra biển, người xem dễ hình dung ngày tháng Sáu năm ấy: một thanh niên hai mươi mốt tuổi mang tên Văn Ba bước lên cầu tàu với đôi bàn tay trắng, mang theo câu hỏi lớn về vận mệnh của dân tộc mình.","doc":11},{"loai":"moc","items":[["1862 – 1863","Xây tòa trụ sở hãng Messageries Impériales – Nhà Rồng"],["1870","Hãng đổi tên thành Messageries Maritimes"],["1904","Tàu Amiral Latouche-Tréville hạ thủy"],["1906","Người Pháp lập Trường Cơ khí Á châu (trường Bá Nghệ)"],["2/1911","Nguyễn Tất Thành đến Sài Gòn, học nghề ở trường Bá Nghệ"],["3/6/1911","Được nhận làm phụ bếp trên tàu với tên Văn Ba"],["5/6/1911","Tàu rời Sài Gòn"],["6/7/1911","Tàu cập cảng Marseille"],["1979","Nhà Rồng trở thành nơi lưu niệm Chủ tịch Hồ Chí Minh"],["16/11/1988","Nhà số 5 Châu Văn Liêm được công nhận di tích lịch sử quốc gia"],["30/10/1995","Thành lập Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh"]]}],"doc":[{"i":-1,"t":"Bến Nhà Rồng – Hai bàn tay và một con tàu. Đầu năm 1911, Nguyễn Tất Thành đến Sài Gòn, học nghề, sống giữa những người thợ và tìm cách ra nước ngoài. Ngày 5/6/1911, với cái tên Văn Ba, người phụ bếp hai mươi mốt tuổi theo tàu Amiral Latouche-Tréville rời Sài Gòn, mở đầu ba mươi năm bôn ba tìm đường cứu nước."},{"t":"Bốn tháng ở Sài Gòn. Tháng 2/1911, rời Phan Thiết, Nguyễn Tất Thành đến Sài Gòn – thành phố cảng lớn của xứ Nam Kỳ thuộc Pháp, nơi những con tàu viễn dương đi về giữa Đông Dương và chính quốc. Người tạm trú tại Liên Thành phân cuộc, chi nhánh của hội Liên Thành ở Chợ Lớn, nay là ngôi nhà số 5 Châu Văn Liêm. Đây cũng là nơi gặp gỡ của nhiều nhà yêu nước trong phong trào Duy Tân. Ngày 16/11/1988, ngôi nhà được công nhận là di tích lịch sử quốc gia. Trong khoảng ba tháng đầu năm 1911, Người theo học Trường Cơ khí Á châu (École des Mécaniciens Asiatiques), người Sài Gòn quen gọi là trường Bá Nghệ. Trường do người Pháp lập năm 1906 để đào tạo thợ máy và nhân viên hàng hải; ngày nay là Trường Cao đẳng Kỹ thuật Cao Thắng. Học nghề, sống giữa những người thợ, lui tới bến cảng, Nguyễn Tất Thành chứng kiến tận mắt đời sống cực nhọc của người lao động dưới chế độ thuộc địa. Ý định ra nước ngoài để xem các nước khác làm thế nào dần trở thành một kế hoạch cụ thể."},{"t":"Bạn có biết? Trường Bá Nghệ – nơi Nguyễn Tất Thành học nghề đầu năm 1911 – cũng là nơi người thợ máy Tôn Đức Thắng từng theo học. Hai học trò của ngôi trường này về sau đều trở thành Chủ tịch nước."},{"t":"“Đây, tiền đây”. Cuốn sách “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên kể lại một cuộc trò chuyện ở Sài Gòn giữa Nguyễn Tất Thành và người bạn tên Lê. Anh hỏi bạn có yêu nước không, có giữ được bí mật không, rồi mới nói ra dự định của mình. Khi người bạn băn khoăn không biết lấy đâu ra tiền để đi, Nguyễn Tất Thành giơ hai bàn tay lên: “Đây, tiền đây”. Anh nói rằng họ sẽ làm việc, làm bất cứ việc gì để sống và để đi. Câu chuyện “hai bàn tay” từ đó trở thành hình ảnh tiêu biểu cho ý chí tự lực của người thanh niên yêu nước: không tiền bạc, không người đỡ đầu, chỉ có sức lao động và khát vọng tìm hiểu thế giới."},{"t":"Tôi muốn đi ra ngoài, xem nước Pháp và các nước khác. Sau khi xem xét họ làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta. — Nguyễn Tất Thành (lời kể trong sách của Trần Dân Tiên)"},{"t":"Người phụ bếp Văn Ba. Ngày 3/6/1911, với cái tên Văn Ba, Nguyễn Tất Thành được nhận làm phụ bếp trên tàu Amiral Latouche-Tréville (Đô đốc Latouche-Tréville) của hãng Chargeurs Réunis, với đồng lương 45 franc mỗi tháng. Theo nhà nghiên cứu Nguyễn Đình Đầu, anh Ba đến xin việc tại văn phòng của hãng tàu trên lầu một quán cà phê La Rotonde, số 2 đường Catinat (nay là đường Đồng Khởi). Amiral Latouche-Tréville là tàu chở hàng kiêm chở khách, hạ thủy năm 1904, trọng tải 5.572 tấn, chạy tuyến Pháp – Đông Dương và hoạt động đến năm 1929. Công việc phụ bếp trên một con tàu viễn dương rất nặng nhọc. Nhưng với Văn Ba, đó là con đường duy nhất để tận mắt nhìn thấy các nước phương Tây “làm như thế nào”."},{"t":"Bạn có biết? Người Việt khi ấy quen gọi hãng Chargeurs Réunis – chủ tàu Amiral Latouche-Tréville – là “hãng Năm Sao”. Con tàu phục vụ từ năm 1904 đến năm 1929."},{"t":"Bạn có biết? Con tàu mang tên đô đốc Pháp Louis-René Levassor de Latouche-Tréville (1745 – 1804), người đã đẩy lui các cuộc tấn công của đô đốc Anh Horatio Nelson vào Boulogne tháng 8/1801."},{"t":"Tòa nhà có đôi rồng chầu. Cái tên Bến Nhà Rồng gắn với tòa nhà trụ sở của Tổng công ty Vận tải Hoàng đế (Messageries Impériales), được xây từ giữa năm 1862 và hoàn thành năm 1863 bên sông Sài Gòn. Trên nóc, người ta đắp đôi rồng chầu mặt nguyệt theo mô típ “lưỡng long chầu nguyệt” quen thuộc của kiến trúc Việt; người dân vì thế gọi tòa nhà là Nhà Rồng. Năm 1870, hãng đổi tên thành Messageries Maritimes (Công ty Vận tải Hàng hải). Tòa nhà với hàng hiên vòm, cửa chớp và mái ngói đỏ dần trở thành một dấu mốc quen thuộc của cảng Sài Gòn, chứng kiến dòng người, dòng hàng hóa đi về giữa thuộc địa và chính quốc suốt nhiều thập kỷ."},{"t":"Bạn có biết? Đôi rồng trên nóc Nhà Rồng từng “đổi dáng” nhiều lần: năm 1870, mặt nguyệt ở giữa bị thay bằng biểu tượng vương miện, mỏ neo và đầu ngựa của hãng Messageries Maritimes – vì thế dân gian gọi đây là “hãng Đầu Ngựa”; sau năm 1955, đôi rồng được thay bằng đôi rồng khác quay đầu ra ngoài."},{"t":"Rời bến ngày 5/6/1911. Ngày 5/6/1911, tàu Amiral Latouche-Tréville rời Sài Gòn. Hải trình đưa người phụ bếp trẻ qua Singapore, Colombo (Tích Lan, nay là Sri Lanka), vượt kênh Suez, ghé Port Said (Ai Cập) rồi cập cảng Marseille ngày 6/7/1911; sau đó tàu vòng lên Le Havre, tới nơi ngày 15/7/1911. Từ đây bắt đầu ba mươi năm Người bôn ba khắp năm châu trước khi trở về Tổ quốc năm 1941. Vị trí chính xác nơi con tàu neo đậu hôm ấy vẫn được giới nghiên cứu bàn luận. Nhà nghiên cứu Nguyễn Đình Đầu cho rằng bến Nhà Rồng khi đó chủ yếu dành cho tàu của hãng Messageries Maritimes, còn tàu của hãng Chargeurs Réunis cập cầu tàu lớn của thương cảng ở đầu đường Charner (nay là đường Nguyễn Huệ). Dù chi tiết ấy thế nào, Bến Nhà Rồng đã trở thành biểu tượng của cuộc ra đi, và ngày 5/6 hằng năm được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước."},{"t":"Từ trụ sở hãng tàu đến bảo tàng. Năm 1979, tòa Nhà Rồng được chọn làm nơi lưu niệm Chủ tịch Hồ Chí Minh. Ngày 30/10/1995, nơi đây chính thức trở thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Các phòng trưng bày giới thiệu cuộc đời, sự nghiệp của Người, đặc biệt là hành trình ra đi tìm đường cứu nước năm 1911. Đứng trên bến sông hôm nay, nhìn dòng Sài Gòn vẫn chảy ra biển, người xem dễ hình dung ngày tháng Sáu năm ấy: một thanh niên hai mươi mốt tuổi mang tên Văn Ba bước lên cầu tàu với đôi bàn tay trắng, mang theo câu hỏi lớn về vận mệnh của dân tộc mình."}],"hien_vat":[{"ten":"Tòa Nhà Rồng","mo_ta":"Xây từ giữa năm 1862, hoàn thành năm 1863, tòa nhà là trụ sở của hãng Messageries Impériales (từ năm 1870 đổi tên là Messageries Maritimes). Năm 1979 nơi đây trở thành nơi lưu niệm Chủ tịch Hồ Chí Minh; từ ngày 30/10/1995 là Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh.","nguon":"https://bennharong.vn/gioi-thieu-bao-tang"},{"ten":"Đôi rồng trên nóc","mo_ta":"Đôi rồng chầu mặt nguyệt theo mô típ “lưỡng long chầu nguyệt” đã đặt tên cho tòa nhà. Năm 1870, mặt nguyệt bị thay bằng biểu tượng vương miện, mỏ neo, đầu ngựa của hãng; sau năm 1955, đôi rồng được thay bằng đôi rồng khác quay đầu ra ngoài.","nguon":"https://svhtt.hochiminhcity.gov.vn/tin-chi-tiet/-/chi-tiet/bao-tang-ho-chi-minh-chi-nhanh-thanh-pho-ho-chi-minh-19084-2015.html"},{"ten":"Tàu Amiral Latouche-Tréville","mo_ta":"Tàu chở hàng kiêm chở khách của hãng Chargeurs Réunis (người Việt gọi là hãng Năm Sao), hạ thủy năm 1904, trọng tải 5.572 tấn, chạy tuyến Pháp – Đông Dương đến năm 1929. Ngày 5/6/1911, tàu rời Sài Gòn và cập cảng Marseille ngày 6/7/1911.","nguon":"https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318"},{"ten":"Cầu lên tàu","mo_ta":"Ngày 3/6/1911, Nguyễn Tất Thành với tên Văn Ba được nhận làm phụ bếp trên tàu, lương 45 franc mỗi tháng. Hai ngày sau, người phụ bếp trẻ theo tàu rời Sài Gòn, bắt đầu hành trình tìm đường cứu nước.","nguon":"https://congnghieptauthuyvietnam.vn/new/hanh-trinh-cua-con-tau-amiral-latouche-treville-dua-nguyen-tat-thanh-ra-di-tim-duong-cuu-nuoc.html"},{"ten":"Bến sông Sài Gòn","mo_ta":"Dọc sông Sài Gòn là các bến, cầu tàu nơi tàu viễn dương neo đậu, bốc dỡ hàng hóa. Nhà nghiên cứu Nguyễn Đình Đầu cho rằng bến Nhà Rồng khi ấy chủ yếu dành cho tàu Messageries Maritimes, còn tàu Chargeurs Réunis cập cầu tàu lớn của thương cảng ở đầu đường Charner (nay là Nguyễn Huệ).","nguon":"https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm"}],"hoi_dap":[{"hoi":"Nguyễn Tất Thành rời Sài Gòn ra đi tìm đường cứu nước vào ngày nào?","dap":"Ngày 5/6/1911, trên tàu Amiral Latouche-Tréville.","sai":["Ngày 19/5/1911","Ngày 2/9/1911","Ngày 3/2/1911"],"nguon":"https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318"},{"hoi":"Khi xin việc trên tàu, Nguyễn Tất Thành lấy tên là gì?","dap":"Văn Ba.","sai":["Lý Thụy","Nguyễn Ái Quốc","Tống Văn Sơ"],"nguon":"https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm"},{"hoi":"Người làm công việc gì trên tàu Amiral Latouche-Tréville?","dap":"Phụ bếp.","sai":["Thủy thủ lái tàu","Thợ máy","Nhân viên điện báo"],"nguon":"https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318"},{"hoi":"Tàu Amiral Latouche-Tréville thuộc hãng tàu nào?","dap":"Hãng Chargeurs Réunis, người Việt quen gọi là hãng Năm Sao.","sai":["Hãng Messageries Maritimes","Hãng Compagnie Générale Transatlantique","Hãng P&O của Anh"],"nguon":"https://congnghieptauthuyvietnam.vn/new/hanh-trinh-cua-con-tau-amiral-latouche-treville-dua-nguyen-tat-thanh-ra-di-tim-duong-cuu-nuoc.html"},{"hoi":"Tòa Nhà Rồng ban đầu là trụ sở của hãng nào?","dap":"Hãng Messageries Impériales, từ năm 1870 đổi tên là Messageries Maritimes.","sai":["Hãng Chargeurs Réunis","Ngân hàng Đông Dương","Sở Thương chính Sài Gòn"],"nguon":"https://bennharong.vn/gioi-thieu-bao-tang"},{"hoi":"Vì sao tòa nhà được gọi là Nhà Rồng?","dap":"Vì trên nóc có đôi rồng chầu mặt nguyệt theo mô típ “lưỡng long chầu nguyệt”.","sai":["Vì được xây trên đất của một làng tên Rồng","Vì do vua Tự Đức ban tên","Vì bên trong đặt một tượng rồng bằng đồng"],"nguon":"https://svhtt.hochiminhcity.gov.vn/tin-chi-tiet/-/chi-tiet/bao-tang-ho-chi-minh-chi-nhanh-thanh-pho-ho-chi-minh-19084-2015.html"},{"hoi":"Trường Bá Nghệ, nơi Nguyễn Tất Thành học nghề đầu năm 1911, nay là trường nào?","dap":"Trường Cao đẳng Kỹ thuật Cao Thắng (TP. Hồ Chí Minh).","sai":["Trường Quốc Học Huế","Trường Petrus Ký","Đại học Bách khoa TP. Hồ Chí Minh"],"nguon":"https://nhandan.vn/ngoi-truong-co-hai-chu-tich-nuoc-tung-theo-hoc-post548579.html"},{"hoi":"Lương tháng của người phụ bếp Văn Ba là bao nhiêu?","dap":"45 franc Pháp mỗi tháng.","sai":["10 franc","100 franc","200 franc"],"nguon":"https://congnghieptauthuyvietnam.vn/new/hanh-trinh-cua-con-tau-amiral-latouche-treville-dua-nguyen-tat-thanh-ra-di-tim-duong-cuu-nuoc.html"},{"hoi":"Tàu Amiral Latouche-Tréville cập cảng Marseille vào ngày nào?","dap":"Ngày 6/7/1911.","sai":["Ngày 5/6/1911","Ngày 15/9/1911","Ngày 25/12/1911"],"nguon":"https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318"},{"hoi":"Nhà Rồng chính thức trở thành Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh vào năm nào?","dap":"Năm 1995 (ngày 30/10/1995).","sai":["Năm 1975","Năm 1985","Năm 2005"],"nguon":"https://bennharong.vn/gioi-thieu-bao-tang"},{"hoi":"Con tàu Amiral Latouche-Tréville mang tên nhân vật lịch sử nào?","dap":"Đô đốc Pháp Latouche-Tréville (1745 – 1804), người từng đẩy lui các cuộc tấn công của Nelson vào Boulogne năm 1801.","sai":["Hoàng đế Napoléon III","Đô đốc Anh Horatio Nelson","Toàn quyền Đông Dương Paul Doumer"],"nguon":"https://www.napoleon-empire.org/en/personalities/latouche_treville.php"},{"hoi":"Ở Sài Gòn năm 1911, Nguyễn Tất Thành tạm trú tại đâu?","dap":"Tại Liên Thành phân cuộc – chi nhánh của hội Liên Thành, nay là nhà số 5 Châu Văn Liêm.","sai":["Dinh Toàn quyền","Nhà thờ Đức Bà","Chợ Bến Thành"],"nguon":"https://vanhoavaphattrien.vn/tp-ho-chi-minh-gia-tri-lich-su-tu-di-tich-quoc-gia-nha-so-5-chau-van-liem-a33966.html"}],"nguon":[{"ten":"Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh: Giới thiệu bảo tàng","url":"https://bennharong.vn/gioi-thieu-bao-tang"},{"ten":"Sở VH-TT TP. Hồ Chí Minh – Bảo tàng Hồ Chí Minh, Chi nhánh TP. Hồ Chí Minh","url":"https://svhtt.hochiminhcity.gov.vn/tin-chi-tiet/-/chi-tiet/bao-tang-ho-chi-minh-chi-nhanh-thanh-pho-ho-chi-minh-19084-2015.html"},{"ten":"Tạp chí Hồ Chí Minh học (Học viện CTQG Hồ Chí Minh) – Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh","url":"https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318"},{"ten":"Công nghiệp Tàu thủy Việt Nam – Hành trình của con tàu Amiral Latouche Tréville","url":"https://congnghieptauthuyvietnam.vn/new/hanh-trinh-cua-con-tau-amiral-latouche-treville-dua-nguyen-tat-thanh-ra-di-tim-duong-cuu-nuoc.html"},{"ten":"Thanh Niên – Nơi Bác ra đi tìm đường cứu nước (Nguyễn Đình Đầu)","url":"https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm"},{"ten":"Tuổi Trẻ – 5-6-1911: Chuyến ra đi lịch sử","url":"https://tuoitre.vn/5-6-1911-chuyen-ra-di-lich-su-204166.htm"},{"ten":"Người Lao Động – Sài Gòn với Nguyễn Tất Thành","url":"https://tuoitre.vn/nld/thoi-su-trong-nuoc/sai-gon-voi-nguyen-tat-thanh-20110522115636410.htm"},{"ten":"Nhân Dân – Ngôi trường có hai Chủ tịch nước từng theo học","url":"https://nhandan.vn/ngoi-truong-co-hai-chu-tich-nuoc-tung-theo-hoc-post548579.html"},{"ten":"Thanh Niên – Ngôi trường người thanh niên yêu nước Nguyễn Tất Thành học tập","url":"https://thanhnien.vn/ngoi-truong-nguoi-thanh-nien-yeu-nuoc-nguyen-tat-thanh-hoc-tap-185260511200325872.htm"},{"ten":"Văn hóa & Phát triển – Giá trị lịch sử từ Di tích quốc gia Nhà số 5 Châu Văn Liêm","url":"https://vanhoavaphattrien.vn/tp-ho-chi-minh-gia-tri-lich-su-tu-di-tich-quoc-gia-nha-so-5-chau-van-liem-a33966.html"},{"ten":"Quận 5 – Nhà số 5 Châu Văn Liêm","url":"https://quan5xinchao.vn/en/nha-luu-niem-bac-ho/"},{"ten":"Wikipédia (đối chiếu) – Latouche-Tréville (navire)","url":"https://fr.wikipedia.org/wiki/Latouche-Tr%C3%A9ville_(navire)"},{"ten":"Napoleon & Empire – Latouche-Tréville","url":"https://www.napoleon-empire.org/en/personalities/latouche_treville.php"}],"so_chu":1129},"G05":{"ma":"G05","tieu_de":"Paris – nơi Văn Ba trở thành Nguyễn Ái Quốc","sapo":"Từ bến cảng Marseille năm 1911 đến căn phòng thuê nhỏ ở ngõ Compoint, nước Pháp là nơi người phụ bếp Văn Ba trở thành Nguyễn Ái Quốc. Ở Paris, bằng nghề sửa ảnh và ngòi bút, Người đưa tiếng nói của dân tộc bị áp bức tới Hội nghị Versailles, tìm thấy con đường giải phóng trong Luận cương của Lê-nin và dựng nên tờ báo Le Paria.","sapo_en":"From the port of Marseille in 1911 to a small rented room in the Impasse Compoint, France was where the ship's kitchen hand Văn Ba became Nguyễn Ái Quốc – petitioning the Versailles Conference, helping found the French Communist Party at Tours and launching the newspaper Le Paria.","bia":{"src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_at_the_age_of_30_in_franc.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Bến Marseille, mùa hè 1911","text":"Ngày 6/7/1911, sau hơn một tháng lênh đênh trên biển, tàu Amiral Latouche-Tréville cập cảng Marseille. Người phụ bếp Văn Ba lần đầu đặt chân lên đất Pháp – đất nước của khẩu hiệu “Tự do, Bình đẳng, Bác ái”. Con tàu sau đó tiếp tục vòng lên cảng Le Havre ở miền Bắc nước Pháp, tới nơi ngày 15/7/1911.\n\nMùa thu năm 1911, Người gửi đơn xin vào học Trường Thuộc địa (École Coloniale) ở Paris, nhưng không được chấp nhận. Những năm tiếp theo, anh làm thuê trên các con tàu, đến nhiều bến cảng ở châu Phi, châu Mỹ, rồi sang nước Anh. Mỗi chặng đường là một bài học về đời sống của người lao động và các dân tộc bị áp bức ở khắp nơi.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_23_10_11_marseille_vue_du_port_btv1b6917711h.jpg","chu_thich":"Cảng Marseille năm 1911, ảnh của hãng Agence Rol (Thư viện Quốc gia Pháp). Tàu Amiral Latouche-Tréville cập cảng này ngày 6/7/1911.","credit":"Ảnh: Agence Rol. Agence photographique (comma · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Trở lại Paris","text":"Theo tiểu sử chính thức, cuối năm 1917 Người từ Anh trở lại Pháp và sống ở Paris; một số nhà nghiên cứu nước ngoài, dựa vào hồ sơ của cảnh sát Pháp, lại cho rằng Người chỉ có mặt ở Paris từ giữa năm 1919. Dù mốc thời gian còn được bàn luận, những năm ở Paris là quãng thời gian quyết định trong cuộc đời hoạt động của Người.\n\nỞ Paris, Nguyễn Tất Thành tham gia nhóm những người Việt Nam yêu nước, sát cánh cùng các bậc đàn anh là nhà Duy Tân Phan Châu Trinh và luật sư Phan Văn Trường, từng ở tại nhà của Phan Văn Trường ở số 6 Villa des Gobelins. Để kiếm sống, Người làm nghề sửa ảnh, rửa ảnh. Thời gian còn lại, Người đọc sách, dự các buổi sinh hoạt chính trị và tập viết báo bằng tiếng Pháp.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_at_the_national_congress_.jpg","chu_thich":"Nguyễn Ái Quốc phát biểu tại Đại hội Tours của Đảng Xã hội Pháp, tháng 12/1920","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Nghề sửa ảnh giúp Nguyễn Ái Quốc tự nuôi sống mình ở Paris. Theo nhiều tài liệu, chính nhà Duy Tân Phan Châu Trinh đã giúp Người làm quen với nghề này.","nguon_ten":"fr.wikipedia.org","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_overview_of_the_congress_tous_comrade_nguyen_ai_.jpg","chu_thich":"Toàn cảnh Đại hội Tours, Nguyễn Ái Quốc ngồi bàn thứ hai bên trái đoàn chủ tịch","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bản yêu sách và cái tên Nguyễn Ái Quốc","text":"Năm 1919, các nước thắng trận trong Chiến tranh thế giới thứ nhất họp hội nghị hòa bình ở Versailles. Ngày 18/6/1919, nhóm người Việt Nam yêu nước ở Pháp gửi tới hội nghị bản “Yêu sách của nhân dân An Nam”. Văn bản chưa đòi độc lập, mà đòi những quyền tự do, dân chủ tối thiểu cho người dân Đông Dương như ân xá tù chính trị, cải cách tư pháp để người bản xứ được bảo đảm về pháp luật như người châu Âu, tự do báo chí và ngôn luận, tự do lập hội và hội họp, tự do đi lại, tự do học tập.\n\nBản yêu sách ký tên Nguyễn Ái Quấc, thay mặt nhóm những người An Nam yêu nước. Nhiều nhà nghiên cứu cho rằng văn bản là trí tuệ chung của cả nhóm, trong đó luật sư Phan Văn Trường góp phần lớn vào việc chấp bút bản tiếng Pháp; còn người trở thành gương mặt công khai của bản yêu sách là Nguyễn Tất Thành. Từ đây, cái tên Nguyễn Ái Quốc – “Nguyễn yêu nước” – khiến giới cầm quyền Pháp phải chú ý, và gắn với Người suốt nhiều năm hoạt động.\n\nCác cường quốc họp ở Versailles không đáp ứng bản yêu sách. Nhưng văn bản đã được truyền đi trong cộng đồng người Việt và trên báo chí, trở thành tiếng nói công khai đầu tiên của người Việt Nam yêu nước trên diễn đàn quốc tế.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_the_can_cuoc_nguyen_ai_quac_ngay_bon_thang_chin_.jpg","chu_thich":"Thẻ căn cước mang tên Nguyễn Ái Quấc (阮愛國), ngày 4/9/1919 – chỉ ít tháng sau khi bản Yêu sách được gửi tới Hội nghị Versailles.","credit":"Ảnh: The government of the Republic of France · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Trên các giấy tờ năm 1919, tên của Người được viết là “Nguyễn Ái Quấc” (阮愛國), như trên thẻ căn cước đề ngày 4/9/1919; về sau cách viết “Nguyễn Ái Quốc” mới trở nên quen thuộc.","nguon_ten":"commons.wikimedia.org","doc":5},{"loai":"doan","tieu_de":"Luận cương của Lê-nin và Đại hội Tours","text":"Tháng 7/1920, trên báo L'Humanité, Nguyễn Ái Quốc đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của V.I. Lê-nin. Văn kiện ấy chỉ ra rằng sự nghiệp giải phóng các dân tộc thuộc địa gắn liền với cuộc đấu tranh của giai cấp vô sản trên toàn thế giới. Bốn mươi năm sau, trong bài “Con đường dẫn tôi đến chủ nghĩa Lênin”, Người kể lại cảm xúc khi đọc văn kiện này.\n\nTừ ngày 25 đến 30/12/1920, Đảng Xã hội Pháp họp đại hội tại thành phố Tours. Nguyễn Ái Quốc dự với tư cách đại biểu Đông Dương, lên diễn đàn tố cáo tội ác của chủ nghĩa thực dân ở Đông Dương và kêu gọi Đảng hành động ủng hộ các dân tộc bị áp bức. Người bỏ phiếu tán thành gia nhập Quốc tế Cộng sản (Quốc tế III), cùng đa số đại biểu lập nên Phân bộ Pháp của Quốc tế Cộng sản, tức Đảng Cộng sản Pháp sau này. Người thanh niên yêu nước trở thành một trong những người sáng lập Đảng Cộng sản Pháp và là người cộng sản Việt Nam đầu tiên.","doc":6},{"loai":"trich","text":"Luận cương của Lê-nin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên.","nguoi":"Hồ Chí Minh","nguon_ten":"“Con đường dẫn tôi đến chủ nghĩa Lênin” (4/1960), Hồ Chí Minh Toàn tập, t.12, Nxb Chính trị quốc gia, H.2011, tr.562; https://hochiminh.vn/book/tac-pham-cua-ho-chi-minh/ho-chi-minh-toan-tap/ho-chi-minh-toan-tap-tap-12-279?categoryId=102001160","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_bibliotheque_nationale_de_france_departement_est.jpg","chu_thich":"Đại biểu Đông Dương Nguyễn Ái Quốc tại Đại hội Marseille, 1921 — ảnh Agence Meurisse, BnF","credit":"Ảnh: Agence de presse Meurisse · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Le Paria – tiếng nói của người cùng khổ","text":"Năm 1921, cùng những người yêu nước đến từ các thuộc địa Pháp ở châu Phi, vùng biển Caribe và nhiều nơi khác, Nguyễn Ái Quốc tham gia sáng lập Hội Liên hiệp thuộc địa (Union intercoloniale). Cuối năm đó, Người dự Đại hội Đảng Cộng sản Pháp ở Marseille với tư cách đại biểu Đông Dương.\n\nNăm 1922, Hội cho ra đời tờ Le Paria (Người cùng khổ); theo tiểu sử chính thức, số đầu tiên ra mắt tháng 4/1922. Nguyễn Ái Quốc là người sáng lập, chủ bút và cây bút chủ lực của tờ báo – tiếng nói chung của nhân dân các thuộc địa Pháp. Tờ báo tồn tại đến năm 1926.\n\nNgười còn viết cho L'Humanité, La Vie ouvrière và nhiều tờ báo khác, viết cả kịch, bằng một lối văn sắc sảo, giàu tính châm biếm. Nhiều bài viết thời kỳ này về sau được tập hợp trong tác phẩm “Bản án chế độ thực dân Pháp” (Le Procès de la colonisation française), xuất bản lần đầu ở Paris năm 1925.","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_portrait_dated_1922_of_ho_chi_minh.jpg","chu_thich":"Chân dung năm 1922","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Le Paria là cơ quan ngôn luận của Hội Liên hiệp thuộc địa, đăng bài của những người đấu tranh vì nhân dân Đông Dương, các thuộc địa Pháp ở châu Phi và vùng Caribe. Tờ báo ra từ năm 1922 đến năm 1926.","nguon_ten":"fr.wikipedia.org","doc":9},{"loai":"anh","src":"textures/ht/ht_anh_impasse_compoint.jpg","chu_thich":"Ngõ Compoint, quận 17 Paris — số 9 là nơi Người ở năm 1921 – 1923","credit":"Ảnh: Rungbachduong at Vietnamese Wikipedia · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Căn phòng số 9 ngõ Compoint","text":"Từ tháng 7/1921, Nguyễn Ái Quốc chuyển đến một căn phòng thuê nhỏ ở số 9 ngõ Compoint, quận 17 – nơi Người ở lâu nhất trong những năm sống ở Paris. Căn phòng chật hẹp, đồ đạc đơn sơ; bên cửa sổ là chiếc bàn nơi Người sửa ảnh kiếm sống và viết báo. Suốt thời gian này, mật thám Pháp theo dõi Người sát sao.\n\nTháng 6/1923, Nguyễn Ái Quốc bí mật rời Paris. Tại Berlin, Người nhận thị thực vào nước Nga Xô viết dưới tên Chen Vang (có tài liệu ghi Cheng Vang), rồi đến Liên Xô vào mùa hè năm ấy. Từ căn phòng nhỏ ở ngõ Compoint, người phụ bếp Văn Ba năm nào đã trở thành một chiến sĩ cách mạng có tầm nhìn quốc tế, sẵn sàng cho chặng đường mới.","doc":10},{"loai":"anh","src":"textures/bai/G05_v4.jpg","chu_thich":"Một góc không gian 3D tái hiện Nước Pháp – Paris","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Thị thực vào nước Nga Xô viết số 1829 được đại diện Liên Xô tại Berlin cấp ngày 16/6/1923 cho một người mang tên “Cheng Vang” – chính là Nguyễn Ái Quốc trên đường bí mật rời nước Pháp.","nguon_ten":"commons.wikimedia.org","doc":11},{"loai":"moc","items":[["6/7/1911","Tàu Amiral Latouche-Tréville cập cảng Marseille"],["15/7/1911","Theo tàu tới Le Havre"],["mùa thu 1911","Gửi đơn xin học Trường Thuộc địa, không được chấp nhận"],["cuối 1917","Trở lại Pháp theo tiểu sử chính thức (hồ sơ cảnh sát Pháp ghi nhận ở Paris từ giữa năm 1919)"],["18/6/1919","Gửi Yêu sách của nhân dân An Nam tới Hội nghị Versailles, ký tên Nguyễn Ái Quấc"],["7/1920","Đọc Luận cương của Lê-nin trên báo L'Humanité"],["25 – 30/12/1920","Đại hội Tours; tham gia sáng lập Đảng Cộng sản Pháp"],["7/1921","Tham gia sáng lập Hội Liên hiệp thuộc địa; chuyển về số 9 ngõ Compoint"],["4/1922","Số đầu tiên của báo Le Paria"],["6/1923","Bí mật rời Paris, qua Berlin sang Liên Xô"],["1925","“Bản án chế độ thực dân Pháp” xuất bản tại Paris"]]}],"doc":[{"i":-1,"t":"Paris – nơi Văn Ba trở thành Nguyễn Ái Quốc. Từ bến cảng Marseille năm 1911 đến căn phòng thuê nhỏ ở ngõ Compoint, nước Pháp là nơi người phụ bếp Văn Ba trở thành Nguyễn Ái Quốc. Ở Paris, bằng nghề sửa ảnh và ngòi bút, Người đưa tiếng nói của dân tộc bị áp bức tới Hội nghị Versailles, tìm thấy con đường giải phóng trong Luận cương của Lê-nin và dựng nên tờ báo Le Paria."},{"t":"Bến Marseille, mùa hè 1911. Ngày 6/7/1911, sau hơn một tháng lênh đênh trên biển, tàu Amiral Latouche-Tréville cập cảng Marseille. Người phụ bếp Văn Ba lần đầu đặt chân lên đất Pháp – đất nước của khẩu hiệu “Tự do, Bình đẳng, Bác ái”. Con tàu sau đó tiếp tục vòng lên cảng Le Havre ở miền Bắc nước Pháp, tới nơi ngày 15/7/1911. Mùa thu năm 1911, Người gửi đơn xin vào học Trường Thuộc địa (École Coloniale) ở Paris, nhưng không được chấp nhận. Những năm tiếp theo, anh làm thuê trên các con tàu, đến nhiều bến cảng ở châu Phi, châu Mỹ, rồi sang nước Anh. Mỗi chặng đường là một bài học về đời sống của người lao động và các dân tộc bị áp bức ở khắp nơi."},{"t":"Trở lại Paris. Theo tiểu sử chính thức, cuối năm 1917 Người từ Anh trở lại Pháp và sống ở Paris; một số nhà nghiên cứu nước ngoài, dựa vào hồ sơ của cảnh sát Pháp, lại cho rằng Người chỉ có mặt ở Paris từ giữa năm 1919. Dù mốc thời gian còn được bàn luận, những năm ở Paris là quãng thời gian quyết định trong cuộc đời hoạt động của Người. Ở Paris, Nguyễn Tất Thành tham gia nhóm những người Việt Nam yêu nước, sát cánh cùng các bậc đàn anh là nhà Duy Tân Phan Châu Trinh và luật sư Phan Văn Trường, từng ở tại nhà của Phan Văn Trường ở số 6 Villa des Gobelins. Để kiếm sống, Người làm nghề sửa ảnh, rửa ảnh. Thời gian còn lại, Người đọc sách, dự các buổi sinh hoạt chính trị và tập viết báo bằng tiếng Pháp."},{"t":"Bạn có biết? Nghề sửa ảnh giúp Nguyễn Ái Quốc tự nuôi sống mình ở Paris. Theo nhiều tài liệu, chính nhà Duy Tân Phan Châu Trinh đã giúp Người làm quen với nghề này."},{"t":"Bản yêu sách và cái tên Nguyễn Ái Quốc. Năm 1919, các nước thắng trận trong Chiến tranh thế giới thứ nhất họp hội nghị hòa bình ở Versailles. Ngày 18/6/1919, nhóm người Việt Nam yêu nước ở Pháp gửi tới hội nghị bản “Yêu sách của nhân dân An Nam”. Văn bản chưa đòi độc lập, mà đòi những quyền tự do, dân chủ tối thiểu cho người dân Đông Dương như ân xá tù chính trị, cải cách tư pháp để người bản xứ được bảo đảm về pháp luật như người châu Âu, tự do báo chí và ngôn luận, tự do lập hội và hội họp, tự do đi lại, tự do học tập. Bản yêu sách ký tên Nguyễn Ái Quấc, thay mặt nhóm những người An Nam yêu nước. Nhiều nhà nghiên cứu cho rằng văn bản là trí tuệ chung của cả nhóm, trong đó luật sư Phan Văn Trường góp phần lớn vào việc chấp bút bản tiếng Pháp; còn người trở thành gương mặt công khai của bản yêu sách là Nguyễn Tất Thành. Từ đây, cái tên Nguyễn Ái Quốc – “Nguyễn yêu nước” – khiến giới cầm quyền Pháp phải chú ý, và gắn với Người suốt nhiều năm hoạt động. Các cường quốc họp ở Versailles không đáp ứng bản yêu sách. Nhưng văn bản đã được truyền đi trong cộng đồng người Việt và trên báo chí, trở thành tiếng nói công khai đầu tiên của người Việt Nam yêu nước trên diễn đàn quốc tế."},{"t":"Bạn có biết? Trên các giấy tờ năm 1919, tên của Người được viết là “Nguyễn Ái Quấc” (阮愛國), như trên thẻ căn cước đề ngày 4/9/1919; về sau cách viết “Nguyễn Ái Quốc” mới trở nên quen thuộc."},{"t":"Luận cương của Lê-nin và Đại hội Tours. Tháng 7/1920, trên báo L'Humanité, Nguyễn Ái Quốc đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của V.I. Lê-nin. Văn kiện ấy chỉ ra rằng sự nghiệp giải phóng các dân tộc thuộc địa gắn liền với cuộc đấu tranh của giai cấp vô sản trên toàn thế giới. Bốn mươi năm sau, trong bài “Con đường dẫn tôi đến chủ nghĩa Lênin”, Người kể lại cảm xúc khi đọc văn kiện này. Từ ngày 25 đến 30/12/1920, Đảng Xã hội Pháp họp đại hội tại thành phố Tours. Nguyễn Ái Quốc dự với tư cách đại biểu Đông Dương, lên diễn đàn tố cáo tội ác của chủ nghĩa thực dân ở Đông Dương và kêu gọi Đảng hành động ủng hộ các dân tộc bị áp bức. Người bỏ phiếu tán thành gia nhập Quốc tế Cộng sản (Quốc tế III), cùng đa số đại biểu lập nên Phân bộ Pháp của Quốc tế Cộng sản, tức Đảng Cộng sản Pháp sau này. Người thanh niên yêu nước trở thành một trong những người sáng lập Đảng Cộng sản Pháp và là người cộng sản Việt Nam đầu tiên."},{"t":"Luận cương của Lê-nin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. — Hồ Chí Minh"},{"t":"Le Paria – tiếng nói của người cùng khổ. Năm 1921, cùng những người yêu nước đến từ các thuộc địa Pháp ở châu Phi, vùng biển Caribe và nhiều nơi khác, Nguyễn Ái Quốc tham gia sáng lập Hội Liên hiệp thuộc địa (Union intercoloniale). Cuối năm đó, Người dự Đại hội Đảng Cộng sản Pháp ở Marseille với tư cách đại biểu Đông Dương. Năm 1922, Hội cho ra đời tờ Le Paria (Người cùng khổ); theo tiểu sử chính thức, số đầu tiên ra mắt tháng 4/1922. Nguyễn Ái Quốc là người sáng lập, chủ bút và cây bút chủ lực của tờ báo – tiếng nói chung của nhân dân các thuộc địa Pháp. Tờ báo tồn tại đến năm 1926. Người còn viết cho L'Humanité, La Vie ouvrière và nhiều tờ báo khác, viết cả kịch, bằng một lối văn sắc sảo, giàu tính châm biếm. Nhiều bài viết thời kỳ này về sau được tập hợp trong tác phẩm “Bản án chế độ thực dân Pháp” (Le Procès de la colonisation française), xuất bản lần đầu ở Paris năm 1925."},{"t":"Bạn có biết? Le Paria là cơ quan ngôn luận của Hội Liên hiệp thuộc địa, đăng bài của những người đấu tranh vì nhân dân Đông Dương, các thuộc địa Pháp ở châu Phi và vùng Caribe. Tờ báo ra từ năm 1922 đến năm 1926."},{"t":"Căn phòng số 9 ngõ Compoint. Từ tháng 7/1921, Nguyễn Ái Quốc chuyển đến một căn phòng thuê nhỏ ở số 9 ngõ Compoint, quận 17 – nơi Người ở lâu nhất trong những năm sống ở Paris. Căn phòng chật hẹp, đồ đạc đơn sơ; bên cửa sổ là chiếc bàn nơi Người sửa ảnh kiếm sống và viết báo. Suốt thời gian này, mật thám Pháp theo dõi Người sát sao. Tháng 6/1923, Nguyễn Ái Quốc bí mật rời Paris. Tại Berlin, Người nhận thị thực vào nước Nga Xô viết dưới tên Chen Vang (có tài liệu ghi Cheng Vang), rồi đến Liên Xô vào mùa hè năm ấy. Từ căn phòng nhỏ ở ngõ Compoint, người phụ bếp Văn Ba năm nào đã trở thành một chiến sĩ cách mạng có tầm nhìn quốc tế, sẵn sàng cho chặng đường mới."},{"t":"Bạn có biết? Thị thực vào nước Nga Xô viết số 1829 được đại diện Liên Xô tại Berlin cấp ngày 16/6/1923 cho một người mang tên “Cheng Vang” – chính là Nguyễn Ái Quốc trên đường bí mật rời nước Pháp."}],"hien_vat":[{"ten":"Số 9 ngõ Compoint","mo_ta":"Căn phòng thuê nhỏ ở số 9 ngõ Compoint, quận 17, là nơi Nguyễn Ái Quốc ở từ tháng 7/1921 đến khi bí mật rời Paris tháng 6/1923. Tại đây Người vừa sửa ảnh kiếm sống, vừa viết báo, trong khi mật thám Pháp thường xuyên theo dõi.","nguon":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"},{"ten":"Bàn sửa ảnh cạnh cửa sổ","mo_ta":"Ở Paris, Nguyễn Ái Quốc kiếm sống bằng nghề sửa ảnh, rửa ảnh. Theo nhiều tài liệu, nhà Duy Tân Phan Châu Trinh đã giúp Người làm quen với nghề này. Cũng trên chiếc bàn ấy, Người viết những bài báo tố cáo chế độ thực dân.","nguon":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"},{"ten":"Chồng báo Le Paria","mo_ta":"Le Paria (Người cùng khổ) là cơ quan ngôn luận của Hội Liên hiệp thuộc địa, ra đời năm 1922 (theo tiểu sử chính thức, số đầu ra tháng 4/1922) và tồn tại đến năm 1926. Nguyễn Ái Quốc là người sáng lập, chủ bút và cây bút chủ lực.","nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9?categoryId=102001152"},{"ten":"Ki-ốt báo","mo_ta":"Những ki-ốt trên phố Paris bày bán L'Humanité – tờ báo đăng bản Sơ thảo luận cương về vấn đề dân tộc và thuộc địa của Lê-nin mà Nguyễn Ái Quốc đọc vào tháng 7/1920. Người cũng viết bài cho L'Humanité và La Vie ouvrière.","nguon":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"},{"ten":"Giá sách","mo_ta":"Những bài báo Nguyễn Ái Quốc viết trong thời gian ở Pháp về sau được tập hợp thành tác phẩm “Bản án chế độ thực dân Pháp” (Le Procès de la colonisation française), xuất bản lần đầu ở Paris năm 1925.","nguon":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"}],"hoi_dap":[{"hoi":"Tàu Amiral Latouche-Tréville đưa Văn Ba cập cảng Marseille vào ngày nào?","dap":"Ngày 6/7/1911.","sai":["Ngày 5/6/1911","Ngày 18/6/1919","Ngày 25/12/1920"],"nguon":"https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318"},{"hoi":"Bản “Yêu sách của nhân dân An Nam” được gửi tới hội nghị nào?","dap":"Hội nghị hòa bình Versailles, ngày 18/6/1919.","sai":["Hội nghị Genève năm 1954","Đại hội Tours năm 1920","Hội nghị Potsdam năm 1945"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9?categoryId=102001152"},{"hoi":"Tên Nguyễn Ái Quốc lần đầu xuất hiện công khai gắn với văn bản nào?","dap":"Bản Yêu sách của nhân dân An Nam gửi Hội nghị Versailles năm 1919 (khi ấy viết là Nguyễn Ái Quấc).","sai":["Báo Thanh niên năm 1925","Tuyên ngôn độc lập năm 1945","Tác phẩm Đường Kách mệnh năm 1927"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9?categoryId=102001152"},{"hoi":"Luật sư, tiến sĩ luật nào ở Paris cùng nhóm người Việt yêu nước góp phần chấp bút bản Yêu sách?","dap":"Phan Văn Trường.","sai":["Phan Bội Châu","Huỳnh Thúc Kháng","Trần Quý Cáp"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Nguyễn Ái Quốc đọc Luận cương của Lê-nin về vấn đề dân tộc và thuộc địa trên tờ báo nào?","dap":"Báo L'Humanité, tháng 7/1920.","sai":["Báo Le Figaro","Báo Le Paria","Báo Le Temps"],"nguon":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"},{"hoi":"Đại hội Tours của Đảng Xã hội Pháp diễn ra khi nào?","dap":"Từ ngày 25 đến 30/12/1920.","sai":["Tháng 7/1920","Tháng 6/1919","Tháng 4/1922"],"nguon":"https://fr.wikipedia.org/wiki/Congr%C3%A8s_de_Tours"},{"hoi":"Tại Đại hội Tours, Nguyễn Ái Quốc bỏ phiếu tán thành điều gì?","dap":"Gia nhập Quốc tế Cộng sản (Quốc tế III); Người trở thành một trong những người sáng lập Đảng Cộng sản Pháp.","sai":["Ở lại Quốc tế II","Rút khỏi Đảng Xã hội Pháp","Thành lập Việt Nam Quốc dân Đảng"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9?categoryId=102001152"},{"hoi":"Báo Le Paria là cơ quan ngôn luận của tổ chức nào?","dap":"Hội Liên hiệp thuộc địa (Union intercoloniale), thành lập năm 1921.","sai":["Đảng Xã hội Pháp","Hội Việt Nam Cách mạng Thanh niên","Quốc tế Nông dân"],"nguon":"https://fr.wikipedia.org/wiki/Le_Paria_(journal)"},{"hoi":"Ở Paris, Nguyễn Ái Quốc kiếm sống chủ yếu bằng nghề gì?","dap":"Sửa ảnh, rửa ảnh.","sai":["Thợ máy ô tô","Dạy tiếng Pháp","Lái xe taxi"],"nguon":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"},{"hoi":"Căn phòng Nguyễn Ái Quốc ở lâu nhất tại Paris nằm ở đâu?","dap":"Số 9 ngõ Compoint, quận 17.","sai":["Phố Rivoli, quận 1","Khu Montmartre, quận 18","Đảo Île de la Cité"],"nguon":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"},{"hoi":"Tháng 6/1923, Nguyễn Ái Quốc rời Paris đi đâu?","dap":"Bí mật qua Berlin sang Liên Xô.","sai":["Về Việt Nam","Sang Quảng Châu (Trung Quốc)","Sang Mỹ"],"nguon":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9?categoryId=102001152"},{"hoi":"Tác phẩm nào tập hợp nhiều bài viết của Nguyễn Ái Quốc thời kỳ ở Pháp, xuất bản ở Paris năm 1925?","dap":"Bản án chế độ thực dân Pháp (Le Procès de la colonisation française).","sai":["Đường Kách mệnh","Nhật ký trong tù","Tuyên ngôn độc lập"],"nguon":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"}],"nguon":[{"ten":"Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh – Tiểu sử Chủ tịch Hồ Chí Minh (1890 – 1969)","url":"https://hochiminh.vn/cuoc-doi-su-nghiep/tieu-su-ho-chi-minh/tieu-su-chu-tich-ho-chi-minh-1890-1969-9?categoryId=102001152"},{"ten":"Hồ Chí Minh Toàn tập, tập 12 (hochiminh.vn)","url":"https://hochiminh.vn/book/tac-pham-cua-ho-chi-minh/ho-chi-minh-toan-tap/ho-chi-minh-toan-tap-tap-12-279?categoryId=102001160"},{"ten":"Tạp chí Hồ Chí Minh học (Học viện CTQG Hồ Chí Minh) – Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh","url":"https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318"},{"ten":"Công nghiệp Tàu thủy Việt Nam – Hành trình của con tàu Amiral Latouche Tréville","url":"https://congnghieptauthuyvietnam.vn/new/hanh-trinh-cua-con-tau-amiral-latouche-treville-dua-nguyen-tat-thanh-ra-di-tim-duong-cuu-nuoc.html"},{"ten":"Wikipédia (đối chiếu) – Hô Chi Minh","url":"https://fr.wikipedia.org/wiki/H%C3%B4_Chi_Minh"},{"ten":"Wikipedia (đối chiếu) – Ho Chi Minh","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Wikipédia (đối chiếu) – Congrès de Tours","url":"https://fr.wikipedia.org/wiki/Congr%C3%A8s_de_Tours"},{"ten":"Wikipédia (đối chiếu) – Le Paria (journal)","url":"https://fr.wikipedia.org/wiki/Le_Paria_(journal)"},{"ten":"Wikimedia Commons – Thẻ căn cước Nguyễn Ái Quấc, 4/9/1919","url":"https://commons.wikimedia.org/wiki/File:Th%E1%BA%BB_c%C4%83n_c%C6%B0%E1%BB%9Bc_Nguy%E1%BB%85n_%C3%81i_Qu%E1%BA%A5c_(%E9%98%AE%E6%84%9B%E5%9C%8B)_-_Ng%C3%A0y_b%E1%BB%91n_th%C3%A1ng_ch%C3%ADn_n%C4%83m_1919.jpg"},{"ten":"Wikimedia Commons – Thị thực số 1829 cấp tại Berlin ngày 16/6/1923 cho Cheng Vang (Nguyễn Ái Quốc)","url":"https://commons.wikimedia.org/wiki/File:Visa_for_entry_into_Russia,_No._1829,_on_June_16,_1923,_issued_by_the_representative_of_the_USSR_in_Berlin,_Germany_to_Cheng_Vang_(Nguyen_Ai_Quoc).jpg"}],"so_chu":1294},"G06":{"ma":"G06","tieu_de":"London sương mù: người thanh niên Việt Nam giữa bếp lò và trang sách","sapo":"Năm 1913, người thanh niên Nguyễn Tất Thành đặt chân đến London, thủ đô của Đế quốc Anh. Những năm cào tuyết, đốt lò, phụ bếp ở đây để lại rất ít giấy tờ. Nhưng chúng cho Người một vốn tiếng Anh, một cái nhìn rộng hơn về phong trào công nhân châu Âu và về số phận các dân tộc thuộc địa. Gian trưng bày này tách bạch điều đã được tư liệu xác nhận với những câu chuyện được lưu truyền.","sapo_en":"In 1913 the young Nguyễn Tất Thành arrived in London, capital of the British Empire, and stayed until 1917. Few records survive of his years shovelling snow, stoking boilers and working in hotel kitchens, so this hall separates what is documented from what is traditional account, including the famous Escoffier story.","bia":{"src":"textures/ht/ht_anh_londen_engeland_sfa006011738.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Đến thủ đô của một đế quốc","text":"Trước đó Người đã qua những chuyến tàu viễn dương và một chặng dừng chân ở Mỹ. Năm 1913, người thanh niên Nguyễn Tất Thành sang nước Anh. Các tài liệu chính thức của Việt Nam đều ghi Người sống ở đây khoảng bốn năm, từ 1913 đến 1917. London khi ấy là trung tâm của Đế quốc Anh. Tàu từ Ấn Độ, Miến Điện hay châu Phi cập bến nơi đây. Khách sạn xa hoa đứng cách không xa những dãy nhà trọ chật chội của người lao động nhập cư.\n\nĐây là quãng đời để lại rất ít giấy tờ gốc. Phần lớn những gì chúng ta biết đến từ lời kể sau này, trước hết là cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” ký bút danh Trần Dân Tiên. Phần còn lại đến từ vài lá thư Người gửi đi. Vì vậy, gian trưng bày này tách bạch điều có tư liệu xác nhận với câu chuyện được lưu truyền.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_plaque_new_zealand_house_80_haymarke.jpg","chu_thich":"Biển tưởng niệm Hồ Chí Minh trên tường New Zealand House, số 80 phố Haymarket, London – nơi trước đây là khách sạn Carlton","credit":"Ảnh: Spudgun67 · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cào tuyết, đốt lò: những ngày đầu","text":"Theo lời kể được lưu truyền, việc đầu tiên Người nhận ở London là cào tuyết cho một trường học. Báo chí trong nước đã nhiều lần nhắc lại chi tiết này. Mùa đông nước Anh ẩm và buốt. Người cào tuyết phải có mặt từ sáng sớm để dọn lối đi trước giờ học.\n\nSau đó Người chuyển sang làm thợ đốt lò. Mỗi ngày, từ lúc trời chưa sáng, người thợ phải xuống tầng hầm nhóm lửa, xúc than cho lò cháy đều. Đó là công việc nóng, bụi và nặng nhọc, trái hẳn với cái lạnh ngoài phố.\n\nKhông có sổ lương hay hồ sơ tuyển dụng nào về hai công việc này được biết đến. Chúng là những chi tiết truyền lại qua hồi ký. Các nguồn đều gặp nhau ở một điểm: ban ngày Người làm việc chân tay, buổi tối tự học tiếng Anh và đọc báo. Vốn tiếng Anh có được ở London đã theo Người suốt những năm hoạt động quốc tế về sau.","doc":2},{"loai":"anh","src":"textures/bai/G06_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Nước Anh – London","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Theo nhà sử học Pierre Brocheux, có năm lá thư gửi đi từ London trong các năm 1913 và 1914 đã bị cơ quan kiểm duyệt Pháp chặn lại. Đó là một trong số ít dấu vết văn bản trực tiếp của chặng đường ở Anh.","nguon_ten":"encyclopedia.1914-1918-online.net","doc":3},{"loai":"anh","src":"textures/bai/G06_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Nước Anh – London","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Drayton Court và Carlton: hai khách sạn, hai mốc thời gian","text":"Tư liệu gắn Người với hai khách sạn. Khách sạn thứ nhất là Drayton Court trên phố The Avenue, khu West Ealing, phía tây London. Đến nay khách sạn này vẫn tự giới thiệu rằng Hồ Chí Minh từng làm việc vất vả trong gian bếp của mình vào năm 1914. Khách sạn thứ hai là Carlton, ở góc phố Haymarket và Pall Mall, giữa khu West End.\n\nCarlton mở cửa năm 1899, do nhà kinh doanh khách sạn César Ritz điều hành. Gian bếp do bếp trưởng lừng danh người Pháp Auguste Escoffier dựng lên. Đây là một trong những khách sạn sang trọng bậc nhất London đầu thế kỷ XX.\n\nCác nguồn không hoàn toàn thống nhất về chi tiết. Biển tưởng niệm ngày nay ghi Người làm việc ở Carlton năm 1913, còn tư liệu về Drayton Court ghi năm 1914. Có tài liệu nói Người phụ bếp, có tài liệu nói Người làm bồi bàn. Những sai khác như vậy là điều thường gặp khi một quãng đời chủ yếu được biết qua lời kể.","doc":4},{"loai":"anh","src":"textures/bai/G06_v4.jpg","chu_thich":"Một góc không gian 3D tái hiện Nước Anh – London","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Mốc thời gian ở London chưa thống nhất: biển tưởng niệm tại phố Haymarket ghi Người làm việc ở khách sạn Carlton năm 1913, còn tư liệu về khách sạn Drayton Court ở West Ealing ghi Người làm bếp ở đó năm 1914.","nguon_ten":"en.nhandan.vn","doc":5},{"loai":"anh","src":"textures/bai/G06_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Nước Anh – London nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Câu chuyện về bếp trưởng Escoffier","text":"Trong các câu chuyện về London, nổi tiếng nhất là chuyện người phụ bếp trẻ được chính Escoffier để ý rồi chuyển sang học làm bánh ngọt. Câu chuyện xuất hiện trong nhiều sách báo và cả trên các trang giới thiệu về London. Tuy vậy, đến nay chưa có tài liệu gốc nào xác nhận nó. Tạp chí Finest Hour của Hội Churchill Quốc tế viết rằng có “rất ít bằng chứng” cho việc Người học nghề làm bánh dưới sự chỉ dẫn của Escoffier.\n\nChỉ phần bối cảnh là chắc chắn. Escoffier (1846–1935) dựng gian bếp Carlton từ năm 1899 và là linh hồn của khách sạn cho tới khi nghỉ hưu năm 1920. Ông hoàn thiện cách tổ chức bếp theo “lữ đoàn” (brigade de cuisine): gian bếp chia thành nhiều tổ chuyên môn, mỗi tổ có trưởng tổ và phần việc riêng. Ông cũng là tác giả cuốn Le Guide Culinaire (1903). Như vậy, trong những năm Người ở London, Escoffier quả thật đang đứng đầu bếp Carlton. Còn cuộc gặp giữa hai người thì đến nay vẫn là một câu chuyện truyền miệng.\n\nMột chuyện khác cũng hay được kể: tối 4/8/1914, ngày nước Anh tham chiến, Winston Churchill dùng bữa ở Carlton đúng lúc Người đang làm trong bếp. Hội Churchill Quốc tế đã khảo cứu chuyện này và kết luận rằng bí ẩn “vẫn chưa được giải đáp”.","doc":6},{"loai":"doan","tieu_de":"Tấm biển trên phố Haymarket","text":"Khách sạn Carlton bị bom Đức tàn phá nặng năm 1940. Phần còn lại bị dỡ bỏ trong hai năm 1957–1958. Trên nền cũ, người ta xây New Zealand House, trụ sở Cao ủy New Zealand, từ năm 1959 đến 1963. Tòa nhà gồm khối đế 4 tầng và tháp 15 tầng, được xếp hạng di sản cấp II năm 1995.\n\nBên lối vào phía phố Haymarket có một tấm biển gốm màu xanh. Dòng chữ tiếng Anh trên biển có nghĩa: “Hồ Chí Minh 1890–1969, người sáng lập nước Việt Nam hiện đại, đã làm việc năm 1913 tại khách sạn Carlton từng đứng trên khu đất này”. Tấm biển không do English Heritage gắn. Nó do hội hữu nghị giữa hai nước vận động dựng lên. Theo Báo Nhân Dân, biển được gắn năm 1990 sau gần ba năm vận động, với sự góp sức của ông Len Aldis, Tổng thư ký Hội Hữu nghị Anh – Việt.\n\nNgày nay, tấm biển nhỏ này là điểm dừng chân của nhiều đoàn khách Việt Nam. Ngày 5/5/2023, nhân dịp sang dự lễ đăng quang của Vua Charles III, Chủ tịch nước Võ Văn Thưởng đã đặt vòng hoa tưởng niệm tại đây.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_1890_1969_founder_of_modern_vietnam_.jpg","chu_thich":"Dòng chữ trên biển tưởng niệm: Hồ Chí Minh 1890–1969, người sáng lập nước Việt Nam hiện đại, đã làm việc năm 1913 tại khách sạn Carlton từng đứng trên khu đất này","credit":"Ảnh: Spudgun67 · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"trich","text":"Ho Chi Minh 1890–1969 founder of modern Vietnam worked in 1913 at the Carlton Hotel which stood on this site (Hồ Chí Minh 1890–1969, người sáng lập nước Việt Nam hiện đại, đã làm việc năm 1913 tại khách sạn Carlton từng đứng trên khu đất này)","nguoi":"Biển tưởng niệm trên tường New Zealand House, phố Haymarket, London","nguon_ten":"https://www.hmdb.org/m.asp?m=109068 ; https://en.nhandan.vn/megastory/hochiminh2020/","doc":8},{"loai":"doan","tieu_de":"Từ London trở lại nước Pháp","text":"Những năm ở Anh trùng với Chiến tranh thế giới thứ nhất. Người thạo thêm tiếng Anh và theo dõi phong trào công nhân châu Âu. Người cũng thấy rằng dưới lá cờ của Đế quốc Anh, các dân tộc thuộc địa chịu cảnh không khác người dân An Nam.\n\nTheo các tài liệu chính thức của Việt Nam, năm 1917 Người vượt eo biển Manche trở lại Pháp. Nhà sử học Pierre Brocheux cũng ghi mốc 1917. Ông cho rằng Người muốn tuyên truyền yêu nước trong số 49.180 lao động và 42.922 binh lính Đông Dương đang có mặt ở Pháp thời chiến. Một số tài liệu nước ngoài khác lại ghi Người đến Paris muộn hơn, vào năm 1919. Dù mốc nào đúng, đến năm 1919 cái tên Nguyễn Ái Quốc đã xuất hiện ở Paris, mở ra một chặng hoạt động mới.","doc":9},{"loai":"moc","items":[["1913","Sang Anh; theo lời kể, làm cào tuyết cho một trường học rồi làm thợ đốt lò"],["1913","Mốc ghi trên biển tưởng niệm: làm việc tại khách sạn Carlton, phố Haymarket"],["1913 – 1914","Năm lá thư gửi từ London bị kiểm duyệt Pháp chặn lại (theo P. Brocheux)"],["1914","Làm bếp tại khách sạn Drayton Court, West Ealing (theo tư liệu của khách sạn)"],["4/8/1914","Nước Anh tham chiến trong Chiến tranh thế giới thứ nhất"],["1917","Trở lại Pháp (theo tài liệu chính thức Việt Nam; có tài liệu nước ngoài ghi 1919)"],["1940","Khách sạn Carlton bị bom tàn phá nặng"],["1957 – 1958","Phần còn lại của khách sạn Carlton bị dỡ bỏ"],["1959 – 1963","Xây dựng New Zealand House trên nền khách sạn cũ"],["1990","Gắn biển tưởng niệm Hồ Chí Minh (theo Báo Nhân Dân)"],["5/5/2023","Chủ tịch nước Võ Văn Thưởng đặt vòng hoa tại biển tưởng niệm"]]}],"doc":[{"i":-1,"t":"London sương mù: người thanh niên Việt Nam giữa bếp lò và trang sách. Năm 1913, người thanh niên Nguyễn Tất Thành đặt chân đến London, thủ đô của Đế quốc Anh. Những năm cào tuyết, đốt lò, phụ bếp ở đây để lại rất ít giấy tờ. Nhưng chúng cho Người một vốn tiếng Anh, một cái nhìn rộng hơn về phong trào công nhân châu Âu và về số phận các dân tộc thuộc địa. Gian trưng bày này tách bạch điều đã được tư liệu xác nhận với những câu chuyện được lưu truyền."},{"t":"Đến thủ đô của một đế quốc. Trước đó Người đã qua những chuyến tàu viễn dương và một chặng dừng chân ở Mỹ. Năm 1913, người thanh niên Nguyễn Tất Thành sang nước Anh. Các tài liệu chính thức của Việt Nam đều ghi Người sống ở đây khoảng bốn năm, từ 1913 đến 1917. London khi ấy là trung tâm của Đế quốc Anh. Tàu từ Ấn Độ, Miến Điện hay châu Phi cập bến nơi đây. Khách sạn xa hoa đứng cách không xa những dãy nhà trọ chật chội của người lao động nhập cư. Đây là quãng đời để lại rất ít giấy tờ gốc. Phần lớn những gì chúng ta biết đến từ lời kể sau này, trước hết là cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” ký bút danh Trần Dân Tiên. Phần còn lại đến từ vài lá thư Người gửi đi. Vì vậy, gian trưng bày này tách bạch điều có tư liệu xác nhận với câu chuyện được lưu truyền."},{"t":"Cào tuyết, đốt lò: những ngày đầu. Theo lời kể được lưu truyền, việc đầu tiên Người nhận ở London là cào tuyết cho một trường học. Báo chí trong nước đã nhiều lần nhắc lại chi tiết này. Mùa đông nước Anh ẩm và buốt. Người cào tuyết phải có mặt từ sáng sớm để dọn lối đi trước giờ học. Sau đó Người chuyển sang làm thợ đốt lò. Mỗi ngày, từ lúc trời chưa sáng, người thợ phải xuống tầng hầm nhóm lửa, xúc than cho lò cháy đều. Đó là công việc nóng, bụi và nặng nhọc, trái hẳn với cái lạnh ngoài phố. Không có sổ lương hay hồ sơ tuyển dụng nào về hai công việc này được biết đến. Chúng là những chi tiết truyền lại qua hồi ký. Các nguồn đều gặp nhau ở một điểm: ban ngày Người làm việc chân tay, buổi tối tự học tiếng Anh và đọc báo. Vốn tiếng Anh có được ở London đã theo Người suốt những năm hoạt động quốc tế về sau."},{"t":"Bạn có biết? Theo nhà sử học Pierre Brocheux, có năm lá thư gửi đi từ London trong các năm 1913 và 1914 đã bị cơ quan kiểm duyệt Pháp chặn lại. Đó là một trong số ít dấu vết văn bản trực tiếp của chặng đường ở Anh."},{"t":"Drayton Court và Carlton: hai khách sạn, hai mốc thời gian. Tư liệu gắn Người với hai khách sạn. Khách sạn thứ nhất là Drayton Court trên phố The Avenue, khu West Ealing, phía tây London. Đến nay khách sạn này vẫn tự giới thiệu rằng Hồ Chí Minh từng làm việc vất vả trong gian bếp của mình vào năm 1914. Khách sạn thứ hai là Carlton, ở góc phố Haymarket và Pall Mall, giữa khu West End. Carlton mở cửa năm 1899, do nhà kinh doanh khách sạn César Ritz điều hành. Gian bếp do bếp trưởng lừng danh người Pháp Auguste Escoffier dựng lên. Đây là một trong những khách sạn sang trọng bậc nhất London đầu thế kỷ XX. Các nguồn không hoàn toàn thống nhất về chi tiết. Biển tưởng niệm ngày nay ghi Người làm việc ở Carlton năm 1913, còn tư liệu về Drayton Court ghi năm 1914. Có tài liệu nói Người phụ bếp, có tài liệu nói Người làm bồi bàn. Những sai khác như vậy là điều thường gặp khi một quãng đời chủ yếu được biết qua lời kể."},{"t":"Bạn có biết? Mốc thời gian ở London chưa thống nhất: biển tưởng niệm tại phố Haymarket ghi Người làm việc ở khách sạn Carlton năm 1913, còn tư liệu về khách sạn Drayton Court ở West Ealing ghi Người làm bếp ở đó năm 1914."},{"t":"Câu chuyện về bếp trưởng Escoffier. Trong các câu chuyện về London, nổi tiếng nhất là chuyện người phụ bếp trẻ được chính Escoffier để ý rồi chuyển sang học làm bánh ngọt. Câu chuyện xuất hiện trong nhiều sách báo và cả trên các trang giới thiệu về London. Tuy vậy, đến nay chưa có tài liệu gốc nào xác nhận nó. Tạp chí Finest Hour của Hội Churchill Quốc tế viết rằng có “rất ít bằng chứng” cho việc Người học nghề làm bánh dưới sự chỉ dẫn của Escoffier. Chỉ phần bối cảnh là chắc chắn. Escoffier (1846–1935) dựng gian bếp Carlton từ năm 1899 và là linh hồn của khách sạn cho tới khi nghỉ hưu năm 1920. Ông hoàn thiện cách tổ chức bếp theo “lữ đoàn” (brigade de cuisine): gian bếp chia thành nhiều tổ chuyên môn, mỗi tổ có trưởng tổ và phần việc riêng. Ông cũng là tác giả cuốn Le Guide Culinaire (1903). Như vậy, trong những năm Người ở London, Escoffier quả thật đang đứng đầu bếp Carlton. Còn cuộc gặp giữa hai người thì đến nay vẫn là một câu chuyện truyền miệng. Một chuyện khác cũng hay được kể: tối 4/8/1914, ngày nước Anh tham chiến, Winston Churchill dùng bữa ở Carlton đúng lúc Người đang làm trong bếp. Hội Churchill Quốc tế đã khảo cứu chuyện này và kết luận rằng bí ẩn “vẫn chưa được giải đáp”."},{"t":"Tấm biển trên phố Haymarket. Khách sạn Carlton bị bom Đức tàn phá nặng năm 1940. Phần còn lại bị dỡ bỏ trong hai năm 1957–1958. Trên nền cũ, người ta xây New Zealand House, trụ sở Cao ủy New Zealand, từ năm 1959 đến 1963. Tòa nhà gồm khối đế 4 tầng và tháp 15 tầng, được xếp hạng di sản cấp II năm 1995. Bên lối vào phía phố Haymarket có một tấm biển gốm màu xanh. Dòng chữ tiếng Anh trên biển có nghĩa: “Hồ Chí Minh 1890–1969, người sáng lập nước Việt Nam hiện đại, đã làm việc năm 1913 tại khách sạn Carlton từng đứng trên khu đất này”. Tấm biển không do English Heritage gắn. Nó do hội hữu nghị giữa hai nước vận động dựng lên. Theo Báo Nhân Dân, biển được gắn năm 1990 sau gần ba năm vận động, với sự góp sức của ông Len Aldis, Tổng thư ký Hội Hữu nghị Anh – Việt. Ngày nay, tấm biển nhỏ này là điểm dừng chân của nhiều đoàn khách Việt Nam. Ngày 5/5/2023, nhân dịp sang dự lễ đăng quang của Vua Charles III, Chủ tịch nước Võ Văn Thưởng đã đặt vòng hoa tưởng niệm tại đây."},{"t":"Ho Chi Minh 1890–1969 founder of modern Vietnam worked in 1913 at the Carlton Hotel which stood on this site (Hồ Chí Minh 1890–1969, người sáng lập nước Việt Nam hiện đại, đã làm việc năm 1913 tại khách sạn Carlton từng đứng trên khu đất này) — Biển tưởng niệm trên tường New Zealand House, phố Haymarket, London"},{"t":"Từ London trở lại nước Pháp. Những năm ở Anh trùng với Chiến tranh thế giới thứ nhất. Người thạo thêm tiếng Anh và theo dõi phong trào công nhân châu Âu. Người cũng thấy rằng dưới lá cờ của Đế quốc Anh, các dân tộc thuộc địa chịu cảnh không khác người dân An Nam. Theo các tài liệu chính thức của Việt Nam, năm 1917 Người vượt eo biển Manche trở lại Pháp. Nhà sử học Pierre Brocheux cũng ghi mốc 1917. Ông cho rằng Người muốn tuyên truyền yêu nước trong số 49.180 lao động và 42.922 binh lính Đông Dương đang có mặt ở Pháp thời chiến. Một số tài liệu nước ngoài khác lại ghi Người đến Paris muộn hơn, vào năm 1919. Dù mốc nào đúng, đến năm 1919 cái tên Nguyễn Ái Quốc đã xuất hiện ở Paris, mở ra một chặng hoạt động mới."}],"hien_vat":[{"ten":"Khách sạn Carlton","mo_ta":"Khách sạn Carlton ở góc phố Haymarket và Pall Mall mở cửa năm 1899, do César Ritz điều hành, bếp do Auguste Escoffier dựng lên. Biển tưởng niệm ngày nay ghi Người làm việc ở đây năm 1913, nhưng chưa có hồ sơ gốc nào xác nhận. Khách sạn bị bom tàn phá nặng năm 1940 và bị dỡ bỏ năm 1957–1958.","nguon":"https://en.wikipedia.org/wiki/Carlton_Hotel,_London"},{"ten":"Nhà hát Hoàng gia Haymarket","mo_ta":"Nằm phía đông phố Haymarket, nhà hát ở vị trí hiện nay từ năm 1821, khi kiến trúc sư John Nash thiết kế lại. Mặt tiền nổi bật với hiên sáu cột kiểu Corinth đỡ trán tường tam giác. Công trình được xếp hạng di sản cấp I.","nguon":"https://en.wikipedia.org/wiki/Theatre_Royal_Haymarket"},{"ten":"Gian bếp khách sạn: lò gang và nồi đồng","mo_ta":"Bếp Carlton được tổ chức theo mô hình “lữ đoàn” (brigade de cuisine) do Escoffier hoàn thiện: nhiều tổ chuyên môn, mỗi tổ có trưởng tổ và phần việc riêng. Escoffier đứng đầu bếp Carlton từ năm 1899 đến khi nghỉ hưu năm 1920. Còn chuyện Người phụ bếp ở đây vẫn chủ yếu dựa vào lời kể.","nguon":"https://en.wikipedia.org/wiki/Auguste_Escoffier"},{"ten":"Bàn nhồi bột","mo_ta":"Theo lời kể được lưu truyền, Người được bếp trưởng Escoffier để ý và chuyển sang học làm bánh ngọt. Hội Churchill Quốc tế nhận định có “rất ít bằng chứng” cho câu chuyện này. Vì vậy nên xem đây là một câu chuyện truyền miệng, chưa phải sự kiện đã được xác nhận.","nguon":"https://winstonchurchill.org/publications/finest-hour/finest-hour-161/history-detectives-did-ho-chi-minh-cook-churchills-veggies-at-the-start-of-world-war-i/"},{"ten":"Hòm thư đỏ","mo_ta":"Những lá thư Người gửi từ London thuộc số ít dấu vết văn bản trực tiếp của chặng đường này. Theo nhà sử học Pierre Brocheux, năm lá thư gửi đi trong các năm 1913–1914 đã bị cơ quan kiểm duyệt Pháp chặn lại.","nguon":"https://encyclopedia.1914-1918-online.net/article/ho-chi-minh/"}],"hoi_dap":[{"hoi":"Khách sạn Carlton ở London nằm ở góc hai phố nào?","dap":"Góc phố Haymarket và phố Pall Mall, giữa khu West End.","sai":["Oxford Street và Regent Street","The Strand và Fleet Street","Baker Street và Marylebone Road"],"nguon":"https://en.nhandan.vn/megastory/hochiminh2020/"},{"hoi":"Tòa nhà nào hiện đứng trên nền khách sạn Carlton cũ?","dap":"New Zealand House, trụ sở Cao ủy New Zealand, xây dựng từ năm 1959 đến 1963.","sai":["Tòa nhà Quốc hội Anh","Khách sạn Ritz London","Bảo tàng Anh"],"nguon":"https://historicengland.org.uk/listing/the-list/list-entry/1242616"},{"hoi":"Biển tưởng niệm ở phố Haymarket ghi Người làm việc tại khách sạn Carlton vào năm nào?","dap":"Năm 1913.","sai":["Năm 1911","Năm 1917","Năm 1919"],"nguon":"https://www.hmdb.org/m.asp?m=109068"},{"hoi":"Ai dựng và đứng đầu gian bếp khách sạn Carlton từ năm 1899 đến năm 1920?","dap":"Bếp trưởng người Pháp Auguste Escoffier.","sai":["César Ritz","Marie-Antoine Carême","Paul Bocuse"],"nguon":"https://en.wikipedia.org/wiki/Auguste_Escoffier"},{"hoi":"Chuyện Người học làm bánh dưới sự chỉ dẫn của Escoffier được giới nghiên cứu đánh giá thế nào?","dap":"Đó là lời kể được lưu truyền; Hội Churchill Quốc tế nhận định có rất ít bằng chứng tư liệu cho câu chuyện này.","sai":["Được ghi trong nhật ký của Escoffier","Được khắc trên biển tưởng niệm ở Haymarket","Được xác nhận bằng thư giới thiệu của khách sạn"],"nguon":"https://winstonchurchill.org/publications/finest-hour/finest-hour-161/history-detectives-did-ho-chi-minh-cook-churchills-veggies-at-the-start-of-world-war-i/"},{"hoi":"Khách sạn Carlton bị bom tàn phá nặng vào năm nào?","dap":"Năm 1940, trong Chiến tranh thế giới thứ hai.","sai":["Năm 1918","Năm 1926","Năm 1966"],"nguon":"https://en.wikipedia.org/wiki/Carlton_Hotel,_London"},{"hoi":"Khách sạn Drayton Court — nơi theo tư liệu của khách sạn, Người từng làm bếp năm 1914 — nằm ở khu nào của London?","dap":"Khu West Ealing, phía tây London.","sai":["Whitechapel","Greenwich","Camden"],"nguon":"https://www.vietnamplus.vn/bac-ho-ra-di-tim-duong-cuu-nuoc-dau-an-cua-nguoi-o-xu-so-suong-mu-post717979.vnp"},{"hoi":"Theo nhà sử học Pierre Brocheux, bao nhiêu lá thư Người gửi từ London trong các năm 1913–1914 bị kiểm duyệt Pháp chặn lại?","dap":"Năm lá thư.","sai":["Một lá thư","Mười lá thư","Hai mươi lá thư"],"nguon":"https://encyclopedia.1914-1918-online.net/article/ho-chi-minh/"},{"hoi":"Theo tài liệu chính thức của Việt Nam, Người rời nước Anh trở lại Pháp vào năm nào?","dap":"Năm 1917 (một số tài liệu nước ngoài ghi mốc muộn hơn).","sai":["Năm 1913","Năm 1915","Năm 1920"],"nguon":"https://www.vietnamplus.vn/bac-ho-ra-di-tim-duong-cuu-nuoc-dau-an-cua-nguoi-o-xu-so-suong-mu-post717979.vnp"},{"hoi":"Theo Báo Nhân Dân, biển tưởng niệm Hồ Chí Minh ở phố Haymarket được gắn vào năm nào?","dap":"Năm 1990, sau gần ba năm vận động của Hội Hữu nghị Anh – Việt.","sai":["Năm 1969","Năm 1975","Năm 2005"],"nguon":"https://en.nhandan.vn/megastory/hochiminh2020/"}],"nguon":[{"ten":"Bác Hồ ra đi tìm đường cứu nước: Dấu ấn của Người ở Xứ sở Sương mù – VietnamPlus (TTXVN)","url":"https://www.vietnamplus.vn/bac-ho-ra-di-tim-duong-cuu-nuoc-dau-an-cua-nguoi-o-xu-so-suong-mu-post717979.vnp"},{"ten":"From London, Ho Chi Minh's ideology spreads over the world – Nhân Dân (bản tiếng Anh)","url":"https://en.nhandan.vn/megastory/hochiminh2020/"},{"ten":"History Detectives: Did Ho Chi Minh Cook Churchill's Veggies at the Start of World War I? – Finest Hour 161, International Churchill Society","url":"https://winstonchurchill.org/publications/finest-hour/finest-hour-161/history-detectives-did-ho-chi-minh-cook-churchills-veggies-at-the-start-of-world-war-i/"},{"ten":"Pierre Brocheux, “Hồ Chí Minh” – 1914-1918-online. International Encyclopedia of the First World War","url":"https://encyclopedia.1914-1918-online.net/article/ho-chi-minh/"},{"ten":"New Zealand House – Historic England, List entry 1242616","url":"https://historicengland.org.uk/listing/the-list/list-entry/1242616"},{"ten":"Ho Chi Minh Historical Marker – The Historical Marker Database","url":"https://www.hmdb.org/m.asp?m=109068"},{"ten":"State leader laid wreath at President Ho Chi Minh plaque in London – Báo Thế giới & Việt Nam","url":"https://en.baoquocte.vn/state-leader-laid-wreath-at-president-ho-chi-minh-plaque-in-london-226017.html"},{"ten":"Carlton Hotel, London – Wikipedia (đối chiếu)","url":"https://en.wikipedia.org/wiki/Carlton_Hotel,_London"},{"ten":"Auguste Escoffier – Wikipedia (đối chiếu)","url":"https://en.wikipedia.org/wiki/Auguste_Escoffier"},{"ten":"Theatre Royal Haymarket – Wikipedia (đối chiếu)","url":"https://en.wikipedia.org/wiki/Theatre_Royal_Haymarket"},{"ten":"Ho Chi Minh – Wikipedia (đối chiếu)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"}],"so_chu":1322},"G07":{"ma":"G07","tieu_de":"Boston – New York: người phụ bếp giữa một nền cộng hòa xa lạ","sapo":"Cuối năm 1912, chàng thanh niên hai mươi hai tuổi rời con tàu viễn dương để đặt chân lên đất Mỹ — một chặng đường mà đến nay giới sử học vẫn phải phân biệt cẩn thận giữa vài dòng tư liệu xác thực và những gì chỉ được biết qua lời kể sau này của chính Người. Ở Boston và New York, Người nhìn thấy cả sự phồn vinh của một nền cộng hòa trẻ lẫn những nghịch lý cay đắng của nó.","sapo_en":"In the winter of 1912–1913, the young Nguyễn Tất Thành spent months in Boston and New York — a chapter historians can document only sparsely, and this exhibit is careful to separate confirmed fact from later recollection.","bia":{"src":"textures/bai/G07_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình"},"khoi":[{"loai":"doan","tieu_de":"Một lá thư từ New York","text":"Trong hồ sơ theo dõi của mật thám Pháp còn lưu lại một dấu vết hiếm hoi: lá thư đề ngày 15/12/1912, đóng dấu bưu điện New York, do Nguyễn Tất Thành gửi cho các quan chức thuộc địa Pháp. Trong đó, Người ghi địa chỉ liên lạc là 'poste restante' (lưu tại bưu điện) ở Le Havre và khai nghề nghiệp là thủy thủ. Đó gần như là bằng chứng giấy tờ duy nhất còn lại xác nhận Người thực sự có mặt trên đất Mỹ vào thời điểm này.\n\nTrước đó, từ giữa năm 1911, chàng thanh niên đã làm phụ bếp trên con tàu Amiral Latouche-Tréville, qua Marseille, Le Havre rồi nhiều cảng ở châu Phi. Khoảng cuối năm 1912, Người theo một con tàu vượt Đại Tây Dương sang nước Mỹ.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","chu_thich":"Khách sạn Parker House trên phố School, Boston — nơi Người từng kể là đã làm phụ bếp mùa đông 1912–1913.","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Điều đã xác thực và điều còn là lời kể","text":"Sử liệu về quãng thời gian này chủ yếu đến từ chính lời kể của Người ở giai đoạn sau, nên các nhà nghiên cứu luôn thận trọng khi trình bày. Trong một tấm bưu thiếp gửi nhà chí sĩ Phan Châu Trinh, Người có nhắc đến việc làm phụ bếp bánh tại khách sạn Parker House. Nhưng khi các nhà viết sử đối chiếu với hồ sơ nhân sự của khách sạn, họ không tìm thấy tên Người trong đó — điều này không có nghĩa câu chuyện là bịa đặt, chỉ có nghĩa là chưa có văn bản độc lập nào xác nhận nó. Tương tự, việc Người sống một thời gian ở khu Harlem, New York trong năm 1912–1913 cũng chỉ được các nhà viết tiểu sử ghi nhận bằng chữ 'có thể', chứ chưa phải một mốc chắc chắn.\n\nĐây cũng là lý do gian trưng bày về nước Mỹ nhỏ hơn nhiều gian khác trong hành trình: không phải vì giai đoạn này kém quan trọng, mà vì tư liệu gốc còn lại quá ít. Bảo tàng chọn cách trình bày trung thực — tách bạch rõ ràng giữa những gì đã được kiểm chứng bằng văn bản và những gì mới chỉ là hồi ức được kể lại.","doc":2},{"loai":"ban_co_biet","text":"Khoảng ba mươi năm sau, một thanh niên da đen tên Malcolm Little — sau này là nhà hoạt động Malcolm X — cũng từng làm bồi bàn tại chính khách sạn Parker House, vào thập niên 1940. Hai số phận từng ghé qua cùng một mái nhà, trước khi cùng dấn thân vào những cuộc đấu tranh cho các dân tộc bị áp bức.","nguon_ten":"en.wikipedia.org","doc":3},{"loai":"anh","src":"textures/bai/G07_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Nước Mỹ – Boston và New York nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Harlem, và những nghịch lý của một nền cộng hòa","text":"Ở New York, theo một số nhà viết tiểu sử, Người có thể đã sống một thời gian ở khu Harlem — nơi cộng đồng người Mỹ gốc Phi đang ngày một đông. Đây là chi tiết được biết qua lời kể hơn là qua văn bản độc lập, nhưng nó phản ánh một sự thật lớn hơn: giữa một nước cộng hòa tự hào về bản Tuyên ngôn Độc lập của mình, người thanh niên xứ Nghệ đã tận mắt chứng kiến nạn phân biệt chủng tộc đối với chính những người dân của đất nước ấy.\n\nNhững gì nhìn thấy ở Mỹ, cùng với những gì chứng kiến sau này ở châu Phi và các thuộc địa Pháp, trở thành chất liệu cho nhiều bài báo và cho cuốn Bản án chế độ thực dân Pháp mà Người viết trong thập niên 1920 — nơi Người vạch trần khoảng cách giữa những lời tuyên ngôn về quyền con người và thực tế cai trị của các đế quốc.","doc":4},{"loai":"doan","tieu_de":"Bản Tuyên ngôn của một nền cộng hòa trẻ","text":"Nước Mỹ mà Người nhìn thấy năm 1912 là một nền cộng hòa đã hơn một thế kỷ tuổi, tự hào về bản Tuyên ngôn Độc lập năm 1776 với những lời mở đầu về quyền bình đẳng, quyền sống, quyền tự do và quyền mưu cầu hạnh phúc của con người. Nhưng cũng chính ở đó, Người chứng kiến khoảng cách giữa lời tuyên ngôn và thực tế đối xử với người da đen. Ba mươi ba năm sau, khi soạn bản Tuyên ngôn Độc lập cho nước Việt Nam vừa giành được tự do, Người đã chọn chính những lời lẽ ấy của nước Mỹ để mở đầu — vừa như một sự trân trọng đối với lý tưởng phổ quát về quyền con người, vừa như một lời nhắc rằng lý tưởng ấy phải được thực hiện cho mọi dân tộc.","doc":5},{"loai":"trich","text":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc.","nguoi":"Trích Tuyên ngôn Độc lập Hoa Kỳ năm 1776, được Chủ tịch Hồ Chí Minh dẫn mở đầu bản Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa","nguon_ten":"Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa, đọc tại Quảng trường Ba Đình ngày 2/9/1945","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_54957839082.jpg","chu_thich":"Mặt tiền khách sạn Parker House ngày nay — khách sạn còn hoạt động liên tục lâu đời nhất nước Mỹ, khai trương từ năm 1855.","credit":"Ảnh: ajay_suresh · CC BY 4.0 · Wikimedia Commons"},{"loai":"anh","src":"textures/bai/G07_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện Nước Mỹ – Boston và New York","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Nhà thờ King's Chapel ở góc phố School – Tremont được xây bằng đá granit từ năm 1749–1754 theo thiết kế kiến trúc sư Peter Harrison, đã đứng đó hơn một thế kỷ rưỡi trước khi Người đặt chân tới Boston, và vẫn còn nguyên vị trí cho đến nay.","nguon_ten":"en.wikipedia.org","doc":7},{"loai":"anh","src":"textures/bai/G07_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Nước Mỹ – Boston và New York","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Tòa nhà khách sạn Parker House mà du khách nhìn thấy ngày nay phần lớn được xây dựng lại từ năm 1927 — nghĩa là kiến trúc hiện tại không hoàn toàn giống tòa nhà nguyên bản của năm 1912, dù vẫn đứng trên cùng nền đất ở góc phố School.","nguon_ten":"en.wikipedia.org","doc":8},{"loai":"anh","src":"textures/bai/G07_v4.jpg","chu_thich":"Một góc không gian 3D tái hiện Nước Mỹ – Boston và New York","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Một chặng ngắn, một dấu mốc dài","text":"Khoảng đầu năm 1913, Người rời nước Mỹ, tiếp tục cuộc hành trình sang nước Anh — nơi tiếp tục làm nhiều nghề chân tay để tự nuôi sống mình trong lúc quan sát, học hỏi. Chặng dừng chân ở Boston và New York vì thế chỉ kéo dài chưa đầy một năm, để lại rất ít dấu vết văn bản. Nhưng ba mươi hai năm sau, khi đứng trước quốc dân đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa, chính Người đã chọn mở đầu bằng những lời của bản Tuyên ngôn Độc lập Hoa Kỳ năm 1776 — như một lời nhắc rằng ngay từ những năm tháng lặng lẽ làm thuê nơi đất khách, Người đã nhìn thấy trong lý tưởng của nước Mỹ trẻ cả ánh sáng lẫn bóng tối của nó.","doc":9},{"loai":"moc","items":[["1912","Đến Mỹ trên tàu viễn dương"],["15/12/1912","Gửi thư từ New York — một trong rất ít bằng chứng giấy tờ về giai đoạn này"],["1912 – 1913","Tương truyền làm phụ bếp tại khách sạn Parker House, Boston; sống một thời gian ở New York"],["1913","Rời Mỹ sang Anh"]]}],"doc":[{"i":-1,"t":"Boston – New York: người phụ bếp giữa một nền cộng hòa xa lạ. Cuối năm 1912, chàng thanh niên hai mươi hai tuổi rời con tàu viễn dương để đặt chân lên đất Mỹ — một chặng đường mà đến nay giới sử học vẫn phải phân biệt cẩn thận giữa vài dòng tư liệu xác thực và những gì chỉ được biết qua lời kể sau này của chính Người. Ở Boston và New York, Người nhìn thấy cả sự phồn vinh của một nền cộng hòa trẻ lẫn những nghịch lý cay đắng của nó."},{"t":"Một lá thư từ New York. Trong hồ sơ theo dõi của mật thám Pháp còn lưu lại một dấu vết hiếm hoi: lá thư đề ngày 15/12/1912, đóng dấu bưu điện New York, do Nguyễn Tất Thành gửi cho các quan chức thuộc địa Pháp. Trong đó, Người ghi địa chỉ liên lạc là 'poste restante' (lưu tại bưu điện) ở Le Havre và khai nghề nghiệp là thủy thủ. Đó gần như là bằng chứng giấy tờ duy nhất còn lại xác nhận Người thực sự có mặt trên đất Mỹ vào thời điểm này. Trước đó, từ giữa năm 1911, chàng thanh niên đã làm phụ bếp trên con tàu Amiral Latouche-Tréville, qua Marseille, Le Havre rồi nhiều cảng ở châu Phi. Khoảng cuối năm 1912, Người theo một con tàu vượt Đại Tây Dương sang nước Mỹ."},{"t":"Điều đã xác thực và điều còn là lời kể. Sử liệu về quãng thời gian này chủ yếu đến từ chính lời kể của Người ở giai đoạn sau, nên các nhà nghiên cứu luôn thận trọng khi trình bày. Trong một tấm bưu thiếp gửi nhà chí sĩ Phan Châu Trinh, Người có nhắc đến việc làm phụ bếp bánh tại khách sạn Parker House. Nhưng khi các nhà viết sử đối chiếu với hồ sơ nhân sự của khách sạn, họ không tìm thấy tên Người trong đó — điều này không có nghĩa câu chuyện là bịa đặt, chỉ có nghĩa là chưa có văn bản độc lập nào xác nhận nó. Tương tự, việc Người sống một thời gian ở khu Harlem, New York trong năm 1912–1913 cũng chỉ được các nhà viết tiểu sử ghi nhận bằng chữ 'có thể', chứ chưa phải một mốc chắc chắn. Đây cũng là lý do gian trưng bày về nước Mỹ nhỏ hơn nhiều gian khác trong hành trình: không phải vì giai đoạn này kém quan trọng, mà vì tư liệu gốc còn lại quá ít. Bảo tàng chọn cách trình bày trung thực — tách bạch rõ ràng giữa những gì đã được kiểm chứng bằng văn bản và những gì mới chỉ là hồi ức được kể lại."},{"t":"Bạn có biết? Khoảng ba mươi năm sau, một thanh niên da đen tên Malcolm Little — sau này là nhà hoạt động Malcolm X — cũng từng làm bồi bàn tại chính khách sạn Parker House, vào thập niên 1940. Hai số phận từng ghé qua cùng một mái nhà, trước khi cùng dấn thân vào những cuộc đấu tranh cho các dân tộc bị áp bức."},{"t":"Harlem, và những nghịch lý của một nền cộng hòa. Ở New York, theo một số nhà viết tiểu sử, Người có thể đã sống một thời gian ở khu Harlem — nơi cộng đồng người Mỹ gốc Phi đang ngày một đông. Đây là chi tiết được biết qua lời kể hơn là qua văn bản độc lập, nhưng nó phản ánh một sự thật lớn hơn: giữa một nước cộng hòa tự hào về bản Tuyên ngôn Độc lập của mình, người thanh niên xứ Nghệ đã tận mắt chứng kiến nạn phân biệt chủng tộc đối với chính những người dân của đất nước ấy. Những gì nhìn thấy ở Mỹ, cùng với những gì chứng kiến sau này ở châu Phi và các thuộc địa Pháp, trở thành chất liệu cho nhiều bài báo và cho cuốn Bản án chế độ thực dân Pháp mà Người viết trong thập niên 1920 — nơi Người vạch trần khoảng cách giữa những lời tuyên ngôn về quyền con người và thực tế cai trị của các đế quốc."},{"t":"Bản Tuyên ngôn của một nền cộng hòa trẻ. Nước Mỹ mà Người nhìn thấy năm 1912 là một nền cộng hòa đã hơn một thế kỷ tuổi, tự hào về bản Tuyên ngôn Độc lập năm 1776 với những lời mở đầu về quyền bình đẳng, quyền sống, quyền tự do và quyền mưu cầu hạnh phúc của con người. Nhưng cũng chính ở đó, Người chứng kiến khoảng cách giữa lời tuyên ngôn và thực tế đối xử với người da đen. Ba mươi ba năm sau, khi soạn bản Tuyên ngôn Độc lập cho nước Việt Nam vừa giành được tự do, Người đã chọn chính những lời lẽ ấy của nước Mỹ để mở đầu — vừa như một sự trân trọng đối với lý tưởng phổ quát về quyền con người, vừa như một lời nhắc rằng lý tưởng ấy phải được thực hiện cho mọi dân tộc."},{"t":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc. — Trích Tuyên ngôn Độc lập Hoa Kỳ năm 1776, được Chủ tịch Hồ Chí Minh dẫn mở đầu bản Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa"},{"t":"Bạn có biết? Nhà thờ King's Chapel ở góc phố School – Tremont được xây bằng đá granit từ năm 1749–1754 theo thiết kế kiến trúc sư Peter Harrison, đã đứng đó hơn một thế kỷ rưỡi trước khi Người đặt chân tới Boston, và vẫn còn nguyên vị trí cho đến nay."},{"t":"Bạn có biết? Tòa nhà khách sạn Parker House mà du khách nhìn thấy ngày nay phần lớn được xây dựng lại từ năm 1927 — nghĩa là kiến trúc hiện tại không hoàn toàn giống tòa nhà nguyên bản của năm 1912, dù vẫn đứng trên cùng nền đất ở góc phố School."},{"t":"Một chặng ngắn, một dấu mốc dài. Khoảng đầu năm 1913, Người rời nước Mỹ, tiếp tục cuộc hành trình sang nước Anh — nơi tiếp tục làm nhiều nghề chân tay để tự nuôi sống mình trong lúc quan sát, học hỏi. Chặng dừng chân ở Boston và New York vì thế chỉ kéo dài chưa đầy một năm, để lại rất ít dấu vết văn bản. Nhưng ba mươi hai năm sau, khi đứng trước quốc dân đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa, chính Người đã chọn mở đầu bằng những lời của bản Tuyên ngôn Độc lập Hoa Kỳ năm 1776 — như một lời nhắc rằng ngay từ những năm tháng lặng lẽ làm thuê nơi đất khách, Người đã nhìn thấy trong lý tưởng của nước Mỹ trẻ cả ánh sáng lẫn bóng tối của nó."}],"hien_vat":[{"ten":"Khách sạn Parker House","mo_ta":"Khai trương năm 1855 do Harvey D. Parker sáng lập, đây là khách sạn còn hoạt động liên tục lâu đời nhất nước Mỹ. Tòa nhà hiện nay phần lớn được xây lại năm 1927, sau thời gian Người từng kể là đã làm việc ở đây.","nguon":"https://en.wikipedia.org/wiki/Omni_Parker_House"},{"ten":"Nhà thờ King's Chapel","mo_ta":"Nhà thờ đá granit theo phong cách Georgia, xây dựng năm 1749–1754 theo thiết kế kiến trúc sư Peter Harrison, tọa lạc ngay góc phố Tremont và School, đối diện khách sạn Parker House.","nguon":"https://en.wikipedia.org/wiki/King%27s_Chapel"},{"ten":"Tòa thị chính cũ Boston (Old City Hall)","mo_ta":"Xây dựng năm 1862–1865 theo phong cách Đế chế thứ hai (Second Empire), do G. J. F. Bryant và Arthur Gilman thiết kế, từng là trụ sở chính quyền thành phố Boston từ 1865 đến 1969, tại số 45 phố School.","nguon":"https://en.wikipedia.org/wiki/Old_City_Hall_(Boston)"},{"ten":"Gian bếp bánh tái hiện","mo_ta":"Phục dựng theo mô tả về khu bếp trong tầng hầm khách sạn Parker House thời kỳ đầu thế kỷ XX: lò gạch nung, bàn gỗ nhồi bột và khay bánh mì kiểu Parker House Roll.","nguon":"https://en.wikipedia.org/wiki/Omni_Parker_House"},{"ten":"Bánh Parker House Roll","mo_ta":"Loại bánh mì mềm, gấp đôi đặc trưng, ra đời tại khách sạn Parker House vào thế kỷ XIX và về sau trở thành món bánh quen thuộc khắp nước Mỹ.","nguon":"https://en.wikipedia.org/wiki/Omni_Parker_House"}],"hoi_dap":[{"hoi":"Bằng chứng giấy tờ nào xác nhận Người có mặt ở Mỹ vào cuối năm 1912?","dap":"Một lá thư đề ngày 15/12/1912, đóng dấu bưu điện New York, gửi cho các quan chức thuộc địa Pháp.","sai":["Hộ chiếu Mỹ được cấp cho Người","Giấy chứng nhận làm việc của khách sạn Parker House","Nhật ký hành trình có chữ ký thị trưởng Boston"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Trong lá thư gửi từ New York, Người khai nghề nghiệp gì?","dap":"Thủy thủ.","sai":["Đầu bếp","Sinh viên","Ký giả"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Khách sạn nào ở Boston tương truyền Người từng làm phụ bếp?","dap":"Khách sạn Parker House.","sai":["The Ritz-Carlton","The Copley Plaza","Omni Shoreham"],"nguon":"https://en.wikipedia.org/wiki/Omni_Parker_House"},{"hoi":"Vì sao câu chuyện làm phụ bếp ở Parker House được xem là một lời kể, chưa hẳn là sự kiện đã kiểm chứng hoàn toàn?","dap":"Vì thông tin chủ yếu đến từ bưu thiếp Người gửi Phan Châu Trinh, còn hồ sơ nhân sự của khách sạn không tìm thấy tên Người.","sai":["Vì khách sạn khi đó chưa xây xong","Vì Người chưa từng đặt chân đến Boston","Vì có ảnh chụp Người ở nơi khác cùng thời điểm"],"nguon":"https://en.wikipedia.org/wiki/Omni_Parker_House"},{"hoi":"Ai cũng từng làm việc tại khách sạn Parker House vào thập niên 1940, khoảng 30 năm sau Người?","dap":"Malcolm X (khi đó tên là Malcolm Little), làm bồi bàn.","sai":["Martin Luther King Jr.","W. E. B. Du Bois","Marcus Garvey"],"nguon":"https://en.wikipedia.org/wiki/Omni_Parker_House"},{"hoi":"Khách sạn Parker House khai trương vào năm nào?","dap":"Năm 1855.","sai":["1832","1901","1927"],"nguon":"https://en.wikipedia.org/wiki/Omni_Parker_House"},{"hoi":"Tòa nhà Parker House mà du khách thấy ngày nay chủ yếu được xây lại vào năm nào?","dap":"Năm 1927.","sai":["1855","1913","1969"],"nguon":"https://en.wikipedia.org/wiki/Omni_Parker_House"},{"hoi":"Nhà thờ đá granit nào đứng ở góc phố Tremont – School từ giữa thế kỷ XVIII?","dap":"King's Chapel.","sai":["Trinity Church","Old North Church","Park Street Church"],"nguon":"https://en.wikipedia.org/wiki/King%27s_Chapel"},{"hoi":"Tòa thị chính cũ của Boston trên phố School được xây trong khoảng thời gian nào?","dap":"1862–1865.","sai":["1776–1780","1855–1858","1901–1905"],"nguon":"https://en.wikipedia.org/wiki/Old_City_Hall_(Boston)"},{"hoi":"Bản Tuyên ngôn Độc lập nào được Người trích dẫn mở đầu Tuyên ngôn Độc lập Việt Nam năm 1945?","dap":"Tuyên ngôn Độc lập Hoa Kỳ năm 1776.","sai":["Tuyên ngôn Nhân quyền và Dân quyền Pháp 1789","Đại Hiến chương Magna Carta của Anh","Tuyên ngôn Quốc tế Nhân quyền 1948"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Sau khi rời Mỹ khoảng đầu năm 1913, Người đến quốc gia nào tiếp theo?","dap":"Nước Anh.","sai":["Nước Nga","Trung Quốc","Đức"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"}],"nguon":[{"ten":"Ho Chi Minh — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Omni Parker House — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Omni_Parker_House"},{"ten":"King's Chapel — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/King%27s_Chapel"},{"ten":"Old City Hall (Boston) — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Old_City_Hall_(Boston)"},{"ten":"Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa, 2/9/1945","url":"https://hochiminh.vn/"}],"so_chu":1097},"G08":{"ma":"G08","tieu_de":"Mátxcơva mùa đông 1924: từ Quốc tế Cộng sản đến ngày tang Lênin","sapo":"Tháng 6/1923, mang trên mình một tấm thị thực đứng tên khác, Nguyễn Ái Quốc lặng lẽ rời Paris để đến với trung tâm phong trào cộng sản quốc tế. Ở Mátxcơva, Người vừa là học trò trong giảng đường Trường Đại học Phương Đông, vừa là đại biểu phát biểu trước những người cộng sản khắp năm châu. Và cũng chính nơi đây, giữa mùa đông năm 1924, Người đứng trong dòng người tiễn đưa lãnh tụ Lênin.","sapo_en":"In June 1923 Nguyễn Ái Quốc travelled secretly from Paris to Soviet Russia, studying at the University of the Toilers of the East, addressing the Communist International on the colonial question, and standing among the mourners at Lenin's funeral in January 1924.","bia":{"src":"textures/ht/ht_anh_nguyen_ai_quoc_in_the_soviet_union_in_1923.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Chuyến đi bí mật mang tên Chen Vang","text":"Giữa năm 1923, Nguyễn Ái Quốc bí mật rời Paris sang nước Nga Xô-viết — bí mật vì khi đó Người đã là mục tiêu theo dõi thường xuyên của mật thám Pháp, và một chuyến đi công khai sang nước Nga Xô-viết hẳn sẽ đặt dấu chấm hết cho khả năng trở lại hoạt động ở châu Âu. Tấm thị thực nhập cảnh Nga số 1829, do đại diện Liên Xô tại Berlin cấp ngày 16/6/1923, mang một cái tên khác — Chen Vang. Ngày 30/6/1923, Người đến Petrograd (nay là Sankt-Peterburg), thành phố vừa trải qua Cách mạng Tháng Mười chưa đầy sáu năm trước, rồi từ đó tiếp tục đến Mátxcơva để bắt đầu quãng thời gian làm việc trong bộ máy Quốc tế Cộng sản (Comintern).","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_visa_for_entry_into_russia_no_1829_on_june_16_19.jpg","chu_thich":"Thị thực nhập cảnh Nga số 1829, cấp ngày 16/6/1923 tại Berlin cho Nguyễn Ái Quốc, mang tên Chen Vang.","credit":"Ảnh: The representative of the Union of Sovie · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Giảng đường Trường Đại học Phương Đông","text":"Tại Mátxcơva, Người theo học tại Trường Đại học Cộng sản của những người lao động phương Đông (KUTV) — ngôi trường được thành lập ở Mátxcơva năm 1921 để đào tạo cán bộ cách mạng cho các dân tộc thuộc địa và phụ thuộc ở châu Á, châu Phi và thế giới Ả Rập, với chương trình gồm lý luận Mác-xít, tổ chức đảng, công tác tuyên truyền và chiến thuật cách mạng. Ở đây, Người vừa học tiếng Nga vừa tiếp cận lý luận cách mạng một cách bài bản lần đầu tiên sau nhiều năm tự học qua sách báo và thực tiễn lao động ở châu Âu. Ít năm sau, chính ngôi trường này còn đào tạo nhiều cán bộ Việt Nam khác, trong đó có ba người sau này lần lượt trở thành Tổng Bí thư đầu tiên của Đảng Cộng sản Việt Nam: Trần Phú, Lê Hồng Phong và Hà Huy Tập.","doc":2},{"loai":"ban_co_biet","text":"Trường Đại học Phương Đông tồn tại chưa đầy hai thập niên: sau khi đào tạo hàng nghìn cán bộ cách mạng từ khắp các thuộc địa và các nước phương Đông, trường bị giải thể trong những năm 1937–1938, giữa cao trào thanh trừng chính trị ở Liên Xô — nhiều giảng viên và cựu sinh viên của trường cũng trở thành nạn nhân của giai đoạn này.","nguon_ten":"en.wikipedia.org","doc":3},{"loai":"doan","tieu_de":"Tiếng nói của một đại biểu tư vấn","text":"Tháng 10/1923, Nguyễn Ái Quốc dự Đại hội thành lập Quốc tế Nông dân (Krestintern) tại Mátxcơva — quy tụ 158 đại biểu từ 40 quốc gia — và được bầu vào Đoàn Chủ tịch của tổ chức này. Người còn viết bài cho tạp chí của Quốc tế Nông dân. Gần một năm sau, từ 17/6 đến 8/7/1924, Đại hội lần thứ V Quốc tế Cộng sản họp tại Mátxcơva. Với tư cách đại biểu tư vấn — được phát biểu nhưng không có quyền biểu quyết như đại biểu chính thức — Người trình bày quan điểm về vấn đề thuộc địa, kêu gọi phong trào cộng sản quốc tế quan tâm nhiều hơn đến cách mạng ở các nước thuộc địa, trong đó có Đông Dương. Cùng thời gian này, Người còn tham gia hoạt động của Quốc tế Thanh niên Cộng sản và Quốc tế Công hội đỏ, hai tổ chức quốc tế khác đặt trụ sở tại Mátxcơva.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_advisory_delegate_card_issued_to_nguyen_ai_quoc_.jpg","chu_thich":"Thẻ đại biểu tư vấn của Nguyễn Ái Quốc dự Đại hội lần thứ V Quốc tế Cộng sản, Mátxcơva 1924.","credit":"Ảnh: 5th Congress of the Communist Internatio · Public domain · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_participants_in_the_5th_congress_of_the_communis.jpg","chu_thich":"Các đại biểu dự Đại hội lần thứ V Quốc tế Cộng sản họp trong Điện Kremli, 1924.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ngày an táng Lênin và bài báo trên Pravda","text":"Lênin từ trần ngày 21/1/1924, ở tuổi 53, sau một thời gian dài lâm bệnh. Tin dữ khiến cả nước Nga Xô-viết chìm trong tang tóc giữa mùa đông khắc nghiệt. Sáu ngày sau, 27/1/1924, lễ tang được cử hành và thi hài Lênin được đưa vào một lăng mộ gỗ dựng tạm bên tường thành Kremli, giữa Quảng trường Đỏ phủ đầy tuyết — công trình lâm thời được dựng cấp tốc để kịp đón hàng vạn người đến viếng trước khi lăng đá kiên cố được xây sau đó. Nguyễn Ái Quốc, khi ấy đang làm việc và học tập tại Mátxcơva, có mặt trong dòng người đến viếng vị lãnh tụ của Cách mạng Tháng Mười. Cũng đúng ngày hôm đó, bài báo 'Lênin và các dân tộc thuộc địa' của Người được đăng trên báo Pravda (Sự thật) — cơ quan ngôn luận trung ương của Đảng Cộng sản (bônsêvích) Nga — bày tỏ lòng tiếc thương và khẳng định ý nghĩa học thuyết của Lênin đối với các dân tộc bị áp bức trên toàn thế giới.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_article_lenin_and_the_colonial_peoples_by_nguyen.jpg","chu_thich":"Bài báo 'Lênin và các dân tộc thuộc địa' của Nguyễn Ái Quốc, đăng trên Pravda ngày 27/1/1924 — đúng ngày an táng Lênin.","credit":"Ảnh: Nguyen Ai Quoc (Ho Chi Minh) · Public domain · Wikimedia Commons"},{"loai":"anh","src":"textures/bai/G08_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Liên Xô – Petrograd và Mátxcơva","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"anh","src":"textures/bai/G08_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Liên Xô – Petrograd và Mátxcơva nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Lần trở lại, những năm 1934–1938","text":"Sau khi rời Liên Xô năm 1924 để sang Quảng Châu hoạt động, rồi trải qua những năm tháng gian khổ ở Xiêm, Hồng Kông và Trung Quốc, giữa năm 1934 Nguyễn Ái Quốc trở lại Mátxcơva. Người theo học Trường Quốc tế Lê-nin, rồi làm nghiên cứu sinh tại Viện Nghiên cứu các vấn đề dân tộc và thuộc địa; năm 1935, Người còn dự Đại hội VII Quốc tế Cộng sản với tư cách đại biểu tư vấn. Đây là giai đoạn Liên Xô trải qua những cuộc thanh trừng chính trị lớn dưới thời Stalin, ảnh hưởng đến rất nhiều cán bộ Quốc tế Cộng sản đến từ các nước; có tài liệu cho rằng trong hoàn cảnh đó, có lúc Người tạm không được giao những nhiệm vụ quan trọng, nhưng cũng có nghiên cứu khác cho rằng Người vẫn là thành viên được tin cậy của Quốc tế Cộng sản trong suốt giai đoạn này. Dù ở hoàn cảnh nào, Người vẫn kiên nhẫn chờ thời cơ để trở về hoạt động ở phương Đông, và đến cuối năm 1938 thì rời Liên Xô, bắt đầu chặng đường trở lại Trung Quốc.","doc":6},{"loai":"anh","src":"textures/bai/G08_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện Liên Xô – Petrograd và Mátxcơva","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Trong hơn ba mươi năm bôn ba hoạt động cách mạng, Nguyễn Ái Quốc — Hồ Chí Minh từng dùng hàng chục bí danh khác nhau để tránh sự truy lùng của mật thám các nước; riêng ở Liên Xô, tùy từng giai đoạn Người từng mang các tên như Chen Vang hay Lin.","nguon_ten":"en.wikipedia.org","doc":7},{"loai":"moc","items":[["30/6/1923","Đến Petrograd"],["10/1923","Dự Đại hội thành lập Quốc tế Nông dân, được bầu vào Đoàn Chủ tịch"],["1923 – 1924","Học Trường Đại học Phương Đông"],["27/1/1924","Dự lễ an táng Lênin tại Quảng trường Đỏ; bài báo Lênin và các dân tộc thuộc địa đăng trên Pravda cùng ngày"],["17/6 – 8/7/1924","Đại biểu tư vấn tại Đại hội V Quốc tế Cộng sản"],["11/1924","Đến Quảng Châu (11/11/1924), bắt đầu hoạt động ở Trung Quốc"],["1934 – 1938","Trở lại Liên Xô: Trường Quốc tế Lê-nin và Viện các vấn đề dân tộc, thuộc địa"]]}],"doc":[{"i":-1,"t":"Mátxcơva mùa đông 1924: từ Quốc tế Cộng sản đến ngày tang Lênin. Tháng 6/1923, mang trên mình một tấm thị thực đứng tên khác, Nguyễn Ái Quốc lặng lẽ rời Paris để đến với trung tâm phong trào cộng sản quốc tế. Ở Mátxcơva, Người vừa là học trò trong giảng đường Trường Đại học Phương Đông, vừa là đại biểu phát biểu trước những người cộng sản khắp năm châu. Và cũng chính nơi đây, giữa mùa đông năm 1924, Người đứng trong dòng người tiễn đưa lãnh tụ Lênin."},{"t":"Chuyến đi bí mật mang tên Chen Vang. Giữa năm 1923, Nguyễn Ái Quốc bí mật rời Paris sang nước Nga Xô-viết — bí mật vì khi đó Người đã là mục tiêu theo dõi thường xuyên của mật thám Pháp, và một chuyến đi công khai sang nước Nga Xô-viết hẳn sẽ đặt dấu chấm hết cho khả năng trở lại hoạt động ở châu Âu. Tấm thị thực nhập cảnh Nga số 1829, do đại diện Liên Xô tại Berlin cấp ngày 16/6/1923, mang một cái tên khác — Chen Vang. Ngày 30/6/1923, Người đến Petrograd (nay là Sankt-Peterburg), thành phố vừa trải qua Cách mạng Tháng Mười chưa đầy sáu năm trước, rồi từ đó tiếp tục đến Mátxcơva để bắt đầu quãng thời gian làm việc trong bộ máy Quốc tế Cộng sản (Comintern)."},{"t":"Giảng đường Trường Đại học Phương Đông. Tại Mátxcơva, Người theo học tại Trường Đại học Cộng sản của những người lao động phương Đông (KUTV) — ngôi trường được thành lập ở Mátxcơva năm 1921 để đào tạo cán bộ cách mạng cho các dân tộc thuộc địa và phụ thuộc ở châu Á, châu Phi và thế giới Ả Rập, với chương trình gồm lý luận Mác-xít, tổ chức đảng, công tác tuyên truyền và chiến thuật cách mạng. Ở đây, Người vừa học tiếng Nga vừa tiếp cận lý luận cách mạng một cách bài bản lần đầu tiên sau nhiều năm tự học qua sách báo và thực tiễn lao động ở châu Âu. Ít năm sau, chính ngôi trường này còn đào tạo nhiều cán bộ Việt Nam khác, trong đó có ba người sau này lần lượt trở thành Tổng Bí thư đầu tiên của Đảng Cộng sản Việt Nam: Trần Phú, Lê Hồng Phong và Hà Huy Tập."},{"t":"Bạn có biết? Trường Đại học Phương Đông tồn tại chưa đầy hai thập niên: sau khi đào tạo hàng nghìn cán bộ cách mạng từ khắp các thuộc địa và các nước phương Đông, trường bị giải thể trong những năm 1937–1938, giữa cao trào thanh trừng chính trị ở Liên Xô — nhiều giảng viên và cựu sinh viên của trường cũng trở thành nạn nhân của giai đoạn này."},{"t":"Tiếng nói của một đại biểu tư vấn. Tháng 10/1923, Nguyễn Ái Quốc dự Đại hội thành lập Quốc tế Nông dân (Krestintern) tại Mátxcơva — quy tụ 158 đại biểu từ 40 quốc gia — và được bầu vào Đoàn Chủ tịch của tổ chức này. Người còn viết bài cho tạp chí của Quốc tế Nông dân. Gần một năm sau, từ 17/6 đến 8/7/1924, Đại hội lần thứ V Quốc tế Cộng sản họp tại Mátxcơva. Với tư cách đại biểu tư vấn — được phát biểu nhưng không có quyền biểu quyết như đại biểu chính thức — Người trình bày quan điểm về vấn đề thuộc địa, kêu gọi phong trào cộng sản quốc tế quan tâm nhiều hơn đến cách mạng ở các nước thuộc địa, trong đó có Đông Dương. Cùng thời gian này, Người còn tham gia hoạt động của Quốc tế Thanh niên Cộng sản và Quốc tế Công hội đỏ, hai tổ chức quốc tế khác đặt trụ sở tại Mátxcơva."},{"t":"Ngày an táng Lênin và bài báo trên Pravda. Lênin từ trần ngày 21/1/1924, ở tuổi 53, sau một thời gian dài lâm bệnh. Tin dữ khiến cả nước Nga Xô-viết chìm trong tang tóc giữa mùa đông khắc nghiệt. Sáu ngày sau, 27/1/1924, lễ tang được cử hành và thi hài Lênin được đưa vào một lăng mộ gỗ dựng tạm bên tường thành Kremli, giữa Quảng trường Đỏ phủ đầy tuyết — công trình lâm thời được dựng cấp tốc để kịp đón hàng vạn người đến viếng trước khi lăng đá kiên cố được xây sau đó. Nguyễn Ái Quốc, khi ấy đang làm việc và học tập tại Mátxcơva, có mặt trong dòng người đến viếng vị lãnh tụ của Cách mạng Tháng Mười. Cũng đúng ngày hôm đó, bài báo 'Lênin và các dân tộc thuộc địa' của Người được đăng trên báo Pravda (Sự thật) — cơ quan ngôn luận trung ương của Đảng Cộng sản (bônsêvích) Nga — bày tỏ lòng tiếc thương và khẳng định ý nghĩa học thuyết của Lênin đối với các dân tộc bị áp bức trên toàn thế giới."},{"t":"Lần trở lại, những năm 1934–1938. Sau khi rời Liên Xô năm 1924 để sang Quảng Châu hoạt động, rồi trải qua những năm tháng gian khổ ở Xiêm, Hồng Kông và Trung Quốc, giữa năm 1934 Nguyễn Ái Quốc trở lại Mátxcơva. Người theo học Trường Quốc tế Lê-nin, rồi làm nghiên cứu sinh tại Viện Nghiên cứu các vấn đề dân tộc và thuộc địa; năm 1935, Người còn dự Đại hội VII Quốc tế Cộng sản với tư cách đại biểu tư vấn. Đây là giai đoạn Liên Xô trải qua những cuộc thanh trừng chính trị lớn dưới thời Stalin, ảnh hưởng đến rất nhiều cán bộ Quốc tế Cộng sản đến từ các nước; có tài liệu cho rằng trong hoàn cảnh đó, có lúc Người tạm không được giao những nhiệm vụ quan trọng, nhưng cũng có nghiên cứu khác cho rằng Người vẫn là thành viên được tin cậy của Quốc tế Cộng sản trong suốt giai đoạn này. Dù ở hoàn cảnh nào, Người vẫn kiên nhẫn chờ thời cơ để trở về hoạt động ở phương Đông, và đến cuối năm 1938 thì rời Liên Xô, bắt đầu chặng đường trở lại Trung Quốc."},{"t":"Bạn có biết? Trong hơn ba mươi năm bôn ba hoạt động cách mạng, Nguyễn Ái Quốc — Hồ Chí Minh từng dùng hàng chục bí danh khác nhau để tránh sự truy lùng của mật thám các nước; riêng ở Liên Xô, tùy từng giai đoạn Người từng mang các tên như Chen Vang hay Lin."}],"hien_vat":[{"ten":"Tường thành và tháp Spasskaya của Điện Kremli","mo_ta":"Tường gạch đỏ có răng cưa hình đuôi én bao quanh Điện Kremli; tháp Spasskaya với đồng hồ bốn mặt và mái chóp xanh là cổng chính hướng ra Quảng trường Đỏ.","nguon":"https://en.wikipedia.org/wiki/Death_and_funeral_of_Vladimir_Lenin"},{"ten":"Lăng gỗ tạm của Lênin","mo_ta":"Dựng cấp tốc ngày 27/1/1924 bên tường Kremli để kịp lễ an táng, đây là công trình lâm thời hình khối lập phương với mái bậc, trước khi lăng đá granit hiện nay được xây dựng thay thế.","nguon":"https://en.wikipedia.org/wiki/Death_and_funeral_of_Vladimir_Lenin"},{"ten":"Nhà thờ Thánh Basil","mo_ta":"Nhà thờ chín mái vòm củ hành nhiều màu ở đầu phía nam Quảng trường Đỏ, một trong những công trình biểu tượng nhất của Mátxcơva, đã đứng đó từ thế kỷ XVI.","nguon":"https://en.wikipedia.org/wiki/Death_and_funeral_of_Vladimir_Lenin"},{"ten":"Cửa hàng bách hóa GUM","mo_ta":"Dãy nhà buôn bán lớn với mái kính đặc trưng, nằm ở cạnh đông của Quảng trường Đỏ, đối diện Điện Kremli qua quảng trường.","nguon":"https://en.wikipedia.org/wiki/Death_and_funeral_of_Vladimir_Lenin"},{"ten":"Bục đá Lobnoye Mesto","mo_ta":"Bục đá tròn cổ trên Quảng trường Đỏ, từng dùng để công bố các sắc lệnh của Sa hoàng thời trước, nằm gần Nhà thờ Thánh Basil.","nguon":"https://en.wikipedia.org/wiki/Death_and_funeral_of_Vladimir_Lenin"}],"hoi_dap":[{"hoi":"Nguyễn Ái Quốc mang tên gì trên tấm thị thực nhập cảnh Nga tháng 6/1923?","dap":"Chen Vang.","sai":["Lý Thụy","Thầu Chín","Nguyễn Ái Quấc"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Người đến Petrograd vào ngày nào?","dap":"30/6/1923.","sai":["1/5/1923","10/10/1923","21/1/1924"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Trường Đại học Phương Đông (KUTV) ở Mátxcơva được lập ra để làm gì?","dap":"Đào tạo cán bộ cách mạng cho các dân tộc thuộc địa và phụ thuộc ở châu Á, châu Phi và thế giới Ả Rập.","sai":["Đào tạo sĩ quan quân đội Liên Xô","Nghiên cứu ngôn ngữ học phương Đông thuần túy","Đào tạo nhà ngoại giao cho chính phủ Liên Xô"],"nguon":"https://en.wikipedia.org/wiki/Communist_University_of_the_Toilers_of_the_East"},{"hoi":"Tại Đại hội thành lập Quốc tế Nông dân tháng 10/1923, Nguyễn Ái Quốc được bầu vào cơ quan nào?","dap":"Đoàn Chủ tịch (Presidium) của Quốc tế Nông dân.","sai":["Ban Chấp hành Quốc tế Cộng sản","Ban Bí thư Đảng Cộng sản Liên Xô","Hội đồng Dân ủy"],"nguon":"https://en.wikipedia.org/wiki/Peasant_International"},{"hoi":"Tại Đại hội lần thứ V Quốc tế Cộng sản năm 1924, Người tham dự với tư cách gì?","dap":"Đại biểu tư vấn.","sai":["Đại biểu chính thức có quyền biểu quyết","Quan sát viên không được phát biểu","Chủ tịch đoàn đại hội"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Lênin từ trần vào ngày nào?","dap":"21/1/1924.","sai":["27/1/1924","7/11/1917","5/3/1953"],"nguon":"https://en.wikipedia.org/wiki/Death_and_funeral_of_Vladimir_Lenin"},{"hoi":"Lăng mộ đầu tiên của Lênin, dựng ngày 27/1/1924, được làm bằng chất liệu gì?","dap":"Gỗ (lăng tạm), trước khi được thay bằng lăng đá.","sai":["Đá hoa cương","Bê tông cốt thép","Đá granit đỏ"],"nguon":"https://en.wikipedia.org/wiki/Death_and_funeral_of_Vladimir_Lenin"},{"hoi":"Bài báo nào của Nguyễn Ái Quốc đăng trên Pravda đúng ngày an táng Lênin?","dap":"\"Lênin và các dân tộc thuộc địa\".","sai":["\"Bản án chế độ thực dân Pháp\"","\"Đường Kách mệnh\"","\"Con rồng tre\""],"nguon":"https://commons.wikimedia.org/wiki/File:Article_%22Lenin_and_the_colonial_peoples%22_by_Nguyen_Ai_Quoc.jpg"},{"hoi":"Người trở lại Liên Xô để theo học Trường Quốc tế Lê-nin vào năm nào?","dap":"Năm 1934.","sai":["1927","1930","1938"],"nguon":"https://baotanghochiminh.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam.htm"},{"hoi":"Trong những năm 1934 – 1938 ở Liên Xô, Người theo học trường nào?","dap":"Trường Quốc tế Lê-nin.","sai":["Trường Đại học Phương Đông","Đại học Tổng hợp Lomonosov","Học viện Quân sự Frunze"],"nguon":"https://baotanghochiminh.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam.htm"},{"hoi":"Trường Đại học Phương Đông ở Mátxcơva ngừng hoạt động trong hoàn cảnh nào?","dap":"Bị giải thể năm 1937–1938, giữa cao trào thanh trừng chính trị ở Liên Xô.","sai":["Bị Đức Quốc xã phá hủy trong chiến tranh","Sáp nhập vào Đại học Lomonosov năm 1930","Ngừng hoạt động vì thiếu kinh phí năm 1925"],"nguon":"https://en.wikipedia.org/wiki/Communist_University_of_the_Toilers_of_the_East"},{"hoi":"Ba Tổng Bí thư đầu tiên của Đảng Cộng sản Việt Nam từng học cùng một trường với Nguyễn Ái Quốc ở Mátxcơva. Đó là trường nào?","dap":"Trường Đại học Phương Đông (KUTV).","sai":["Trường Quốc tế Lê-nin","Trường Quân sự Hoàng Phố","Đại học Tổng hợp Lomonosov"],"nguon":"https://en.wikipedia.org/wiki/Communist_University_of_the_Toilers_of_the_East"}],"nguon":[{"ten":"Ho Chi Minh — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Communist University of the Toilers of the East — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Communist_University_of_the_Toilers_of_the_East"},{"ten":"Peasant International — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Peasant_International"},{"ten":"Fifth World Congress of the Comintern — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Fifth_Congress_of_the_Comintern"},{"ten":"Death and funeral of Vladimir Lenin — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Death_and_funeral_of_Vladimir_Lenin"},{"ten":"85 năm Ngày Bác Hồ trở về Tổ quốc — Bảo tàng Hồ Chí Minh","url":"https://baotanghochiminh.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam.htm"}],"so_chu":1032},"G09":{"ma":"G09","tieu_de":"Quảng Châu 1924–1927: lớp học trên phố Văn Minh và con đường Kách mệnh","sapo":"Tháng 11/1924, mang tên Lý Thụy, Người đến Quảng Châu — thành phố đang là trung tâm của cuộc cách mạng dân tộc Trung Hoa với sự trợ giúp của các cố vấn Liên Xô. Trong hơn hai năm ở đây, Người sáng lập Hội Việt Nam Cách mạng Thanh niên, ra báo Thanh Niên, mở những lớp huấn luyện đầu tiên cho thanh niên yêu nước từ trong nước sang. Từ những bài giảng ấy, cuốn Đường Kách mệnh ra đời, trở thành cẩm nang của cả một thế hệ cách mạng Việt Nam.","sapo_en":"Arriving in Guangzhou in November 1924 under the alias Lý Thụy, Hồ Chí Minh founded the Revolutionary Youth League of Vietnam, its newspaper Thanh Niên, and training classes whose lectures later became the book The Revolutionary Path.","bia":{"src":"textures/ht/ht_anh_comrade_nguyen_ai_quoc_1924.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Lý Thụy đến Quảng Châu","text":"Ngày 11/11/1924, Nguyễn Ái Quốc đến Quảng Châu dưới cái tên Lý Thụy, sau chặng đường từ Mátxcơva rời đi từ tháng trước đó. Đây là thời điểm thành phố đang là trung tâm của chính phủ Quốc dân Đảng do Tôn Trung Sơn lãnh đạo, với sự hậu thuẫn của các cố vấn Liên Xô trong Mặt trận thống nhất lần thứ nhất giữa Quốc dân Đảng và Đảng Cộng sản Trung Quốc còn non trẻ. Tại đây, Người làm phiên dịch trong đoàn cố vấn của Mikhail Borodin — trưởng đoàn cố vấn chính trị Liên Xô bên cạnh chính phủ Tôn Trung Sơn — nhờ đó có điều kiện tiếp cận nhiều nhà cách mạng Trung Quốc và quốc tế đang hội tụ về thành phố cảng sông Châu Giang này, trong đó có nhiều thanh niên yêu nước Việt Nam đã bí mật vượt biên sang tìm đường hoạt động.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_2025_02_05_former_residence_of_ho_chi_minh_kunmi.jpg","chu_thich":"Nhà lưu niệm Hồ Chí Minh tại Côn Minh, Vân Nam","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Hội Việt Nam Cách mạng Thanh niên và báo Thanh Niên","text":"Tháng 6/1925, Người sáng lập Hội Việt Nam Cách mạng Thanh niên — tổ chức cách mạng đầu tiên theo khuynh hướng cộng sản của người Việt Nam — và cho ra số báo Thanh Niên đầu tiên, tờ báo cách mạng bí mật được tìm cách chuyển về nước qua nhiều ngả. Trụ sở và lớp huấn luyện đặt tại một căn nhà trên phố Văn Minh, khu phố có những dãy nhà 'kỵ lâu' kiểu Lĩnh Nam đặc trưng — tầng trệt lùi vào tạo thành hiên có mái che, các tầng trên nhô ra che nắng mưa cho người đi bộ. Từ năm 1925 đến 1927, Người đã mở ba lớp huấn luyện chính trị với khoảng 75 học viên là thanh niên yêu nước từ trong nước bí mật sang học; nhiều người trong số họ sau đó được gửi theo học tại Trường Quân sự Hoàng Phố gần đó.","doc":2},{"loai":"anh","src":"textures/bai/G09_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Trung Quốc – Quảng Châu","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"anh","src":"textures/ht/ht_anh_whampoa_military_academy_gate.jpg","chu_thich":"Cổng Trường Quân sự Hoàng Phố, Quảng Châu — nơi nhiều học viên của Hội Việt Nam Cách mạng Thanh niên theo học.","credit":"Ảnh: Chintunglee · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Trường Quân sự Hoàng Phố khai giảng tháng 6/1924 trên đảo Trường Châu (Quảng Châu), do Tưởng Giới Thạch làm hiệu trưởng, với sự tham gia giảng dạy của các cố vấn quân sự Liên Xô — đây chính là ngôi trường Nguyễn Ái Quốc gửi nhiều học viên Việt Nam của mình sang học quân sự.","nguon_ten":"en.wikipedia.org","doc":3},{"loai":"doan","tieu_de":"Đường Kách mệnh — cẩm nang của một thế hệ","text":"Các bài giảng của Người trong những lớp huấn luyện ấy — về tư cách một người cách mệnh, về lịch sử các cuộc cách mạng trên thế giới, về con đường giải phóng dân tộc — được tập hợp và xuất bản năm 1927 thành cuốn Đường Kách mệnh. Đây là một trong những văn kiện lý luận cách mạng bằng tiếng Việt sớm nhất, được in bí mật rồi tìm cách đưa về nước, trở thành sách gối đầu giường của nhiều thế hệ thanh niên yêu nước Việt Nam trong những năm sau đó.","doc":4},{"loai":"anh","src":"textures/bai/G09_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Trung Quốc – Quảng Châu nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Biến cố tháng 4/1927","text":"Đầu năm 1927, những rạn nứt trong Mặt trận thống nhất Quốc – Cộng ngày càng lộ rõ. Tháng 4/1927, Tưởng Giới Thạch quay sang đàn áp những người cộng sản — trước hết ở Thượng Hải, rồi lan tới Quảng Châu — chấm dứt Mặt trận thống nhất Quốc – Cộng. Nhiều cơ sở cách mạng bị khủng bố; đầu tháng 5/1927, Nguyễn Ái Quốc phải rời Quảng Châu sang Hồng Kông trong hoàn cảnh khẩn cấp, rồi tiếp tục hành trình sang Liên Xô và châu Âu, trước khi tìm đường về gần Tổ quốc hơn.","doc":5},{"loai":"doan","tieu_de":"Trở lại Trung Quốc: Côn Minh, Quế Lâm (1938–1940)","text":"Cuối năm 1938, sau nhiều năm ở Liên Xô, Người trở lại Trung Quốc. Người đến Diên An, rồi xuống Quế Lâm (Quảng Tây) làm việc tại Văn phòng Bát lộ quân — lực lượng vũ trang do Đảng Cộng sản Trung Quốc lãnh đạo — trong vai một sĩ quan mang tên Hồ Quang; năm 1939, Người có thời gian công tác cùng tướng Diệp Kiếm Anh tại lớp huấn luyện du kích ở Hồ Nam, rồi đầu năm 1940 đến Côn Minh (Vân Nam). So với mười bốn năm trước, khi lần đầu đến Quảng Châu, lần trở lại này Người đã là một nhà cách mạng dày dạn kinh nghiệm. Đây là quãng thời gian Người kiên trì tìm cách bắt liên lạc với các cơ sở cách mạng trong nước, chuẩn bị cho ngày trở về sau gần ba mươi năm bôn ba tìm đường cứu nước.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_2025_02_05_interior_of_ho_chi_minh_s_former_resi.jpg","chu_thich":"Bên trong nhà lưu niệm Hồ Chí Minh ở Côn Minh","credit":"Ảnh: 源義信 · CC BY 4.0 · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_to_cuoi_tap_tho_nhat_ky_trong_tu.jpg","chu_thich":"Tờ cuối bản thảo Nhật ký trong tù (1942 – 1943)","credit":"Ảnh: 7ieulong · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ ngục tối Quảng Tây: Nhật ký trong tù","text":"Tháng 8/1942, trên đường trở lại Trung Quốc để bắt liên lạc với lực lượng Đồng minh chống phát xít, Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ với nghi vấn là gián điệp, rồi bị giải qua hơn mười nhà lao thuộc tỉnh Quảng Tây trong suốt mười ba tháng, đến tháng 9/1943 mới được trả tự do. Trong những ngày bị giam cầm ấy, Người đã viết tập thơ chữ Hán Nhật ký trong tù — hơn một trăm bài thơ vừa ghi lại cảnh ngục tù khắc nghiệt, vừa thể hiện tinh thần lạc quan và ý chí kiên cường của một người cách mạng. Bản thảo tập thơ hiện là Bảo vật quốc gia, được lưu giữ và trưng bày tại Bảo tàng Hồ Chí Minh.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_s_prison_diary_in_2016.jpg","chu_thich":"Bản thảo Nhật ký trong tù — Bảo vật quốc gia, trưng bày tại Bảo tàng Hồ Chí Minh","credit":"Ảnh: Cookie Nguyen · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"anh","src":"textures/bai/G09_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện Trung Quốc – Quảng Châu","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"trich","text":"Không có gì quý hơn độc lập, tự do.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Lời kêu gọi ngày 17/7/1966","doc":8},{"loai":"moc","items":[["11/11/1924","Đến Quảng Châu với tên Lý Thụy"],["6/1925","Lập Hội Việt Nam Cách mạng Thanh niên; ra báo Thanh Niên"],["1925 – 1927","Mở ba lớp huấn luyện chính trị tại phố Văn Minh"],["1927","Xuất bản Đường Kách mệnh"],["4/1927","Biến cố Tưởng Giới Thạch đàn áp cộng sản; đầu tháng 5, Người rời Quảng Châu sang Hồng Kông"],["1938 – 1940","Ở Quế Lâm, Côn Minh; bắt liên lạc với trong nước"],["8/1942 – 9/1943","Bị giam ở Quảng Tây; viết Nhật ký trong tù"]]}],"doc":[{"i":-1,"t":"Quảng Châu 1924–1927: lớp học trên phố Văn Minh và con đường Kách mệnh. Tháng 11/1924, mang tên Lý Thụy, Người đến Quảng Châu — thành phố đang là trung tâm của cuộc cách mạng dân tộc Trung Hoa với sự trợ giúp của các cố vấn Liên Xô. Trong hơn hai năm ở đây, Người sáng lập Hội Việt Nam Cách mạng Thanh niên, ra báo Thanh Niên, mở những lớp huấn luyện đầu tiên cho thanh niên yêu nước từ trong nước sang. Từ những bài giảng ấy, cuốn Đường Kách mệnh ra đời, trở thành cẩm nang của cả một thế hệ cách mạng Việt Nam."},{"t":"Lý Thụy đến Quảng Châu. Ngày 11/11/1924, Nguyễn Ái Quốc đến Quảng Châu dưới cái tên Lý Thụy, sau chặng đường từ Mátxcơva rời đi từ tháng trước đó. Đây là thời điểm thành phố đang là trung tâm của chính phủ Quốc dân Đảng do Tôn Trung Sơn lãnh đạo, với sự hậu thuẫn của các cố vấn Liên Xô trong Mặt trận thống nhất lần thứ nhất giữa Quốc dân Đảng và Đảng Cộng sản Trung Quốc còn non trẻ. Tại đây, Người làm phiên dịch trong đoàn cố vấn của Mikhail Borodin — trưởng đoàn cố vấn chính trị Liên Xô bên cạnh chính phủ Tôn Trung Sơn — nhờ đó có điều kiện tiếp cận nhiều nhà cách mạng Trung Quốc và quốc tế đang hội tụ về thành phố cảng sông Châu Giang này, trong đó có nhiều thanh niên yêu nước Việt Nam đã bí mật vượt biên sang tìm đường hoạt động."},{"t":"Hội Việt Nam Cách mạng Thanh niên và báo Thanh Niên. Tháng 6/1925, Người sáng lập Hội Việt Nam Cách mạng Thanh niên — tổ chức cách mạng đầu tiên theo khuynh hướng cộng sản của người Việt Nam — và cho ra số báo Thanh Niên đầu tiên, tờ báo cách mạng bí mật được tìm cách chuyển về nước qua nhiều ngả. Trụ sở và lớp huấn luyện đặt tại một căn nhà trên phố Văn Minh, khu phố có những dãy nhà 'kỵ lâu' kiểu Lĩnh Nam đặc trưng — tầng trệt lùi vào tạo thành hiên có mái che, các tầng trên nhô ra che nắng mưa cho người đi bộ. Từ năm 1925 đến 1927, Người đã mở ba lớp huấn luyện chính trị với khoảng 75 học viên là thanh niên yêu nước từ trong nước bí mật sang học; nhiều người trong số họ sau đó được gửi theo học tại Trường Quân sự Hoàng Phố gần đó."},{"t":"Bạn có biết? Trường Quân sự Hoàng Phố khai giảng tháng 6/1924 trên đảo Trường Châu (Quảng Châu), do Tưởng Giới Thạch làm hiệu trưởng, với sự tham gia giảng dạy của các cố vấn quân sự Liên Xô — đây chính là ngôi trường Nguyễn Ái Quốc gửi nhiều học viên Việt Nam của mình sang học quân sự."},{"t":"Đường Kách mệnh — cẩm nang của một thế hệ. Các bài giảng của Người trong những lớp huấn luyện ấy — về tư cách một người cách mệnh, về lịch sử các cuộc cách mạng trên thế giới, về con đường giải phóng dân tộc — được tập hợp và xuất bản năm 1927 thành cuốn Đường Kách mệnh. Đây là một trong những văn kiện lý luận cách mạng bằng tiếng Việt sớm nhất, được in bí mật rồi tìm cách đưa về nước, trở thành sách gối đầu giường của nhiều thế hệ thanh niên yêu nước Việt Nam trong những năm sau đó."},{"t":"Biến cố tháng 4/1927. Đầu năm 1927, những rạn nứt trong Mặt trận thống nhất Quốc – Cộng ngày càng lộ rõ. Tháng 4/1927, Tưởng Giới Thạch quay sang đàn áp những người cộng sản — trước hết ở Thượng Hải, rồi lan tới Quảng Châu — chấm dứt Mặt trận thống nhất Quốc – Cộng. Nhiều cơ sở cách mạng bị khủng bố; đầu tháng 5/1927, Nguyễn Ái Quốc phải rời Quảng Châu sang Hồng Kông trong hoàn cảnh khẩn cấp, rồi tiếp tục hành trình sang Liên Xô và châu Âu, trước khi tìm đường về gần Tổ quốc hơn."},{"t":"Trở lại Trung Quốc: Côn Minh, Quế Lâm (1938–1940). Cuối năm 1938, sau nhiều năm ở Liên Xô, Người trở lại Trung Quốc. Người đến Diên An, rồi xuống Quế Lâm (Quảng Tây) làm việc tại Văn phòng Bát lộ quân — lực lượng vũ trang do Đảng Cộng sản Trung Quốc lãnh đạo — trong vai một sĩ quan mang tên Hồ Quang; năm 1939, Người có thời gian công tác cùng tướng Diệp Kiếm Anh tại lớp huấn luyện du kích ở Hồ Nam, rồi đầu năm 1940 đến Côn Minh (Vân Nam). So với mười bốn năm trước, khi lần đầu đến Quảng Châu, lần trở lại này Người đã là một nhà cách mạng dày dạn kinh nghiệm. Đây là quãng thời gian Người kiên trì tìm cách bắt liên lạc với các cơ sở cách mạng trong nước, chuẩn bị cho ngày trở về sau gần ba mươi năm bôn ba tìm đường cứu nước."},{"t":"Từ ngục tối Quảng Tây: Nhật ký trong tù. Tháng 8/1942, trên đường trở lại Trung Quốc để bắt liên lạc với lực lượng Đồng minh chống phát xít, Người bị chính quyền địa phương của Tưởng Giới Thạch bắt giữ với nghi vấn là gián điệp, rồi bị giải qua hơn mười nhà lao thuộc tỉnh Quảng Tây trong suốt mười ba tháng, đến tháng 9/1943 mới được trả tự do. Trong những ngày bị giam cầm ấy, Người đã viết tập thơ chữ Hán Nhật ký trong tù — hơn một trăm bài thơ vừa ghi lại cảnh ngục tù khắc nghiệt, vừa thể hiện tinh thần lạc quan và ý chí kiên cường của một người cách mạng. Bản thảo tập thơ hiện là Bảo vật quốc gia, được lưu giữ và trưng bày tại Bảo tàng Hồ Chí Minh."},{"t":"Không có gì quý hơn độc lập, tự do. — Chủ tịch Hồ Chí Minh"}],"hien_vat":[{"ten":"Dãy nhà kỵ lâu trên phố Văn Minh","mo_ta":"Kiến trúc phố thị đặc trưng vùng Lĩnh Nam: tầng trệt lùi vào tạo hiên có mái che cho người đi bộ, các tầng trên xây nhô ra che nắng mưa, tường vữa màu nhạt, cửa chớp gỗ.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Nhà số 248–250, phố Văn Minh","mo_ta":"Ngôi nhà nơi Nguyễn Ái Quốc mở các lớp huấn luyện cán bộ của Hội Việt Nam Cách mạng Thanh niên (1925–1927) và tổ chức in báo Thanh Niên.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Gian lớp học tái hiện","mo_ta":"Không gian tầng trệt được phục dựng với ghế băng gỗ, bàn giảng và bảng đen — nơi khoảng 75 học viên qua ba khóa được Người trực tiếp giảng dạy trong hai năm 1925–1927.","nguon":"https://baotanghochiminh.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam.htm"},{"ten":"Chồng báo Thanh Niên và sách Đường Kách mệnh","mo_ta":"Báo Thanh Niên, tờ báo cách mạng do Người sáng lập tháng 6/1925, và sách Đường Kách mệnh in năm 1927 từ các bài giảng — hai ấn phẩm được bí mật chuyển về nước để tuyên truyền tư tưởng cách mạng.","nguon":"https://baotanghochiminh.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam.htm"},{"ten":"Cây đa đầu phố Văn Minh","mo_ta":"Cây cổ thụ đứng ở đầu phố, một chi tiết cảnh quan quen thuộc của các phố thị Lĩnh Nam đầu thế kỷ XX, được phục dựng trong không gian 3D của gian trưng bày.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"}],"hoi_dap":[{"hoi":"Nguyễn Ái Quốc đến Quảng Châu ngày nào, dưới tên gì?","dap":"Ngày 11/11/1924, dưới tên Lý Thụy.","sai":["Ngày 5/6/1911, dưới tên Văn Ba","Ngày 30/6/1923, dưới tên Chen Vang","Ngày 28/1/1941, dưới tên Già Thu"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Hội Việt Nam Cách mạng Thanh niên được thành lập vào thời gian nào?","dap":"Tháng 6/1925.","sai":["Tháng 11/1924","Tháng 1/1927","Tháng 2/1930"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Tờ báo cách mạng do Nguyễn Ái Quốc sáng lập ở Quảng Châu tên là gì?","dap":"Báo Thanh Niên.","sai":["Báo Việt Nam hồn","Báo Người cùng khổ (Le Paria)","Báo Cứu quốc"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Lớp huấn luyện chính trị của Người ở Quảng Châu đặt tại đâu?","dap":"Một căn nhà trên phố Văn Minh, Quảng Châu.","sai":["Trong khuôn viên Trường Quân sự Hoàng Phố","Trên một chiếc thuyền neo trên sông Châu Giang","Trong trụ sở lãnh sự quán Pháp"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Nhiều học viên của Hội Việt Nam Cách mạng Thanh niên được gửi đi học quân sự ở đâu?","dap":"Trường Quân sự Hoàng Phố.","sai":["Học viện Quân sự Frunze ở Mátxcơva","Trường Võ bị Bảo Định","Học viện Lục quân Nam Kinh"],"nguon":"https://en.wikipedia.org/wiki/Whampoa_Military_Academy"},{"hoi":"Cuốn sách nào được tập hợp từ các bài giảng trong lớp huấn luyện, xuất bản năm 1927?","dap":"Đường Kách mệnh.","sai":["Bản án chế độ thực dân Pháp","Nhật ký trong tù","Con rồng tre"],"nguon":"https://baotanghochiminh.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam.htm"},{"hoi":"Biến cố nào vào tháng 4/1927 khiến Người phải rời Quảng Châu?","dap":"Tưởng Giới Thạch quay sang đàn áp những người cộng sản, chấm dứt Mặt trận thống nhất Quốc dân Đảng – Cộng sản.","sai":["Động đất lớn phá hủy phố Văn Minh","Nhật Bản chiếm đóng Quảng Châu","Tôn Trung Sơn ra lệnh trục xuất người nước ngoài"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Trong giai đoạn 1938–1940, Người hoạt động ở những thành phố nào của Trung Quốc?","dap":"Côn Minh (Vân Nam) và Quế Lâm (Quảng Tây).","sai":["Thượng Hải và Nam Kinh","Bắc Kinh và Thiên Tân","Trùng Khánh và Thành Đô"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Từ 8/1942 đến 9/1943, Người bị chính quyền Tưởng Giới Thạch giam giữ tại tỉnh nào?","dap":"Quảng Tây.","sai":["Vân Nam","Quảng Đông","Tứ Xuyên"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Tác phẩm nào ra đời trong thời gian Người bị giam giữ ở Quảng Tây 1942–1943?","dap":"Nhật ký trong tù.","sai":["Đường Kách mệnh","Bản án chế độ thực dân Pháp","Tuyên ngôn Độc lập"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"}],"nguon":[{"ten":"Ho Chi Minh — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Whampoa Military Academy — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Whampoa_Military_Academy"},{"ten":"Mikhail Borodin — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Mikhail_Borodin"},{"ten":"Zeng Xueming — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Zeng_Xueming"},{"ten":"85 năm Ngày Bác Hồ trở về Tổ quốc — Bảo tàng Hồ Chí Minh","url":"https://baotanghochiminh.vn/85-nam-ngay-bac-ho-tro-ve-to-quoc-mo-ra-thoi-ky-moi-cua-cach-mang-viet-nam.htm"}],"so_chu":949},"G10":{"ma":"G10","tieu_de":"Thầu Chín — người con xa xứ giữa lòng kiều bào đất Xiêm","sapo":"Giữa năm 1928, một người đàn ông đội nón lá, đi dép, tự nhận là Thầu Chín, lặng lẽ đến sống trong các xóm Việt kiều dọc sông Mê Kông ở đông bắc Xiêm La. Suốt hơn một năm, ông cùng bà con cày ruộng, đào giếng, dạy chữ, dịch sách và gây dựng những cơ sở cách mạng đầu tiên nối liền với quê nhà qua ngả Lào. Đó chính là lãnh tụ Nguyễn Ái Quốc, đang âm thầm tìm đường trở về Tổ quốc.","sapo_en":"In mid-1928 a man calling himself Thau Chin quietly settled among Vietnamese immigrant communities in north-eastern Siam, farming, teaching and building the first revolutionary networks linking back to Vietnam through Laos. He was Nguyen Ai Quoc, the future Ho Chi Minh, biding his time before returning home.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_front.jpg","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một cái tên mới bên dòng Mê Kông","text":"Giữa năm 1928, sau nhiều năm bôn ba qua Pháp, Liên Xô và Trung Quốc, Nguyễn Ái Quốc tìm đường để được ở gần Tổ quốc hơn. Tháng 7 năm ấy, Người đặt chân tới Xiêm La (nay là Thái Lan), lấy tên Thầu Chín — một cái tên bình dị, hoà lẫn vào cách gọi thân thuộc của bà con Việt kiều vùng đông bắc Thái. Xiêm khi đó là vương quốc độc lập duy nhất trong khu vực, nằm ngoài tầm kiểm soát trực tiếp của thực dân Pháp, lại có một cộng đồng người Việt đông đảo đã sang lập nghiệp từ trước. Đây là nơi thuận lợi để xây dựng một hậu cứ cách mạng: vừa đủ an toàn để tổ chức, vừa đủ gần để giữ liên lạc với quê nhà qua ngả nước Lào láng giềng. Từ Phichit, Udon Thani, Sakon Nakhon đến Nakhon Phanom, ông Thầu Chín lần lượt sống trong các xóm Việt kiều ven sông Mê Kông, nơi những người con xa xứ đã chờ đợi một người dẫn đường như thế từ lâu.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_house_hochiminh_stayed_nakhonphanom.jpg","chu_thich":"Ngôi nhà Người từng ở tại Nakhon Phanom, phục dựng","credit":"Ảnh: BacLuong at Vietnamese Wikipedia · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cùng bà con cày ruộng, đào giếng, dựng trường","text":"Ở đất khách, ông Thầu Chín sống hệt như một người nông dân trong xóm: đội nón lá, đi chân đất hoặc đi dép, cùng bà con ra đồng cày cấy, đào giếng lấy nước ngọt, trồng rau, trồng chuối quanh nhà. Ban ngày lao động, tối đến ông mở lớp dạy chữ quốc ngữ cho trẻ nhỏ và dạy cả người lớn biết đọc, biết viết, để bà con giữ được tiếng nói và gốc gác của mình nơi đất người. Ông còn vận động dựng trường, lập hội tương tế giúp nhau lúc ốm đau hoạn nạn, và gây dựng tờ báo Thân Ái để gắn kết kiều bào rải rác nhiều tỉnh, truyền đi tin tức về phong trào yêu nước trong nước. Chính từ những buổi lên lớp giản dị ấy, từ những đêm ngồi bên bà con kể chuyện quê hương, tinh thần yêu nước được nhen lên bền bỉ trong lòng người Việt xa xứ, để rồi hàng chục năm sau, chính cộng đồng ấy vẫn một lòng hướng về kháng chiến, góp người, góp của cho cách mạng.","doc":2},{"loai":"ban_co_biet","text":"Trong suốt cuộc đời hoạt động cách mạng, Nguyễn Ái Quốc — Hồ Chí Minh đã sử dụng hơn một trăm tên gọi, bí danh, bút danh khác nhau để che giấu tung tích trước mật thám nhiều nước; \"Thầu Chín\" là một trong những cái tên gắn với giai đoạn sống gần dân, giản dị nhất của Người.","nguon_ten":"en.wikipedia.org","doc":3},{"loai":"anh","src":"textures/bai/G10_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Thái Lan – Thầu Chín","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Nhịp cầu bí mật nối liền quê hương","text":"Không chỉ là nơi nương náu, các xóm Việt kiều ở đông bắc Xiêm còn trở thành một mắt xích quan trọng trong mạng lưới liên lạc bí mật giữa những người cách mạng Việt Nam ở nước ngoài với phong trào trong nước. Qua ngả Lào, tài liệu, sách báo cách mạng được bí mật chuyển về Nghệ An, Hà Tĩnh; những thanh niên yêu nước từ trong nước cũng tìm đường sang đây để được giác ngộ rồi trở về hoạt động. Suốt hơn một năm, ông Thầu Chín di chuyển liên tục giữa Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom, vừa để mở rộng cơ sở, vừa để tránh sự theo dõi của mật thám Pháp vốn có tai mắt cả trên đất Xiêm. Cuộc sống giản dị, khiêm nhường của một ông Thầu bình thường trong xóm đã khéo léo che giấu một nhà cách mạng đang âm thầm chuẩn bị cho những nhiệm vụ lớn — trong đó có việc hợp nhất các tổ chức cộng sản trong nước mà ông sẽ hoàn thành chỉ ít lâu sau đó, tại Hồng Kông.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_nakhonphanom_coco.jpg","chu_thich":"Hàng dừa trong khu lưu niệm Nakhon Phanom","credit":"Ảnh: BacLuong · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Nakhon Phanom trong tiếng Thái có nghĩa là \"thành phố núi\", nhưng những dãy núi đá vôi nổi bật nhìn thấy từ bờ sông thành phố thực ra thuộc tỉnh Khăm Muộn của Lào, ở bên kia sông Mê Kông.","nguon_ten":"en.wikipedia.org","doc":5},{"loai":"anh","src":"textures/bai/G10_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện Thái Lan – Thầu Chín","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Ngôi nhà nhỏ ở bản Mạy hôm nay","text":"Ngôi nhà tranh vách ván nơi ông Thầu Chín từng ở tại bản Mạy (Na Chok), ngoại ô thành phố Nakhon Phanom, nay đã được phục dựng và gìn giữ như một chứng tích sống động của những năm tháng ấy. Nhà sàn thấp, mái lá, hiên có bậc thang gỗ, bên trong bày giường tre, bàn viết, đèn dầu đơn sơ; quanh nhà là giếng nước, hàng dừa, vườn xoài, chuối, khóm tre thân thuộc của một làng quê Việt Nam giữa đất Thái. Địa điểm này, cùng khu tưởng niệm ở Udon Thani, do chính kiều bào và bạn bè người Thái cùng nhau gìn giữ suốt nhiều thế hệ; ngôi nhà và khu trưng bày nay vẫn mở cửa đón khách trong và ngoài nước tới thăm, như một biểu tượng đẹp cho tình hữu nghị Việt – Thái được vun đắp từ chính những năm tháng gian khó ấy.","doc":6},{"loai":"anh","src":"textures/bai/G10_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Thái Lan – Thầu Chín nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"anh","src":"textures/bai/G10_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Thái Lan – Thầu Chín","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Rời Xiêm, hướng về ngày hợp nhất","text":"Cuối năm 1929, khi phong trào cộng sản trong nước đã hình thành ba tổ chức riêng rẽ và đặt ra yêu cầu cấp thiết phải thống nhất, ông Thầu Chín rời đất Xiêm, tạm biệt bà con đã cưu mang mình hơn một năm, lên đường sang Hồng Kông. Ở đó, chỉ ít tuần sau, ông sẽ chủ trì hội nghị hợp nhất các tổ chức cộng sản thành một chính đảng duy nhất. Những năm tháng Thầu Chín ở Xiêm La vì thế không chỉ là một chặng nghỉ chân trên hành trình bôn ba cứu nước, mà còn là nơi ông tôi luyện cách gắn bó với dân, sống cùng dân, dựa vào dân — bài học sẽ theo ông suốt những chặng đường cách mạng còn lại.","doc":7},{"loai":"anh","src":"textures/bai/G10_v5.jpg","chu_thich":"Một góc không gian 3D tái hiện Thái Lan – Thầu Chín","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"moc","items":[["7/1928","Đến Xiêm, lấy tên Thầu Chín"],["1928 – 1929","Hoạt động trong kiều bào ở Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom"],["cuối 1929","Rời Xiêm đi Hồng Kông chuẩn bị hợp nhất các tổ chức cộng sản"]]}],"doc":[{"i":-1,"t":"Thầu Chín — người con xa xứ giữa lòng kiều bào đất Xiêm. Giữa năm 1928, một người đàn ông đội nón lá, đi dép, tự nhận là Thầu Chín, lặng lẽ đến sống trong các xóm Việt kiều dọc sông Mê Kông ở đông bắc Xiêm La. Suốt hơn một năm, ông cùng bà con cày ruộng, đào giếng, dạy chữ, dịch sách và gây dựng những cơ sở cách mạng đầu tiên nối liền với quê nhà qua ngả Lào. Đó chính là lãnh tụ Nguyễn Ái Quốc, đang âm thầm tìm đường trở về Tổ quốc."},{"t":"Một cái tên mới bên dòng Mê Kông. Giữa năm 1928, sau nhiều năm bôn ba qua Pháp, Liên Xô và Trung Quốc, Nguyễn Ái Quốc tìm đường để được ở gần Tổ quốc hơn. Tháng 7 năm ấy, Người đặt chân tới Xiêm La (nay là Thái Lan), lấy tên Thầu Chín — một cái tên bình dị, hoà lẫn vào cách gọi thân thuộc của bà con Việt kiều vùng đông bắc Thái. Xiêm khi đó là vương quốc độc lập duy nhất trong khu vực, nằm ngoài tầm kiểm soát trực tiếp của thực dân Pháp, lại có một cộng đồng người Việt đông đảo đã sang lập nghiệp từ trước. Đây là nơi thuận lợi để xây dựng một hậu cứ cách mạng: vừa đủ an toàn để tổ chức, vừa đủ gần để giữ liên lạc với quê nhà qua ngả nước Lào láng giềng. Từ Phichit, Udon Thani, Sakon Nakhon đến Nakhon Phanom, ông Thầu Chín lần lượt sống trong các xóm Việt kiều ven sông Mê Kông, nơi những người con xa xứ đã chờ đợi một người dẫn đường như thế từ lâu."},{"t":"Cùng bà con cày ruộng, đào giếng, dựng trường. Ở đất khách, ông Thầu Chín sống hệt như một người nông dân trong xóm: đội nón lá, đi chân đất hoặc đi dép, cùng bà con ra đồng cày cấy, đào giếng lấy nước ngọt, trồng rau, trồng chuối quanh nhà. Ban ngày lao động, tối đến ông mở lớp dạy chữ quốc ngữ cho trẻ nhỏ và dạy cả người lớn biết đọc, biết viết, để bà con giữ được tiếng nói và gốc gác của mình nơi đất người. Ông còn vận động dựng trường, lập hội tương tế giúp nhau lúc ốm đau hoạn nạn, và gây dựng tờ báo Thân Ái để gắn kết kiều bào rải rác nhiều tỉnh, truyền đi tin tức về phong trào yêu nước trong nước. Chính từ những buổi lên lớp giản dị ấy, từ những đêm ngồi bên bà con kể chuyện quê hương, tinh thần yêu nước được nhen lên bền bỉ trong lòng người Việt xa xứ, để rồi hàng chục năm sau, chính cộng đồng ấy vẫn một lòng hướng về kháng chiến, góp người, góp của cho cách mạng."},{"t":"Bạn có biết? Trong suốt cuộc đời hoạt động cách mạng, Nguyễn Ái Quốc — Hồ Chí Minh đã sử dụng hơn một trăm tên gọi, bí danh, bút danh khác nhau để che giấu tung tích trước mật thám nhiều nước; \"Thầu Chín\" là một trong những cái tên gắn với giai đoạn sống gần dân, giản dị nhất của Người."},{"t":"Nhịp cầu bí mật nối liền quê hương. Không chỉ là nơi nương náu, các xóm Việt kiều ở đông bắc Xiêm còn trở thành một mắt xích quan trọng trong mạng lưới liên lạc bí mật giữa những người cách mạng Việt Nam ở nước ngoài với phong trào trong nước. Qua ngả Lào, tài liệu, sách báo cách mạng được bí mật chuyển về Nghệ An, Hà Tĩnh; những thanh niên yêu nước từ trong nước cũng tìm đường sang đây để được giác ngộ rồi trở về hoạt động. Suốt hơn một năm, ông Thầu Chín di chuyển liên tục giữa Phichit, Udon Thani, Sakon Nakhon, Nakhon Phanom, vừa để mở rộng cơ sở, vừa để tránh sự theo dõi của mật thám Pháp vốn có tai mắt cả trên đất Xiêm. Cuộc sống giản dị, khiêm nhường của một ông Thầu bình thường trong xóm đã khéo léo che giấu một nhà cách mạng đang âm thầm chuẩn bị cho những nhiệm vụ lớn — trong đó có việc hợp nhất các tổ chức cộng sản trong nước mà ông sẽ hoàn thành chỉ ít lâu sau đó, tại Hồng Kông."},{"t":"Bạn có biết? Nakhon Phanom trong tiếng Thái có nghĩa là \"thành phố núi\", nhưng những dãy núi đá vôi nổi bật nhìn thấy từ bờ sông thành phố thực ra thuộc tỉnh Khăm Muộn của Lào, ở bên kia sông Mê Kông."},{"t":"Ngôi nhà nhỏ ở bản Mạy hôm nay. Ngôi nhà tranh vách ván nơi ông Thầu Chín từng ở tại bản Mạy (Na Chok), ngoại ô thành phố Nakhon Phanom, nay đã được phục dựng và gìn giữ như một chứng tích sống động của những năm tháng ấy. Nhà sàn thấp, mái lá, hiên có bậc thang gỗ, bên trong bày giường tre, bàn viết, đèn dầu đơn sơ; quanh nhà là giếng nước, hàng dừa, vườn xoài, chuối, khóm tre thân thuộc của một làng quê Việt Nam giữa đất Thái. Địa điểm này, cùng khu tưởng niệm ở Udon Thani, do chính kiều bào và bạn bè người Thái cùng nhau gìn giữ suốt nhiều thế hệ; ngôi nhà và khu trưng bày nay vẫn mở cửa đón khách trong và ngoài nước tới thăm, như một biểu tượng đẹp cho tình hữu nghị Việt – Thái được vun đắp từ chính những năm tháng gian khó ấy."},{"t":"Rời Xiêm, hướng về ngày hợp nhất. Cuối năm 1929, khi phong trào cộng sản trong nước đã hình thành ba tổ chức riêng rẽ và đặt ra yêu cầu cấp thiết phải thống nhất, ông Thầu Chín rời đất Xiêm, tạm biệt bà con đã cưu mang mình hơn một năm, lên đường sang Hồng Kông. Ở đó, chỉ ít tuần sau, ông sẽ chủ trì hội nghị hợp nhất các tổ chức cộng sản thành một chính đảng duy nhất. Những năm tháng Thầu Chín ở Xiêm La vì thế không chỉ là một chặng nghỉ chân trên hành trình bôn ba cứu nước, mà còn là nơi ông tôi luyện cách gắn bó với dân, sống cùng dân, dựa vào dân — bài học sẽ theo ông suốt những chặng đường cách mạng còn lại."}],"hien_vat":[{"ten":"Ngôi nhà sàn phục dựng ở bản Mạy","mo_ta":"Ngôi nhà sàn thấp, vách ván, mái lá, phỏng theo nếp nhà ông Thầu Chín từng ở tại bản Mạy (Na Chok), ngoại ô Nakhon Phanom. Nhà chỉ có vài gian nhỏ, hiên trước có bậc thang gỗ bước lên, xung quanh là vườn cây và giếng nước. Đây là một trong những di tích được kiều bào và chính quyền địa phương Thái Lan gìn giữ cẩn thận qua nhiều thế hệ.","nguon":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"},{"ten":"Giếng nước trong khu lưu niệm","mo_ta":"Chiếc giếng nhỏ trong khuôn viên nhà lưu niệm, tương truyền do ông Thầu Chín cùng bà con đào để lấy nước sinh hoạt trong những năm sống tại đây. Giếng nay vẫn được giữ nguyên vị trí như một phần của khu di tích.","nguon":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"},{"ten":"Bàn viết và đèn dầu","mo_ta":"Bộ bàn ghế mộc mạc và chiếc đèn dầu trong nhà — nơi ông Thầu Chín soạn tài liệu, dịch sách và viết thư từ liên lạc vào những đêm sống giữa xóm Việt kiều.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Vườn dừa, xoài, chuối quanh nhà","mo_ta":"Hàng dừa, xoài, chuối xanh tốt quanh nhà trong khuôn viên khu lưu niệm, gợi lại không gian một làng quê Việt Nam giữa đất Thái.","nguon":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"},{"ten":"Ruộng lúa và nhà sàn kiểu Isan của xóm giềng","mo_ta":"Bao quanh khu lưu niệm là ruộng lúa và những nếp nhà sàn gỗ kiểu Isan của bà con trong vùng — khung cảnh mà ông Thầu Chín đã sống cùng, cùng lao động suốt hơn một năm ở đông bắc Xiêm.","nguon":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"},{"ten":"Dãy núi đá vôi Khăm Muộn bên kia sông Mê Kông","mo_ta":"Nhìn từ bờ Thái Lan qua sông Mê Kông là dãy núi đá vôi thuộc tỉnh Khăm Muộn của Lào. Dù tên gọi Nakhon Phanom nghĩa là \"thành phố núi\", những ngọn núi đá vôi nổi bật nhất nhìn từ thành phố lại nằm ở phía bờ Lào đối diện.","nguon":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"}],"hoi_dap":[{"hoi":"Ông Thầu Chín đến Xiêm La (Thái Lan) vào thời gian nào?","dap":"Tháng 7 năm 1928.","sai":["Tháng 7 năm 1925","Tháng 1 năm 1930","Tháng 7 năm 1930"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"\"Thầu Chín\" là tên ông dùng để sinh hoạt cùng ai?","dap":"Cộng đồng người Việt (kiều bào) ở vùng đông bắc Xiêm.","sai":["Quan chức triều đình Xiêm","Các nhà truyền giáo phương Tây","Thương nhân người Hoa"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Ở Xiêm, ông Thầu Chín cùng bà con kiều bào làm những việc gì?","dap":"Làm ruộng, đào giếng, dạy học, dịch sách, ra báo.","sai":["Buôn bán tơ lụa xuyên biên giới","Mở đồn điền cao su","Làm phiên dịch cho chính quyền Xiêm"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Tờ báo của kiều bào mà ông Thầu Chín góp phần gây dựng có tên gì?","dap":"Báo Thân Ái.","sai":["Báo Việt Nam Độc lập","Báo Người Cùng Khổ","Báo Thanh Niên"],"nguon":"https://baotanghochiminh.vn"},{"hoi":"Vì sao Xiêm La được chọn làm nơi hoạt động trong giai đoạn này?","dap":"Vì là vương quốc độc lập ngoài tầm kiểm soát trực tiếp của Pháp, lại có đông kiều bào và tiện liên lạc với trong nước qua ngả Lào.","sai":["Vì khí hậu ôn hòa hơn Việt Nam","Vì đã có sẵn cơ quan của Quốc tế Cộng sản","Vì gần nước Anh"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Cuối năm 1929, ông Thầu Chín rời Xiêm La để đến đâu?","dap":"Hồng Kông, chuẩn bị hội nghị hợp nhất các tổ chức cộng sản.","sai":["Trở về thẳng Việt Nam","Sang Ấn Độ định cư","Quay lại Liên Xô"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Nakhon Phanom nằm bên dòng sông nào?","dap":"Sông Mê Kông.","sai":["Sông Chao Phraya","Sông Hồng","Sông Tonlé Sap"],"nguon":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"},{"hoi":"Đối diện Nakhon Phanom, bên kia sông Mê Kông là tỉnh nào của Lào?","dap":"Khăm Muộn (Khammouan).","sai":["Viêng Chăn","Savannakhet","Champasak"],"nguon":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"},{"hoi":"Ngôi nhà ông Thầu Chín từng ở tại bản Mạy hiện nay có vai trò gì?","dap":"Là nhà lưu niệm / di tích, mở cửa đón khách tham quan.","sai":["Đã bị phá bỏ hoàn toàn","Trở thành trường học của Thái Lan","Chuyển thành chùa Phật giáo"],"nguon":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"}],"nguon":[{"ten":"Ho Chi Minh – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Nakhon Phanom province – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Nakhon_Phanom_province"},{"ten":"Cổng thông tin Bảo tàng Hồ Chí Minh","url":"https://baotanghochiminh.vn"}],"so_chu":1024},"G11":{"ma":"G11","tieu_de":"Cửu Long, mùa xuân 1930 — đêm hợp nhất khai sinh một chính đảng","sapo":"Đầu năm 1930, trong một căn phòng nhỏ giữa phố xá đông đúc của Cửu Long, Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức cộng sản Việt Nam thành một chính đảng duy nhất. Chỉ hơn một năm sau, chính ông bị cảnh sát Hồng Kông bắt giữ với cái tên Tống Văn Sơ, mở ra một vụ án pháp lý ly kỳ, kéo dài tới tận Hội đồng Cơ mật ở Luân Đôn.","sapo_en":"In early 1930, in a small room in crowded Kowloon, Nguyen Ai Quoc chaired the conference that unified Vietnam's communist groups into a single party. Just over a year later he was arrested by Hong Kong police as Tong Van So, triggering a legal battle that reached the Privy Council in London.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_sung_man_cho_victoria_prison_1930.jpg","credit":"Ảnh: Victoria Prison · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một căn phòng nhỏ, một quyết định lớn","text":"Cuối năm 1929, phong trào cộng sản trong nước tồn tại cùng lúc ba tổ chức: Đông Dương Cộng sản Đảng ở Bắc Kỳ, An Nam Cộng sản Đảng ở Nam Kỳ và Đông Dương Cộng sản Liên đoàn ở Trung Kỳ. Ba tổ chức cùng chung lý tưởng nhưng hoạt động riêng rẽ, thậm chí có lúc cạnh tranh lẫn nhau, khiến phong trào bị phân tán ngay trước những thử thách lớn. Nhận rõ nguy cơ đó, với tư cách phái viên của Quốc tế Cộng sản, Nguyễn Ái Quốc rời Xiêm sang Hồng Kông, triệu tập đại biểu các tổ chức về Cửu Long để bàn việc hợp nhất. Hội nghị diễn ra kín đáo trong một căn phòng nhỏ ở khu phố lao động, kéo dài từ đầu tháng 1 đến đầu tháng 2 năm 1930. Hội nghị nhất trí hợp nhất Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng thành một chính đảng duy nhất — Đảng Cộng sản Việt Nam — và thông qua Chính cương vắn tắt, Sách lược vắn tắt do chính Nguyễn Ái Quốc soạn thảo; ngày 24/2/1930, Đông Dương Cộng sản Liên đoàn cũng được kết nạp vào Đảng. Về sau, Đại hội đại biểu toàn quốc lần thứ III của Đảng (1960) quyết định lấy ngày 3-2 hằng năm làm ngày kỷ niệm thành lập Đảng. Chặng đường từ những xóm Việt kiều heo hút ở Xiêm La đến một chính đảng thống nhất chỉ vỏn vẹn hơn một năm, nhưng đã đặt nền móng cho cả phong trào giải phóng dân tộc sau này.","doc":1},{"loai":"anh","src":"textures/bai/G11_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Hồng Kông – Thành lập Đảng nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Hội nghị Cửu Long có đại biểu của Đông Dương Cộng sản Đảng (thành lập ở Hà Nội, tháng 6/1929) và An Nam Cộng sản Đảng (ra đời tháng 8/1929); Đông Dương Cộng sản Liên đoàn ở Trung Kỳ chưa kịp cử đại biểu và được kết nạp vào Đảng Cộng sản Việt Nam ngày 24/2/1930.","nguon_ten":"en.wikipedia.org","doc":2},{"loai":"doan","tieu_de":"Phố Cửu Long những năm 1930","text":"Cửu Long khi ấy là một góc phố thuộc địa sầm uất: những dãy nhà \"đường lâu\" (唐樓) bốn tầng san sát, tầng trệt có hàng cột đỡ mái hiên che nắng che mưa cho người đi bộ, các tầng trên treo sào phơi quần áo và biển hiệu chữ Hán chi chít; xe kéo tay, xe đẩy hàng rong nối đuôi nhau trên vỉa hè. Cuối phố là bến cảng Tiêm Sa Chủy nhìn sang cảng Victoria, nơi sừng sững tháp đồng hồ ga xe lửa Cửu Long – Quảng Châu xây năm 1915, còn xa hơn là đảo Hồng Kông với đỉnh núi Thái Bình. Chính trong khung cảnh phồn hoa nhưng đầy tai mắt mật thám ấy, các đại biểu phải hết sức thận trọng, tránh mọi sự chú ý để giữ bí mật cho hội nghị của mình.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_sung_wong_toi_in_1930s.jpg","chu_thich":"Một góc Cửu Long, Hồng Kông những năm 1930 — khung cảnh phố xá nơi hội nghị hợp nhất từng diễn ra.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Tống Văn Sơ bị bắt","text":"Hơn một năm sau ngày Đảng ra đời, đêm 6 tháng 6 năm 1931, cảnh sát Hồng Kông bất ngờ ập vào bắt giữ một người đàn ông mang tên Tống Văn Sơ. Đó chính là Nguyễn Ái Quốc. Cuộc bắt giữ là kết quả một chiến dịch phối hợp giữa lực lượng chống cộng của cảnh sát Hồng Kông với mật thám Pháp ở Đông Dương, nhằm dẫn độ ông về nước để xét xử. Ông bị giam tại nhà tù Victoria, nhà tù lâu đời nhất Hồng Kông thời thuộc địa.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_sung_man_cho_ho_chi_minh_1931.jpg","chu_thich":"Ảnh hồ sơ Tống Văn Sơ, 1931","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_nguyen_ai_quoc_in_silk_gown_made_by_rosa_loseby.jpg","chu_thich":"Nguyễn Ái Quốc trong bộ áo lụa do bà Rosa Loseby may, 1932","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Luật sư Loseby và phiên tòa tới tận Luân Đôn","text":"Giữa lúc hiểm nghèo ấy, luật sư người Anh Frank Loseby nhận lời bào chữa cho người tù mang tên Tống Văn Sơ, bất chấp áp lực chính trị từ nhà cầm quyền Pháp. Vụ án được đưa ra tòa án Hồng Kông rồi kháng cáo lên tới Hội đồng Cơ mật (Privy Council) tại Luân Đôn — cơ quan xét xử tối cao của cả Đế quốc Anh khi đó. Vụ kiện khép lại bằng một thỏa thuận trước Hội đồng Cơ mật: ông vẫn bị trục xuất khỏi Hồng Kông, nhưng được tự chọn nơi đến thay vì bị trao cho nhà cầm quyền Pháp. Năm 1932, tin Nguyễn Ái Quốc đã chết vì bệnh lao trong tù còn được loan đi, khiến mật thám Pháp có lúc tưởng ông không còn nữa. Vợ chồng luật sư Loseby sau đó còn giúp ông cải trang để bí mật rời Hồng Kông.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_victoria_prison_block_d.jpg","chu_thich":"Nhà tù Victoria, Hồng Kông — nơi Người bị giam giữ trong vụ án Tống Văn Sơ, 1931 – 1932.","credit":"Ảnh: Zhu yihan · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"anh","src":"textures/bai/G11_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Hồng Kông – Thành lập Đảng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Vụ kiện trước Hội đồng Cơ mật tại Luân Đôn kết thúc bằng một thỏa thuận: lệnh trục xuất vẫn giữ nguyên, nhưng Tống Văn Sơ được tự chọn nơi đến thay vì bị giao cho nhà cầm quyền Pháp — điều kiện đã gián tiếp cứu ông khỏi việc bị áp giải về Đông Dương, nơi ông đã bị kết án tử hình vắng mặt.","nguon_ten":"en.wikipedia.org","doc":6},{"loai":"doan","tieu_de":"Rời Hồng Kông, tiếp tục hành trình","text":"Sau gần hai năm bị giam giữ và theo đuổi vụ kiện, Nguyễn Ái Quốc được trả tự do; đầu năm 1933, Người bí mật rời Hồng Kông đi Hạ Môn (Trung Quốc), rồi Thượng Hải, trước khi tìm đường trở lại Liên Xô. Vụ án Tống Văn Sơ khép lại, nhưng câu chuyện về một luật sư người Anh dám đứng về phía một nhà cách mạng châu Á xa lạ, bất chấp thân phận, chủng tộc và chính kiến khác biệt, vẫn được nhắc lại như một minh chứng đẹp cho tình người vượt lên trên mọi biên giới. Hành trình của Người từ căn phòng nhỏ nơi khai sinh chính đảng đến xà lim nhà tù Victoria, rồi tới phòng xử án tận Luân Đôn, cho thấy rõ những hiểm nguy mà một người cách mạng phải đối mặt trên con đường tìm lại độc lập cho dân tộc mình.","doc":7},{"loai":"ban_co_biet","text":"Tên gọi \"Cửu Long\" (tiếng Quảng Đông: Kowloon, 九龍) có nghĩa là \"chín rồng\", bắt nguồn từ truyền thuyết về tám ngọn núi quanh vùng cộng với vị hoàng đế nhỏ tuổi cuối triều Tống được ví như con rồng thứ chín.","nguon_ten":"en.wikipedia.org","doc":8},{"loai":"anh","src":"textures/bai/G11_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Hồng Kông – Thành lập Đảng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"moc","items":[["6/1 – 7/2/1930","Hội nghị hợp nhất các tổ chức cộng sản tại Cửu Long"],["3/2/1930","Ngày thành lập Đảng Cộng sản Việt Nam"],["6/6/1931","Bị bắt tại Hồng Kông với tên Tống Văn Sơ"],["1931 – 1932","Vụ án Tống Văn Sơ; luật sư Frank Loseby bào chữa, kháng án tới Hội đồng Cơ mật ở Luân Đôn"],["đầu 1933","Được trả tự do, bí mật rời Hồng Kông đi Hạ Môn"]]}],"doc":[{"i":-1,"t":"Cửu Long, mùa xuân 1930 — đêm hợp nhất khai sinh một chính đảng. Đầu năm 1930, trong một căn phòng nhỏ giữa phố xá đông đúc của Cửu Long, Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức cộng sản Việt Nam thành một chính đảng duy nhất. Chỉ hơn một năm sau, chính ông bị cảnh sát Hồng Kông bắt giữ với cái tên Tống Văn Sơ, mở ra một vụ án pháp lý ly kỳ, kéo dài tới tận Hội đồng Cơ mật ở Luân Đôn."},{"t":"Một căn phòng nhỏ, một quyết định lớn. Cuối năm 1929, phong trào cộng sản trong nước tồn tại cùng lúc ba tổ chức: Đông Dương Cộng sản Đảng ở Bắc Kỳ, An Nam Cộng sản Đảng ở Nam Kỳ và Đông Dương Cộng sản Liên đoàn ở Trung Kỳ. Ba tổ chức cùng chung lý tưởng nhưng hoạt động riêng rẽ, thậm chí có lúc cạnh tranh lẫn nhau, khiến phong trào bị phân tán ngay trước những thử thách lớn. Nhận rõ nguy cơ đó, với tư cách phái viên của Quốc tế Cộng sản, Nguyễn Ái Quốc rời Xiêm sang Hồng Kông, triệu tập đại biểu các tổ chức về Cửu Long để bàn việc hợp nhất. Hội nghị diễn ra kín đáo trong một căn phòng nhỏ ở khu phố lao động, kéo dài từ đầu tháng 1 đến đầu tháng 2 năm 1930. Hội nghị nhất trí hợp nhất Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng thành một chính đảng duy nhất — Đảng Cộng sản Việt Nam — và thông qua Chính cương vắn tắt, Sách lược vắn tắt do chính Nguyễn Ái Quốc soạn thảo; ngày 24/2/1930, Đông Dương Cộng sản Liên đoàn cũng được kết nạp vào Đảng. Về sau, Đại hội đại biểu toàn quốc lần thứ III của Đảng (1960) quyết định lấy ngày 3-2 hằng năm làm ngày kỷ niệm thành lập Đảng. Chặng đường từ những xóm Việt kiều heo hút ở Xiêm La đến một chính đảng thống nhất chỉ vỏn vẹn hơn một năm, nhưng đã đặt nền móng cho cả phong trào giải phóng dân tộc sau này."},{"t":"Bạn có biết? Hội nghị Cửu Long có đại biểu của Đông Dương Cộng sản Đảng (thành lập ở Hà Nội, tháng 6/1929) và An Nam Cộng sản Đảng (ra đời tháng 8/1929); Đông Dương Cộng sản Liên đoàn ở Trung Kỳ chưa kịp cử đại biểu và được kết nạp vào Đảng Cộng sản Việt Nam ngày 24/2/1930."},{"t":"Phố Cửu Long những năm 1930. Cửu Long khi ấy là một góc phố thuộc địa sầm uất: những dãy nhà \"đường lâu\" (唐樓) bốn tầng san sát, tầng trệt có hàng cột đỡ mái hiên che nắng che mưa cho người đi bộ, các tầng trên treo sào phơi quần áo và biển hiệu chữ Hán chi chít; xe kéo tay, xe đẩy hàng rong nối đuôi nhau trên vỉa hè. Cuối phố là bến cảng Tiêm Sa Chủy nhìn sang cảng Victoria, nơi sừng sững tháp đồng hồ ga xe lửa Cửu Long – Quảng Châu xây năm 1915, còn xa hơn là đảo Hồng Kông với đỉnh núi Thái Bình. Chính trong khung cảnh phồn hoa nhưng đầy tai mắt mật thám ấy, các đại biểu phải hết sức thận trọng, tránh mọi sự chú ý để giữ bí mật cho hội nghị của mình."},{"t":"Tống Văn Sơ bị bắt. Hơn một năm sau ngày Đảng ra đời, đêm 6 tháng 6 năm 1931, cảnh sát Hồng Kông bất ngờ ập vào bắt giữ một người đàn ông mang tên Tống Văn Sơ. Đó chính là Nguyễn Ái Quốc. Cuộc bắt giữ là kết quả một chiến dịch phối hợp giữa lực lượng chống cộng của cảnh sát Hồng Kông với mật thám Pháp ở Đông Dương, nhằm dẫn độ ông về nước để xét xử. Ông bị giam tại nhà tù Victoria, nhà tù lâu đời nhất Hồng Kông thời thuộc địa."},{"t":"Luật sư Loseby và phiên tòa tới tận Luân Đôn. Giữa lúc hiểm nghèo ấy, luật sư người Anh Frank Loseby nhận lời bào chữa cho người tù mang tên Tống Văn Sơ, bất chấp áp lực chính trị từ nhà cầm quyền Pháp. Vụ án được đưa ra tòa án Hồng Kông rồi kháng cáo lên tới Hội đồng Cơ mật (Privy Council) tại Luân Đôn — cơ quan xét xử tối cao của cả Đế quốc Anh khi đó. Vụ kiện khép lại bằng một thỏa thuận trước Hội đồng Cơ mật: ông vẫn bị trục xuất khỏi Hồng Kông, nhưng được tự chọn nơi đến thay vì bị trao cho nhà cầm quyền Pháp. Năm 1932, tin Nguyễn Ái Quốc đã chết vì bệnh lao trong tù còn được loan đi, khiến mật thám Pháp có lúc tưởng ông không còn nữa. Vợ chồng luật sư Loseby sau đó còn giúp ông cải trang để bí mật rời Hồng Kông."},{"t":"Bạn có biết? Vụ kiện trước Hội đồng Cơ mật tại Luân Đôn kết thúc bằng một thỏa thuận: lệnh trục xuất vẫn giữ nguyên, nhưng Tống Văn Sơ được tự chọn nơi đến thay vì bị giao cho nhà cầm quyền Pháp — điều kiện đã gián tiếp cứu ông khỏi việc bị áp giải về Đông Dương, nơi ông đã bị kết án tử hình vắng mặt."},{"t":"Rời Hồng Kông, tiếp tục hành trình. Sau gần hai năm bị giam giữ và theo đuổi vụ kiện, Nguyễn Ái Quốc được trả tự do; đầu năm 1933, Người bí mật rời Hồng Kông đi Hạ Môn (Trung Quốc), rồi Thượng Hải, trước khi tìm đường trở lại Liên Xô. Vụ án Tống Văn Sơ khép lại, nhưng câu chuyện về một luật sư người Anh dám đứng về phía một nhà cách mạng châu Á xa lạ, bất chấp thân phận, chủng tộc và chính kiến khác biệt, vẫn được nhắc lại như một minh chứng đẹp cho tình người vượt lên trên mọi biên giới. Hành trình của Người từ căn phòng nhỏ nơi khai sinh chính đảng đến xà lim nhà tù Victoria, rồi tới phòng xử án tận Luân Đôn, cho thấy rõ những hiểm nguy mà một người cách mạng phải đối mặt trên con đường tìm lại độc lập cho dân tộc mình."},{"t":"Bạn có biết? Tên gọi \"Cửu Long\" (tiếng Quảng Đông: Kowloon, 九龍) có nghĩa là \"chín rồng\", bắt nguồn từ truyền thuyết về tám ngọn núi quanh vùng cộng với vị hoàng đế nhỏ tuổi cuối triều Tống được ví như con rồng thứ chín."}],"hien_vat":[{"ten":"Dãy phố \"đường lâu\" Cửu Long","mo_ta":"Những dãy nhà bốn tầng kiểu \"đường lâu\" (唐樓) đặc trưng của Hồng Kông – Cửu Long đầu thế kỷ XX: tầng trệt có hàng cột đỡ mái hiên che cho người đi bộ, các tầng trên là ban công lan can, sào phơi quần áo và biển hiệu chữ Hán. Đây là khung cảnh phố xá nơi những người cách mạng Việt Nam ẩn mình hoạt động đầu năm 1930.","nguon":"https://en.wikipedia.org/wiki/Kowloon"},{"ten":"Căn phòng họp Hội nghị hợp nhất","mo_ta":"Căn phòng nhỏ ở tầng trệt một ngôi nhà trong xóm lao động Cửu Long, với bàn gỗ, ghế đẩu, đèn dầu và giấy tờ — nơi Nguyễn Ái Quốc chủ trì hội nghị hợp nhất các tổ chức cộng sản thành Đảng Cộng sản Việt Nam đầu năm 1930.","nguon":"https://en.wikipedia.org/wiki/Communist_Party_of_Vietnam"},{"ten":"Tháp đồng hồ ga Cửu Long – Quảng Châu","mo_ta":"Tháp đồng hồ cao 44 mét, hoàn thành năm 1915, là phần còn sót lại của nhà ga xe lửa Cửu Long – Quảng Châu nguyên bản, được giữ lại làm biểu tượng khi tòa nhà chính của ga bị phá dỡ cuối thập niên 1970. Ngày nay tháp đứng bên bờ Tiêm Sa Chủy, cạnh Trung tâm Văn hóa Hồng Kông.","nguon":"https://en.wikipedia.org/wiki/Tsim_Sha_Tsui"},{"ten":"Nhà tù Victoria","mo_ta":"Nhà tù thời thuộc địa ở trung tâm Hồng Kông, nơi Nguyễn Ái Quốc — dưới tên Tống Văn Sơ — bị giam giữ trong suốt vụ án dẫn độ 1931 – 1932, trước khi được trả tự do và rời Hồng Kông đầu năm 1933.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Bến Tiêm Sa Chủy và cảng Victoria","mo_ta":"Khu bến cảng sầm uất ở mũi bán đảo Cửu Long, nơi tàu thuyền cập bến nối Hồng Kông với các cảng khác trong vùng; từ đây có thể nhìn thấy trọn vẹn đảo Hồng Kông bên kia cảng Victoria.","nguon":"https://en.wikipedia.org/wiki/Tsim_Sha_Tsui"},{"ten":"Núi Thái Bình Sơn (Victoria Peak)","mo_ta":"Ngọn núi cao nhất đảo Hồng Kông, cao 552 mét, nổi bật trên đường chân trời nhìn từ phía Cửu Long qua cảng Victoria; là một trong những địa danh dễ nhận biết nhất của Hồng Kông từ đầu thế kỷ XX.","nguon":"https://en.wikipedia.org/wiki/Victoria_Peak"}],"hoi_dap":[{"hoi":"Ngày nào được lấy làm ngày thành lập Đảng Cộng sản Việt Nam?","dap":"Ngày 3 tháng 2 năm 1930.","sai":["Ngày 6 tháng 1 năm 1930","Ngày 7 tháng 2 năm 1930","Ngày 19 tháng 5 năm 1930"],"nguon":"https://en.wikipedia.org/wiki/Communist_Party_of_Vietnam"},{"hoi":"Hội nghị hợp nhất các tổ chức cộng sản đầu năm 1930 diễn ra ở đâu?","dap":"Cửu Long (Kowloon), Hồng Kông.","sai":["Quảng Châu, Trung Quốc","Ma Cao","Thượng Hải"],"nguon":"https://en.wikipedia.org/wiki/Communist_Party_of_Vietnam"},{"hoi":"Hội nghị Cửu Long đầu năm 1930 đã hợp nhất những tổ chức cộng sản nào?","dap":"Đông Dương Cộng sản Đảng và An Nam Cộng sản Đảng; ngày 24/2/1930, Đông Dương Cộng sản Liên đoàn cũng được kết nạp vào Đảng.","sai":["Việt Nam Quốc dân Đảng, Tân Việt Cách mạng Đảng, Duy Tân hội","Đảng Lập hiến, Đảng Thanh niên, Việt Nam Cách mạng Đồng minh Hội","Hội Việt Nam Cách mạng Thanh niên, Đông Kinh Nghĩa Thục, Duy Tân hội"],"nguon":"https://en.wikipedia.org/wiki/Communist_Party_of_Vietnam"},{"hoi":"Nguyễn Ái Quốc bị bắt tại Hồng Kông ngày nào, với tên gì?","dap":"Ngày 6 tháng 6 năm 1931, với tên Tống Văn Sơ.","sai":["Ngày 6 tháng 6 năm 1930, với tên Lý Thụy","Ngày 3 tháng 2 năm 1931, với tên Thầu Chín","Ngày 6 tháng 6 năm 1932, với tên Nguyễn Ái Quốc"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Ông bị giam giữ ở đâu trong vụ án Tống Văn Sơ?","dap":"Nhà tù Victoria, Hồng Kông.","sai":["Nhà tù Hỏa Lò","Nhà tù Côn Đảo","Nhà tù Sơn La"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Ai là luật sư đã bào chữa cho Tống Văn Sơ?","dap":"Frank Loseby, luật sư người Anh ở Hồng Kông.","sai":["William Ashe","Henry Pollitt","James Cook"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Vụ án được kháng cáo lên cơ quan tư pháp cao nhất nào của Đế quốc Anh khi đó?","dap":"Hội đồng Cơ mật (Privy Council) tại Luân Đôn.","sai":["Tòa án Tối cao Hồng Kông","Nghị viện Anh","Tòa án Công lý Quốc tế"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Năm 1932, tin gì về Nguyễn Ái Quốc đã được loan đi, khiến mật thám Pháp có lúc tưởng ông không còn nữa?","dap":"Tin ông đã qua đời.","sai":["Tin ông đã về nước đầu thú","Tin ông sang Mỹ định cư","Tin ông bị trục xuất về Pháp"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Đầu năm 1933, sau khi được thả, ông bí mật rời Hồng Kông đi đâu?","dap":"Hạ Môn (Amoy), Trung Quốc.","sai":["Hà Nội","Băng Cốc","Ma Cao"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Tên gọi \"Cửu Long\" (Kowloon) có nghĩa là gì?","dap":"\"Chín rồng\".","sai":["\"Chín ngọn núi\"","\"Con rồng vàng\"","\"Cổng rồng\""],"nguon":"https://en.wikipedia.org/wiki/Kowloon"}],"nguon":[{"ten":"Ho Chi Minh – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Communist Party of Vietnam – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Communist_Party_of_Vietnam"},{"ten":"Kowloon – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Kowloon"},{"ten":"Tsim Sha Tsui – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Tsim_Sha_Tsui"},{"ten":"Victoria Peak – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Victoria_Peak"},{"ten":"Cổng thông tin Bảo tàng Hồ Chí Minh","url":"https://baotanghochiminh.vn"}],"so_chu":1052},"G12":{"ma":"G12","tieu_de":"Pác Bó — bước chân đầu tiên sau ba mươi năm xa xứ","sapo":"Sáng 28 tháng 1 năm 1941, tại cột mốc biên giới 108 thuộc xã Trường Hà, huyện Hà Quảng, tỉnh Cao Bằng, Nguyễn Ái Quốc đặt chân trở lại quê hương sau ba mươi năm bôn ba. Người chọn hang Cốc Bó làm nơi ở, đặt tên dòng suối trước hang là suối Lê-nin, ngọn núi phía sau là núi Các Mác, và từ đây trực tiếp chuẩn bị cho cao trào giải phóng dân tộc.","sapo_en":"On the morning of 28 January 1941, at border marker 108 in Cao Bang province, Nguyen Ai Quoc set foot back on Vietnamese soil after thirty years abroad. He made the Pac Bo caves his base, naming the nearby stream after Lenin and the mountain after Marx, and from there prepared the movement that would become the Viet Minh.","bia":{"src":"textures/ht/ht_anh_coc_bo.jpg","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Cột mốc 108 và bước chân trở về","text":"Sau gần ba mươi năm bôn ba tìm đường cứu nước, sáng ngày 28 tháng 1 năm 1941, Nguyễn Ái Quốc vượt qua cột mốc biên giới số 108 thuộc xã Trường Hà, huyện Hà Quảng, tỉnh Cao Bằng, đặt chân trở lại đất mẹ. Trước đó, từ cuối năm 1940, Người đã bí mật hoạt động ở vùng biên Việt – Trung, theo dõi sát tình hình trong nước qua các cán bộ liên lạc, chờ thời điểm thuận lợi để về nước trực tiếp lãnh đạo phong trào. Người mang tên gọi mới — Già Thu — hoà vào cuộc sống của đồng bào Tày, Nùng nơi miền biên viễn. Pác Bó được chọn làm điểm dừng chân đầu tiên không phải ngẫu nhiên: địa hình núi đá vôi hiểm trở dễ ẩn náu, lại chỉ cách biên giới Trung Quốc trong gang tấc để có thể lui về khi cần, trong khi bà con dân tộc nơi đây từ lâu đã một lòng tin theo cách mạng.","doc":1},{"loai":"anh","src":"textures/bai/G12_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Pác Bó – Cao Bằng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Hang Cốc Bó, suối Lê-nin, núi Các Mác","text":"Những ngày đầu về nước, Người ở tạm nhà một gia đình đồng bào trong bản Pác Bó, rồi ít ngày sau chuyển vào hang Cốc Bó — một hang đá nhỏ dưới chân núi, nền hang kê tấm ván làm giường, góc hang là bếp lửa nhỏ và chiếc hòm gỗ đựng tài liệu. Người đặt tên cho dòng suối trong vắt chảy qua trước cửa hang là suối Lê-nin, và ngọn núi sừng sững phía sau là núi Các Mác — những cái tên vừa giản dị vừa thiêng liêng, gửi gắm lý tưởng dẫn đường cho sự nghiệp cách mạng. Bên bờ suối có một phiến đá nhỏ, mấp mô không bằng phẳng, được Người dùng làm bàn làm việc để dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô làm tài liệu huấn luyện cán bộ. Chính từ hình ảnh giản dị ấy, bài thơ Tức cảnh Pác Bó ra đời, ghi lại cuộc sống kham khổ mà tin yêu: “Sáng ra bờ suối, tối vào hang / Cháo bẹ rau măng vẫn sẵn sàng / Bàn đá chông chênh dịch sử Đảng / Cuộc đời cách mạng thật là sang.”","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_pac_bo.jpg","chu_thich":"Suối Lê-nin dưới chân núi Các Mác, Pác Bó","credit":"Ảnh: [Tycho] talk , http://shansov.net · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"anh","src":"textures/bai/G12_v4.jpg","chu_thich":"Một góc không gian 3D tái hiện Pác Bó – Cao Bằng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Trong tiếng Tày, \"Pác Bó\" có nghĩa là \"đầu nguồn\" — nơi con suối bắt đầu chảy ra.","nguon_ten":"en.wikipedia.org","doc":3},{"loai":"trich","text":"Sáng ra bờ suối, tối vào hang / Cháo bẹ rau măng vẫn sẵn sàng / Bàn đá chông chênh dịch sử Đảng / Cuộc đời cách mạng thật là sang.","nguoi":"Hồ Chí Minh","nguon_ten":"Bài thơ Tức cảnh Pác Bó, sáng tác năm 1941","doc":4},{"loai":"anh","src":"textures/bai/G12_v6.jpg","chu_thich":"Một góc không gian 3D tái hiện Pác Bó – Cao Bằng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"anh","src":"textures/bai/G12_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Pác Bó – Cao Bằng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Theo một số tài liệu, Người chỉ ở hẳn trong hang Cốc Bó khoảng bảy tuần đầu, vào tháng 2 và 3 năm 1941, trước khi chuyển tới nơi ở kín đáo hơn gần đó, tiếp tục bám trụ vùng Pác Bó – Việt Bắc trong nhiều năm sau.","nguon_ten":"en.wikipedia.org","doc":5},{"loai":"doan","tieu_de":"Hội nghị Trung ương 8 và sự ra đời của Việt Minh","text":"Tháng 5 năm 1941, tại lán Khuổi Nặm cách hang Cốc Bó không xa, Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng họp từ ngày 10 đến 19-5, do Nguyễn Ái Quốc chủ trì. Hội nghị đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, tạm gác khẩu hiệu cách mạng ruộng đất, và quyết định thành lập một mặt trận dân tộc thống nhất rộng rãi lấy tên Việt Nam Độc lập Đồng minh — gọi tắt là Việt Minh — chính thức ra đời ngày 19-5-1941. Đây được xem là một trong những quyết định có tính bước ngoặt của cách mạng Việt Nam, đặt nền tảng tư tưởng và tổ chức cho thắng lợi của Cách mạng Tháng Tám bốn năm sau đó. Các hội Cứu quốc lần lượt được vận động thành lập trong công nhân, nông dân, phụ nữ, thanh niên; tờ báo Việt Nam Độc lập do Người sáng lập được dùng để tuyên truyền, vận động quần chúng khắp vùng căn cứ.","doc":6},{"loai":"anh","src":"textures/bai/G12_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Pác Bó – Cao Bằng nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Từ núi rừng Pác Bó đến ngày Tổng khởi nghĩa","text":"Từ những quyết sách được vạch ra ở Pác Bó, phong trào cách mạng ở Cao Bằng và các tỉnh lân cận phát triển nhanh chóng. Ngày 22 tháng 12 năm 1944, thực hiện chỉ thị của Người, Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập trong rừng, ban đầu chỉ với 34 chiến sĩ và một số vũ khí thô sơ, do Võ Nguyên Giáp trực tiếp chỉ huy. Nhiệm vụ đầu tiên Người giao là phải giành được thắng lợi ngay trong trận đánh ra quân, và đội quân nhỏ bé ấy đã hoàn thành xuất sắc nhiệm vụ chỉ vài ngày sau khi thành lập — đặt viên gạch đầu tiên cho Quân đội nhân dân Việt Nam sau này. Suốt những năm 1941 – 1945, Pác Bó và vùng Việt Bắc trở thành cái nôi đào tạo hàng loạt cán bộ cốt cán, chuẩn bị lực lượng cho cuộc Tổng khởi nghĩa giành chính quyền trong cả nước.","doc":7},{"loai":"ban_co_biet","text":"Đội Việt Nam Tuyên truyền Giải phóng quân khi mới thành lập chỉ có 34 chiến sĩ, được trang bị vỏn vẹn hai khẩu súng ngắn, mười bảy khẩu súng trường, một khẩu trung liên và mười bốn khẩu súng kíp, nhưng đã lập chiến công ngay trong những ngày đầu ra quân.","nguon_ten":"en.wikipedia.org","doc":8},{"loai":"doan","tieu_de":"Nơi bắt đầu của một thời đại","text":"Từ căn cứ địa Pác Bó, con đường cách mạng tiếp tục mở rộng ra Tân Trào rồi tiến về Hà Nội trong mùa thu năm 1945. Ngày nay, hang Cốc Bó, suối Lê-nin, núi Các Mác và \"bàn đá chông chênh\" bên bờ suối vẫn được gìn giữ gần như nguyên vẹn giữa núi rừng Cao Bằng, trở thành nơi mỗi người Việt Nam tìm về để hiểu thêm về những ngày tháng gian khổ mà rạng rỡ ấy — nơi một hành trình dài ba mươi năm khép lại để mở ra một hành trình mới của cả dân tộc. Từ thung lũng nhỏ hẹp giữa bốn bề núi đá này, một cao trào giải phóng dân tộc đã được nhen nhóm, để rồi chỉ ít năm sau lan rộng khắp cả nước, dẫn tới ngày độc lập mùa thu năm 1945.","doc":9},{"loai":"moc","items":[["28/1/1941","Về nước tại cột mốc 108, Pác Bó"],["2 – 3/1941","Ở hang Cốc Bó; đặt tên suối Lê-nin, núi Các Mác"],["10 – 19/5/1941","Hội nghị Trung ương lần thứ 8, họp tại Khuổi Nặm"],["19/5/1941","Thành lập Mặt trận Việt Minh"],["22/12/1944","Thành lập Đội Việt Nam Tuyên truyền Giải phóng quân"]]}],"doc":[{"i":-1,"t":"Pác Bó — bước chân đầu tiên sau ba mươi năm xa xứ. Sáng 28 tháng 1 năm 1941, tại cột mốc biên giới 108 thuộc xã Trường Hà, huyện Hà Quảng, tỉnh Cao Bằng, Nguyễn Ái Quốc đặt chân trở lại quê hương sau ba mươi năm bôn ba. Người chọn hang Cốc Bó làm nơi ở, đặt tên dòng suối trước hang là suối Lê-nin, ngọn núi phía sau là núi Các Mác, và từ đây trực tiếp chuẩn bị cho cao trào giải phóng dân tộc."},{"t":"Cột mốc 108 và bước chân trở về. Sau gần ba mươi năm bôn ba tìm đường cứu nước, sáng ngày 28 tháng 1 năm 1941, Nguyễn Ái Quốc vượt qua cột mốc biên giới số 108 thuộc xã Trường Hà, huyện Hà Quảng, tỉnh Cao Bằng, đặt chân trở lại đất mẹ. Trước đó, từ cuối năm 1940, Người đã bí mật hoạt động ở vùng biên Việt – Trung, theo dõi sát tình hình trong nước qua các cán bộ liên lạc, chờ thời điểm thuận lợi để về nước trực tiếp lãnh đạo phong trào. Người mang tên gọi mới — Già Thu — hoà vào cuộc sống của đồng bào Tày, Nùng nơi miền biên viễn. Pác Bó được chọn làm điểm dừng chân đầu tiên không phải ngẫu nhiên: địa hình núi đá vôi hiểm trở dễ ẩn náu, lại chỉ cách biên giới Trung Quốc trong gang tấc để có thể lui về khi cần, trong khi bà con dân tộc nơi đây từ lâu đã một lòng tin theo cách mạng."},{"t":"Hang Cốc Bó, suối Lê-nin, núi Các Mác. Những ngày đầu về nước, Người ở tạm nhà một gia đình đồng bào trong bản Pác Bó, rồi ít ngày sau chuyển vào hang Cốc Bó — một hang đá nhỏ dưới chân núi, nền hang kê tấm ván làm giường, góc hang là bếp lửa nhỏ và chiếc hòm gỗ đựng tài liệu. Người đặt tên cho dòng suối trong vắt chảy qua trước cửa hang là suối Lê-nin, và ngọn núi sừng sững phía sau là núi Các Mác — những cái tên vừa giản dị vừa thiêng liêng, gửi gắm lý tưởng dẫn đường cho sự nghiệp cách mạng. Bên bờ suối có một phiến đá nhỏ, mấp mô không bằng phẳng, được Người dùng làm bàn làm việc để dịch cuốn Lịch sử Đảng Cộng sản (b) Liên Xô làm tài liệu huấn luyện cán bộ. Chính từ hình ảnh giản dị ấy, bài thơ Tức cảnh Pác Bó ra đời, ghi lại cuộc sống kham khổ mà tin yêu: “Sáng ra bờ suối, tối vào hang / Cháo bẹ rau măng vẫn sẵn sàng / Bàn đá chông chênh dịch sử Đảng / Cuộc đời cách mạng thật là sang.”"},{"t":"Bạn có biết? Trong tiếng Tày, \"Pác Bó\" có nghĩa là \"đầu nguồn\" — nơi con suối bắt đầu chảy ra."},{"t":"Sáng ra bờ suối, tối vào hang / Cháo bẹ rau măng vẫn sẵn sàng / Bàn đá chông chênh dịch sử Đảng / Cuộc đời cách mạng thật là sang. — Hồ Chí Minh"},{"t":"Bạn có biết? Theo một số tài liệu, Người chỉ ở hẳn trong hang Cốc Bó khoảng bảy tuần đầu, vào tháng 2 và 3 năm 1941, trước khi chuyển tới nơi ở kín đáo hơn gần đó, tiếp tục bám trụ vùng Pác Bó – Việt Bắc trong nhiều năm sau."},{"t":"Hội nghị Trung ương 8 và sự ra đời của Việt Minh. Tháng 5 năm 1941, tại lán Khuổi Nặm cách hang Cốc Bó không xa, Hội nghị lần thứ tám Ban Chấp hành Trung ương Đảng họp từ ngày 10 đến 19-5, do Nguyễn Ái Quốc chủ trì. Hội nghị đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, tạm gác khẩu hiệu cách mạng ruộng đất, và quyết định thành lập một mặt trận dân tộc thống nhất rộng rãi lấy tên Việt Nam Độc lập Đồng minh — gọi tắt là Việt Minh — chính thức ra đời ngày 19-5-1941. Đây được xem là một trong những quyết định có tính bước ngoặt của cách mạng Việt Nam, đặt nền tảng tư tưởng và tổ chức cho thắng lợi của Cách mạng Tháng Tám bốn năm sau đó. Các hội Cứu quốc lần lượt được vận động thành lập trong công nhân, nông dân, phụ nữ, thanh niên; tờ báo Việt Nam Độc lập do Người sáng lập được dùng để tuyên truyền, vận động quần chúng khắp vùng căn cứ."},{"t":"Từ núi rừng Pác Bó đến ngày Tổng khởi nghĩa. Từ những quyết sách được vạch ra ở Pác Bó, phong trào cách mạng ở Cao Bằng và các tỉnh lân cận phát triển nhanh chóng. Ngày 22 tháng 12 năm 1944, thực hiện chỉ thị của Người, Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập trong rừng, ban đầu chỉ với 34 chiến sĩ và một số vũ khí thô sơ, do Võ Nguyên Giáp trực tiếp chỉ huy. Nhiệm vụ đầu tiên Người giao là phải giành được thắng lợi ngay trong trận đánh ra quân, và đội quân nhỏ bé ấy đã hoàn thành xuất sắc nhiệm vụ chỉ vài ngày sau khi thành lập — đặt viên gạch đầu tiên cho Quân đội nhân dân Việt Nam sau này. Suốt những năm 1941 – 1945, Pác Bó và vùng Việt Bắc trở thành cái nôi đào tạo hàng loạt cán bộ cốt cán, chuẩn bị lực lượng cho cuộc Tổng khởi nghĩa giành chính quyền trong cả nước."},{"t":"Bạn có biết? Đội Việt Nam Tuyên truyền Giải phóng quân khi mới thành lập chỉ có 34 chiến sĩ, được trang bị vỏn vẹn hai khẩu súng ngắn, mười bảy khẩu súng trường, một khẩu trung liên và mười bốn khẩu súng kíp, nhưng đã lập chiến công ngay trong những ngày đầu ra quân."},{"t":"Nơi bắt đầu của một thời đại. Từ căn cứ địa Pác Bó, con đường cách mạng tiếp tục mở rộng ra Tân Trào rồi tiến về Hà Nội trong mùa thu năm 1945. Ngày nay, hang Cốc Bó, suối Lê-nin, núi Các Mác và \"bàn đá chông chênh\" bên bờ suối vẫn được gìn giữ gần như nguyên vẹn giữa núi rừng Cao Bằng, trở thành nơi mỗi người Việt Nam tìm về để hiểu thêm về những ngày tháng gian khổ mà rạng rỡ ấy — nơi một hành trình dài ba mươi năm khép lại để mở ra một hành trình mới của cả dân tộc. Từ thung lũng nhỏ hẹp giữa bốn bề núi đá này, một cao trào giải phóng dân tộc đã được nhen nhóm, để rồi chỉ ít năm sau lan rộng khắp cả nước, dẫn tới ngày độc lập mùa thu năm 1945."}],"hien_vat":[{"ten":"Cột mốc biên giới 108","mo_ta":"Cột mốc phân định biên giới Việt – Trung, nơi Nguyễn Ái Quốc bước qua để trở về Tổ quốc sáng 28-1-1941 sau ba mươi năm xa xứ. Đây được coi là điểm khởi đầu của cả giai đoạn cách mạng tiếp theo.","nguon":"https://en.wikipedia.org/wiki/Pac_Bo"},{"ten":"Hang Cốc Bó","mo_ta":"Hang đá nhỏ dưới chân núi, nơi Người sống và làm việc trong những tuần đầu về nước năm 1941; bên trong hang có tấm ván làm giường, bếp lửa nhỏ và chiếc hòm gỗ đựng tài liệu.","nguon":"https://en.wikipedia.org/wiki/Pac_Bo"},{"ten":"Bàn đá chông chênh","mo_ta":"Phiến đá mấp mô bên bờ suối Lê-nin, nơi Người ngồi làm việc, dịch sách lý luận để huấn luyện cán bộ — hình ảnh đã đi vào bài thơ Tức cảnh Pác Bó.","nguon":"Bài thơ Tức cảnh Pác Bó, 1941"},{"ten":"Suối Lê-nin và núi Các Mác","mo_ta":"Dòng suối trong vắt và ngọn núi đá vôi phía sau hang Cốc Bó được Người đặt tên theo hai lãnh tụ của chủ nghĩa Mác – Lê-nin, thể hiện lý tưởng dẫn đường cho sự nghiệp cách mạng.","nguon":"https://en.wikipedia.org/wiki/Pac_Bo"},{"ten":"Lán Khuổi Nặm","mo_ta":"Lán nhỏ dựng bằng tre nứa, mái lá cọ trong rừng gần Pác Bó, nơi diễn ra Hội nghị Trung ương lần thứ 8 (5/1941) — quyết định thành lập Mặt trận Việt Minh.","nguon":"https://en.wikipedia.org/wiki/Viet_Minh"},{"ten":"Chiếc hòm gỗ trong hang Cốc Bó","mo_ta":"Vật dụng đơn sơ dùng để cất giữ tài liệu, sách báo cách mạng trong điều kiện sống và làm việc bí mật, gian khổ giữa núi rừng.","nguon":"https://en.wikipedia.org/wiki/Pac_Bo"}],"hoi_dap":[{"hoi":"Nguyễn Ái Quốc trở về nước qua cột mốc biên giới nào, vào ngày nào?","dap":"Cột mốc 108, ngày 28 tháng 1 năm 1941.","sai":["Cột mốc 108, ngày 19 tháng 5 năm 1941","Cột mốc 0, ngày 2 tháng 9 năm 1941","Cột mốc 108, ngày 22 tháng 12 năm 1944"],"nguon":"https://en.wikipedia.org/wiki/Pac_Bo"},{"hoi":"Khi mới về Pác Bó, Nguyễn Ái Quốc mang tên gọi gì?","dap":"Già Thu.","sai":["Thầu Chín","Tống Văn Sơ","Lý Thụy"],"nguon":"https://baotanghochiminh.vn"},{"hoi":"Trong những tuần đầu về nước năm 1941, Người sống và làm việc ở đâu tại Pác Bó?","dap":"Hang Cốc Bó.","sai":["Lán Nà Nưa","Lán Khuổi Nặm","Đình Tân Trào"],"nguon":"https://en.wikipedia.org/wiki/Pac_Bo"},{"hoi":"Người đặt tên dòng suối trước hang Cốc Bó là gì?","dap":"Suối Lê-nin.","sai":["Suối Các Mác","Suối Độc Lập","Suối Bác Hồ"],"nguon":"https://en.wikipedia.org/wiki/Pac_Bo"},{"hoi":"Ngọn núi phía sau hang Cốc Bó được Người đặt tên là gì?","dap":"Núi Các Mác.","sai":["Núi Lê-nin","Núi Độc Lập","Núi Trường Sơn"],"nguon":"https://en.wikipedia.org/wiki/Pac_Bo"},{"hoi":"Bài thơ nào ra đời gắn với hình ảnh \"bàn đá chông chênh\" bên bờ suối?","dap":"Tức cảnh Pác Bó.","sai":["Nguyên tiêu","Cảnh khuya","Nhật ký trong tù"],"nguon":"Bài thơ Tức cảnh Pác Bó, 1941"},{"hoi":"Hội nghị Trung ương lần thứ 8 họp ở đâu, vào thời gian nào?","dap":"Tại lán Khuổi Nặm, từ 10 đến 19-5-1941.","sai":["Tại Tân Trào, tháng 8-1945","Tại hang Cốc Bó, tháng 1-1941","Tại Hà Nội, tháng 5-1941"],"nguon":"https://en.wikipedia.org/wiki/Viet_Minh"},{"hoi":"Mặt trận Việt Minh chính thức thành lập ngày nào?","dap":"Ngày 19 tháng 5 năm 1941.","sai":["Ngày 3 tháng 2 năm 1941","Ngày 2 tháng 9 năm 1945","Ngày 22 tháng 12 năm 1944"],"nguon":"https://en.wikipedia.org/wiki/Viet_Minh"},{"hoi":"Đội Việt Nam Tuyên truyền Giải phóng quân thành lập ngày nào, do ai chỉ huy?","dap":"Ngày 22 tháng 12 năm 1944, do Võ Nguyên Giáp chỉ huy.","sai":["Ngày 19 tháng 5 năm 1941, do Nguyễn Ái Quốc chỉ huy","Ngày 2 tháng 9 năm 1945, do Trường Chinh chỉ huy","Ngày 22 tháng 12 năm 1944, do Phạm Văn Đồng chỉ huy"],"nguon":"https://en.wikipedia.org/wiki/V%C3%B5_Nguy%C3%AAn_Gi%C3%A1p"},{"hoi":"\"Pác Bó\" trong tiếng Tày có nghĩa là gì?","dap":"\"Đầu nguồn\".","sai":["\"Núi đá\"","\"Dòng suối trong\"","\"Rừng sâu\""],"nguon":"https://en.wikipedia.org/wiki/Pac_Bo"}],"nguon":[{"ten":"Ho Chi Minh – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Pác Bó – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Pac_Bo"},{"ten":"Việt Minh – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Viet_Minh"},{"ten":"Cao Bằng province – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Cao_B%E1%BA%B1ng_province"},{"ten":"Võ Nguyên Giáp – Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/V%C3%B5_Nguy%C3%AAn_Gi%C3%A1p"},{"ten":"Cổng thông tin Bảo tàng Hồ Chí Minh","url":"https://baotanghochiminh.vn"}],"so_chu":1075},"G13":{"ma":"G13","tieu_de":"Tân Trào – Bình minh của một dân tộc","sapo":"Giữa những cánh rừng cọ và ruộng bậc thấp ở Sơn Dương, Tuyên Quang, một mái đình nhỏ và một lán nứa đơn sơ đã trở thành nơi phát lệnh Tổng khởi nghĩa tháng Tám năm 1945. Tại Tân Trào, trong vài tháng ngắn ngủi, một khu giải phóng, một chính phủ lâm thời và một lá cờ Tổ quốc đã ra đời.","sapo_en":"In the forests of Son Duong, Tuyen Quang, a modest hut and a communal house became the birthplace of Vietnam's August 1945 uprising, where Ho Chi Minh and the National Congress charted the nation's path to independence.","bia":{"src":"textures/ht/ht_anh_dinh_tan_trao.jpg","credit":"Ảnh: Bùi Thụy Đào Nguyên · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Từ hang đá Pác Bó tới rừng cọ Tân Trào","text":"Đầu tháng 5 năm 1945, sau hơn bốn năm gây dựng cơ sở cách mạng ở vùng biên giới Cao Bằng, Hồ Chí Minh rời Pác Bó, vượt đường rừng để về Tân Trào — một xã nhỏ thuộc huyện Sơn Dương, tỉnh Tuyên Quang. Người chọn nơi này làm trung tâm chỉ đạo phong trào cách mạng cả nước vì địa thế hiểm trở, dân cư phần đông là đồng bào Tày một lòng theo cách mạng, lại thuận đường liên lạc với các chiến khu lân cận.\n\nTân Trào khi ấy chỉ là một thung lũng nhỏ nép giữa những đồi cọ và ruộng bậc thấp ven suối, nhưng nhờ vị trí ấy, nơi đây nhanh chóng trở thành “thủ đô lâm thời” của Khu giải phóng, quy tụ các cơ quan đầu não của Việt Minh trong những tháng quyết định của cuộc Tổng khởi nghĩa.","doc":1},{"loai":"ban_co_biet","text":"Trước năm 1945, xã Tân Trào có tên là Kim Long; tên Tân Trào được đặt khi nơi đây trở thành trung tâm của Khu giải phóng Việt Bắc.","nguon_ten":"tantrao.hochiminh.vn","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_lan_na_lua.jpg","chu_thich":"Lán Nà Nưa (thường được ghi là Nà Lừa) dưới chân núi Hồng — nơi Chủ tịch Hồ Chí Minh ở và làm việc từ tháng 5 đến tháng 8 năm 1945.","credit":"Ảnh: Liftold (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Lán Nà Nưa – nơi Người ốm nặng vẫn không rời việc nước","text":"Trên sườn đồi Nà Nưa, cách đình Tân Trào không xa, Người cho dựng một lán nhỏ hai gian bằng tre nứa, mái lợp lá cọ — vừa đủ kê một bộ bàn ghế tre để làm việc, vừa là chỗ nghỉ. Từ đây, Người theo dõi sát tình hình trong nước, chỉ đạo mở các lớp huấn luyện quân sự, chính trị cho cán bộ, và soạn thảo các văn kiện chuẩn bị cho Tổng khởi nghĩa.\n\nGiữa lúc thời cuộc chuyển biến từng ngày, Người trải qua một cơn sốt rất nặng ngay tại lán. Dù sức khỏe suy kiệt, Người vẫn dặn các đồng chí của mình phải tranh thủ thời cơ, không được chậm trễ — lời dặn ấy sau này được nhắc lại trong nhiều tư liệu về giai đoạn tiền khởi nghĩa.","doc":3},{"loai":"trich","text":"Lúc này thời cơ thuận lợi đã tới, dù hy sinh tới đâu, dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập.","nguoi":"Hồ Chí Minh, nói với đồng chí Võ Nguyên Giáp tại lán Nà Nưa khi đang ốm nặng, mùa hè 1945","nguon_ten":"Võ Nguyên Giáp, hồi ký Những năm tháng không thể nào quên","doc":4},{"loai":"anh","src":"textures/bai/G13_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Tân Trào – Thủ đô Khu giải phóng nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Trong tiếng Tày, “nà” nghĩa là ruộng; tên “Nà Nưa” về sau còn được ghi là “Nà Lừa” trên nhiều biển chỉ dẫn và tài liệu, nên cả hai cách gọi cùng tồn tại cho đến nay.","nguon_ten":"tantrao.hochiminh.vn","doc":5},{"loai":"doan","tieu_de":"Khu giải phóng Việt Bắc và mười chính sách lớn","text":"Ngày 4 tháng 6 năm 1945, tại Tân Trào, Khu giải phóng Việt Bắc chính thức được thành lập, bao trùm phần lớn các tỉnh Cao Bằng, Bắc Kạn, Lạng Sơn, Hà Giang, Tuyên Quang, Thái Nguyên — thường được gọi tắt là “Cao – Bắc – Lạng – Hà – Tuyên – Thái”. Đây là hình ảnh thu nhỏ của một chính quyền cách mạng: có Ủy ban chỉ huy lâm thời, có lực lượng vũ trang, có chính quyền cơ sở, và có mười chính sách lớn của Việt Minh về ruộng đất, thuế khóa, quyền tự do dân chủ, bình đẳng dân tộc.\n\nTừ căn cứ địa này, các đội tuyên truyền vũ trang tỏa đi khắp các tỉnh trung du và đồng bằng Bắc Bộ, chuẩn bị lực lượng cho giờ phút quyết định. Khu giải phóng Việt Bắc trở thành hậu phương vững chắc, nơi cung cấp cán bộ, lương thực cho phong trào khởi nghĩa đang dâng cao trong cả nước.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_cay_da_lich_su_tan_trao.jpg","chu_thich":"Cây đa Tân Trào, nơi Giải phóng quân xuất phát về xuôi","credit":"Ảnh: Liftold (thảo luận) · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Quốc dân Đại hội dưới mái đình làng","text":"Ngày 16 và 17 tháng 8 năm 1945, hơn 60 đại biểu đại diện cho ba miền Bắc – Trung – Nam, các đảng phái, đoàn thể cứu quốc, các dân tộc và tôn giáo đã về họp tại đình Tân Trào — một ngôi đình làng bình dị vốn chỉ dùng để thờ thành hoàng. Đại hội tán thành chủ trương Tổng khởi nghĩa giành chính quyền trong cả nước, thông qua mười chính sách lớn của Việt Minh, quy định quốc kỳ nền đỏ sao vàng năm cánh và quốc ca là bài Tiến quân ca.\n\nĐại hội cũng bầu ra Ủy ban Dân tộc Giải phóng Việt Nam — thực chất là Chính phủ lâm thời — do Hồ Chí Minh làm Chủ tịch. Chỉ trong hai ngày, những quyết định mang tính bước ngoặt của cả một dân tộc đã được đưa ra dưới mái đình gỗ đơn sơ ấy.","doc":7},{"loai":"anh","src":"textures/bai/G13_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Tân Trào – Thủ đô Khu giải phóng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Dưới bóng cây đa lịch sử","text":"Ngay chiều 16 tháng 8, trước khi Quốc dân Đại hội kết thúc, dưới gốc đa cổ thụ đầu làng, đội Việt Nam Giải phóng quân làm lễ xuất quân dưới sự chỉ huy của Võ Nguyên Giáp, tiến về giải phóng thị xã Thái Nguyên, mở đầu cho các mũi tiến công giành chính quyền trên cả nước. Cây đa Tân Trào từ đó trở thành biểu tượng cho thời khắc chuyển giao lịch sử — nơi một đội quân cách mạng còn non trẻ bước ra từ rừng sâu để tiến về các đô thị.\n\nChỉ ít ngày sau, ngày 22 tháng 8 năm 1945, Chủ tịch Hồ Chí Minh rời Tân Trào về Hà Nội, khép lại quãng thời gian ngắn ngủi nhưng có ý nghĩa quyết định khi Tân Trào là “Thủ đô Khu giải phóng”.","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_ngay_28_08_1945_doan_giai_phong_quan_o_viet_bac_.jpg","chu_thich":"Ngày 28/8/1945, Giải phóng quân từ Việt Bắc về duyệt binh ở Quảng trường Nhà hát Lớn, Hà Nội","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Đội quân xuất phát từ cây đa Tân Trào chính là Việt Nam Giải phóng quân, vừa được hợp nhất từ Việt Nam Tuyên truyền Giải phóng quân và Cứu quốc quân ít tháng trước đó, đặt nền móng cho Quân đội nhân dân Việt Nam sau này.","nguon_ten":"en.wikipedia.org","doc":9},{"loai":"anh","src":"textures/bai/G13_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện Tân Trào – Thủ đô Khu giải phóng","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Tân Trào hôm nay","text":"Chưa đầy hai tuần sau lễ xuất quân, cuộc Tổng khởi nghĩa đã giành chính quyền trong cả nước, và ngày 2 tháng 9 năm 1945, nước Việt Nam Dân chủ Cộng hòa ra đời tại Hà Nội. Tân Trào — nơi khởi phát của chuỗi sự kiện ấy — nay là Khu di tích quốc gia đặc biệt, nơi lán Nà Nưa, đình Tân Trào và cây đa lịch sử vẫn được gìn giữ gần như nguyên vẹn.\n\nMỗi độ tháng Tám về, hàng vạn người từ khắp cả nước lại tìm về thung lũng nhỏ giữa núi rừng Tuyên Quang này, để đứng dưới tán cây đa cổ thụ và hình dung lại giờ phút một dân tộc đứng lên giành lấy vận mệnh của chính mình.","doc":10},{"loai":"moc","items":[["4/5/1945","Rời Pác Bó về Tân Trào"],["4/6/1945","Thành lập Khu giải phóng Việt Bắc"],["13/8/1945","Ủy ban khởi nghĩa toàn quốc ra Quân lệnh số 1"],["16–17/8/1945","Quốc dân Đại hội Tân Trào"],["22/8/1945","Rời Tân Trào về Hà Nội"]]}],"doc":[{"i":-1,"t":"Tân Trào – Bình minh của một dân tộc. Giữa những cánh rừng cọ và ruộng bậc thấp ở Sơn Dương, Tuyên Quang, một mái đình nhỏ và một lán nứa đơn sơ đã trở thành nơi phát lệnh Tổng khởi nghĩa tháng Tám năm 1945. Tại Tân Trào, trong vài tháng ngắn ngủi, một khu giải phóng, một chính phủ lâm thời và một lá cờ Tổ quốc đã ra đời."},{"t":"Từ hang đá Pác Bó tới rừng cọ Tân Trào. Đầu tháng 5 năm 1945, sau hơn bốn năm gây dựng cơ sở cách mạng ở vùng biên giới Cao Bằng, Hồ Chí Minh rời Pác Bó, vượt đường rừng để về Tân Trào — một xã nhỏ thuộc huyện Sơn Dương, tỉnh Tuyên Quang. Người chọn nơi này làm trung tâm chỉ đạo phong trào cách mạng cả nước vì địa thế hiểm trở, dân cư phần đông là đồng bào Tày một lòng theo cách mạng, lại thuận đường liên lạc với các chiến khu lân cận. Tân Trào khi ấy chỉ là một thung lũng nhỏ nép giữa những đồi cọ và ruộng bậc thấp ven suối, nhưng nhờ vị trí ấy, nơi đây nhanh chóng trở thành “thủ đô lâm thời” của Khu giải phóng, quy tụ các cơ quan đầu não của Việt Minh trong những tháng quyết định của cuộc Tổng khởi nghĩa."},{"t":"Bạn có biết? Trước năm 1945, xã Tân Trào có tên là Kim Long; tên Tân Trào được đặt khi nơi đây trở thành trung tâm của Khu giải phóng Việt Bắc."},{"t":"Lán Nà Nưa – nơi Người ốm nặng vẫn không rời việc nước. Trên sườn đồi Nà Nưa, cách đình Tân Trào không xa, Người cho dựng một lán nhỏ hai gian bằng tre nứa, mái lợp lá cọ — vừa đủ kê một bộ bàn ghế tre để làm việc, vừa là chỗ nghỉ. Từ đây, Người theo dõi sát tình hình trong nước, chỉ đạo mở các lớp huấn luyện quân sự, chính trị cho cán bộ, và soạn thảo các văn kiện chuẩn bị cho Tổng khởi nghĩa. Giữa lúc thời cuộc chuyển biến từng ngày, Người trải qua một cơn sốt rất nặng ngay tại lán. Dù sức khỏe suy kiệt, Người vẫn dặn các đồng chí của mình phải tranh thủ thời cơ, không được chậm trễ — lời dặn ấy sau này được nhắc lại trong nhiều tư liệu về giai đoạn tiền khởi nghĩa."},{"t":"Lúc này thời cơ thuận lợi đã tới, dù hy sinh tới đâu, dù phải đốt cháy cả dãy Trường Sơn cũng phải kiên quyết giành cho được độc lập. — Hồ Chí Minh, nói với đồng chí Võ Nguyên Giáp tại lán Nà Nưa khi đang ốm nặng, mùa hè 1945"},{"t":"Bạn có biết? Trong tiếng Tày, “nà” nghĩa là ruộng; tên “Nà Nưa” về sau còn được ghi là “Nà Lừa” trên nhiều biển chỉ dẫn và tài liệu, nên cả hai cách gọi cùng tồn tại cho đến nay."},{"t":"Khu giải phóng Việt Bắc và mười chính sách lớn. Ngày 4 tháng 6 năm 1945, tại Tân Trào, Khu giải phóng Việt Bắc chính thức được thành lập, bao trùm phần lớn các tỉnh Cao Bằng, Bắc Kạn, Lạng Sơn, Hà Giang, Tuyên Quang, Thái Nguyên — thường được gọi tắt là “Cao – Bắc – Lạng – Hà – Tuyên – Thái”. Đây là hình ảnh thu nhỏ của một chính quyền cách mạng: có Ủy ban chỉ huy lâm thời, có lực lượng vũ trang, có chính quyền cơ sở, và có mười chính sách lớn của Việt Minh về ruộng đất, thuế khóa, quyền tự do dân chủ, bình đẳng dân tộc. Từ căn cứ địa này, các đội tuyên truyền vũ trang tỏa đi khắp các tỉnh trung du và đồng bằng Bắc Bộ, chuẩn bị lực lượng cho giờ phút quyết định. Khu giải phóng Việt Bắc trở thành hậu phương vững chắc, nơi cung cấp cán bộ, lương thực cho phong trào khởi nghĩa đang dâng cao trong cả nước."},{"t":"Quốc dân Đại hội dưới mái đình làng. Ngày 16 và 17 tháng 8 năm 1945, hơn 60 đại biểu đại diện cho ba miền Bắc – Trung – Nam, các đảng phái, đoàn thể cứu quốc, các dân tộc và tôn giáo đã về họp tại đình Tân Trào — một ngôi đình làng bình dị vốn chỉ dùng để thờ thành hoàng. Đại hội tán thành chủ trương Tổng khởi nghĩa giành chính quyền trong cả nước, thông qua mười chính sách lớn của Việt Minh, quy định quốc kỳ nền đỏ sao vàng năm cánh và quốc ca là bài Tiến quân ca. Đại hội cũng bầu ra Ủy ban Dân tộc Giải phóng Việt Nam — thực chất là Chính phủ lâm thời — do Hồ Chí Minh làm Chủ tịch. Chỉ trong hai ngày, những quyết định mang tính bước ngoặt của cả một dân tộc đã được đưa ra dưới mái đình gỗ đơn sơ ấy."},{"t":"Dưới bóng cây đa lịch sử. Ngay chiều 16 tháng 8, trước khi Quốc dân Đại hội kết thúc, dưới gốc đa cổ thụ đầu làng, đội Việt Nam Giải phóng quân làm lễ xuất quân dưới sự chỉ huy của Võ Nguyên Giáp, tiến về giải phóng thị xã Thái Nguyên, mở đầu cho các mũi tiến công giành chính quyền trên cả nước. Cây đa Tân Trào từ đó trở thành biểu tượng cho thời khắc chuyển giao lịch sử — nơi một đội quân cách mạng còn non trẻ bước ra từ rừng sâu để tiến về các đô thị. Chỉ ít ngày sau, ngày 22 tháng 8 năm 1945, Chủ tịch Hồ Chí Minh rời Tân Trào về Hà Nội, khép lại quãng thời gian ngắn ngủi nhưng có ý nghĩa quyết định khi Tân Trào là “Thủ đô Khu giải phóng”."},{"t":"Bạn có biết? Đội quân xuất phát từ cây đa Tân Trào chính là Việt Nam Giải phóng quân, vừa được hợp nhất từ Việt Nam Tuyên truyền Giải phóng quân và Cứu quốc quân ít tháng trước đó, đặt nền móng cho Quân đội nhân dân Việt Nam sau này."},{"t":"Tân Trào hôm nay. Chưa đầy hai tuần sau lễ xuất quân, cuộc Tổng khởi nghĩa đã giành chính quyền trong cả nước, và ngày 2 tháng 9 năm 1945, nước Việt Nam Dân chủ Cộng hòa ra đời tại Hà Nội. Tân Trào — nơi khởi phát của chuỗi sự kiện ấy — nay là Khu di tích quốc gia đặc biệt, nơi lán Nà Nưa, đình Tân Trào và cây đa lịch sử vẫn được gìn giữ gần như nguyên vẹn. Mỗi độ tháng Tám về, hàng vạn người từ khắp cả nước lại tìm về thung lũng nhỏ giữa núi rừng Tuyên Quang này, để đứng dưới tán cây đa cổ thụ và hình dung lại giờ phút một dân tộc đứng lên giành lấy vận mệnh của chính mình."}],"hien_vat":[{"ten":"Lán Nà Nưa","mo_ta":"Lán nứa hai gian, mái lá cọ, dựng trên sườn đồi Nà Nưa — nơi Chủ tịch Hồ Chí Minh ở và làm việc từ tháng 5 đến tháng 8/1945, kể cả trong cơn sốt nặng trước ngày Tổng khởi nghĩa.","nguon":"https://tantrao.hochiminh.vn/"},{"ten":"Đình Tân Trào","mo_ta":"Ngôi đình làng ba gian bằng gỗ, sàn cao, mái lợp lá cọ, vốn là nơi thờ thành hoàng. Ngày 16–17/8/1945, đây là nơi Quốc dân Đại hội họp và quyết định Tổng khởi nghĩa.","nguon":"https://tantrao.hochiminh.vn/"},{"ten":"Cây đa Tân Trào","mo_ta":"Cây đa cổ thụ đầu làng, nơi chiều 16/8/1945 đội Việt Nam Giải phóng quân làm lễ xuất quân tiến về giải phóng thị xã Thái Nguyên, dưới sự chỉ huy của Võ Nguyên Giáp.","nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"ten":"Xóm nhà sàn Tày","mo_ta":"Những nếp nhà sàn mái lá của đồng bào Tày quanh thung lũng Tân Trào — cộng đồng đã che chở, nuôi giấu cán bộ cách mạng suốt những năm chuẩn bị khởi nghĩa.","nguon":"https://tantrao.hochiminh.vn/"},{"ten":"Lá cờ đỏ sao vàng","mo_ta":"Quốc dân Đại hội Tân Trào chính thức quy định quốc kỳ nền đỏ, sao vàng năm cánh — lá cờ đã tung bay trong lễ xuất quân dưới cây đa và theo đoàn quân về giải phóng các đô thị.","nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"ten":"Đồi cọ, rừng nứa Tân Trào","mo_ta":"Địa hình đồi cọ xen ruộng bậc thấp và rừng nứa quanh Tân Trào tạo thế tiến có thể đánh, lui có thể giữ — lý do Người chọn nơi này làm trung tâm chỉ đạo Tổng khởi nghĩa.","nguon":"https://tantrao.hochiminh.vn/"}],"hoi_dap":[{"hoi":"Chủ tịch Hồ Chí Minh rời Pác Bó về Tân Trào vào thời gian nào?","dap":"Đầu tháng 5 năm 1945, Người rời Pác Bó (Cao Bằng) để về Tân Trào (Tuyên Quang) chỉ đạo phong trào cách mạng cả nước.","sai":["Cuối năm 1944","Tháng 8 năm 1945","Đầu năm 1946"],"nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"hoi":"Người ở và làm việc tại lán nào trong thời gian ở Tân Trào?","dap":"Lán Nà Nưa (còn gọi là Nà Lừa), một lán nứa nhỏ trên sườn đồi cùng tên.","sai":["Lán Khuôn Tát","Lán Tỉn Keo","Hang Pác Bó"],"nguon":"https://tantrao.hochiminh.vn/"},{"hoi":"Quốc dân Đại hội Tân Trào diễn ra trong hai ngày nào?","dap":"Ngày 16 và 17 tháng 8 năm 1945.","sai":["19 và 20 tháng 8 năm 1945","2 và 3 tháng 9 năm 1945","4 và 5 tháng 6 năm 1945"],"nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"hoi":"Quốc dân Đại hội được tổ chức tại địa điểm nào?","dap":"Tại đình Tân Trào, một ngôi đình làng bằng gỗ vốn dùng để thờ thành hoàng.","sai":["Lán Nà Nưa","Nhà số 48 Hàng Ngang","Bắc Bộ phủ"],"nguon":"https://tantrao.hochiminh.vn/"},{"hoi":"Quốc dân Đại hội đã bầu ra cơ quan lãnh đạo nào, do Hồ Chí Minh làm Chủ tịch?","dap":"Ủy ban Dân tộc Giải phóng Việt Nam — tiền thân của Chính phủ lâm thời nước Việt Nam Dân chủ Cộng hòa.","sai":["Ủy ban Kháng chiến toàn quốc","Ủy ban khởi nghĩa Nam Kỳ","Quốc hội khóa I"],"nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"hoi":"Quốc kỳ được Quốc dân Đại hội Tân Trào quyết định có hình gì?","dap":"Cờ nền đỏ, ở giữa có ngôi sao vàng năm cánh.","sai":["Cờ vàng ba sọc đỏ","Cờ đỏ búa liềm","Cờ nền vàng sao đỏ"],"nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"hoi":"Bài hát nào được Quốc dân Đại hội chọn làm quốc ca?","dap":"Bài Tiến quân ca.","sai":["Bài Diệt phát xít","Bài Du kích ca","Bài Quốc tế ca"],"nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"hoi":"Ai chỉ huy đội Việt Nam Giải phóng quân làm lễ xuất quân dưới cây đa Tân Trào?","dap":"Võ Nguyên Giáp.","sai":["Trường Chinh","Phạm Văn Đồng","Chu Văn Tấn"],"nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"hoi":"Khu giải phóng Việt Bắc được thành lập vào ngày nào?","dap":"Ngày 4 tháng 6 năm 1945, gồm phần lớn các tỉnh Cao Bằng, Bắc Kạn, Lạng Sơn, Hà Giang, Tuyên Quang, Thái Nguyên.","sai":["Ngày 2 tháng 9 năm 1945","Ngày 19 tháng 5 năm 1941","Ngày 22 tháng 12 năm 1944"],"nguon":"ctx_G13"},{"hoi":"Trong cơn sốt nặng tại lán Nà Nưa, Người đã dặn các đồng chí điều gì?","dap":"Phải kiên quyết giành cho được độc lập, dù phải hy sinh tới đâu, dù phải đốt cháy cả dãy Trường Sơn.","sai":["Phải chờ quân Đồng minh vào mới hành động","Phải hoãn khởi nghĩa để chữa bệnh cho Người","Phải rút toàn bộ lực lượng về Cao Bằng"],"nguon":"ctx_G13"},{"hoi":"Người rời Tân Trào về Hà Nội vào ngày nào?","dap":"Ngày 22 tháng 8 năm 1945.","sai":["Ngày 2 tháng 9 năm 1945","Ngày 19 tháng 8 năm 1945","Ngày 25 tháng 8 năm 1945"],"nguon":"ctx_G13"},{"hoi":"Sau khi xuất quân từ cây đa Tân Trào, Giải phóng quân tiến về giải phóng nơi nào đầu tiên?","dap":"Thị xã Thái Nguyên.","sai":["Thành phố Hà Nội","Thị xã Tuyên Quang","Thành phố Hải Phòng"],"nguon":"https://en.wikipedia.org/wiki/August_Revolution"}],"nguon":[{"ten":"August Revolution – Wikipedia (đối chiếu mốc thời gian, quyết định của Quốc dân Đại hội)","url":"https://en.wikipedia.org/wiki/August_Revolution"},{"ten":"Khu di tích quốc gia đặc biệt Tân Trào – Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh","url":"https://tantrao.hochiminh.vn/"},{"ten":"Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh","url":"https://hochiminh.vn"}],"so_chu":1084},"G14":{"ma":"G14","tieu_de":"Hà Nội, mùa thu độc lập","sapo":"Cuối tháng Tám năm 1945, từ một căn gác nhỏ trên phố Hàng Ngang, Chủ tịch Hồ Chí Minh đã viết nên bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa. Chiều 2 tháng 9, giữa Quảng trường Ba Đình rợp cờ, Người đọc bản Tuyên ngôn ấy trước hàng chục vạn đồng bào, mở ra một kỷ nguyên mới cho dân tộc.","sapo_en":"In late August 1945, in a small room on Hang Ngang Street, Ho Chi Minh drafted Vietnam's Declaration of Independence, which he read before hundreds of thousands of people at Ba Dinh Square on 2 September, founding the Democratic Republic of Vietnam.","bia":{"src":"textures/ht/ht_anh_ba_dinh_square_september_2nd_1945.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Từ chiến khu về giữa phố phường","text":"Ngày 25 tháng 8 năm 1945, chỉ vài ngày sau khi rời Tân Trào, Chủ tịch Hồ Chí Minh về tới Hà Nội. Người được bố trí ở tại căn nhà số 48 phố Hàng Ngang — khi đó là cửa hàng tơ lụa Phúc Lợi của gia đình ông bà Trịnh Văn Bô, những nhà tư sản dân tộc có cảm tình sâu sắc với Việt Minh. Con phố Hàng Ngang khi ấy vẫn còn mang dáng dấp phố cổ với những dãy nhà ống mái ngói, cửa hàng buôn bán tơ lụa sầm uất bậc nhất Hà Nội.\n\nChính tại căn gác hai của ngôi nhà này, trong không khí khẩn trương của những ngày chính quyền cách mạng còn non trẻ, Người đã dành phần lớn thời gian để soạn thảo văn kiện quan trọng bậc nhất của lịch sử Việt Nam hiện đại: bản Tuyên ngôn Độc lập.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_tonkin_hanoi_rue_des_cantonnais.jpg","chu_thich":"Phố Hàng Ngang (người Pháp gọi là rue des Cantonnais) đầu thế kỷ XX — nơi có ngôi nhà số 48, địa điểm Người soạn thảo Tuyên ngôn Độc lập.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những ngày viết Tuyên ngôn trên căn gác nhỏ","text":"Trong những ngày cuối tháng 8, Người làm việc cả ngày lẫn đêm bên chiếc bàn nhỏ trên gác hai nhà 48 Hàng Ngang, xung quanh là các cộng sự thân cận. Bản Tuyên ngôn Độc lập không chỉ khẳng định quyền độc lập, tự do của dân tộc Việt Nam mà còn mở đầu bằng việc trích dẫn những lời trong bản Tuyên ngôn Độc lập năm 1776 của Hợp chúng quốc Hoa Kỳ và Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp (được dẫn trong văn bản là năm 1791) — đặt cuộc đấu tranh giành độc lập của một dân tộc nhỏ bé vào dòng chảy chung của khát vọng tự do nhân loại.\n\nBản thảo được hoàn thành trong sự thận trọng, cân nhắc từng câu chữ, bởi đây sẽ là văn kiện pháp lý đầu tiên tuyên bố với thế giới về sự ra đời của một nhà nước độc lập, sau gần một thế kỷ Việt Nam chịu ách đô hộ.","doc":2},{"loai":"anh","src":"textures/bai/G14_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Hà Nội 1945 – Ba Đình nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Ngôi nhà số 48 Hàng Ngang là của gia đình ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ — những thương gia yêu nước sau này còn đóng góp cho chính quyền cách mạng non trẻ nhiều vàng bạc trong phong trào Tuần lễ Vàng cuối năm 1945.","nguon_ten":"hochiminh.vn","doc":3},{"loai":"doan","tieu_de":"Chiều mùng Hai tháng Chín","text":"Chiều 2 tháng 9 năm 1945, tại Quảng trường Ba Đình, trước hàng chục vạn đồng bào Hà Nội và các tỉnh lân cận, Chủ tịch Hồ Chí Minh thay mặt Chính phủ lâm thời đọc bản Tuyên ngôn Độc lập, chính thức khai sinh nước Việt Nam Dân chủ Cộng hòa. Lễ đài được dựng gấp trong những ngày trước đó, do kiến trúc sư Ngô Huy Quỳnh phác thảo và chỉ đạo thi công — một khung gỗ giản dị khoác vải, phông nền đỏ phía sau, đủ trang nghiêm cho một buổi lễ có ý nghĩa lịch sử trọng đại.\n\nGiữa buổi lễ, Người bất ngờ dừng lại, hỏi đồng bào một câu giản dị mà xúc động: “Tôi nói, đồng bào nghe rõ không?”. Câu hỏi ấy, không có trong bất kỳ bản thảo nào, đã trở thành một trong những khoảnh khắc được nhắc nhớ nhiều nhất của ngày Độc lập, cho thấy hình ảnh một vị lãnh tụ gần gũi, giản dị giữa muôn triệu đồng bào.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_toan_canh_le_dai_tai_quang_truong_ba_dinh_ha_noi.jpg","chu_thich":"Toàn cảnh lễ đài tại Quảng trường Ba Đình, chiều 2/9/1945.","credit":"Ảnh: The government of Vietnam. · Public domain · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_president_ho_chi_minh_lit_la_proclamation_d_inde.jpg","chu_thich":"Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập trên lễ đài Ba Đình, 2/9/1945.","credit":"Ảnh: Front pour l'indépendance du Việt-Nam · Public domain · Wikimedia Commons"},{"loai":"trich","text":"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.","nguoi":"Hồ Chí Minh, Tuyên ngôn Độc lập, 2/9/1945","nguon_ten":"https://hochiminh.vn/tu-tuong-dao-duc-ho-chi-minh/tuyen-ngon-doc-lap-nam-1945-va-loi-the-bao-ve-to-quoc.html","doc":5},{"loai":"ban_co_biet","text":"Người phụ trách thiết kế và chỉ đạo dựng lễ đài tại Quảng trường Ba Đình là kiến trúc sư Ngô Huy Quỳnh, khi đó còn rất trẻ; toàn bộ lễ đài — khung gỗ khoác vải, phông nền, bậc lên xuống — được dựng gấp rút chỉ trong vài ngày trước lễ Độc lập.","nguon_ten":"ctx_G14 (canh_3d)","doc":6},{"loai":"doan","tieu_de":"Những thử thách của một chính quyền non trẻ","text":"Chính phủ lâm thời ra đời trong hoàn cảnh ngặt nghèo: nạn đói cuối năm 1944 đầu 1945 đã cướp đi sinh mạng của hàng triệu người, phần lớn dân số mù chữ, ngân khố quốc gia gần như trống rỗng, trong khi quân đội nước ngoài lần lượt kéo vào Việt Nam với danh nghĩa giải giáp quân Nhật. Người phát động ngay các phong trào diệt giặc đói, diệt giặc dốt: kêu gọi nhường cơm sẻ áo qua “Hũ gạo cứu đói”, mở các lớp bình dân học vụ dạy chữ quốc ngữ khắp cả nước.\n\nNgày 6 tháng 1 năm 1946, cuộc Tổng tuyển cử đầu tiên trong lịch sử dân tộc được tổ chức trên cả nước, không phân biệt giàu nghèo, nam nữ, dân tộc hay tôn giáo, bầu ra Quốc hội khóa I. Hai tháng sau, ngày 6 tháng 3 năm 1946, Người ký với đại diện Pháp bản Hiệp định Sơ bộ, công nhận Việt Nam là một quốc gia tự do trong Liên bang Đông Dương, nhằm tránh một cuộc chiến tranh sớm bùng nổ và tạo thời gian hòa hoãn quý giá cho chính quyền cách mạng còn non trẻ củng cố lực lượng.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_ngay_tieu_tru_nan_doi.jpg","chu_thich":"Ngày Tiễu trừ nạn đói được phát động tại Hà Nội, tháng 10/1945.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Phong trào “Tuần lễ Vàng” được phát động tháng 9/1945 để quyên góp vàng, tiền ủng hộ ngân quỹ quốc gia; nhiều gia đình tư sản Hà Nội, trong đó có gia đình ông bà Trịnh Văn Bô, đã hiến hàng nghìn lượng vàng cho chính phủ non trẻ.","nguon_ten":"hochiminh.vn","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_quoc_hoi_vndcch_khoa_i.jpg","chu_thich":"Quốc hội khóa I nước Việt Nam Dân chủ Cộng hòa, được bầu ra sau cuộc Tổng tuyển cử ngày 6/1/1946.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Lời kêu gọi giữa đêm mùa đông","text":"Hòa hoãn không kéo dài được lâu. Sau Hiệp định Sơ bộ và chuyến đi Pháp đàm phán không đạt kết quả như mong muốn, quan hệ Việt – Pháp ngày càng căng thẳng. Đêm 19 tháng 12 năm 1946, tại làng Vạn Phúc (Hà Đông), Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến, chính thức mở đầu cuộc kháng chiến trường kỳ chống thực dân Pháp.\n\nTừ Quảng trường Ba Đình rợp nắng thu 1945, chỉ hơn một năm sau, cả dân tộc lại bước vào một chặng đường mới — gian khổ hơn nhưng cũng kiên cường hơn, để bảo vệ chính nền độc lập vừa giành được.","doc":9},{"loai":"anh","src":"textures/bai/G14_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Hà Nội 1945 – Ba Đình","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"moc","items":[["25/8/1945","Về Hà Nội, ở 48 Hàng Ngang"],["2/9/1945","Đọc Tuyên ngôn Độc lập tại Ba Đình"],["6/1/1946","Tổng tuyển cử đầu tiên"],["6/3/1946","Ký Hiệp định Sơ bộ"],["19/12/1946","Lời kêu gọi toàn quốc kháng chiến"]]}],"doc":[{"i":-1,"t":"Hà Nội, mùa thu độc lập. Cuối tháng Tám năm 1945, từ một căn gác nhỏ trên phố Hàng Ngang, Chủ tịch Hồ Chí Minh đã viết nên bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa. Chiều 2 tháng 9, giữa Quảng trường Ba Đình rợp cờ, Người đọc bản Tuyên ngôn ấy trước hàng chục vạn đồng bào, mở ra một kỷ nguyên mới cho dân tộc."},{"t":"Từ chiến khu về giữa phố phường. Ngày 25 tháng 8 năm 1945, chỉ vài ngày sau khi rời Tân Trào, Chủ tịch Hồ Chí Minh về tới Hà Nội. Người được bố trí ở tại căn nhà số 48 phố Hàng Ngang — khi đó là cửa hàng tơ lụa Phúc Lợi của gia đình ông bà Trịnh Văn Bô, những nhà tư sản dân tộc có cảm tình sâu sắc với Việt Minh. Con phố Hàng Ngang khi ấy vẫn còn mang dáng dấp phố cổ với những dãy nhà ống mái ngói, cửa hàng buôn bán tơ lụa sầm uất bậc nhất Hà Nội. Chính tại căn gác hai của ngôi nhà này, trong không khí khẩn trương của những ngày chính quyền cách mạng còn non trẻ, Người đã dành phần lớn thời gian để soạn thảo văn kiện quan trọng bậc nhất của lịch sử Việt Nam hiện đại: bản Tuyên ngôn Độc lập."},{"t":"Những ngày viết Tuyên ngôn trên căn gác nhỏ. Trong những ngày cuối tháng 8, Người làm việc cả ngày lẫn đêm bên chiếc bàn nhỏ trên gác hai nhà 48 Hàng Ngang, xung quanh là các cộng sự thân cận. Bản Tuyên ngôn Độc lập không chỉ khẳng định quyền độc lập, tự do của dân tộc Việt Nam mà còn mở đầu bằng việc trích dẫn những lời trong bản Tuyên ngôn Độc lập năm 1776 của Hợp chúng quốc Hoa Kỳ và Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp (được dẫn trong văn bản là năm 1791) — đặt cuộc đấu tranh giành độc lập của một dân tộc nhỏ bé vào dòng chảy chung của khát vọng tự do nhân loại. Bản thảo được hoàn thành trong sự thận trọng, cân nhắc từng câu chữ, bởi đây sẽ là văn kiện pháp lý đầu tiên tuyên bố với thế giới về sự ra đời của một nhà nước độc lập, sau gần một thế kỷ Việt Nam chịu ách đô hộ."},{"t":"Bạn có biết? Ngôi nhà số 48 Hàng Ngang là của gia đình ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ — những thương gia yêu nước sau này còn đóng góp cho chính quyền cách mạng non trẻ nhiều vàng bạc trong phong trào Tuần lễ Vàng cuối năm 1945."},{"t":"Chiều mùng Hai tháng Chín. Chiều 2 tháng 9 năm 1945, tại Quảng trường Ba Đình, trước hàng chục vạn đồng bào Hà Nội và các tỉnh lân cận, Chủ tịch Hồ Chí Minh thay mặt Chính phủ lâm thời đọc bản Tuyên ngôn Độc lập, chính thức khai sinh nước Việt Nam Dân chủ Cộng hòa. Lễ đài được dựng gấp trong những ngày trước đó, do kiến trúc sư Ngô Huy Quỳnh phác thảo và chỉ đạo thi công — một khung gỗ giản dị khoác vải, phông nền đỏ phía sau, đủ trang nghiêm cho một buổi lễ có ý nghĩa lịch sử trọng đại. Giữa buổi lễ, Người bất ngờ dừng lại, hỏi đồng bào một câu giản dị mà xúc động: “Tôi nói, đồng bào nghe rõ không?”. Câu hỏi ấy, không có trong bất kỳ bản thảo nào, đã trở thành một trong những khoảnh khắc được nhắc nhớ nhiều nhất của ngày Độc lập, cho thấy hình ảnh một vị lãnh tụ gần gũi, giản dị giữa muôn triệu đồng bào."},{"t":"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy. — Hồ Chí Minh, Tuyên ngôn Độc lập, 2/9/1945"},{"t":"Bạn có biết? Người phụ trách thiết kế và chỉ đạo dựng lễ đài tại Quảng trường Ba Đình là kiến trúc sư Ngô Huy Quỳnh, khi đó còn rất trẻ; toàn bộ lễ đài — khung gỗ khoác vải, phông nền, bậc lên xuống — được dựng gấp rút chỉ trong vài ngày trước lễ Độc lập."},{"t":"Những thử thách của một chính quyền non trẻ. Chính phủ lâm thời ra đời trong hoàn cảnh ngặt nghèo: nạn đói cuối năm 1944 đầu 1945 đã cướp đi sinh mạng của hàng triệu người, phần lớn dân số mù chữ, ngân khố quốc gia gần như trống rỗng, trong khi quân đội nước ngoài lần lượt kéo vào Việt Nam với danh nghĩa giải giáp quân Nhật. Người phát động ngay các phong trào diệt giặc đói, diệt giặc dốt: kêu gọi nhường cơm sẻ áo qua “Hũ gạo cứu đói”, mở các lớp bình dân học vụ dạy chữ quốc ngữ khắp cả nước. Ngày 6 tháng 1 năm 1946, cuộc Tổng tuyển cử đầu tiên trong lịch sử dân tộc được tổ chức trên cả nước, không phân biệt giàu nghèo, nam nữ, dân tộc hay tôn giáo, bầu ra Quốc hội khóa I. Hai tháng sau, ngày 6 tháng 3 năm 1946, Người ký với đại diện Pháp bản Hiệp định Sơ bộ, công nhận Việt Nam là một quốc gia tự do trong Liên bang Đông Dương, nhằm tránh một cuộc chiến tranh sớm bùng nổ và tạo thời gian hòa hoãn quý giá cho chính quyền cách mạng còn non trẻ củng cố lực lượng."},{"t":"Bạn có biết? Phong trào “Tuần lễ Vàng” được phát động tháng 9/1945 để quyên góp vàng, tiền ủng hộ ngân quỹ quốc gia; nhiều gia đình tư sản Hà Nội, trong đó có gia đình ông bà Trịnh Văn Bô, đã hiến hàng nghìn lượng vàng cho chính phủ non trẻ."},{"t":"Lời kêu gọi giữa đêm mùa đông. Hòa hoãn không kéo dài được lâu. Sau Hiệp định Sơ bộ và chuyến đi Pháp đàm phán không đạt kết quả như mong muốn, quan hệ Việt – Pháp ngày càng căng thẳng. Đêm 19 tháng 12 năm 1946, tại làng Vạn Phúc (Hà Đông), Chủ tịch Hồ Chí Minh ra Lời kêu gọi toàn quốc kháng chiến, chính thức mở đầu cuộc kháng chiến trường kỳ chống thực dân Pháp. Từ Quảng trường Ba Đình rợp nắng thu 1945, chỉ hơn một năm sau, cả dân tộc lại bước vào một chặng đường mới — gian khổ hơn nhưng cũng kiên cường hơn, để bảo vệ chính nền độc lập vừa giành được."}],"hien_vat":[{"ten":"Nhà số 48 Hàng Ngang","mo_ta":"Căn nhà ống hai tầng, mặt tiền vữa vàng, từng là cửa hàng tơ lụa Phúc Lợi của gia đình ông bà Trịnh Văn Bô. Trên gác hai, Chủ tịch Hồ Chí Minh đã soạn thảo bản Tuyên ngôn Độc lập trong những ngày cuối tháng 8/1945.","nguon":"https://hochiminh.vn"},{"ten":"Bàn viết và bản thảo trong phòng làm việc","mo_ta":"Chiếc bàn gỗ nhỏ cùng đèn dầu và tập bản thảo viết tay, tái hiện không gian nơi Người làm việc suốt nhiều ngày đêm để hoàn thành văn kiện lập quốc.","nguon":"https://hochiminh.vn"},{"ten":"Lễ đài Ba Đình","mo_ta":"Khung gỗ khoác vải vàng nhạt, phông đỏ phía sau, do kiến trúc sư Ngô Huy Quỳnh phác thảo và dựng gấp trong vài ngày — nơi Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập chiều 2/9/1945.","nguon":"ctx_G14 (canh_3d)"},{"ten":"Cột cờ và lá cờ đỏ sao vàng","mo_ta":"Cột cờ giữa Quảng trường Ba Đình, nơi lá cờ đỏ sao vàng — quốc kỳ vừa được Quốc dân Đại hội Tân Trào quy định ít ngày trước — tung bay trong buổi lễ Độc lập.","nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"ten":"Loa phóng thanh trên lễ đài","mo_ta":"Hệ thống loa được bố trí quanh lễ đài để giọng đọc của Chủ tịch Hồ Chí Minh có thể vang tới hàng chục vạn đồng bào đứng chật quảng trường và các phố lân cận.","nguon":"ctx_G14 (canh_3d)"},{"ten":"Phủ Toàn quyền cũ","mo_ta":"Tòa nhà tường vàng phía bắc Quảng trường Ba Đình, từng là Phủ Toàn quyền Đông Dương thời Pháp thuộc, nay là Phủ Chủ tịch nước Cộng hòa Xã hội chủ nghĩa Việt Nam.","nguon":"ctx_G14 (canh_3d)"}],"hoi_dap":[{"hoi":"Chủ tịch Hồ Chí Minh về tới Hà Nội vào ngày nào, sau khi rời Tân Trào?","dap":"Ngày 25 tháng 8 năm 1945.","sai":["Ngày 2 tháng 9 năm 1945","Ngày 19 tháng 8 năm 1945","Ngày 22 tháng 8 năm 1945"],"nguon":"ctx_G14"},{"hoi":"Người soạn thảo Tuyên ngôn Độc lập tại địa chỉ nào ở Hà Nội?","dap":"Nhà số 48 phố Hàng Ngang.","sai":["Bắc Bộ phủ","Nhà số 5D Hàm Long","Phủ Toàn quyền cũ"],"nguon":"https://hochiminh.vn"},{"hoi":"Ngôi nhà 48 Hàng Ngang là của gia đình nào?","dap":"Gia đình ông Trịnh Văn Bô và bà Hoàng Thị Minh Hồ.","sai":["Gia đình nhà tư sản Bạch Thái Bưởi","Gia đình học giả Nguyễn Văn Tố","Gia đình bác sĩ Trần Duy Hưng"],"nguon":"https://hochiminh.vn"},{"hoi":"Tuyên ngôn Độc lập được đọc vào ngày nào, tại đâu?","dap":"Chiều 2 tháng 9 năm 1945, tại Quảng trường Ba Đình, Hà Nội.","sai":["Ngày 19/8/1945, tại đình Tân Trào","Ngày 25/8/1945, tại 48 Hàng Ngang","Ngày 6/1/1946, tại Bắc Bộ phủ"],"nguon":"https://en.wikipedia.org/wiki/Ba_Dinh_Square"},{"hoi":"Ai thiết kế và chỉ đạo dựng lễ đài tại Quảng trường Ba Đình cho buổi lễ 2/9/1945?","dap":"Kiến trúc sư Ngô Huy Quỳnh.","sai":["Kiến trúc sư Huỳnh Tấn Phát","Họa sĩ Tô Ngọc Vân","Kỹ sư Trần Đại Nghĩa"],"nguon":"ctx_G14 (canh_3d)"},{"hoi":"Giữa bài đọc Tuyên ngôn, Người dừng lại và hỏi đồng bào câu gì?","dap":"“Tôi nói, đồng bào nghe rõ không?”","sai":["“Đồng bào có đói không?”","“Các cụ có khỏe không?”","“Đồng bào có đồng ý không?”"],"nguon":"ctx_G14"},{"hoi":"Cuộc Tổng tuyển cử đầu tiên của nước Việt Nam Dân chủ Cộng hòa diễn ra vào ngày nào?","dap":"Ngày 6 tháng 1 năm 1946.","sai":["Ngày 2 tháng 9 năm 1945","Ngày 6 tháng 3 năm 1946","Ngày 19 tháng 12 năm 1946"],"nguon":"ctx_G14"},{"hoi":"Hiệp định Sơ bộ giữa Việt Nam và Pháp được ký vào ngày nào?","dap":"Ngày 6 tháng 3 năm 1946.","sai":["Ngày 6 tháng 1 năm 1946","Ngày 19 tháng 12 năm 1946","Ngày 21 tháng 7 năm 1954"],"nguon":"ctx_G14"},{"hoi":"Lời kêu gọi toàn quốc kháng chiến được Người phát đi vào đêm nào, tại đâu?","dap":"Đêm 19 tháng 12 năm 1946, tại làng Vạn Phúc, Hà Đông.","sai":["Đêm 2/9/1945, tại Ba Đình","Đêm 6/3/1946, tại Bắc Bộ phủ","Đêm 6/12/1953, tại Việt Bắc"],"nguon":"ctx_G14"},{"hoi":"Phong trào quyên góp vàng ủng hộ chính phủ cuối năm 1945 có tên gọi gì?","dap":"Tuần lễ Vàng.","sai":["Hũ gạo cứu đói","Bình dân học vụ","Đời sống mới"],"nguon":"https://hochiminh.vn"},{"hoi":"Tuyên ngôn Độc lập mở đầu bằng cách trích dẫn hai bản tuyên ngôn nào của thế giới?","dap":"Tuyên ngôn Độc lập năm 1776 của Hoa Kỳ và Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp.","sai":["Hiến chương Liên hợp quốc và Tuyên ngôn Nhân quyền 1948","Đại hiến chương Anh (Magna Carta) và Bộ luật Napoléon","Tuyên ngôn Cộng sản và Tuyên ngôn Nhân quyền Pháp"],"nguon":"ctx_G14 (trich)"}],"nguon":[{"ten":"hochiminh.vn — Tuyên ngôn Độc lập năm 1945 và lời thề bảo vệ Tổ quốc","url":"https://hochiminh.vn/tu-tuong-dao-duc-ho-chi-minh/tuyen-ngon-doc-lap-nam-1945-va-loi-the-bao-ve-to-quoc.html"},{"ten":"hochiminh.vn — Infographic: Tuyên ngôn Độc lập, văn kiện lịch sử vô giá","url":"https://hochiminh.vn/da-phuong-tien/infogaphics/tuyen-ngon-doc-lap-van-kien-lich-su-vo-gia.html"},{"ten":"Ba Đình Square – Wikipedia (đối chiếu)","url":"https://en.wikipedia.org/wiki/Ba_Dinh_Square"},{"ten":"First Indochina War – Wikipedia (đối chiếu bối cảnh 1945–1946)","url":"https://en.wikipedia.org/wiki/First_Indochina_War"}],"so_chu":1086},"G15":{"ma":"G15","tieu_de":"Việt Bắc – Chín năm giữa rừng cọ, đồi chè","sapo":"Suốt chín năm kháng chiến chống Pháp, Chủ tịch Hồ Chí Minh cùng cơ quan đầu não kháng chiến ẩn mình giữa rừng cọ, đồi chè Định Hóa, Sơn Dương, Chiêm Hóa. Từ những mái lán nứa đơn sơ ấy, những quyết định làm nên chiến thắng Điện Biên Phủ đã ra đời.","sapo_en":"For nine years of resistance against France, Ho Chi Minh and Vietnam's wartime leadership worked from simple bamboo huts among the forests and tea hills of Viet Bac — including the meeting that launched the Dien Bien Phu campaign.","bia":{"src":"textures/ht/ht_anh_atk_dinh_hoa.jpg","credit":"Ảnh: Viethavvh at Vietnamese Wikipedia · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Trở lại núi rừng Việt Bắc","text":"Sau Lời kêu gọi toàn quốc kháng chiến đêm 19/12/1946, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương rời Hà Nội, ngược lên vùng núi phía Bắc để bảo toàn lực lượng cho một cuộc chiến tranh được xác định sẽ lâu dài. Từ tháng 5 năm 1947, Người chọn Định Hóa (Thái Nguyên) cùng các huyện lân cận thuộc Tuyên Quang, Bắc Kạn làm nơi đặt An toàn khu (ATK) — trung tâm đầu não của cuộc kháng chiến suốt gần một thập kỷ sau đó.\n\nĐây là vùng đất được đồng bào các dân tộc Tày, Nùng, Dao một lòng che chở, địa hình đồi núi xen kẽ thuận lợi cho việc di chuyển, ẩn náu và giữ bí mật — điều kiện sống còn đối với một cơ quan lãnh đạo tối cao phải hoạt động ngay trong vùng quân Pháp có thể đánh chiếm bất cứ lúc nào. Suốt những năm sau đó, An toàn khu không chỉ là nơi trú ẩn mà còn là một hậu phương thu nhỏ, nơi vừa sản xuất lương thực, mở lớp huấn luyện cán bộ, vừa duy trì mạch liên lạc thông suốt giữa Trung ương với các chiến trường trên cả nước.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_chu_tich_ho_chi_minh_trao_doi_cong_viec_voi_dong.jpg","chu_thich":"Chủ tịch Hồ Chí Minh trao đổi công việc với các đồng chí Tôn Đức Thắng và Hoàng Quốc Việt tại An toàn khu, năm 1947.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cuộc sống giữa những mái lán nứa","text":"Suốt chín năm ở Việt Bắc, Người liên tục di chuyển qua nhiều địa điểm trong An toàn khu — Khuôn Tát, Tỉn Keo và nhiều lán khác quanh Định Hóa, Sơn Dương — mỗi nơi chỉ ở một thời gian ngắn rồi lại chuyển đi để giữ bí mật tuyệt đối. Ở đâu cũng vậy: một lán nứa nhỏ, mái lá cọ, một bộ bàn ghế tre, một chiếc giường tre, chiếc đèn dầu và chiếc máy chữ để soạn thảo chỉ thị, thư từ, bài viết.\n\nTừ những căn lán đơn sơ ấy, Người vẫn nắm chắc diễn biến các mặt trận, chỉ đạo xây dựng hậu phương, phát triển sản xuất, đồng thời trực tiếp góp ý về chiến lược quân sự cho Bộ Tổng tư lệnh trong hầu hết các chiến dịch lớn của cuộc kháng chiến.","doc":2},{"loai":"anh","src":"textures/bai/G15_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Việt Bắc – An toàn khu nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Trong những năm kháng chiến ở Việt Bắc, Người thường tự tay đánh máy thư từ, bài viết trên một chiếc máy chữ xách tay; chiếc máy chữ ấy nay được gìn giữ như một trong những kỷ vật tiêu biểu về cuộc đời hoạt động cách mạng của Người.","nguon_ten":"ctx_G15 (canh_3d)","doc":3},{"loai":"ban_co_biet","text":"Để nấu ăn giữa rừng mà không để khói bốc thẳng lên trời, dễ bị máy bay trinh sát phát hiện, bộ đội và cơ quan kháng chiến ở Việt Bắc dùng loại bếp có hệ thống rãnh dẫn khói tỏa rộng và nguội dần trong lòng đất, gắn với tên người sáng chế — anh nuôi Hoàng Cầm — và trở thành vật dụng quen thuộc suốt những năm kháng chiến, đặc biệt trong Chiến dịch Điện Biên Phủ.","nguon_ten":"ctx_G15 (canh_3d)","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_and_vietnam_women_union_s_cadres_at_.jpg","chu_thich":"Chủ tịch Hồ Chí Minh với cán bộ Hội Phụ nữ tại Việt Bắc, tháng 2/1949 — hình ảnh đời thường giữa những năm kháng chiến.","credit":"Ảnh: Musée Annam · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Đại hội đưa Đảng ra hoạt động công khai","text":"Tháng 2 năm 1951, tại Chiêm Hóa, Tuyên Quang, Đại hội đại biểu toàn quốc lần thứ II của Đảng được triệu tập ngay giữa núi rừng Việt Bắc. Đại hội quyết định đưa Đảng ra hoạt động công khai trở lại với tên gọi Đảng Lao động Việt Nam, sau nhiều năm phải rút vào bí mật; đồng thời đề ra đường lối đẩy mạnh kháng chiến đến thắng lợi hoàn toàn.\n\nĐây là một trong những sự kiện chính trị quan trọng nhất của cả cuộc kháng chiến chín năm, diễn ra không xa những lán nứa nơi Người vẫn ngày ngày làm việc.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_dai_hoi_dai_bieu_toan_quoc_lan_thu_hai_dang_cong.jpg","chu_thich":"Đại hội đại biểu toàn quốc lần thứ II của Đảng, họp tại Chiêm Hóa, Tuyên Quang, tháng 2/1951.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Ngày 11/11/1945, để tránh mũi nhọn tấn công của quân Tưởng và các thế lực phản động, Đảng Cộng sản Đông Dương tuyên bố “tự giải tán” nhưng thực chất vẫn tiếp tục hoạt động bí mật; phải đến Đại hội II năm 1951 giữa An toàn khu, Đảng mới chính thức ra hoạt động công khai trở lại.","nguon_ten":"en.wikipedia.org","doc":6},{"loai":"doan","tieu_de":"Những chiến dịch chỉ đạo từ hậu phương","text":"Từ căn cứ địa Việt Bắc, Người trực tiếp theo dõi và góp ý chỉ đạo hàng loạt chiến dịch lớn: Chiến dịch Việt Bắc thu – đông 1947 đập tan cuộc tấn công quy mô lớn đầu tiên của quân Pháp lên An toàn khu; Chiến dịch Biên giới năm 1950 khai thông đường liên lạc quốc tế, nơi Người từng trực tiếp có mặt quan sát mặt trận Đông Khê; rồi các chiến dịch Hòa Bình, Tây Bắc những năm sau đó, từng bước làm xoay chuyển cục diện chiến trường.\n\nChính từ những mái lán nhỏ giữa rừng, những bức điện, những chỉ thị, thư từ gõ trên chiếc máy chữ cũ đã đến được với các mặt trận xa xôi, góp phần định hình từng bước đi của cuộc kháng chiến.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_in_dong_khe_1950.jpg","chu_thich":"Chủ tịch Hồ Chí Minh quan sát mặt trận Đông Khê trong Chiến dịch Biên giới, năm 1950.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Năm 1948, họa sĩ Phan Kế An có dịp sống gần và trực tiếp ký họa chân dung Người tại Việt Bắc — một trong những bộ ký họa hiếm hoi ghi lại hình ảnh đời thường của Chủ tịch Hồ Chí Minh giữa những năm kháng chiến gian khổ.","nguon_ten":"ctx_G15 (anh_hien_co)","doc":8},{"loai":"doan","tieu_de":"Đêm quyết định tại Tỉn Keo","text":"Ngày 6 tháng 12 năm 1953, tại lán Tỉn Keo dưới chân đèo De (Định Hóa, Thái Nguyên), Bộ Chính trị họp dưới sự chủ trì của Chủ tịch Hồ Chí Minh, thông qua chủ trương mở Chiến dịch Điện Biên Phủ — trận quyết chiến chiến lược sẽ định đoạt cục diện toàn cuộc kháng chiến. Cũng chính căn lán nhỏ ấy, với bộ bàn ghế mộc và tấm bản đồ tác chiến, đã chứng kiến một trong những quyết định quân sự quan trọng nhất trong lịch sử chiến tranh Việt Nam.\n\nGần năm tháng sau, ngày 7 tháng 5 năm 1954, quân đội Việt Nam giành thắng lợi hoàn toàn tại Điện Biên Phủ, kết thúc chiến dịch mà quyết định khởi đầu của nó đã được đưa ra giữa rừng cọ Định Hóa.","doc":9},{"loai":"anh","src":"textures/bai/G15_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Việt Bắc – An toàn khu","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"trich","text":"Tiếng suối trong như tiếng hát xa, Trăng lồng cổ thụ bóng lồng hoa. Cảnh khuya như vẽ người chưa ngủ, Chưa ngủ vì lo nỗi nước nhà.","nguoi":"Hồ Chí Minh, bài thơ “Cảnh khuya”, sáng tác tại Việt Bắc năm 1947","nguon_ten":"Hồ Chí Minh Toàn tập; sách giáo khoa Ngữ văn phổ thông","doc":10},{"loai":"doan","tieu_de":"Trở về Thủ đô sau chín năm","text":"Chiến thắng Điện Biên Phủ buộc Pháp phải ngồi vào bàn đàm phán tại Genève. Hiệp định Genève được ký kết giữa năm 1954, chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương. Ngày 10 tháng 10 năm 1954, Thủ đô được giải phóng; cũng trong tháng 10 năm ấy, Chủ tịch Hồ Chí Minh trở về Hà Nội, khép lại những năm tháng lãnh đạo kháng chiến giữa núi rừng Việt Bắc.\n\nNhững mái lán nứa ở Định Hóa, Tỉn Keo, Khuôn Tát giờ đây trở thành di tích, nhưng câu chuyện về một cơ quan đầu não kháng chiến vận hành giữa núi rừng suốt chín năm, để rồi làm nên chiến thắng Điện Biên Phủ, vẫn còn nguyên giá trị cho tới hôm nay.","doc":11},{"loai":"anh","src":"textures/ht/ht_anh_painter_phan_ke_an_sketched_a_portrait_of_presid.jpg","chu_thich":"Họa sĩ Phan Kế An ký họa Chủ tịch Hồ Chí Minh tại Việt Bắc, 11/1948","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"moc","items":[["5/1947","Lên Việt Bắc, ở Định Hóa"],["1947 – 1952","Chỉ đạo các chiến dịch Việt Bắc, Biên giới, Hòa Bình, Tây Bắc"],["2/1951","Đại hội II của Đảng tại Chiêm Hóa"],["6/12/1953","Quyết định mở Chiến dịch Điện Biên Phủ tại Tỉn Keo"],["7/5/1954","Chiến thắng Điện Biên Phủ"],["10/10/1954","Giải phóng Thủ đô; tháng 10/1954 Người về Hà Nội"]]}],"doc":[{"i":-1,"t":"Việt Bắc – Chín năm giữa rừng cọ, đồi chè. Suốt chín năm kháng chiến chống Pháp, Chủ tịch Hồ Chí Minh cùng cơ quan đầu não kháng chiến ẩn mình giữa rừng cọ, đồi chè Định Hóa, Sơn Dương, Chiêm Hóa. Từ những mái lán nứa đơn sơ ấy, những quyết định làm nên chiến thắng Điện Biên Phủ đã ra đời."},{"t":"Trở lại núi rừng Việt Bắc. Sau Lời kêu gọi toàn quốc kháng chiến đêm 19/12/1946, Chủ tịch Hồ Chí Minh cùng các cơ quan Trung ương rời Hà Nội, ngược lên vùng núi phía Bắc để bảo toàn lực lượng cho một cuộc chiến tranh được xác định sẽ lâu dài. Từ tháng 5 năm 1947, Người chọn Định Hóa (Thái Nguyên) cùng các huyện lân cận thuộc Tuyên Quang, Bắc Kạn làm nơi đặt An toàn khu (ATK) — trung tâm đầu não của cuộc kháng chiến suốt gần một thập kỷ sau đó. Đây là vùng đất được đồng bào các dân tộc Tày, Nùng, Dao một lòng che chở, địa hình đồi núi xen kẽ thuận lợi cho việc di chuyển, ẩn náu và giữ bí mật — điều kiện sống còn đối với một cơ quan lãnh đạo tối cao phải hoạt động ngay trong vùng quân Pháp có thể đánh chiếm bất cứ lúc nào. Suốt những năm sau đó, An toàn khu không chỉ là nơi trú ẩn mà còn là một hậu phương thu nhỏ, nơi vừa sản xuất lương thực, mở lớp huấn luyện cán bộ, vừa duy trì mạch liên lạc thông suốt giữa Trung ương với các chiến trường trên cả nước."},{"t":"Cuộc sống giữa những mái lán nứa. Suốt chín năm ở Việt Bắc, Người liên tục di chuyển qua nhiều địa điểm trong An toàn khu — Khuôn Tát, Tỉn Keo và nhiều lán khác quanh Định Hóa, Sơn Dương — mỗi nơi chỉ ở một thời gian ngắn rồi lại chuyển đi để giữ bí mật tuyệt đối. Ở đâu cũng vậy: một lán nứa nhỏ, mái lá cọ, một bộ bàn ghế tre, một chiếc giường tre, chiếc đèn dầu và chiếc máy chữ để soạn thảo chỉ thị, thư từ, bài viết. Từ những căn lán đơn sơ ấy, Người vẫn nắm chắc diễn biến các mặt trận, chỉ đạo xây dựng hậu phương, phát triển sản xuất, đồng thời trực tiếp góp ý về chiến lược quân sự cho Bộ Tổng tư lệnh trong hầu hết các chiến dịch lớn của cuộc kháng chiến."},{"t":"Bạn có biết? Trong những năm kháng chiến ở Việt Bắc, Người thường tự tay đánh máy thư từ, bài viết trên một chiếc máy chữ xách tay; chiếc máy chữ ấy nay được gìn giữ như một trong những kỷ vật tiêu biểu về cuộc đời hoạt động cách mạng của Người."},{"t":"Bạn có biết? Để nấu ăn giữa rừng mà không để khói bốc thẳng lên trời, dễ bị máy bay trinh sát phát hiện, bộ đội và cơ quan kháng chiến ở Việt Bắc dùng loại bếp có hệ thống rãnh dẫn khói tỏa rộng và nguội dần trong lòng đất, gắn với tên người sáng chế — anh nuôi Hoàng Cầm — và trở thành vật dụng quen thuộc suốt những năm kháng chiến, đặc biệt trong Chiến dịch Điện Biên Phủ."},{"t":"Đại hội đưa Đảng ra hoạt động công khai. Tháng 2 năm 1951, tại Chiêm Hóa, Tuyên Quang, Đại hội đại biểu toàn quốc lần thứ II của Đảng được triệu tập ngay giữa núi rừng Việt Bắc. Đại hội quyết định đưa Đảng ra hoạt động công khai trở lại với tên gọi Đảng Lao động Việt Nam, sau nhiều năm phải rút vào bí mật; đồng thời đề ra đường lối đẩy mạnh kháng chiến đến thắng lợi hoàn toàn. Đây là một trong những sự kiện chính trị quan trọng nhất của cả cuộc kháng chiến chín năm, diễn ra không xa những lán nứa nơi Người vẫn ngày ngày làm việc."},{"t":"Bạn có biết? Ngày 11/11/1945, để tránh mũi nhọn tấn công của quân Tưởng và các thế lực phản động, Đảng Cộng sản Đông Dương tuyên bố “tự giải tán” nhưng thực chất vẫn tiếp tục hoạt động bí mật; phải đến Đại hội II năm 1951 giữa An toàn khu, Đảng mới chính thức ra hoạt động công khai trở lại."},{"t":"Những chiến dịch chỉ đạo từ hậu phương. Từ căn cứ địa Việt Bắc, Người trực tiếp theo dõi và góp ý chỉ đạo hàng loạt chiến dịch lớn: Chiến dịch Việt Bắc thu – đông 1947 đập tan cuộc tấn công quy mô lớn đầu tiên của quân Pháp lên An toàn khu; Chiến dịch Biên giới năm 1950 khai thông đường liên lạc quốc tế, nơi Người từng trực tiếp có mặt quan sát mặt trận Đông Khê; rồi các chiến dịch Hòa Bình, Tây Bắc những năm sau đó, từng bước làm xoay chuyển cục diện chiến trường. Chính từ những mái lán nhỏ giữa rừng, những bức điện, những chỉ thị, thư từ gõ trên chiếc máy chữ cũ đã đến được với các mặt trận xa xôi, góp phần định hình từng bước đi của cuộc kháng chiến."},{"t":"Bạn có biết? Năm 1948, họa sĩ Phan Kế An có dịp sống gần và trực tiếp ký họa chân dung Người tại Việt Bắc — một trong những bộ ký họa hiếm hoi ghi lại hình ảnh đời thường của Chủ tịch Hồ Chí Minh giữa những năm kháng chiến gian khổ."},{"t":"Đêm quyết định tại Tỉn Keo. Ngày 6 tháng 12 năm 1953, tại lán Tỉn Keo dưới chân đèo De (Định Hóa, Thái Nguyên), Bộ Chính trị họp dưới sự chủ trì của Chủ tịch Hồ Chí Minh, thông qua chủ trương mở Chiến dịch Điện Biên Phủ — trận quyết chiến chiến lược sẽ định đoạt cục diện toàn cuộc kháng chiến. Cũng chính căn lán nhỏ ấy, với bộ bàn ghế mộc và tấm bản đồ tác chiến, đã chứng kiến một trong những quyết định quân sự quan trọng nhất trong lịch sử chiến tranh Việt Nam. Gần năm tháng sau, ngày 7 tháng 5 năm 1954, quân đội Việt Nam giành thắng lợi hoàn toàn tại Điện Biên Phủ, kết thúc chiến dịch mà quyết định khởi đầu của nó đã được đưa ra giữa rừng cọ Định Hóa."},{"t":"Tiếng suối trong như tiếng hát xa, Trăng lồng cổ thụ bóng lồng hoa. Cảnh khuya như vẽ người chưa ngủ, Chưa ngủ vì lo nỗi nước nhà. — Hồ Chí Minh, bài thơ “Cảnh khuya”, sáng tác tại Việt Bắc năm 1947"},{"t":"Trở về Thủ đô sau chín năm. Chiến thắng Điện Biên Phủ buộc Pháp phải ngồi vào bàn đàm phán tại Genève. Hiệp định Genève được ký kết giữa năm 1954, chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương. Ngày 10 tháng 10 năm 1954, Thủ đô được giải phóng; cũng trong tháng 10 năm ấy, Chủ tịch Hồ Chí Minh trở về Hà Nội, khép lại những năm tháng lãnh đạo kháng chiến giữa núi rừng Việt Bắc. Những mái lán nứa ở Định Hóa, Tỉn Keo, Khuôn Tát giờ đây trở thành di tích, nhưng câu chuyện về một cơ quan đầu não kháng chiến vận hành giữa núi rừng suốt chín năm, để rồi làm nên chiến thắng Điện Biên Phủ, vẫn còn nguyên giá trị cho tới hôm nay."}],"hien_vat":[{"ten":"Lán Tỉn Keo","mo_ta":"Lán nứa nhỏ, mái lá cọ, dưới chân đèo De — nơi Chủ tịch Hồ Chí Minh ở, làm việc, và nơi Bộ Chính trị họp ngày 6/12/1953 quyết định mở Chiến dịch Điện Biên Phủ.","nguon":"https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu"},{"ten":"Chiếc máy chữ","mo_ta":"Chiếc máy chữ xách tay Người dùng để tự đánh máy thư từ, bài viết trong những năm kháng chiến ở Việt Bắc.","nguon":"ctx_G15 (canh_3d)"},{"ten":"Lán họp Bộ Chính trị","mo_ta":"Bộ bàn ghế mộc cùng tấm bản đồ tác chiến — không gian nơi ngày 6/12/1953 diễn ra cuộc họp lịch sử quyết định mở Chiến dịch Điện Biên Phủ.","nguon":"https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu"},{"ten":"Hầm trú ẩn","mo_ta":"Hầm đào sâu vào sườn đồi, lối xuống ốp gỗ, nơi cơ quan lãnh đạo trú ẩn khi có báo động máy bay hoặc nguy cơ địch càn quét vào khu căn cứ.","nguon":"ctx_G15 (canh_3d)"},{"ten":"Bếp Hoàng Cầm","mo_ta":"Loại bếp không khói với hệ thống rãnh dẫn khói tản rộng trong lòng đất, giúp nấu ăn giữa rừng mà không bị máy bay trinh sát phát hiện, được dùng rộng rãi trong kháng chiến.","nguon":"ctx_G15 (canh_3d)"},{"ten":"Đồi chè, rừng cọ Thái Nguyên","mo_ta":"Cảnh quan đặc trưng của An toàn khu Định Hóa — vừa che giấu, vừa nuôi sống cơ quan đầu não kháng chiến suốt chín năm giữa núi rừng Việt Bắc.","nguon":"ctx_G15 (canh_3d)"}],"hoi_dap":[{"hoi":"Người trở lại Việt Bắc, lập An toàn khu từ thời gian nào?","dap":"Từ tháng 5 năm 1947.","sai":["Từ tháng 12 năm 1946","Từ tháng 2 năm 1951","Từ tháng 12 năm 1953"],"nguon":"ctx_G15"},{"hoi":"An toàn khu của Trung ương chủ yếu đặt tại huyện nào, tỉnh nào?","dap":"Huyện Định Hóa, tỉnh Thái Nguyên.","sai":["Huyện Sơn Dương, tỉnh Tuyên Quang","Huyện Hà Quảng, tỉnh Cao Bằng","Huyện Chợ Đồn, tỉnh Bắc Kạn"],"nguon":"ctx_G15"},{"hoi":"Đại hội đại biểu toàn quốc lần thứ II của Đảng họp ở đâu, khi nào?","dap":"Tại Chiêm Hóa, Tuyên Quang, vào tháng 2 năm 1951.","sai":["Tại Tân Trào, Tuyên Quang, tháng 8/1945","Tại Định Hóa, Thái Nguyên, tháng 12/1953","Tại Pác Bó, Cao Bằng, tháng 5/1941"],"nguon":"ctx_G15"},{"hoi":"Tại Đại hội II, Đảng đổi tên thành gì?","dap":"Đảng Lao động Việt Nam.","sai":["Đảng Cộng sản Việt Nam","Đảng Cộng sản Đông Dương","Việt Nam Độc lập Đồng minh"],"nguon":"https://en.wikipedia.org/wiki/August_Revolution"},{"hoi":"Cuộc họp Bộ Chính trị quyết định mở Chiến dịch Điện Biên Phủ diễn ra ở đâu, ngày nào?","dap":"Tại lán Tỉn Keo (Định Hóa, Thái Nguyên), ngày 6 tháng 12 năm 1953.","sai":["Tại Tân Trào, ngày 16/8/1945","Tại Chiêm Hóa, tháng 2/1951","Tại Hà Nội, ngày 19/12/1946"],"nguon":"https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu"},{"hoi":"Ai chủ trì cuộc họp Bộ Chính trị quyết định mở Chiến dịch Điện Biên Phủ?","dap":"Chủ tịch Hồ Chí Minh.","sai":["Đại tướng Võ Nguyên Giáp","Tổng Bí thư Trường Chinh","Thủ tướng Phạm Văn Đồng"],"nguon":"ctx_G15"},{"hoi":"Chiến thắng Điện Biên Phủ diễn ra vào ngày nào?","dap":"Ngày 7 tháng 5 năm 1954.","sai":["Ngày 6 tháng 12 năm 1953","Ngày 20 tháng 11 năm 1953","Ngày 21 tháng 7 năm 1954"],"nguon":"https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu"},{"hoi":"Loại bếp không khói dùng phổ biến trong kháng chiến gắn với tên ai?","dap":"Anh nuôi Hoàng Cầm.","sai":["Kiến trúc sư Ngô Huy Quỳnh","Họa sĩ Phan Kế An","Đại tướng Võ Nguyên Giáp"],"nguon":"ctx_G15 (canh_3d)"},{"hoi":"Năm 1950, Người trực tiếp có mặt quan sát mặt trận nào trong Chiến dịch Biên giới?","dap":"Mặt trận Đông Khê.","sai":["Mặt trận Điện Biên Phủ","Mặt trận Hòa Bình","Mặt trận Tây Bắc"],"nguon":"ctx_G15 (anh_hien_co)"},{"hoi":"Sau chiến thắng Điện Biên Phủ, hiệp định nào chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương?","dap":"Hiệp định Genève.","sai":["Hiệp định Sơ bộ","Hiệp định Paris","Tạm ước 14/9"],"nguon":"https://en.wikipedia.org/wiki/First_Indochina_War"},{"hoi":"Sau chiến thắng Điện Biên Phủ, Chủ tịch Hồ Chí Minh trở về Hà Nội vào thời gian nào?","dap":"Tháng 10 năm 1954.","sai":["Tháng 5 năm 1954","Tháng 7 năm 1954","Tháng 9 năm 1945"],"nguon":"ctx_G15"},{"hoi":"Bài thơ nào Người sáng tác tại Việt Bắc năm 1947 có câu “Chưa ngủ vì lo nỗi nước nhà”?","dap":"Bài thơ “Cảnh khuya”.","sai":["Bài thơ “Nguyên tiêu”","Bài thơ “Tức cảnh Pác Bó”","Nhật ký trong tù"],"nguon":"Hồ Chí Minh Toàn tập; sách giáo khoa Ngữ văn phổ thông"}],"nguon":[{"ten":"First Indochina War – Wikipedia (đối chiếu mốc 1947, chiến dịch Biên giới, Điện Biên Phủ)","url":"https://en.wikipedia.org/wiki/First_Indochina_War"},{"ten":"Battle of Dien Bien Phu – Wikipedia (đối chiếu ngày tháng chiến dịch)","url":"https://en.wikipedia.org/wiki/Battle_of_Dien_Bien_Phu"},{"ten":"August Revolution – Wikipedia (đối chiếu quá trình hoạt động của Đảng)","url":"https://en.wikipedia.org/wiki/August_Revolution"},{"ten":"Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh","url":"https://hochiminh.vn"}],"so_chu":1175},"G16":{"ma":"G16","tieu_de":"Nhà Sàn Giữa Vườn Cây, Ao Cá","sapo":"Về Hà Nội sau chín năm kháng chiến, Chủ tịch Hồ Chí Minh từ chối tòa dinh thự nguy nga từng là Phủ Toàn quyền Đông Dương, chọn sống mười lăm năm cuối đời trong ngôi nhà nhỏ của người thợ điện rồi ngôi nhà sàn gỗ giản dị bên ao cá. Ở đó, Người vừa điều hành việc nước, trồng cây, nuôi cá, vừa dành bốn năm cuối cùng lặng lẽ viết bản Di chúc để lại cho muôn đời sau.","sapo_en":"Rather than the grand halls of the former Governor-General's Palace, President Ho Chi Minh spent his last fifteen years in a modest electrician's house and then a simple wooden stilt house by a fish pond in Hanoi, where he governed the nation, tended his garden, and quietly wrote his Testament.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_s_stilt_house_hanoi_1_38439116266.jpg","credit":"Ảnh: Richard Mortel from Riyadh, Saudi Arabia · CC BY 2.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Từ chối dinh thự, chọn nhà thợ điện","text":"Tháng 10/1954, sau chín năm kháng chiến, Chủ tịch Hồ Chí Minh trở về Hà Nội. Chính phủ định mời Người vào ở tại tòa dinh thự nguy nga từng là Phủ Toàn quyền Đông Dương — nay là Phủ Chủ tịch — nhưng Người từ chối. Người chọn một căn nhà nhỏ nguyên là nơi ở của người thợ điện phục vụ Phủ Toàn quyền cũ, nằm khuất phía sau tòa nhà lớn, được gọi là Nhà 54. Tháng 12/1954, Người dọn về đây, chỉ giữ lại vài vật dụng đơn sơ: giường gỗ, bàn làm việc, tủ sách nhỏ. Trong những năm sống ở đó, Người vẫn giữ nếp sinh hoạt giản dị quen thuộc từ thời kháng chiến: dậy sớm, tập thể dục, tự tay chăm sóc cây cối quanh nhà. Ngôi nhà nhỏ ấy trở thành nơi ở và làm việc của Chủ tịch nước trong gần bốn năm, trước khi Người chuyển sang ngôi nhà sàn mới dựng bên ao cá.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_bedroom_of_ho_chi_minh_s_house_attached_to_the_p.jpg","chu_thich":"Phòng ngủ giản dị trong Nhà 54 — nơi Bác Hồ ở từ tháng 12/1954 đến năm 1958","credit":"Ảnh: Esemono · CC0 · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_presidential_palace_hanoi_vietnam.jpg","chu_thich":"Phủ Chủ tịch — tòa dinh thự Bác Hồ chỉ dùng để tiếp khách, chưa từng chọn làm nơi ở","credit":"Ảnh: RB Photo · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ngôi nhà sàn dựng theo ký ức Việt Bắc","text":"Năm 1958, Bác đề nghị dựng một ngôi nhà sàn nhỏ, theo đúng kiểu nhà sàn Người từng ở trong những năm kháng chiến trên chiến khu Việt Bắc. Kiến trúc sư Nguyễn Văn Ninh phác thảo theo ý Người: ngôi nhà gỗ hai tầng mang dáng dấp nhà sàn của đồng bào Tày, Thái, dài 10,5 mét, rộng 6,2 mét, mái lợp ngói, xung quanh có hành lang và mành tre che nắng. Ngày 17/5/1958, ít ngày trước sinh nhật lần thứ 68 của Người, Bác chính thức dọn sang ở và làm việc tại ngôi nhà sàn mới, ngay cạnh Nhà 54 cũ, mở đầu mười một năm gắn bó cuối cùng của cuộc đời Người tại đây.","doc":2},{"loai":"anh","src":"textures/bai/G16_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Phủ Chủ tịch – Nhà sàn","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Ngôi nhà sàn do kiến trúc sư Nguyễn Văn Ninh thiết kế theo đúng mong muốn của Bác: một ngôi nhà sàn nhỏ, giản dị như những ngôi nhà Người từng ở giữa núi rừng Việt Bắc thời kháng chiến.","nguon_ten":"vnexpress.net","doc":3},{"loai":"doan","tieu_de":"Tầng dưới họp việc nước, tầng trên là chốn riêng","text":"Tầng trệt của nhà sàn để trống, thoáng mát, là nơi Bác họp Bộ Chính trị, tiếp cán bộ và làm việc trong những ngày hè oi bức. Cầu thang gỗ dẫn lên tầng hai, nơi có hai gian nhỏ — một phòng làm việc, một phòng ngủ — ngăn cách bằng chiếc giá sách kiêm vách ngăn giản dị. Đồ đạc trong nhà đơn sơ đến mức nhiều đoàn khách quốc tế từng ngạc nhiên khi bước vào nơi ở của một vị nguyên thủ quốc gia. Không phòng khách lớn, không đồ trang trí cầu kỳ, chỉ có ánh sáng tự nhiên tràn qua cửa sổ gỗ và hành lang bao quanh.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_office.jpg","chu_thich":"Phòng làm việc của Người trên tầng hai nhà sàn","credit":"Ảnh: Dennis G. Jarvis · CC BY-SA 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ao cá, vườn cây và những buổi chiều đời thường","text":"Trước nhà sàn là một cầu ao nhỏ, nơi hằng ngày, sau giờ làm việc, Bác thường ra cho cá ăn — thói quen giản dị được duy trì suốt hơn một thập niên. Xung quanh nhà sàn là cả một khu vườn do Người tự tay trồng và chăm sóc, quy tụ nhiều loài cây từ khắp các vùng miền đất nước, nối với Phủ Chủ tịch bằng con đường rợp bóng xoài. Đây cũng là nơi Bác tiếp nhiều đoàn khách quốc tế, các cháu thiếu nhi, các đoàn nông dân và công nhân đến thăm, và là nơi gắn với phong trào Tết trồng cây mà Người phát động, kêu gọi mỗi người dân góp một phần xanh cho đất nước mỗi độ xuân về. Không ít lần, Người rời khu vườn nhỏ này để đến thăm trực tiếp các hợp tác xã nông nghiệp, nhà máy, đơn vị bộ đội, rồi trở về viết lại những điều mắt thấy tai nghe thành các bài báo, lời khen, lời nhắc nhở ngắn gọn, giản dị như chính lối sống của Người.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_jawaharlal_nehru_with_dr_ho_chi_minh.jpg","chu_thich":"Chủ tịch Hồ Chí Minh và Thủ tướng Ấn Độ Jawaharlal Nehru, năm 1958 — năm Người sang thăm hữu nghị Ấn Độ","credit":"Ảnh: Nehru Memorial Museum & Library · Public domain · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_president_ho_chi_minh_watching_soccer_1958.jpg","chu_thich":"Người xem một trận bóng đá, 1958 — một trong những thú vui đời thường của Bác","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Nhà để xe cạnh nhà sàn còn lưu giữ những chiếc xe từng phục vụ Chủ tịch Hồ Chí Minh, gồm các xe Pobeda, ZIS và Peugeot 404 — những phương tiện đi lại giản dị so với địa vị một nguyên thủ quốc gia.","nguon_ten":"en.wikipedia.org","doc":6},{"loai":"doan","tieu_de":"Bốn năm viết một bản Di chúc","text":"Sáng 10/5/1965, đúng dịp sinh nhật lần thứ 75, Bác bắt đầu đặt bút viết những dòng đầu tiên của bản Di chúc, tại chính căn phòng làm việc trên tầng hai nhà sàn. Người viết vào những giờ tĩnh lặng nhất trong ngày, từ 9 đến 10 giờ sáng — quãng thời gian được thư ký Vũ Kỳ giữ bí mật tuyệt đối, cất tài liệu vào nơi an toàn và chỉ mang ra đúng hẹn của năm sau. Trong các năm 1965, 1966, 1968 và 1969, mỗi dịp sinh nhật, Người lại giở bản thảo cũ ra, sửa chữa, bổ sung thêm những điều tâm huyết: về giữ gìn đoàn kết trong Đảng, về thực hành dân chủ rộng rãi, về chăm lo đời sống nhân dân sau chiến tranh. Bản Di chúc được Người xem lại lần cuối vào sáng 10/5/1969.","doc":7},{"loai":"trich","text":"Tôi để lại muôn vàn tình thân yêu cho toàn dân, toàn Đảng, cho toàn thể bộ đội, cho các cháu thanh niên và nhi đồng.","nguoi":"Chủ tịch Hồ Chí Minh, Di chúc","nguon_ten":"https://hochiminh.vn/hoc-va-lam-theo-bac/di-chuc","doc":8},{"loai":"anh","src":"textures/bai/G16_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Phủ Chủ tịch – Nhà sàn","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"ban_co_biet","text":"Vì Bác mất đúng ngày Quốc khánh 2/9, Bộ Chính trị khi đó quyết định công bố ngày mất của Người là 3/9/1969; đến năm 1989, Bộ Chính trị mới chính thức đính chính Người từ trần ngày 2/9/1969. Bản Di chúc được công bố tại Lễ truy điệu ngày 9/9/1969.","nguon_ten":"vnexpress.net","doc":9},{"loai":"doan","tieu_de":"Ngày 2 tháng 9 và tình thân yêu để lại","text":"Chủ tịch Hồ Chí Minh từ trần lúc 9 giờ 47 phút ngày 2/9/1969 tại Nhà 67 — ngôi nhà nhỏ gần nhà sàn, nơi Người được các thầy thuốc chăm sóc, điều trị trong những ngày cuối đời. Trong bản Di chúc, Người viết lại những dòng giản dị mà xúc động: để lại muôn vàn tình thân yêu cho toàn dân, toàn Đảng, cho bộ đội, cho các cháu thanh niên và nhi đồng. Sau khi Người qua đời, Bộ Chính trị quyết định xây dựng Lăng ngay tại Quảng trường Ba Đình — nơi Người từng đọc Tuyên ngôn Độc lập — để đồng bào cả nước và bạn bè quốc tế được đến viếng Người, còn ngôi nhà sàn cùng khu vườn, ao cá được giữ nguyên trạng như những ngày Người còn sống và làm việc. Ngôi nhà sàn nhỏ bên ao cá — nơi in dấu những năm tháng bình dị nhất của một vị Chủ tịch nước — từ đó trở thành một phần của Khu Di tích Phủ Chủ tịch, nơi đã đón hàng chục triệu lượt khách trong nước và quốc tế, và được công nhận Di tích quốc gia đặc biệt năm 2009.","doc":10},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_with_children_6.jpg","chu_thich":"Bác Hồ với các cháu thiếu nhi","credit":"Ảnh: Musée Annam · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Khu Di tích Phủ Chủ tịch — gồm Nhà 54, nhà sàn, ao cá và vườn cây — được Nhà nước công nhận là Di tích quốc gia đặc biệt vào năm 2009 và đã đón hàng chục triệu lượt khách tham quan trong nước và quốc tế.","nguon_ten":"vnexpress.net","doc":11},{"loai":"moc","items":[["12/1954","Về ở Nhà 54 trong khu Phủ Chủ tịch"],["17/5/1958","Chuyển sang ở và làm việc tại nhà sàn"],["1959","Phát động phong trào Tết trồng cây"],["10/5/1965","Bắt đầu viết Di chúc, sửa lại mỗi năm vào dịp sinh nhật"],["2/9/1969","Từ trần tại Hà Nội; Di chúc được công bố tại Lễ truy điệu ngày 9/9/1969"],["2009","Khu Di tích Phủ Chủ tịch được công nhận Di tích quốc gia đặc biệt"]]},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_anefo.jpg","chu_thich":"Chủ tịch Hồ Chí Minh năm 1967 — ảnh Anefo, Lưu trữ Quốc gia Hà Lan","credit":"Ảnh: Không rõ tác giả · CC BY-SA 3.0 nl · Wikimedia Commons"}],"doc":[{"i":-1,"t":"Nhà Sàn Giữa Vườn Cây, Ao Cá. Về Hà Nội sau chín năm kháng chiến, Chủ tịch Hồ Chí Minh từ chối tòa dinh thự nguy nga từng là Phủ Toàn quyền Đông Dương, chọn sống mười lăm năm cuối đời trong ngôi nhà nhỏ của người thợ điện rồi ngôi nhà sàn gỗ giản dị bên ao cá. Ở đó, Người vừa điều hành việc nước, trồng cây, nuôi cá, vừa dành bốn năm cuối cùng lặng lẽ viết bản Di chúc để lại cho muôn đời sau."},{"t":"Từ chối dinh thự, chọn nhà thợ điện. Tháng 10/1954, sau chín năm kháng chiến, Chủ tịch Hồ Chí Minh trở về Hà Nội. Chính phủ định mời Người vào ở tại tòa dinh thự nguy nga từng là Phủ Toàn quyền Đông Dương — nay là Phủ Chủ tịch — nhưng Người từ chối. Người chọn một căn nhà nhỏ nguyên là nơi ở của người thợ điện phục vụ Phủ Toàn quyền cũ, nằm khuất phía sau tòa nhà lớn, được gọi là Nhà 54. Tháng 12/1954, Người dọn về đây, chỉ giữ lại vài vật dụng đơn sơ: giường gỗ, bàn làm việc, tủ sách nhỏ. Trong những năm sống ở đó, Người vẫn giữ nếp sinh hoạt giản dị quen thuộc từ thời kháng chiến: dậy sớm, tập thể dục, tự tay chăm sóc cây cối quanh nhà. Ngôi nhà nhỏ ấy trở thành nơi ở và làm việc của Chủ tịch nước trong gần bốn năm, trước khi Người chuyển sang ngôi nhà sàn mới dựng bên ao cá."},{"t":"Ngôi nhà sàn dựng theo ký ức Việt Bắc. Năm 1958, Bác đề nghị dựng một ngôi nhà sàn nhỏ, theo đúng kiểu nhà sàn Người từng ở trong những năm kháng chiến trên chiến khu Việt Bắc. Kiến trúc sư Nguyễn Văn Ninh phác thảo theo ý Người: ngôi nhà gỗ hai tầng mang dáng dấp nhà sàn của đồng bào Tày, Thái, dài 10,5 mét, rộng 6,2 mét, mái lợp ngói, xung quanh có hành lang và mành tre che nắng. Ngày 17/5/1958, ít ngày trước sinh nhật lần thứ 68 của Người, Bác chính thức dọn sang ở và làm việc tại ngôi nhà sàn mới, ngay cạnh Nhà 54 cũ, mở đầu mười một năm gắn bó cuối cùng của cuộc đời Người tại đây."},{"t":"Bạn có biết? Ngôi nhà sàn do kiến trúc sư Nguyễn Văn Ninh thiết kế theo đúng mong muốn của Bác: một ngôi nhà sàn nhỏ, giản dị như những ngôi nhà Người từng ở giữa núi rừng Việt Bắc thời kháng chiến."},{"t":"Tầng dưới họp việc nước, tầng trên là chốn riêng. Tầng trệt của nhà sàn để trống, thoáng mát, là nơi Bác họp Bộ Chính trị, tiếp cán bộ và làm việc trong những ngày hè oi bức. Cầu thang gỗ dẫn lên tầng hai, nơi có hai gian nhỏ — một phòng làm việc, một phòng ngủ — ngăn cách bằng chiếc giá sách kiêm vách ngăn giản dị. Đồ đạc trong nhà đơn sơ đến mức nhiều đoàn khách quốc tế từng ngạc nhiên khi bước vào nơi ở của một vị nguyên thủ quốc gia. Không phòng khách lớn, không đồ trang trí cầu kỳ, chỉ có ánh sáng tự nhiên tràn qua cửa sổ gỗ và hành lang bao quanh."},{"t":"Ao cá, vườn cây và những buổi chiều đời thường. Trước nhà sàn là một cầu ao nhỏ, nơi hằng ngày, sau giờ làm việc, Bác thường ra cho cá ăn — thói quen giản dị được duy trì suốt hơn một thập niên. Xung quanh nhà sàn là cả một khu vườn do Người tự tay trồng và chăm sóc, quy tụ nhiều loài cây từ khắp các vùng miền đất nước, nối với Phủ Chủ tịch bằng con đường rợp bóng xoài. Đây cũng là nơi Bác tiếp nhiều đoàn khách quốc tế, các cháu thiếu nhi, các đoàn nông dân và công nhân đến thăm, và là nơi gắn với phong trào Tết trồng cây mà Người phát động, kêu gọi mỗi người dân góp một phần xanh cho đất nước mỗi độ xuân về. Không ít lần, Người rời khu vườn nhỏ này để đến thăm trực tiếp các hợp tác xã nông nghiệp, nhà máy, đơn vị bộ đội, rồi trở về viết lại những điều mắt thấy tai nghe thành các bài báo, lời khen, lời nhắc nhở ngắn gọn, giản dị như chính lối sống của Người."},{"t":"Bạn có biết? Nhà để xe cạnh nhà sàn còn lưu giữ những chiếc xe từng phục vụ Chủ tịch Hồ Chí Minh, gồm các xe Pobeda, ZIS và Peugeot 404 — những phương tiện đi lại giản dị so với địa vị một nguyên thủ quốc gia."},{"t":"Bốn năm viết một bản Di chúc. Sáng 10/5/1965, đúng dịp sinh nhật lần thứ 75, Bác bắt đầu đặt bút viết những dòng đầu tiên của bản Di chúc, tại chính căn phòng làm việc trên tầng hai nhà sàn. Người viết vào những giờ tĩnh lặng nhất trong ngày, từ 9 đến 10 giờ sáng — quãng thời gian được thư ký Vũ Kỳ giữ bí mật tuyệt đối, cất tài liệu vào nơi an toàn và chỉ mang ra đúng hẹn của năm sau. Trong các năm 1965, 1966, 1968 và 1969, mỗi dịp sinh nhật, Người lại giở bản thảo cũ ra, sửa chữa, bổ sung thêm những điều tâm huyết: về giữ gìn đoàn kết trong Đảng, về thực hành dân chủ rộng rãi, về chăm lo đời sống nhân dân sau chiến tranh. Bản Di chúc được Người xem lại lần cuối vào sáng 10/5/1969."},{"t":"Tôi để lại muôn vàn tình thân yêu cho toàn dân, toàn Đảng, cho toàn thể bộ đội, cho các cháu thanh niên và nhi đồng. — Chủ tịch Hồ Chí Minh, Di chúc"},{"t":"Bạn có biết? Vì Bác mất đúng ngày Quốc khánh 2/9, Bộ Chính trị khi đó quyết định công bố ngày mất của Người là 3/9/1969; đến năm 1989, Bộ Chính trị mới chính thức đính chính Người từ trần ngày 2/9/1969. Bản Di chúc được công bố tại Lễ truy điệu ngày 9/9/1969."},{"t":"Ngày 2 tháng 9 và tình thân yêu để lại. Chủ tịch Hồ Chí Minh từ trần lúc 9 giờ 47 phút ngày 2/9/1969 tại Nhà 67 — ngôi nhà nhỏ gần nhà sàn, nơi Người được các thầy thuốc chăm sóc, điều trị trong những ngày cuối đời. Trong bản Di chúc, Người viết lại những dòng giản dị mà xúc động: để lại muôn vàn tình thân yêu cho toàn dân, toàn Đảng, cho bộ đội, cho các cháu thanh niên và nhi đồng. Sau khi Người qua đời, Bộ Chính trị quyết định xây dựng Lăng ngay tại Quảng trường Ba Đình — nơi Người từng đọc Tuyên ngôn Độc lập — để đồng bào cả nước và bạn bè quốc tế được đến viếng Người, còn ngôi nhà sàn cùng khu vườn, ao cá được giữ nguyên trạng như những ngày Người còn sống và làm việc. Ngôi nhà sàn nhỏ bên ao cá — nơi in dấu những năm tháng bình dị nhất của một vị Chủ tịch nước — từ đó trở thành một phần của Khu Di tích Phủ Chủ tịch, nơi đã đón hàng chục triệu lượt khách trong nước và quốc tế, và được công nhận Di tích quốc gia đặc biệt năm 2009."},{"t":"Bạn có biết? Khu Di tích Phủ Chủ tịch — gồm Nhà 54, nhà sàn, ao cá và vườn cây — được Nhà nước công nhận là Di tích quốc gia đặc biệt vào năm 2009 và đã đón hàng chục triệu lượt khách tham quan trong nước và quốc tế."}],"hien_vat":[{"ten":"Nhà sàn gỗ hai tầng","mo_ta":"Ngôi nhà sàn gỗ hai tầng dài 10,5 m, rộng 6,2 m, do kiến trúc sư Nguyễn Văn Ninh thiết kế theo kiểu nhà sàn của đồng bào Tày, Thái ở Việt Bắc. Bác Hồ chuyển đến ở và làm việc tại đây từ ngày 17/5/1958 đến năm 1969.","nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"ten":"Nhà 54","mo_ta":"Căn nhà nhỏ nguyên là nơi ở của người thợ điện phục vụ Phủ Toàn quyền cũ. Chủ tịch Hồ Chí Minh chọn ở đây từ tháng 12/1954 khi vừa trở về Hà Nội, trước khi chuyển sang nhà sàn năm 1958.","nguon":"https://vnexpress.net/tong-thong-sri-lanka-tham-nha-san-ao-ca-ho-chu-tich-4881785.html"},{"ten":"Ao cá trước nhà sàn","mo_ta":"Chiếc ao nhỏ ngay trước nhà sàn, nơi Bác Hồ thường ra cho cá ăn mỗi ngày sau giờ làm việc — một thói quen giản dị được duy trì suốt những năm Người sống tại đây.","nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"ten":"Đường xoài","mo_ta":"Con đường rợp bóng cây xoài nối nhà sàn với khu Phủ Chủ tịch, nơi Bác Hồ thường đi lại và cũng là lối các đoàn khách quốc tế đi qua khi đến thăm nơi ở của Người.","nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"ten":"Giá sách ngăn phòng","mo_ta":"Trên tầng hai nhà sàn, một chiếc giá sách đơn sơ được dùng làm vách ngăn giữa phòng làm việc và phòng ngủ của Bác — chi tiết cho thấy lối sống giản dị của Người.","nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"ten":"Ba chiếc ô tô trong nhà để xe","mo_ta":"Nhà để xe bên cạnh nhà sàn còn lưu giữ những chiếc xe từng phục vụ Chủ tịch Hồ Chí Minh, gồm các xe Pobeda, ZIS và Peugeot 404.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Phủ Chủ tịch","mo_ta":"Tòa nhà sơn màu vàng, nguyên là Phủ Toàn quyền Đông Dương thời Pháp thuộc, nằm không xa nhà sàn. Bác Hồ chỉ dùng nơi đây để tiếp khách quốc tế và họp những sự kiện lớn, chứ không chọn làm nơi ở.","nguon":"https://vnexpress.net/tong-thong-sri-lanka-tham-nha-san-ao-ca-ho-chu-tich-4881785.html"}],"hoi_dap":[{"hoi":"Vì sao Chủ tịch Hồ Chí Minh không ở trong tòa nhà từng là Phủ Toàn quyền Đông Dương?","dap":"Vì Người muốn sống giản dị, gần gũi với đời sống nhân dân, nên chọn ở nhà nhỏ rồi nhà sàn thay vì dinh thự lớn.","sai":["Vì tòa nhà đã bị hư hỏng nặng sau chiến tranh","Vì chính phủ Pháp không cho phép Người sử dụng","Vì tòa nhà được dùng làm trụ sở Quốc hội"],"nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"hoi":"Bác Hồ chuyển đến ở và làm việc tại nhà sàn từ ngày nào?","dap":"Ngày 17/5/1958.","sai":["Ngay khi về Hà Nội năm 1954","Năm 1960, sau Đại hội Đảng III","Năm 1965, cùng thời điểm bắt đầu viết Di chúc"],"nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"hoi":"Kiến trúc ngôi nhà sàn được lấy cảm hứng từ đâu?","dap":"Từ kiểu nhà sàn của đồng bào Tày, Thái mà Người từng ở trong những năm kháng chiến ở Việt Bắc.","sai":["Từ kiến trúc biệt thự Pháp","Từ nhà rường Huế truyền thống","Từ nhà dài Tây Nguyên"],"nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"hoi":"Nhà sàn có kích thước như thế nào?","dap":"Dài 10,5 mét, rộng 6,2 mét, gồm hai tầng bằng gỗ, mái ngói.","sai":["Dài 20 mét, rộng 10 mét","Chỉ có một tầng, không có gác trên","Xây bằng bê tông giả gỗ"],"nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"hoi":"Tầng trệt của nhà sàn thường được dùng để làm gì?","dap":"Là nơi thoáng mát để Bác họp Bộ Chính trị và tiếp cán bộ, nhất là vào mùa hè.","sai":["Là nơi ở của đội cảnh vệ","Là nhà kho chứa sách báo","Là nơi tổ chức tiệc chiêu đãi khách quốc tế"],"nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"hoi":"Bác Hồ bắt đầu viết bản Di chúc vào thời điểm nào?","dap":"Sáng 10/5/1965, đúng dịp sinh nhật lần thứ 75 của Người.","sai":["Ngày 2/9/1969, ngay trước khi qua đời","Ngày 19/5/1969","Ngày 10/5/1960"],"nguon":"https://vnexpress.net/bon-nam-chu-tich-ho-chi-minh-viet-di-chuc-4786386.html"},{"hoi":"Ai là người được Bác Hồ giao giữ bí mật bản thảo Di chúc mỗi năm?","dap":"Thư ký Vũ Kỳ, người cất giữ tài liệu và chỉ mang ra theo đúng hẹn của Người vào tháng 5 năm sau.","sai":["Đại tướng Võ Nguyên Giáp","Thủ tướng Phạm Văn Đồng","Luật sư Phan Anh"],"nguon":"https://vnexpress.net/bon-nam-chu-tich-ho-chi-minh-viet-di-chuc-4786386.html"},{"hoi":"Việc gì diễn ra đều đặn mỗi ngày ở chiếc ao trước nhà sàn?","dap":"Bác Hồ thường ra cho cá ăn sau giờ làm việc.","sai":["Bác tắm sông mỗi sáng sớm","Bác câu cá để dùng cho bữa ăn","Đây là nơi tổ chức thi bơi cho thiếu nhi"],"nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"hoi":"Phong trào nào gắn liền với khu vườn nhà sàn, do Bác phát động để góp phần xanh cho đất nước?","dap":"Phong trào Tết trồng cây.","sai":["Phong trào Bình dân học vụ","Phong trào diệt giặc đói, giặc dốt","Phong trào Ba sẵn sàng"],"nguon":"https://hochiminh.vn/hoc-va-lam-theo-bac/di-chuc"},{"hoi":"Khu Di tích Phủ Chủ tịch được công nhận là gì vào năm 2009?","dap":"Di tích quốc gia đặc biệt.","sai":["Di sản văn hóa thế giới của UNESCO","Bảo vật quốc gia","Công trình kiến trúc tiêu biểu ASEAN"],"nguon":"https://vnexpress.net/nha-san-bac-ho-4155765.html"}],"nguon":[{"ten":"Nhà sàn Bác Hồ — VnExpress","url":"https://vnexpress.net/nha-san-bac-ho-4155765.html"},{"ten":"Bốn năm Chủ tịch Hồ Chí Minh viết di chúc — VnExpress","url":"https://vnexpress.net/bon-nam-chu-tich-ho-chi-minh-viet-di-chuc-4786386.html"},{"ten":"Tổng thống Sri Lanka thăm Nhà sàn, ao cá Hồ Chủ tịch — VnExpress","url":"https://vnexpress.net/tong-thong-sri-lanka-tham-nha-san-ao-ca-ho-chu-tich-4881785.html"},{"ten":"Di chúc — Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh","url":"https://hochiminh.vn/hoc-va-lam-theo-bac/di-chuc"},{"ten":"Ho Chi Minh — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"}],"so_chu":1223},"G17":{"ma":"G17","tieu_de":"Lăng Bác, Bảo Tàng, Và Một Tư Tưởng Sống Mãi","sapo":"Ngày 29/8/1975, giữa Quảng trường Ba Đình lịch sử — nơi Người từng đọc Tuyên ngôn Độc lập — Lăng Chủ tịch Hồ Chí Minh được khánh thành, đưa Người trở về ở giữa lòng nhân dân. Mười lăm năm sau, đúng dịp kỷ niệm 100 năm ngày sinh của Người, Bảo tàng Hồ Chí Minh mở cửa; lễ kỷ niệm năm ấy được tổ chức theo nghị quyết UNESCO thông qua từ năm 1987, tôn vinh Người là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất. Và từ đó đến nay, tư tưởng, đạo đức, phong cách của Người vẫn tiếp tục được học và làm theo trong đời sống hằng ngày.","sapo_en":"On 29 August 1975, in Ba Dinh Square where he once read the Declaration of Independence, President Ho Chi Minh's Mausoleum was inaugurated; fifteen years later, on the centenary of his birth, the Ho Chi Minh Museum opened as UNESCO honored him as a hero of national liberation and an outstanding man of culture.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_ba_dinh_square_and_ho_chi_minh_mau.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Trở về giữa Ba Đình","text":"Quảng trường Ba Đình mang một dấu ấn đặc biệt trong lịch sử dân tộc: chính tại đây, ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Ba mươi năm sau, cũng tại quảng trường này, công trình Lăng của Người được khởi công xây dựng ngày 2/9/1973 và khánh thành ngày 29/8/1975, kịp trước dịp kỷ niệm 30 năm Quốc khánh. Từ đó, hàng triệu người Việt Nam và bạn bè quốc tế mỗi năm tìm về đây, xếp hàng lặng lẽ để được vào viếng Người. Nhiều nguyên thủ, lãnh đạo các nước khi thăm Việt Nam cũng dành thời gian đến đặt vòng hoa, vào Lăng viếng Chủ tịch Hồ Chí Minh trước khi thăm Khu Di tích Phủ Chủ tịch và Bảo tàng liền kề.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_guards_of_the_ho_chi_minh_mausoleum.jpg","chu_thich":"Tiêu binh trước Lăng","credit":"Ảnh: Christophe95 · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Công trình Lăng được khởi công đúng ngày 2/9/1973 — tròn bốn năm sau ngày Chủ tịch Hồ Chí Minh qua đời — và hoàn thành sau gần hai năm xây dựng, kịp khánh thành vào ngày 29/8/1975.","nguon_ten":"en.wikipedia.org","doc":2},{"loai":"doan","tieu_de":"Ba lớp kiến trúc, một dáng hình đất nước","text":"Lăng cao 21,6 mét, gồm ba lớp chính: lớp dưới cùng là bậc thềm với hai khán đài hai bên dành cho các đoàn diễu hành trong dịp lễ lớn; lớp giữa là phần trung tâm, được bao quanh bởi hàng cột vuông ốp đá hoa cương xám; và lớp trên là phần mái xếp tầng theo dáng cách điệu. Mặt trước Lăng có dòng chữ CHỦ TỊCH HỒ-CHÍ-MINH ghép bằng đá ngọc đỏ lấy từ Cao Bằng. Bên ngoài ốp đá granite xám, bên trong là đá hoa cương xám, đen và đỏ được đánh bóng; nhiều loại gỗ quý, đá quý từ khắp các miền đất nước cũng được đưa về xây dựng Lăng. Lăng do các kiến trúc sư Việt Nam và Liên Xô cùng thiết kế, kết hợp kiến trúc hiện đại với những yếu tố mang bản sắc dân tộc.","doc":3},{"loai":"anh","src":"textures/bai/G17_v1.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Di sản – Học và làm theo Bác nhìn từ trên cao","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Quảng trường, hàng tre và phiên gác danh dự","text":"Trước Lăng là Quảng trường Ba Đình rộng lớn, chia thành hàng trăm ô cỏ vuông xen giữa các lối đi, giữa quảng trường là cột cờ nơi diễn ra nghi lễ thượng cờ vào buổi sáng và hạ cờ vào buổi tối mỗi ngày. Hai bên Lăng là những hàng tre — biểu tượng quen thuộc của làng quê Việt Nam — cùng hàng cây vạn tuế được trồng mang ý nghĩa tượng trưng cho cuộc đời Người. Đội tiêu binh danh dự luôn túc trực, thay gác theo nghi thức nghiêm trang. Lăng mở cửa đón khách năm ngày mỗi tuần, miễn phí vé vào cửa; mỗi tuần có hàng chục nghìn lượt người đến viếng. Khách vào Lăng phải giữ trang phục nghiêm chỉnh, không mang theo máy ảnh, điện thoại có chức năng quay chụp và giữ im lặng trong suốt hành trình — những quy định nhỏ nhưng góp phần giữ trọn vẹn không khí trang nghiêm của nơi này.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_quang_truong_ba_dinh_ve_dem.jpg","chu_thich":"Quảng trường Ba Đình về đêm","credit":"Ảnh: Nguyễn Thanh Quang · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Quanh Lăng có 79 cây vạn tuế được trồng, con số được chọn để tượng trưng cho 79 mùa xuân cuộc đời của Chủ tịch Hồ Chí Minh (1890 – 1969).","nguon_ten":"en.wikipedia.org","doc":5},{"loai":"anh","src":"textures/bai/G17_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện Di sản – Học và làm theo Bác","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Bảo tàng của một cuộc đời, một dân tộc","text":"Ngày 19/5/1990, đúng kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh chính thức mở cửa ngay cạnh Lăng và Khu Di tích Phủ Chủ tịch. Phần trưng bày chính được sắp xếp theo dòng thời gian, tái hiện cuộc đời và sự nghiệp của Người từ thời niên thiếu ở quê hương Nghệ An, những năm bôn ba tìm đường cứu nước, sáng lập Đảng và lãnh đạo cách mạng, cho đến tình cảm của nhân dân Việt Nam và bạn bè thế giới dành cho Người. Kho của Bảo tàng lưu giữ hơn 170.000 tài liệu, hiện vật và phim ảnh.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_hanoi_vietnam_ho_chi_minh_museum_the_pyramid.jpg","chu_thich":"Bảo tàng Hồ Chí Minh, Hà Nội — khánh thành 19/5/1990","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},{"loai":"anh","src":"textures/ht/ht_anh_hanoi_vietnam_interiors_of_ho_chi_minh_museum.jpg","chu_thich":"Không gian trưng bày bên trong Bảo tàng Hồ Chí Minh","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Bảo tàng Hồ Chí Minh hiện lưu giữ hơn 170.000 tài liệu, hiện vật và phim ảnh về cuộc đời, sự nghiệp của Chủ tịch Hồ Chí Minh — nguồn tư liệu quý cho nghiên cứu và giáo dục truyền thống.","nguon_ten":"en.wikipedia.org","doc":7},{"loai":"doan","tieu_de":"Một nghị quyết của thế giới","text":"Cũng hướng tới sự kiện trọng đại ấy, năm 1987, Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO) đã ra nghị quyết vinh danh Hồ Chí Minh là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam, nhân dịp kỷ niệm 100 năm ngày sinh của Người vào năm 1990. Đây là một trong số ít trường hợp một tổ chức quốc tế chính thức ghi nhận tầm vóc của một lãnh tụ cách mạng ở cả hai phương diện: đấu tranh giải phóng dân tộc và đóng góp văn hóa cho nhân loại.","doc":8},{"loai":"doan","tieu_de":"Học và làm theo Bác, từ tư tưởng đến việc làm","text":"Tư tưởng Hồ Chí Minh, cùng với chủ nghĩa Mác - Lênin, được Đại hội đại biểu toàn quốc lần thứ VII của Đảng, năm 1991, xác định là nền tảng tư tưởng, kim chỉ nam cho hành động. Từ đó, một cuộc vận động học tập và làm theo Người được phát động rộng khắp, mang nhiều tên gọi qua từng giai đoạn, và từ năm 2016 được gọi chính thức là Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh theo Chỉ thị số 05 của Bộ Chính trị. Trong đó, tinh thần thực hành tiết kiệm, chống tham ô, lãng phí — điều chính Người từng căn dặn trong Di chúc — vẫn được nhắc lại như một tiêu chí cụ thể của việc học và làm theo Bác hôm nay. Không chỉ dừng ở khẩu hiệu, cuộc vận động ấy đi vào từng việc làm cụ thể ở mỗi địa phương — từ nêu gương cán bộ, đảng viên đến những phong trào thi đua nhỏ ở cơ sở, trong đó có nhiều câu chuyện đang tiếp diễn ngay tại Ninh Bình hôm nay.","doc":9},{"loai":"trich","text":"Đảng ta là một Đảng cầm quyền. Mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư.","nguoi":"Chủ tịch Hồ Chí Minh, Di chúc (1969)","nguon_ten":"https://hochiminh.vn/hoc-va-lam-theo-bac/di-chuc","doc":10},{"loai":"ban_co_biet","text":"Phải hơn hai mươi năm sau khi Chủ tịch Hồ Chí Minh qua đời, tư tưởng Hồ Chí Minh mới chính thức được Đại hội VII của Đảng (1991) xác định là nền tảng tư tưởng, cùng với chủ nghĩa Mác - Lênin.","nguon_ten":"en.wikipedia.org","doc":11},{"loai":"anh","src":"textures/bai/G17_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện Di sản – Học và làm theo Bác","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"anh","src":"textures/bai/G17_v3.jpg","chu_thich":"Một góc không gian 3D tái hiện Di sản – Học và làm theo Bác","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"moc","items":[["29/8/1975","Khánh thành Lăng Chủ tịch Hồ Chí Minh"],["1987","UNESCO ra nghị quyết vinh danh Người là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất"],["19/5/1990","Khánh thành Bảo tàng Hồ Chí Minh, đúng kỷ niệm 100 năm ngày sinh"],["1991","Đại hội VII của Đảng xác định tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam hành động"],["2016 – nay","Cuộc vận động Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh theo Chỉ thị 05-CT/TW"]]}],"doc":[{"i":-1,"t":"Lăng Bác, Bảo Tàng, Và Một Tư Tưởng Sống Mãi. Ngày 29/8/1975, giữa Quảng trường Ba Đình lịch sử — nơi Người từng đọc Tuyên ngôn Độc lập — Lăng Chủ tịch Hồ Chí Minh được khánh thành, đưa Người trở về ở giữa lòng nhân dân. Mười lăm năm sau, đúng dịp kỷ niệm 100 năm ngày sinh của Người, Bảo tàng Hồ Chí Minh mở cửa; lễ kỷ niệm năm ấy được tổ chức theo nghị quyết UNESCO thông qua từ năm 1987, tôn vinh Người là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất. Và từ đó đến nay, tư tưởng, đạo đức, phong cách của Người vẫn tiếp tục được học và làm theo trong đời sống hằng ngày."},{"t":"Trở về giữa Ba Đình. Quảng trường Ba Đình mang một dấu ấn đặc biệt trong lịch sử dân tộc: chính tại đây, ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Ba mươi năm sau, cũng tại quảng trường này, công trình Lăng của Người được khởi công xây dựng ngày 2/9/1973 và khánh thành ngày 29/8/1975, kịp trước dịp kỷ niệm 30 năm Quốc khánh. Từ đó, hàng triệu người Việt Nam và bạn bè quốc tế mỗi năm tìm về đây, xếp hàng lặng lẽ để được vào viếng Người. Nhiều nguyên thủ, lãnh đạo các nước khi thăm Việt Nam cũng dành thời gian đến đặt vòng hoa, vào Lăng viếng Chủ tịch Hồ Chí Minh trước khi thăm Khu Di tích Phủ Chủ tịch và Bảo tàng liền kề."},{"t":"Bạn có biết? Công trình Lăng được khởi công đúng ngày 2/9/1973 — tròn bốn năm sau ngày Chủ tịch Hồ Chí Minh qua đời — và hoàn thành sau gần hai năm xây dựng, kịp khánh thành vào ngày 29/8/1975."},{"t":"Ba lớp kiến trúc, một dáng hình đất nước. Lăng cao 21,6 mét, gồm ba lớp chính: lớp dưới cùng là bậc thềm với hai khán đài hai bên dành cho các đoàn diễu hành trong dịp lễ lớn; lớp giữa là phần trung tâm, được bao quanh bởi hàng cột vuông ốp đá hoa cương xám; và lớp trên là phần mái xếp tầng theo dáng cách điệu. Mặt trước Lăng có dòng chữ CHỦ TỊCH HỒ-CHÍ-MINH ghép bằng đá ngọc đỏ lấy từ Cao Bằng. Bên ngoài ốp đá granite xám, bên trong là đá hoa cương xám, đen và đỏ được đánh bóng; nhiều loại gỗ quý, đá quý từ khắp các miền đất nước cũng được đưa về xây dựng Lăng. Lăng do các kiến trúc sư Việt Nam và Liên Xô cùng thiết kế, kết hợp kiến trúc hiện đại với những yếu tố mang bản sắc dân tộc."},{"t":"Quảng trường, hàng tre và phiên gác danh dự. Trước Lăng là Quảng trường Ba Đình rộng lớn, chia thành hàng trăm ô cỏ vuông xen giữa các lối đi, giữa quảng trường là cột cờ nơi diễn ra nghi lễ thượng cờ vào buổi sáng và hạ cờ vào buổi tối mỗi ngày. Hai bên Lăng là những hàng tre — biểu tượng quen thuộc của làng quê Việt Nam — cùng hàng cây vạn tuế được trồng mang ý nghĩa tượng trưng cho cuộc đời Người. Đội tiêu binh danh dự luôn túc trực, thay gác theo nghi thức nghiêm trang. Lăng mở cửa đón khách năm ngày mỗi tuần, miễn phí vé vào cửa; mỗi tuần có hàng chục nghìn lượt người đến viếng. Khách vào Lăng phải giữ trang phục nghiêm chỉnh, không mang theo máy ảnh, điện thoại có chức năng quay chụp và giữ im lặng trong suốt hành trình — những quy định nhỏ nhưng góp phần giữ trọn vẹn không khí trang nghiêm của nơi này."},{"t":"Bạn có biết? Quanh Lăng có 79 cây vạn tuế được trồng, con số được chọn để tượng trưng cho 79 mùa xuân cuộc đời của Chủ tịch Hồ Chí Minh (1890 – 1969)."},{"t":"Bảo tàng của một cuộc đời, một dân tộc. Ngày 19/5/1990, đúng kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh chính thức mở cửa ngay cạnh Lăng và Khu Di tích Phủ Chủ tịch. Phần trưng bày chính được sắp xếp theo dòng thời gian, tái hiện cuộc đời và sự nghiệp của Người từ thời niên thiếu ở quê hương Nghệ An, những năm bôn ba tìm đường cứu nước, sáng lập Đảng và lãnh đạo cách mạng, cho đến tình cảm của nhân dân Việt Nam và bạn bè thế giới dành cho Người. Kho của Bảo tàng lưu giữ hơn 170.000 tài liệu, hiện vật và phim ảnh."},{"t":"Bạn có biết? Bảo tàng Hồ Chí Minh hiện lưu giữ hơn 170.000 tài liệu, hiện vật và phim ảnh về cuộc đời, sự nghiệp của Chủ tịch Hồ Chí Minh — nguồn tư liệu quý cho nghiên cứu và giáo dục truyền thống."},{"t":"Một nghị quyết của thế giới. Cũng hướng tới sự kiện trọng đại ấy, năm 1987, Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO) đã ra nghị quyết vinh danh Hồ Chí Minh là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam, nhân dịp kỷ niệm 100 năm ngày sinh của Người vào năm 1990. Đây là một trong số ít trường hợp một tổ chức quốc tế chính thức ghi nhận tầm vóc của một lãnh tụ cách mạng ở cả hai phương diện: đấu tranh giải phóng dân tộc và đóng góp văn hóa cho nhân loại."},{"t":"Học và làm theo Bác, từ tư tưởng đến việc làm. Tư tưởng Hồ Chí Minh, cùng với chủ nghĩa Mác - Lênin, được Đại hội đại biểu toàn quốc lần thứ VII của Đảng, năm 1991, xác định là nền tảng tư tưởng, kim chỉ nam cho hành động. Từ đó, một cuộc vận động học tập và làm theo Người được phát động rộng khắp, mang nhiều tên gọi qua từng giai đoạn, và từ năm 2016 được gọi chính thức là Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh theo Chỉ thị số 05 của Bộ Chính trị. Trong đó, tinh thần thực hành tiết kiệm, chống tham ô, lãng phí — điều chính Người từng căn dặn trong Di chúc — vẫn được nhắc lại như một tiêu chí cụ thể của việc học và làm theo Bác hôm nay. Không chỉ dừng ở khẩu hiệu, cuộc vận động ấy đi vào từng việc làm cụ thể ở mỗi địa phương — từ nêu gương cán bộ, đảng viên đến những phong trào thi đua nhỏ ở cơ sở, trong đó có nhiều câu chuyện đang tiếp diễn ngay tại Ninh Bình hôm nay."},{"t":"Đảng ta là một Đảng cầm quyền. Mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư. — Chủ tịch Hồ Chí Minh, Di chúc (1969)"},{"t":"Bạn có biết? Phải hơn hai mươi năm sau khi Chủ tịch Hồ Chí Minh qua đời, tư tưởng Hồ Chí Minh mới chính thức được Đại hội VII của Đảng (1991) xác định là nền tảng tư tưởng, cùng với chủ nghĩa Mác - Lênin."}],"hien_vat":[{"ten":"Khối kiến trúc ba lớp của Lăng","mo_ta":"Lăng cao 21,6 mét, gồm ba lớp: bậc thềm dưới cùng với hai khán đài hai bên, khối trung tâm bao quanh bởi hàng cột vuông đá hoa cương xám, và phần mái xếp tầng phía trên.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"ten":"Dòng chữ CHỦ TỊCH HỒ-CHÍ-MINH","mo_ta":"Dòng chữ ghép bằng đá ngọc đỏ lấy từ Cao Bằng, gắn trên diềm mặt trước Lăng, là chi tiết đầu tiên đập vào mắt người đứng ở Quảng trường Ba Đình nhìn lên.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"ten":"Hàng cột đá hoa cương xám","mo_ta":"Hàng cột vuông ốp đá hoa cương xám bao quanh phần giữa của Lăng, tạo nên vẻ trang nghiêm, bền vững cho toàn bộ công trình.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"ten":"Quảng trường Ba Đình","mo_ta":"Quảng trường rộng lớn trước Lăng, được chia thành nhiều ô cỏ vuông xen giữa các lối đi lát đá — nơi từng diễn ra lễ Tuyên ngôn Độc lập ngày 2/9/1945 và nay là nơi tổ chức các nghi lễ trọng đại của đất nước.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"ten":"Cột cờ giữa quảng trường","mo_ta":"Cột cờ ở trung tâm Quảng trường Ba Đình, nơi diễn ra nghi lễ thượng cờ vào buổi sáng và hạ cờ vào buổi tối mỗi ngày, thu hút đông đảo người dân đến xem.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"ten":"Hàng tre và cây vạn tuế","mo_ta":"Hai bên Lăng trồng hàng tre — biểu tượng làng quê Việt Nam — cùng 79 cây vạn tuế, con số tượng trưng cho 79 mùa xuân cuộc đời Chủ tịch Hồ Chí Minh.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"ten":"Bảo tàng Hồ Chí Minh","mo_ta":"Công trình khánh thành ngày 19/5/1990, nằm cạnh Lăng, lưu giữ hơn 170.000 tài liệu, hiện vật, phim ảnh về cuộc đời và sự nghiệp của Chủ tịch Hồ Chí Minh.","nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Museum"}],"hoi_dap":[{"hoi":"Lăng Chủ tịch Hồ Chí Minh được khánh thành vào ngày nào?","dap":"Ngày 29/8/1975, tại Quảng trường Ba Đình, Hà Nội.","sai":["2/9/1969","19/5/1975","2/9/1975"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"hoi":"Lăng được khởi công xây dựng vào thời gian nào?","dap":"Ngày 2/9/1973.","sai":["Ngay sau khi Bác mất năm 1969","Năm 1970","Năm 1975, cùng năm khánh thành"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"hoi":"Lăng Chủ tịch Hồ Chí Minh cao bao nhiêu mét?","dap":"21,6 mét.","sai":["15 mét","30 mét","12 mét"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"hoi":"Dòng chữ trên mặt trước Lăng được ghép bằng loại đá gì?","dap":"Đá ngọc đỏ lấy từ Cao Bằng.","sai":["Đá cẩm thạch trắng","Đá granite đen","Đá hoa cương xanh"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"hoi":"Số cây vạn tuế trồng quanh Lăng mang ý nghĩa tượng trưng gì?","dap":"79 cây, tượng trưng cho 79 mùa xuân cuộc đời của Chủ tịch Hồ Chí Minh.","sai":["Tượng trưng cho 79 tỉnh thành cả nước","Tượng trưng cho 79 năm thành lập Đảng","Không mang ý nghĩa đặc biệt nào"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"hoi":"Bảo tàng Hồ Chí Minh được khánh thành vào dịp nào?","dap":"Ngày 19/5/1990, đúng kỷ niệm 100 năm ngày sinh của Chủ tịch Hồ Chí Minh.","sai":["Ngày 2/9/1990, kỷ niệm Quốc khánh","Ngày 19/5/1969","Ngày 3/2/1990, kỷ niệm ngày thành lập Đảng"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Museum"},{"hoi":"UNESCO ra nghị quyết vinh danh Chủ tịch Hồ Chí Minh vào năm nào, với danh hiệu gì?","dap":"Năm 1987, với danh hiệu Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất.","sai":["Năm 1990, Danh nhân văn hóa thế giới","Năm 1969, Anh hùng dân tộc","Năm 1975, Nhà lãnh đạo kiệt xuất châu Á"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"hoi":"Bảo tàng Hồ Chí Minh hiện lưu giữ khoảng bao nhiêu tài liệu, hiện vật, phim ảnh?","dap":"Hơn 170.000 tài liệu, hiện vật và phim ảnh.","sai":["Khoảng 10.000","Hơn 1 triệu","Chỉ khoảng 5.000 hiện vật gốc"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Museum"},{"hoi":"Tư tưởng Hồ Chí Minh được Đảng Cộng sản Việt Nam xác định là nền tảng tư tưởng từ đại hội nào?","dap":"Đại hội đại biểu toàn quốc lần thứ VII, năm 1991.","sai":["Đại hội II, năm 1951","Đại hội IV, năm 1976","Đại hội VI, năm 1986"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Thought"},{"hoi":"Cuộc vận động Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh mang tên gọi chính thức này từ văn kiện nào?","dap":"Chỉ thị số 05-CT/TW của Bộ Chính trị, ban hành năm 2016.","sai":["Nghị quyết Đại hội VII, năm 1991","Di chúc của Chủ tịch Hồ Chí Minh, năm 1969","Nghị quyết UNESCO, năm 1987"],"nguon":"https://hochiminh.vn/hoc-va-lam-theo-bac/di-chuc"},{"hoi":"Lăng Chủ tịch Hồ Chí Minh đóng cửa vào những ngày nào trong tuần?","dap":"Thứ Hai và thứ Sáu, trừ một số ngày lễ đặc biệt.","sai":["Chủ nhật và thứ Bảy","Chỉ đóng cửa thứ Hai","Mở cửa tất cả các ngày trong tuần"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"hoi":"Quảng trường Ba Đình có ý nghĩa lịch sử gì trước khi Lăng được xây dựng?","dap":"Đây là nơi Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập ngày 2/9/1945, khai sinh nước Việt Nam Dân chủ Cộng hòa.","sai":["Là nơi diễn ra Hội nghị Genève năm 1954","Là quảng trường mới được xây hoàn toàn năm 1975","Là nơi đặt trụ sở Phủ Toàn quyền Đông Dương"],"nguon":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"}],"nguon":[{"ten":"Ho Chi Minh Mausoleum — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Mausoleum"},{"ten":"Ho Chi Minh Museum — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Museum"},{"ten":"Ho Chi Minh Thought — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh_Thought"},{"ten":"Ho Chi Minh — Wikipedia (tiếng Anh)","url":"https://en.wikipedia.org/wiki/Ho_Chi_Minh"},{"ten":"Di chúc — Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh","url":"https://hochiminh.vn/hoc-va-lam-theo-bac/di-chuc"}],"so_chu":1162}};
